def _load_project_env_files() -> None:
    env_paths = [
        (BACKEND_ENV_PATH, True),
        (FRONTEND_ENV_PATH, False),
    ]
    for env_path, should_override in env_paths:
        try:
            if env_path.exists():
                load_dotenv(env_path, override=should_override)
        except Exception:
            logging.exception("Failed to load environment file: %s", env_path)


