PCAP_ARTIFACT_ENCRYPTION_MAGIC = b"SPCAPENC1"
PCAP_ARTIFACT_ENCRYPTION_CHUNK_SIZE = 1024 * 1024
PCAP_ARTIFACT_TERMINAL_STATUSES = {"done", "error", "failed", "cancelled"}
