def _utc_now_z() -> str:
    return datetime.now(UTC).isoformat().replace("+00:00", "Z")


def _artifact_protection_record(
    path: Path,
    *,
    artifact_type: str,
    reason: Optional[str] = None,
    encrypted_path: Optional[Path] = None,
    status: str = "skipped",
) -> dict[str, object]:
    if status == "encrypted":
        return {
            "original_name": path.name,
            "encrypted_name": encrypted_path.name if encrypted_path else f"{path.name}.enc",
            "type": artifact_type,
            "status": "encrypted",
        }
    return {
        "name": path.name,
        "type": artifact_type,
        "reason": reason or "not_sensitive",
        "status": status,
    }


def _derive_pcap_artifact_encryption_key(raw_key: str) -> bytes:
    return hashlib.sha256(str(raw_key or "").encode("utf-8")).digest()


def _encrypt_file_copy_verify_delete(source_path: Path, key: bytes) -> Path:
    encrypted_path = source_path.with_name(f"{source_path.name}.enc")
    temp_path = source_path.with_name(f"{source_path.name}.enc.tmp")
    nonce = secrets.token_bytes(12)
    encryptor = Cipher(algorithms.AES(key), modes.GCM(nonce)).encryptor()
    encryptor.authenticate_additional_data(source_path.name.encode("utf-8", errors="ignore"))

    try:
        with source_path.open("rb") as src, temp_path.open("wb") as dst:
            dst.write(PCAP_ARTIFACT_ENCRYPTION_MAGIC)
            dst.write(nonce)
            while True:
                chunk = src.read(PCAP_ARTIFACT_ENCRYPTION_CHUNK_SIZE)
                if not chunk:
                    break
                dst.write(encryptor.update(chunk))
            dst.write(encryptor.finalize())
            dst.write(encryptor.tag)
            dst.flush()
            os.fsync(dst.fileno())
        os.replace(temp_path, encrypted_path)
    finally:
        if temp_path.exists():
            try:
                temp_path.unlink()
            except OSError:
                logging.warning("Failed to remove temporary encrypted artifact %s", temp_path)

    if not encrypted_path.exists() or encrypted_path.stat().st_size <= (
        len(PCAP_ARTIFACT_ENCRYPTION_MAGIC) + 12 + 16
    ):
        raise RuntimeError("Encrypted artifact verification failed.")

    source_path.unlink()
    return encrypted_path


def _add_unique_artifact_candidate(
    candidates: list[tuple[Path, str]],
    seen: set[Path],
    raw_path: object,
    artifact_type: str,
) -> None:
    if not raw_path:
        return
    try:
        path = Path(str(raw_path)).expanduser().resolve()
    except Exception:
        return
    if path in seen:
        return
    seen.add(path)
    candidates.append((path, artifact_type))


def _pcap_artifact_candidates(job_state) -> list[tuple[Path, str]]:
    candidates: list[tuple[Path, str]] = []
    seen: set[Path] = set()

    upload_path = getattr(job_state, "upload_path", None)
    if upload_path and Path(str(upload_path)).suffix.lower() in PCAP_ARTIFACT_PCAP_SUFFIXES:
        _add_unique_artifact_candidate(candidates, seen, upload_path, "pcap")

    packet_csv_path = getattr(job_state, "packet_csv_path", None)
    if packet_csv_path:
        _add_unique_artifact_candidate(candidates, seen, packet_csv_path, "csv")

    try:
        job_dir = _job_dir_from_state(job_state)
    except Exception:
        job_dir = Path(JOBS_FOLDER) / str(getattr(job_state, "job_id", ""))

    if job_dir.exists():
        for path in job_dir.rglob("*"):
            if not path.is_file():
                continue
            suffix = path.suffix.lower()
            name = path.name.lower()
            if suffix in PCAP_ARTIFACT_PCAP_SUFFIXES:
                _add_unique_artifact_candidate(candidates, seen, path, "pcap")
            elif suffix == ".csv" and name not in {"report.csv", "summary.csv"}:
                _add_unique_artifact_candidate(candidates, seen, path, "csv")

    return candidates


def _build_artifact_protection_metadata(
    *,
    enabled: bool,
    reason: Optional[str] = None,
    protected_files: Optional[list[dict[str, object]]] = None,
    skipped_files: Optional[list[dict[str, object]]] = None,
    warnings: Optional[list[str]] = None,
) -> dict[str, object]:
    payload: dict[str, object] = {
        "enabled": bool(enabled),
        "mode": "encrypted_at_rest" if enabled else "disabled",
        "protected_at": _utc_now_z(),
        "protected_files": protected_files or [],
        "skipped_files": skipped_files or [],
    }
    if reason:
        payload["reason"] = reason
    if warnings:
        payload["warnings"] = warnings
    return payload


def _write_artifact_protection_metadata(job_state, metadata: dict[str, object]) -> None:
    job_id = str(getattr(job_state, "job_id", "") or "")
    if not job_id:
        return

    jobs.update(job_id, artifact_protection=_sanitize_for_json(metadata))

    report_path = getattr(job_state, "report_path", None)
    if not report_path:
        fallback = Path(JOBS_FOLDER) / job_id / "report.json"
        report_path = str(fallback) if fallback.exists() else None
    if not report_path:
        return

    path = Path(report_path)
    if not path.exists() or not path.is_file():
        return

    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(payload, dict):
            return
        meta = payload.get("meta")
        if not isinstance(meta, dict):
            meta = {}
        meta["artifact_protection"] = _sanitize_for_json(metadata)
        payload["meta"] = meta
        path.write_text(
            json.dumps(_sanitize_for_json(payload), indent=2, allow_nan=False),
            encoding="utf-8",
        )
    except Exception:
        logging.exception(
            "Failed to write artifact protection metadata to report | job_id=%s",
            job_id,
        )


def _protect_pcap_artifacts_after_terminal_state(job_state) -> Optional[dict[str, object]]:
    """
    Protect raw PCAP artifacts after, and only after, a terminal job status.

    The analysis pipeline has already completed or stopped when this hook runs.
    report.json and state.json stay plaintext so UI, chatbot, reports, alerts,
    and history can keep reading completed analysis metadata.
    """
    if not PCAP_PROTECT_ARTIFACTS:
        return None

    status = str(getattr(job_state, "status", "") or "").strip().lower()
    if status not in PCAP_ARTIFACT_TERMINAL_STATUSES:
        return _build_artifact_protection_metadata(
            enabled=False,
            reason="non_terminal_status",
            skipped_files=[],
        )

    if PCAP_ARTIFACT_ENCRYPTION_MODE != "copy_encrypt_verify":
        metadata = _build_artifact_protection_metadata(
            enabled=False,
            reason="unsupported_encryption_mode",
            warnings=["PCAP_ARTIFACT_ENCRYPTION_MODE must be copy_encrypt_verify."],
        )
        _write_artifact_protection_metadata(job_state, metadata)
        return metadata

    raw_key = str(PCAP_ARTIFACT_ENCRYPTION_KEY or "").strip()
    if not raw_key:
        metadata = _build_artifact_protection_metadata(
            enabled=False,
            reason="missing_encryption_key",
            skipped_files=[
                _artifact_protection_record(path, artifact_type=artifact_type, reason="missing_key")
                for path, artifact_type in _pcap_artifact_candidates(job_state)
                if path.exists() and path.is_file()
            ],
        )
        _write_artifact_protection_metadata(job_state, metadata)
        return metadata

    key = _derive_pcap_artifact_encryption_key(raw_key)
    protected_files: list[dict[str, object]] = []
    skipped_files: list[dict[str, object]] = []
    warnings: list[str] = []

    for source_path, artifact_type in _pcap_artifact_candidates(job_state):
        if source_path.name.lower() in {"report.json", "state.json"}:
            skipped_files.append(
                _artifact_protection_record(
                    source_path,
                    artifact_type=artifact_type,
                    reason="required_by_ui",
                )
            )
            continue
        if source_path.suffix.lower() == ".enc":
            skipped_files.append(
                _artifact_protection_record(
                    source_path,
                    artifact_type=artifact_type,
                    reason="already_encrypted",
                )
            )
            continue
        if not source_path.exists() or not source_path.is_file():
            skipped_files.append(
                _artifact_protection_record(
                    source_path,
                    artifact_type=artifact_type,
                    reason="not_found",
                )
            )
            continue
        encrypted_path = source_path.with_name(f"{source_path.name}.enc")
        if encrypted_path.exists() and encrypted_path.stat().st_size > 0:
            skipped_files.append(
                _artifact_protection_record(
                    source_path,
                    artifact_type=artifact_type,
                    reason="already_encrypted",
                )
            )
            continue
        try:
            encrypted_path = _encrypt_file_copy_verify_delete(source_path, key)
            protected_files.append(
                _artifact_protection_record(
                    source_path,
                    artifact_type=artifact_type,
                    encrypted_path=encrypted_path,
                    status="encrypted",
                )
            )
        except Exception:
            warnings.append(f"encryption_failed:{source_path.name}")
            skipped_files.append(
                _artifact_protection_record(
                    source_path,
                    artifact_type=artifact_type,
                    reason="encryption_failed",
                )
            )
            logging.exception(
                "PCAP artifact encryption failed; original file was kept | job_id=%s | artifact=%s",
                getattr(job_state, "job_id", None),
                source_path.name,
            )

    evidence_dir = getattr(job_state, "evidence_dir", None)
    if evidence_dir:
        try:
            for zeek_path in Path(str(evidence_dir)).glob("*"):
                if zeek_path.is_file() and zeek_path.name.lower() in PCAP_ARTIFACT_RAW_ZEEK_NAMES:
                    skipped_files.append(
                        _artifact_protection_record(
                            zeek_path,
                            artifact_type="zeek",
                            reason="required_by_ui",
                        )
                    )
        except Exception:
            warnings.append("zeek_skip_scan_failed")

    try:
        bundle_path = _job_dir_from_state(job_state) / "evidence_bundle.zip"
        if bundle_path.exists():
            skipped_files.append(
                _artifact_protection_record(
                    bundle_path,
                    artifact_type="evidence",
                    reason="required_by_ui",
                )
            )
    except Exception:
        pass

    metadata = _build_artifact_protection_metadata(
        enabled=bool(protected_files),
        reason=None if protected_files else "no_sensitive_artifacts_found",
        protected_files=protected_files,
        skipped_files=skipped_files,
        warnings=warnings,
    )
    _write_artifact_protection_metadata(job_state, metadata)
    return metadata


def _build_allowed_frontend_origins() -> list[str]:
    origins = set()

    raw = str(FRONTEND_BASE_URL or "").strip()
    if raw:
        origins.add(raw.rstrip("/"))

    local_ports = {"3000", "5173", "4173"}
    for scheme in ("http", "https"):
        for host in ("localhost", "127.0.0.1"):
            for port in local_ports:
                origins.add(f"{scheme}://{host}:{port}")

    return sorted(origins)


ALLOWED_FRONTEND_ORIGINS = _build_allowed_frontend_origins()

