_JOB_POLL_ACCESS_RE = re.compile(
    r'"GET (?P<path>/job/[^ ]+|/pcap/result/[^ ]+|/pcap/status/[^ ]+|/jobs(?:\?[^ ]*)?|/pcap/jobs(?:\?[^ ]*)?) HTTP/[^"]+" 200'
)


def _should_emit_throttled_log(key: str, window_s: int) -> bool:
    now = time.monotonic()
    with _pcap_log_throttle_lock:
        last_seen = _pcap_log_throttle_state.get(key, 0.0)
        if now - last_seen < max(int(window_s), 1):
            return False
        _pcap_log_throttle_state[key] = now
        if len(_pcap_log_throttle_state) > 4096:
            cutoff = now - max(int(window_s), 1) * 2
            stale_keys = [
                state_key
                for state_key, seen_at in _pcap_log_throttle_state.items()
                if seen_at < cutoff
            ]
            for state_key in stale_keys[:2048]:
                _pcap_log_throttle_state.pop(state_key, None)
    return True


class _JobPollAccessLogFilter(logging.Filter):
    def filter(self, record: logging.LogRecord) -> bool:
        try:
            message = record.getMessage()
        except Exception:
            return True

        match = _JOB_POLL_ACCESS_RE.search(message)
        if not match:
            return True

        raw_path = str(match.group("path") or "")
        path_only = raw_path.split("?", 1)[0]
        throttle_key = f"poll_access|{path_only}"
        return _should_emit_throttled_log(throttle_key, PCAP_POLL_LOG_WINDOW_S)


logging.getLogger("werkzeug").addFilter(_JobPollAccessLogFilter())


