def _path_is_within_base(path: Path, base: Path) -> bool:
    try:
        path.relative_to(base)
        return True
    except ValueError:
        return False


def _resolve_analyze_local_path(raw_path) -> Path:
    requested_text = str(raw_path or "").strip()
    if not requested_text:
        raise ValueError("No PCAP path provided")

    allowed_root = ANALYZE_LOCAL_ALLOWED_ROOT.resolve()
    try:
        requested_path = Path(requested_text).expanduser().resolve(strict=False)
    except Exception as exc:
        logging.warning(
            "Rejected analyze_local path with invalid format | requested=%s | error=%s",
            requested_text,
            str(exc),
        )
        raise ValueError("Invalid pcap_path") from exc

    if not _path_is_within_base(requested_path, allowed_root):
        logging.warning(
            "Blocked analyze_local path access | requested=%s | resolved=%s | allowed_root=%s",
            requested_text,
            requested_path,
            allowed_root,
        )
        raise PermissionError("pcap_path is outside the allowed analysis directory")

    if not requested_path.exists() or not requested_path.is_file():
        raise FileNotFoundError("File not found")

    return requested_path


