def init_storage() -> None:
    LOG_DIR.mkdir(exist_ok=True)
    conn = sqlite3.connect(str(DB_PATH))
    cur = conn.cursor()
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS threat_logs (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            run_at TEXT,
            time TEXT,
            src_ip TEXT,
            dst_ip TEXT,
            protocol TEXT,
            port INTEGER,
            prediction TEXT,
            risk TEXT,
            confidence REAL,
            dataset TEXT,
            blocked INTEGER DEFAULT 0
        )
        """
    )
    conn.commit()
    conn.close()


def save_threats_to_storage(threats, run_at=None):
    if not threats:
        return

    init_storage()
    if run_at is None:
        run_at = datetime.now(UTC).isoformat()

    rows = []
    for t in threats:
        rows.append(
            (
                run_at,
                t.get("time"),
                t.get("src_ip") or t.get("srcIP") or "",
                t.get("dst_ip") or t.get("dstIP") or "",
                t.get("protocol") or t.get("proto") or "",
                int(t.get("port") or 0),
                t.get("prediction") or "",
                t.get("risk") or "",
                float(t.get("confidence") or 0.0),
                t.get("dataset") or "",
            )
        )

    conn = sqlite3.connect(str(DB_PATH))
    cur = conn.cursor()
    cur.executemany(
        """
        INSERT INTO threat_logs (
            run_at, time, src_ip, dst_ip, protocol, port,
            prediction, risk, confidence, dataset
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        rows,
    )
    conn.commit()
    conn.close()

    write_header = not CSV_PATH.exists()
    with CSV_PATH.open("a", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        if write_header:
            writer.writerow(
                [
                    "run_at",
                    "time",
                    "src_ip",
                    "dst_ip",
                    "protocol",
                    "port",
                    "prediction",
                    "risk",
                    "confidence",
                    "dataset",
                ]
            )
        writer.writerows(rows)


