@app.route("/pcap/result/<job_id>", methods=["GET"])
@app.route("/pcap/status/<job_id>", methods=["GET"])
@app.route("/job/<job_id>", methods=["GET"])
def get_job(job_id):
    ctx, auth_error = _resolve_authenticated_pcap_request_context()
    if auth_error:
        return auth_error

    st, job_error = _get_authorized_job_for_context(job_id, ctx)
    if job_error:
        return job_error

    artifacts = _collect_job_export_artifacts(st)
    payload = {
        "job_id": st.job_id,
        "status": st.status,
        "created_at": st.created_at,
        "started_at": st.started_at,
        "finished_at": st.finished_at,
        "progress": st.progress,
        "message": st.message,
        "error": _summarize_job_error(st.error),
        "upload_path": st.upload_path,
        "upload_name": Path(st.upload_path).name if st.upload_path else "",
        "report_path": (
            str(artifacts["report_path"]) if artifacts["report_path"] else None
        ),
        "report_available": artifacts["report_path"] is not None,
        "evidence_available": bool(artifacts["zeek_files"]),
        "artifact_protection": getattr(st, "artifact_protection", None),
    }
    if st.status in {"queued", "running"}:
        payload["poll_after_ms"] = PCAP_RECOMMENDED_POLL_MS

    # If done, return report content inline (or only path)
    if (
        st.status == "done"
        and artifacts["report_path"] is not None
        and artifacts["report_path"].exists()
    ):
        try:
            payload["report"] = json.loads(
                artifacts["report_path"].read_text(encoding="utf-8")
            )
        except Exception:
            payload["report_path"] = str(artifacts["report_path"])

    response = _make_pcap_response(payload, 200, ctx)
    if st.status in {"queued", "running"}:
        response.headers["Retry-After"] = str(max(1, PCAP_RECOMMENDED_POLL_MS // 1000))
    return response


@app.route("/api/pcap/cancel/<job_id>", methods=["POST"])
@app.route("/pcap/cancel/<job_id>", methods=["POST"])
def cancel_pcap_job(job_id):
    ctx, auth_error = _resolve_authenticated_pcap_request_context()
    if auth_error:
        return auth_error

    st, job_error = _get_authorized_job_for_context(job_id, ctx)
    if job_error:
        return job_error

    status = str(getattr(st, "status", "") or "").strip().lower()
    upload_name = Path(st.upload_path).name if getattr(st, "upload_path", None) else job_id

    if status == "done":
        return _make_pcap_response(
            {
                "ok": False,
                "status": "done",
                "message": "Analysis already completed.",
            },
            200,
            ctx,
        )

    if status in {"error", "failed"}:
        return _make_pcap_response(
            {
                "ok": False,
                "status": "failed",
                "message": "Analysis already failed.",
            },
            200,
            ctx,
        )

    if status == "cancelled":
        return _make_pcap_response(
            {
                "ok": True,
                "status": "cancelled",
                "message": "Analysis cancelled.",
            },
            200,
            ctx,
        )

    if status not in {"queued", "running", "processing"}:
        return _make_pcap_response(
            {
                "ok": False,
                "status": status or "unknown",
                "message": "Analysis is not running.",
            },
            200,
            ctx,
        )

    process_terminated = False
    try:
        _log_pcap_analysis_activity(
            action_type="pcap_analysis_cancel_requested",
            user_id=int(ctx.owner_user_id),
            job_id=job_id,
            upload_name=upload_name,
            file_hash=getattr(st, "file_hash", None),
            description="A PCAP analysis cancellation was requested.",
            status=STATUS_INFO,
            severity=SEVERITY_LOW,
            metadata={"status": status, "reason": "user_requested"},
            commit=False,
        )
        jobs.request_cancel(job_id, reason="user_requested")
        process_terminated = _terminate_active_pcap_process(job_id)
        _log_pcap_analysis_activity(
            action_type="pcap_analysis_cancelled",
            user_id=int(ctx.owner_user_id),
            job_id=job_id,
            upload_name=upload_name,
            file_hash=getattr(st, "file_hash", None),
            description="A PCAP analysis job was cancelled by the user.",
            status=STATUS_SUCCESS,
            severity=SEVERITY_LOW,
            metadata={
                "status": "cancelled",
                "reason": "user_requested",
                "process_terminated": process_terminated,
            },
            commit=False,
        )
        db.session.commit()
    except Exception:
        db.session.rollback()
        logging.exception("Failed to cancel PCAP job | job_id=%s", job_id)
        try:
            _log_pcap_analysis_activity(
                action_type="pcap_analysis_cancel_failed",
                user_id=int(ctx.owner_user_id),
                job_id=job_id,
                upload_name=upload_name,
                file_hash=getattr(st, "file_hash", None),
                description="PCAP analysis cancellation failed.",
                status=STATUS_FAILED,
                severity=SEVERITY_MEDIUM,
                metadata={"status": status, "reason": "cancel_exception"},
            )
        except Exception:
            logging.exception("Failed to record PCAP cancel failure activity")
        return _make_pcap_response(
            {
                "ok": False,
                "status": status or "unknown",
                "message": "Unable to cancel analysis right now.",
            },
            500,
            ctx,
        )

    return _make_pcap_response(
        {
            "ok": True,
            "status": "cancelled",
            "message": "Analysis cancelled.",
            "process_terminated": process_terminated,
        },
        200,
        ctx,
    )


@app.route("/pcap/report/<job_id>", methods=["GET"])
@app.route("/job/<job_id>/export", methods=["GET"])
def export_job_artifact(job_id):
    ctx, auth_error = _resolve_authenticated_pcap_request_context()
    if auth_error:
        return auth_error

    st, job_error = _get_authorized_job_for_context(job_id, ctx)
    if job_error:
        return job_error

    export_type = (
        "report"
        if request.path.startswith(f"/pcap/report/{job_id}")
        else str(request.args.get("type", "report")).strip().lower()
    )
    if export_type not in {"report", "evidence", "bundle"}:
        return jsonify({"error": "Invalid export type"}), 400

    if st.status != "done":
        return jsonify({"error": "Job not completed yet"}), 409

    artifacts = _collect_job_export_artifacts(st)
    if export_type == "report":
        if artifacts["report_path"] is None:
            return jsonify({"error": "Report artifact not found"}), 404

        try:
            _log_pcap_analysis_activity(
                action_type="pcap_report_downloaded",
                user_id=int(ctx.owner_user_id),
                job_id=job_id,
                upload_name=Path(st.upload_path).name if getattr(st, "upload_path", None) else job_id,
                file_hash=getattr(st, "file_hash", None),
                description="The analysis report artifact was downloaded.",
                status=STATUS_SUCCESS,
                severity=SEVERITY_LOW,
                metadata={"export_type": "report"},
            )
        except Exception:
            db.session.rollback()
            logging.exception("Failed to record report download activity for job %s", job_id)

        try:
            gamification_service.record_download_event(
                ctx.owner_user_id,
                job_id,
                "report",
            )
        except Exception:
            logging.exception("Failed to record report download gamification event for job %s", job_id)

        return send_file(
            artifacts["report_path"],
            as_attachment=True,
            download_name=f"pcap_report_{job_id}.json",
            mimetype="application/json",
        )

    bundle_path = _build_job_evidence_bundle(st)
    if bundle_path is None or not bundle_path.exists():
        return jsonify({"error": "Evidence bundle not available"}), 404

    try:
        _log_pcap_analysis_activity(
            action_type="pcap_evidence_downloaded",
            user_id=int(ctx.owner_user_id),
            job_id=job_id,
            upload_name=Path(st.upload_path).name if getattr(st, "upload_path", None) else job_id,
            file_hash=getattr(st, "file_hash", None),
            description="The evidence bundle was downloaded for offline review.",
            status=STATUS_SUCCESS,
            severity=SEVERITY_LOW,
            metadata={"export_type": export_type},
        )
    except Exception:
        db.session.rollback()
        logging.exception("Failed to record evidence download activity for job %s", job_id)

    try:
        gamification_service.record_download_event(
            ctx.owner_user_id,
            job_id,
            "evidence",
            evidence_key="bundle",
        )
    except Exception:
        logging.exception("Failed to record evidence download gamification event for job %s", job_id)

    return send_file(
        bundle_path,
        as_attachment=True,
        download_name=f"pcap_evidence_{job_id}.zip",
        mimetype="application/zip",
    )


@app.route("/pcap/analyze-local", methods=["POST"])
@app.route("/analyze-local", methods=["POST"])
def analyze_local():
    try:
        ctx, auth_error = _resolve_authenticated_pcap_request_context()
        if auth_error:
            return auth_error

        data = request.get_json()

        if not data or not str(data.get("pcap_path") or "").strip():
            return jsonify({"error": "No PCAP path provided"}), 400

        try:
            pcap_path = str(_resolve_analyze_local_path(data["pcap_path"]))
        except PermissionError as exc:
            return jsonify({"error": str(exc)}), 403
        except FileNotFoundError:
            return jsonify({"error": "File not found"}), 400
        except ValueError as exc:
            return jsonify({"error": str(exc)}), 400

        include_zeek_raw = data.get("include_zeek", True)
        if isinstance(include_zeek_raw, str):
            include_zeek = include_zeek_raw.strip().lower() not in {
                "false",
                "0",
                "no",
                "off",
            }
        else:
            include_zeek = bool(include_zeek_raw)

        confidence_mode = _normalize_confidence_mode_value(data.get("confidence_mode"))

        max_alerts = _parse_positive_int(data.get("max_alerts"), None)
        max_clusters = _parse_positive_int(data.get("max_clusters"), None)
        file_hash = None
        try:
            file_hash = _compute_file_sha256(pcap_path)
        except Exception:
            logging.exception("Failed to compute SHA-256 for local PCAP %s", pcap_path)

        analysis_key = _build_analysis_key(
            source_key=_build_local_analysis_source_key(pcap_path),
            ctx=ctx,
            include_zeek=include_zeek,
            confidence_mode=confidence_mode,
            max_alerts=max_alerts,
            max_clusters=max_clusters,
        )

        st, created = jobs.create_or_reuse_active(
            upload_path=pcap_path,
            owner_user_id=ctx.owner_user_id,
            owner_user_scope=ctx.owner_user_scope,
            owner_client_id=ctx.owner_client_id,
            analysis_key=analysis_key,
        )
        reused_response = _reuse_existing_analysis_job(
            st=st,
            created=created,
            ctx=ctx,
            route_name="/analyze-local",
        )
        if reused_response is not None:
            return reused_response

        job_id = st.job_id
        jobs.update(job_id, file_hash=file_hash)
        upload_name = Path(pcap_path).name
        has_prior_analysis = (
            UserActivityLog.query.filter(
                UserActivityLog.user_id == int(ctx.owner_user_id),
                UserActivityLog.module == MODULE_PCAP,
                UserActivityLog.target_label == upload_name,
                UserActivityLog.action_type.in_(
                    [
                        "pcap_analysis_started",
                        "pcap_analysis_completed",
                        "pcap_analysis_failed",
                    ]
                ),
            )
            .limit(1)
            .first()
            is not None
        )
        try:
            _log_pcap_analysis_activity(
                action_type="pcap_analysis_started",
                user_id=int(ctx.owner_user_id),
                job_id=job_id,
                upload_name=upload_name,
                file_hash=file_hash,
                description="A local PCAP file was queued for analysis.",
                status=STATUS_INFO,
                severity=SEVERITY_MEDIUM,
                metadata={"analysis_source": "local_path"},
                commit=False,
            )
            if has_prior_analysis:
                _log_pcap_analysis_activity(
                    action_type="pcap_reanalysis_started",
                    user_id=int(ctx.owner_user_id),
                    job_id=job_id,
                    upload_name=upload_name,
                    file_hash=file_hash,
                    description="A previously analyzed local PCAP file was submitted again.",
                    status=STATUS_WARNING,
                    severity=SEVERITY_MEDIUM,
                    metadata={"analysis_source": "local_path"},
                    commit=False,
                )
            db.session.commit()
        except Exception:
            db.session.rollback()
            logging.exception(
                "Failed to record local PCAP start activity for job %s", job_id
            )
        try:
            gamification_service.record_upload(
                ctx.owner_user_id,
                job_id,
                file_hash,
                upload_name=upload_name,
            )
        except Exception:
            logging.exception("Failed to record gamification upload event for local job %s", job_id)
        try:
            _create_job_started_notification(st)
        except Exception:
            logging.exception("Failed to create start notification for job %s", job_id)

        def pipeline():
            return run_pcap_pipeline(
                pcap_path=pcap_path,
                job_id=job_id,
                include_zeek=include_zeek,
                confidence_mode=confidence_mode,
                max_alerts=max_alerts,
                max_clusters=max_clusters,
                zeek_status_progress=20,
                ml_progress=60,
                ml_message="Running ML inference",
                zeek_loading_progress=70,
            )

        jobs.submit(
            job_id,
            pipeline,
            on_success=_notify_job_success,
            on_error=_notify_job_failure,
            on_terminal=_protect_pcap_artifacts_after_terminal_state,
        )

        return _make_pcap_response(
            {"job_id": job_id, "status": "queued", "poll": f"/job/{job_id}"},
            202,
            ctx,
        )

    except Exception as e:
        return jsonify({"error": str(e)}), 500


