def _normalize_notification_type(value, metadata=None) -> str:
    raw_type = str(value or "").strip().lower()
    metadata = metadata if isinstance(metadata, dict) else {}

    if raw_type == "high_risk_detected":
        risk_level = str(metadata.get("risk_level") or "").strip().lower()
        return (
            NOTIFICATION_TYPE_CRITICAL_DETECTED
            if risk_level == "critical"
            else NOTIFICATION_TYPE_SUSPICIOUS_DETECTED
        )
    if raw_type == "export_ready":
        artifact_type = str(metadata.get("artifact_type") or "").strip().lower()
        if artifact_type == "evidence":
            return NOTIFICATION_TYPE_EVIDENCE_READY
        return NOTIFICATION_TYPE_REPORT_READY
    if raw_type in VALID_NOTIFICATION_TYPES:
        return raw_type
    return raw_type or NOTIFICATION_TYPE_JOB_COMPLETED


def _normalize_notification_severity(value, *, type=None, metadata=None) -> str:
    raw = str(value or "").strip().lower()
    if raw in VALID_NOTIFICATION_SEVERITIES:
        return raw

    metadata = metadata if isinstance(metadata, dict) else {}
    normalized_type = _normalize_notification_type(type, metadata)
    if normalized_type == NOTIFICATION_TYPE_JOB_FAILED:
        return NOTIFICATION_SEVERITY_ERROR
    if normalized_type == NOTIFICATION_TYPE_JOB_COMPLETED:
        return NOTIFICATION_SEVERITY_SUCCESS
    if normalized_type in {
        NOTIFICATION_TYPE_REPORT_READY,
        NOTIFICATION_TYPE_EVIDENCE_READY,
    }:
        return NOTIFICATION_SEVERITY_SUCCESS
    if normalized_type == NOTIFICATION_TYPE_CRITICAL_DETECTED:
        return NOTIFICATION_SEVERITY_CRITICAL
    if normalized_type == NOTIFICATION_TYPE_SUSPICIOUS_DETECTED:
        return NOTIFICATION_SEVERITY_WARNING
    return NOTIFICATION_SEVERITY_INFO


def _notification_metadata_to_json(metadata) -> str:
    if metadata is None:
        return "{}"
    try:
        return json.dumps(metadata, ensure_ascii=False)
    except Exception:
        logging.exception("notification metadata serialization failed")
        return "{}"


def _notification_metadata_from_json(raw_value) -> dict:
    if not raw_value:
        return {}
    try:
        parsed = json.loads(raw_value)
        return parsed if isinstance(parsed, dict) else {}
    except Exception:
        return {}


def _notification_job_id(
    notification: UserNotification, metadata: dict | None = None
) -> Optional[str]:
    direct_job_id = str(getattr(notification, "job_id", "") or "").strip()
    if direct_job_id:
        return direct_job_id

    metadata = (
        metadata
        if isinstance(metadata, dict)
        else _notification_metadata_from_json(
            getattr(notification, "metadata_json", None)
        )
    )
    metadata_job_id = str(metadata.get("job_id") or "").strip()
    return metadata_job_id or None


def _serialize_notification(notification: UserNotification) -> dict:
    metadata = _notification_metadata_from_json(notification.metadata_json)
    job_id = _notification_job_id(notification, metadata)
    normalized_type = _normalize_notification_type(notification.type, metadata)
    severity = _normalize_notification_severity(
        getattr(notification, "severity", None),
        type=normalized_type,
        metadata=metadata,
    )
    message = str(getattr(notification, "body", "") or "").strip()
    if job_id and not metadata.get("job_id"):
        metadata = {**metadata, "job_id": job_id}

    # Safely handle created_at which may be naive or aware
    created_at_str = None
    if notification.created_at:
        created_at_utc = _to_utc_aware(notification.created_at)
        if created_at_utc:
            created_at_str = created_at_utc.isoformat()

    return {
        "id": notification.id,
        "user_id": int(notification.user_id),
        "type": normalized_type,
        "severity": severity,
        "title": notification.title,
        "message": message,
        "body": message,
        "job_id": job_id,
        "metadata": _sanitize_for_json(metadata),
        "is_read": bool(notification.is_read),
        "created_at": created_at_str,
    }


def _notification_unread_count(user_id: int) -> int:
    app_count = (
        UserNotification.query.filter_by(user_id=user_id, is_read=False).count()
        if user_id
        else 0
    )
    identity_count = identity_web_unread_alert_count(int(user_id)) if user_id else 0
    return int(app_count or 0) + int(identity_count or 0)


def _identity_notification_severity(alert: dict) -> str:
    severity = str(alert.get("severity") or "").strip().lower()
    if severity == "critical":
        return "critical"
    if severity == "high":
        return "error"
    if severity == "medium":
        return "warning"
    if severity == "low":
        return "success"
    return "info"


def _serialize_identity_alert_notification(alert: dict, user_id: int) -> dict:
    alert_id = int(alert.get("id") or 0)
    scan_id = int(alert.get("scan_id") or 0)
    action_url = f"/identityleak-monitor?scan_id={scan_id}" if scan_id else "/identityleak-monitor"
    metadata = {
        "module": "Identity Leak Monitor",
        "source": "identity",
        "source_id": alert_id,
        "scan_id": scan_id,
        "action_url": action_url,
        "risk_level": alert.get("severity"),
    }
    message = str(alert.get("message") or "").strip()
    return {
        "id": f"identity-{alert_id}",
        "user_id": int(user_id),
        "module": "Identity Leak Monitor",
        "source": "identity",
        "source_id": alert_id,
        "scan_id": scan_id,
        "action_url": action_url,
        "type": "identity_leak",
        "severity": _identity_notification_severity(alert),
        "title": str(alert.get("title") or "Identity exposure alert"),
        "message": message,
        "body": message,
        "job_id": None,
        "metadata": _sanitize_for_json(metadata),
        "is_read": bool(alert.get("is_read")),
        "created_at": alert.get("created_at"),
    }


def _notification_created_sort_key(notification: dict) -> str:
    return str(notification.get("created_at") or "")


def require_notification_user():
    user, auth_error = require_full_auth_user()
    if user is not None:
        return user, None

    admin = get_current_admin()
    admin_user_id = admin.get("user_id") if admin else None
    if admin_user_id is not None:
        admin_user = db.session.get(User, int(admin_user_id))
        if admin_user is not None:
            _, security_error = _enforce_user_security_state(admin_user)
            if security_error:
                return None, security_error
            return admin_user, None

    return None, auth_error or (jsonify({"error": "Unauthorized"}), 401)


def _admin_notification_numeric_id(notification_key: str) -> int:
    digest = hashlib.sha256(str(notification_key or "").encode("utf-8")).digest()
    value = int.from_bytes(digest[:4], "big") & 0x7FFFFFFF
    return value or 1


def _admin_notification_read_keys(admin_email: str) -> set[str]:
    email = str(admin_email or "").strip().lower()
    if not email:
        return set()
    return {
        str(key)
        for (key,) in db.session.query(AdminNotificationRead.notification_key)
        .filter(AdminNotificationRead.admin_email == email)
        .all()
    }


def _mark_admin_notification_keys_read(admin_email: str, keys: list[str]) -> int:
    email = str(admin_email or "").strip().lower()
    unique_keys = sorted({str(key or "").strip() for key in keys if str(key or "").strip()})
    if not email or not unique_keys:
        return 0

    existing = {
        str(key)
        for (key,) in db.session.query(AdminNotificationRead.notification_key)
        .filter(
            AdminNotificationRead.admin_email == email,
            AdminNotificationRead.notification_key.in_(unique_keys),
        )
        .all()
    }
    new_keys = [key for key in unique_keys if key not in existing]
    for key in new_keys:
        db.session.add(
            AdminNotificationRead(
                admin_email=email,
                notification_key=key,
                read_at=datetime.now(UTC),
            )
        )
    if new_keys:
        db.session.commit()
    return len(new_keys)


def _admin_notification_item(
    *,
    key: str,
    type: str,
    severity: str,
    title: str,
    message: str,
    created_at,
    read_keys: set[str],
    job_id: str | None = None,
    metadata: dict | None = None,
) -> dict[str, object]:
    metadata_payload = metadata if isinstance(metadata, dict) else {}
    created_at_dt = None
    if isinstance(created_at, str) and created_at.strip():
        try:
            created_at_dt = _as_utc_datetime(datetime.fromisoformat(created_at.replace("Z", "+00:00")))
        except ValueError:
            created_at_dt = None
    elif isinstance(created_at, (int, float)) and float(created_at or 0) > 0:
        created_at_dt = datetime.fromtimestamp(float(created_at), tz=UTC)
    else:
        created_at_dt = _as_utc_datetime(created_at)
    created_at_value = created_at_dt.isoformat() if created_at_dt else None
    return {
        "id": _admin_notification_numeric_id(key),
        "key": key,
        "type": type,
        "severity": severity,
        "title": title,
        "message": message,
        "body": message,
        "job_id": job_id,
        "metadata": _sanitize_for_json(metadata_payload),
        "is_read": key in read_keys,
        "created_at": created_at_value,
    }


def _build_admin_notifications(admin_email: str, limit: int = 20, offset: int = 0) -> tuple[list[dict[str, object]], int]:
    read_keys = _admin_notification_read_keys(admin_email)
    user_by_id = {
        int(user.id): user
        for user in User.query.order_by(User.id.desc()).limit(500).all()
        if getattr(user, "id", None) is not None
    }
    items: list[dict[str, object]] = []

    notifications = (
        UserNotification.query.order_by(UserNotification.created_at.desc(), UserNotification.id.desc())
        .limit(120)
        .all()
    )
    for notification in notifications:
        metadata = _notification_metadata_from_json(getattr(notification, "metadata_json", None))
        user = user_by_id.get(int(getattr(notification, "user_id", 0) or 0))
        user_email = str(getattr(user, "email", "") or "").strip().lower()
        user_name = str(getattr(user, "full_name", "") or "").strip() or user_email or "Unknown user"
        serialized = _serialize_notification(notification)
        key = f"user-notification:{notification.id}"
        title = str(serialized.get("title") or "User security notification")
        message = str(serialized.get("message") or serialized.get("body") or "Notification received.")
        if user_email:
            message = f"{message} Admin monitoring event recorded."
        items.append(
            _admin_notification_item(
                key=key,
                type=str(serialized.get("type") or "info"),
                severity=str(serialized.get("severity") or "info"),
                title=title,
                message=message,
                created_at=getattr(notification, "created_at", None),
                read_keys=read_keys,
                job_id=serialized.get("job_id"),
                metadata={
                    **(metadata if isinstance(metadata, dict) else {}),
                    "admin_scope": "system",
                    "affected_user_id": getattr(notification, "user_id", None),
                    "affected_user_email": user_email,
                    "affected_user_name": user_name,
                },
            )
        )

    for job_state in jobs.list_recent(limit=80):
        status = _pcap_admin_status(getattr(job_state, "status", None))
        job_id = str(getattr(job_state, "job_id", "") or "").strip()
        if not job_id:
            continue
        report = _pcap_admin_report_for_job(job_state) if status == "done" else None
        row = _pcap_admin_job_row(job_state, report)
        filename = str(row.get("filename") or "PCAP file")
        created_at = row.get("finished_at") or row.get("created_at") or datetime.now(UTC)
        if status == "error":
            items.append(
                _admin_notification_item(
                    key=f"pcap-job-failed:{job_id}",
                    type="job_failed",
                    severity="critical",
                    title="PCAP job failed",
                    message=f"{filename} failed during analysis. {_summarize_job_error(getattr(job_state, 'error', None))}",
                    created_at=created_at,
                    read_keys=read_keys,
                    job_id=job_id,
                    metadata={"admin_scope": "system", "filename": filename, "status": status},
                )
            )
        elif status == "done":
            score = row.get("score")
            if score is not None and float(score or 0) >= 70:
                items.append(
                    _admin_notification_item(
                        key=f"pcap-critical-score:{job_id}",
                        type="critical_detected",
                        severity="critical" if float(score or 0) >= 85 else "warning",
                        title="High-risk PCAP analysis",
                        message=f"{filename} completed with risk score {score}.",
                        created_at=created_at,
                        read_keys=read_keys,
                        job_id=job_id,
                        metadata={"admin_scope": "system", "filename": filename, "score": score},
                    )
                )
            elif row.get("report_available"):
                items.append(
                    _admin_notification_item(
                        key=f"pcap-report-ready:{job_id}",
                        type="report_ready",
                        severity="success",
                        title="PCAP report ready",
                        message=f"{filename} finished and the report is available.",
                        created_at=created_at,
                        read_keys=read_keys,
                        job_id=job_id,
                        metadata={"admin_scope": "system", "filename": filename, "score": score},
                    )
                )

    items.sort(
        key=lambda item: _parse_dashboard_alert_epoch(item.get("created_at"), fallback=0.0),
        reverse=True,
    )
    unread_count = sum(1 for item in items if not item.get("is_read"))
    return items[offset : offset + limit], unread_count


def _safe_str(value, default: str = "") -> str:
    if value is None:
        return default
    try:
        text_value = str(value).strip()
    except Exception:
        return default
    return text_value or default


def _safe_int(value, default=0) -> int:
    try:
        return int(float(value))
    except (TypeError, ValueError):
        return default


def _safe_float(value, default=0.0) -> float:
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def _to_utc_aware(dt):
    """
    Normalize a datetime to UTC-aware format.
    - If None, returns None
    - If naive, assumes UTC and makes it aware
    - If aware, converts to UTC
    """
    if dt is None:
        return None
    try:
        if dt.tzinfo is None:
            # Naive datetime; assume it's UTC
            return dt.replace(tzinfo=UTC)
        else:
            # Aware datetime; convert to UTC
            return dt.astimezone(UTC)
    except (AttributeError, ValueError):
        return None


def _ensure_notification_schema_initialized() -> None:
    global _notification_schema_initialized
    if _notification_schema_initialized:
        return

    with _notification_schema_lock:
        if _notification_schema_initialized:
            return

        db.create_all()

        inspector = inspect(db.engine)
        if not inspector.has_table(UserNotification.__tablename__):
            _notification_schema_initialized = True
            return

        column_names = {
            str(column.get("name") or "").strip()
            for column in inspector.get_columns(UserNotification.__tablename__)
        }
        statements = []
        if "severity" not in column_names:
            statements.append(
                text(
                    "ALTER TABLE user_notification "
                    "ADD COLUMN severity VARCHAR(20) NOT NULL DEFAULT 'info'"
                )
            )
        if "job_id" not in column_names:
            statements.append(
                text("ALTER TABLE user_notification ADD COLUMN job_id VARCHAR(80)")
            )

        try:
            for statement in statements:
                db.session.execute(statement)
            if statements:
                db.session.commit()
        except Exception:
            db.session.rollback()
            logging.exception("Failed to ensure notification schema columns")
            raise

        inspector = inspect(db.engine)
        existing_indexes = {
            str(index.get("name") or "").strip()
            for index in inspector.get_indexes(UserNotification.__tablename__)
        }
        index_statements = []
        if "ix_user_notification_job_id" not in existing_indexes:
            index_statements.append(
                text(
                    "CREATE INDEX ix_user_notification_job_id "
                    "ON user_notification (job_id)"
                )
            )
        if "ix_user_notification_severity" not in existing_indexes:
            index_statements.append(
                text(
                    "CREATE INDEX ix_user_notification_severity "
                    "ON user_notification (severity)"
                )
            )

        try:
            for statement in index_statements:
                db.session.execute(statement)
            if index_statements:
                db.session.commit()
        except Exception:
            db.session.rollback()
            logging.exception("Failed to ensure notification schema indexes")
            raise

        _notification_schema_initialized = True


