def _request_ip_address() -> str | None:
    if not has_request_context():
        return None
    forwarded_for = str(request.headers.get("X-Forwarded-For") or "").strip()
    if forwarded_for:
        first_hop = forwarded_for.split(",", 1)[0].strip()
        if first_hop:
            return first_hop[:64]
    remote_addr = str(request.remote_addr or "").strip()
    return remote_addr[:64] if remote_addr else None


def _request_session_id() -> str | None:
    if not has_request_context():
        return None
    refresh_token = str(request.cookies.get("refresh_token") or "").strip()
    access_token = _extract_access_token_from_request() or ""
    raw_value = refresh_token or access_token
    if not raw_value:
        return None
    return hashlib.sha256(raw_value.encode("utf-8")).hexdigest()[:24]


def _request_device_fingerprint() -> str:
    seed_parts = [
        str(request.headers.get("User-Agent") or "").strip(),
        str(request.headers.get("Accept-Language") or "").strip().lower(),
        str(request.headers.get("Sec-CH-UA-Platform") or "").strip().lower(),
    ]
    return hashlib.sha256("|".join(seed_parts).encode("utf-8")).hexdigest()[:32]


def _request_device_label() -> str:
    user_agent = str(request.headers.get("User-Agent") or "").strip()
    if not user_agent:
        return "Unknown device"

    lowered = user_agent.lower()
    browser = "Browser"
    if "edg/" in lowered:
        browser = "Microsoft Edge"
    elif "chrome/" in lowered and "edg/" not in lowered:
        browser = "Google Chrome"
    elif "firefox/" in lowered:
        browser = "Mozilla Firefox"
    elif "safari/" in lowered and "chrome/" not in lowered:
        browser = "Safari"

    platform = "desktop"
    if "windows" in lowered:
        platform = "Windows"
    elif "mac os" in lowered or "macintosh" in lowered:
        platform = "macOS"
    elif "android" in lowered:
        platform = "Android"
    elif "iphone" in lowered or "ipad" in lowered or "ios" in lowered:
        platform = "iOS"
    elif "linux" in lowered:
        platform = "Linux"

    return f"{browser} on {platform}"


def _sanitize_activity_metadata_for_user(metadata) -> dict[str, object]:
    raw_metadata = (
        metadata if isinstance(metadata, dict) else deserialize_activity_metadata(metadata)
    )
    safe = safe_activity_metadata(raw_metadata)
    filtered: dict[str, object] = {}
    sensitive_fragments = {
        "token",
        "secret",
        "cookie",
        "authorization",
        "password",
        "hash",
    }

    for key, value in safe.items():
        lower_key = str(key).lower()
        if any(fragment in lower_key for fragment in sensitive_fragments):
            continue
        filtered[str(key)] = value
    return filtered


def log_user_event(
    *,
    user_id,
    module,
    action_type,
    title=None,
    description=None,
    status=None,
    severity=None,
    risk_score=None,
    target_type=None,
    target_id=None,
    target_label=None,
    ip_address=None,
    session_id=None,
    is_sensitive=False,
    is_suspicious=False,
    created_at=None,
    metadata_json=None,
    event_id=None,
    commit=False,
):
    normalized_user_id = _safe_int(user_id, 0)
    if normalized_user_id <= 0:
        return None

    _ensure_activity_logs_schema_initialized()

    payload = UserEventPayload(
        event_id=safe_activity_str(event_id) or generate_event_id(),
        user_id=normalized_user_id,
        module=normalize_activity_module(module),
        action_type=normalize_activity_action_type(action_type),
        title=safe_activity_str(title)[:200]
        or USER_ACTIVITY_LABELS.get(
            normalize_activity_action_type(action_type), "User activity event"
        ),
        description=safe_activity_str(description),
        status=normalize_activity_status(status),
        severity=normalize_activity_severity(severity),
        risk_score=clamp_risk_score(risk_score),
        target_type=safe_activity_str(target_type)[:80] or None,
        target_id=safe_activity_str(target_id)[:140] or None,
        target_label=safe_activity_str(target_label)[:200] or None,
        ip_address=safe_activity_str(ip_address or _request_ip_address())[:64] or None,
        session_id=safe_activity_str(session_id or _request_session_id())[:140] or None,
        is_sensitive=bool(is_sensitive),
        is_suspicious=bool(is_suspicious),
        created_at=_as_utc_datetime(created_at) if created_at else datetime.now(UTC),
        metadata_json=safe_activity_metadata(metadata_json or {}),
    )
    record = build_user_activity_record(payload)
    db.session.add(record)
    if commit:
        db.session.commit()
    else:
        db.session.flush()
    return record


def _identity_severity_from_risk_level(risk_level: object) -> str:
    normalized = str(risk_level or "Low").strip().lower()
    if normalized == "critical":
        return SEVERITY_CRITICAL
    if normalized == "high":
        return SEVERITY_HIGH
    if normalized == "medium":
        return SEVERITY_MEDIUM
    return SEVERITY_LOW


def _identity_safe_target(*values: object) -> str:
    parts = [safe_activity_str(value) for value in values if safe_activity_str(value)]
    if not parts:
        return "Identity scan"
    text = " / ".join(parts)
    if "@" in text:
        local, _, domain = text.partition("@")
        if local:
            text = f"{local[:2]}***@{domain}"
    return text[:160]


def _identity_sources_checked(result: dict) -> int:
    if not isinstance(result, dict):
        return 0
    return _safe_int(result.get("sources_checked"), 0)


def _identity_log_event(user_id: int, action_type: str, **kwargs):
    try:
        return log_user_event(
            user_id=user_id,
            module=MODULE_IDENTITY,
            action_type=action_type,
            commit=True,
            **kwargs,
        )
    except Exception:
        db.session.rollback()
        logging.exception(
            "Failed to record Identity Leak Monitor activity | user_id=%s | action_type=%s",
            user_id,
            action_type,
        )
        return None


def _identity_log_scan_completed(user_id: int, scan_id: int, result: dict, target: str):
    risk_level = str(result.get("risk_level") or "Low")
    total_findings = _safe_int(result.get("total_findings"), 0)
    _identity_log_event(
        user_id,
        "identity_scan_completed",
        title="Identity scan completed",
        description=f"Identity scan completed with risk level {risk_level}.",
        status=STATUS_SUCCESS,
        severity=_identity_severity_from_risk_level(risk_level),
        risk_score=result.get("risk_score"),
        target_type="identity_scan",
        target_id=str(scan_id),
        target_label=target or f"Scan #{scan_id}",
        is_suspicious=_identity_risk_rank(risk_level) >= _identity_risk_rank("High"),
        metadata_json={
            "scan_id": scan_id,
            "risk_score": _safe_int(result.get("risk_score"), 0),
            "risk_level": risk_level,
            "total_findings": total_findings,
            "sources_checked": _identity_sources_checked(result),
        },
    )


def _identity_log_alerts(user_id: int, alert_id: int | None, scan_id: int, result: dict, findings: list[dict]):
    if not alert_id:
        return
    risk_level = str(result.get("risk_level") or "High")
    category = None
    if findings:
        category = safe_activity_str((findings[0] or {}).get("category")) or None
    severity = (
        SEVERITY_CRITICAL
        if _identity_risk_rank(risk_level) >= _identity_risk_rank("Critical")
        else SEVERITY_HIGH
    )
    _identity_log_event(
        user_id,
        "identity_alert_generated",
        title="Identity alert generated",
        description="Identity Leak Monitor generated an alert for a risky scan.",
        status=STATUS_WARNING,
        severity=severity,
        risk_score=result.get("risk_score"),
        target_type="identity_scan",
        target_id=str(scan_id),
        target_label=f"Scan #{scan_id}",
        is_suspicious=True,
        metadata_json={
            "alert_id": alert_id,
            "scan_id": scan_id,
            "severity": risk_level,
            "category": category,
        },
    )

    if any(str(finding.get("category") or "") == "confirmed_breach" for finding in findings or []):
        matched_field = next(
            (
                safe_activity_str(finding.get("matched_field"))
                for finding in findings
                if str(finding.get("category") or "") == "confirmed_breach"
            ),
            "",
        )
        _identity_log_event(
            user_id,
            "identity_confirmed_breach_detected",
            title="Confirmed identity breach detected",
            description="Known breach metadata matched the monitored identity.",
            status=STATUS_WARNING,
            severity=SEVERITY_CRITICAL,
            risk_score=result.get("risk_score"),
            target_type="identity_scan",
            target_id=str(scan_id),
            target_label=matched_field or f"Scan #{scan_id}",
            is_suspicious=True,
            metadata_json={
                "scan_id": scan_id,
                "category": "confirmed_breach",
                "source": "LeakCheck Public API",
            },
        )


def _record_identity_scan_gamification(user_id: int, scan_id: int, result: dict, target_label: str | None = None) -> None:
    try:
        gamification_service.record_identity_scan_completion(
            int(user_id),
            int(scan_id),
            risk_level=str(result.get("risk_level") or "Low"),
            risk_score=_safe_int(result.get("risk_score"), 0),
            total_findings=_safe_int(result.get("total_findings"), 0),
            target_label=target_label or "",
        )
    except Exception:
        logging.exception(
            "Failed to record Identity gamification scan completion | user_id=%s | scan_id=%s",
            user_id,
            scan_id,
        )


def _record_identity_alert_review_gamification(user_id: int, alert_ids: list[int]) -> None:
    for alert_id in sorted({int(item) for item in alert_ids if int(item) > 0}):
        try:
            gamification_service.process_event(
                int(user_id),
                "alert_reviewed",
                {
                    "job_id": "identity",
                    "alert_id": f"identity-{alert_id}",
                    "source_module": "identity",
                },
            )
        except Exception:
            logging.exception(
                "Failed to record Identity gamification alert review | user_id=%s | alert_id=%s",
                user_id,
                alert_id,
            )


def _identity_row_to_plain_dict(row) -> dict:
    if row is None:
        return {}
    return {key: row[key] for key in row.keys()}


def _identity_safe_preview(value: object, limit: int = 160) -> str:
    text_value = safe_activity_str(value)
    if not text_value:
        return ""
    return text_value[:limit]


def _identity_category_counts(findings: list[dict]) -> dict[str, int]:
    categories = {
        "public_mention": 0,
        "possible_exposure": 0,
        "confirmed_exposure": 0,
        "confirmed_breach": 0,
    }
    for finding in findings:
        category = str(finding.get("category") or "public_mention").strip()
        if category in categories:
            categories[category] += 1
    return categories


def _identity_source_coverage(scan: dict) -> dict[str, object]:
    raw_status = scan.get("source_status") if isinstance(scan, dict) else {}
    if isinstance(raw_status, str):
        try:
            raw_status = json.loads(raw_status or "{}")
        except Exception:
            raw_status = {}
    raw_status = raw_status if isinstance(raw_status, dict) else {}

    def source_state(*keys: str) -> object:
        for key in keys:
            if key in raw_status:
                return raw_status.get(key)
        return "unavailable"

    return {
        "DuckDuckGo": source_state("duckduckgo", "DuckDuckGo"),
        "GitHub": source_state("github", "GitHub"),
        "GitLab": source_state("gitlab", "GitLab"),
        "Stack Exchange": source_state("stackexchange", "Stack Exchange"),
        "LeakCheck": source_state("leakcheck", "LeakCheck"),
    }


def _identity_chatbot_context(user_id: int, scan_id: int | None, include_latest_scan: bool = True) -> dict:
    with get_identity_web_connection() as conn:
        total_scans = int(
            conn.execute("SELECT COUNT(*) AS count FROM identity_scans WHERE user_id=?", (user_id,)).fetchone()["count"]
            or 0
        )
        selected_scan = None
        if scan_id:
            selected_scan = conn.execute(
                "SELECT * FROM identity_scans WHERE id=? AND user_id=?",
                (scan_id, user_id),
            ).fetchone()
        if selected_scan is None and include_latest_scan:
            selected_scan = conn.execute(
                """
                SELECT * FROM identity_scans
                WHERE user_id=?
                ORDER BY datetime(created_at) DESC, id DESC
                LIMIT 1
                """,
                (user_id,),
            ).fetchone()

        scan = _identity_row_to_plain_dict(selected_scan) if selected_scan else {}
        active_scan_id = _safe_int(scan.get("id"), 0) if scan else 0
        finding_rows = []
        if active_scan_id > 0:
            finding_rows = conn.execute(
                """
                SELECT id, scan_id, source, category, severity, title, url, matched_field,
                       found_in_search, found_in_page, risk_keyword_detected, confidence, detected_at
                FROM identity_findings
                WHERE scan_id=? AND user_id=?
                ORDER BY id ASC
                """,
                (active_scan_id, user_id),
            ).fetchall()
        findings = [_identity_row_to_plain_dict(row) for row in finding_rows]

        alert_rows = conn.execute(
            """
            SELECT id, scan_id, title, message, severity, created_at, is_read, email_status
            FROM identity_alerts
            WHERE user_id=?
            ORDER BY datetime(created_at) DESC, id DESC
            LIMIT 5
            """,
            (user_id,),
        ).fetchall()
        alerts = [_identity_row_to_plain_dict(row) for row in alert_rows]

        asset_rows = conn.execute(
            """
            SELECT id, asset_type, asset_value, label, status, last_scan_id, last_risk_score,
                   last_risk_level, last_findings_count, last_checked_at, auto_scan_enabled
            FROM identity_monitored_assets
            WHERE user_id=?
            ORDER BY datetime(created_at) DESC, id DESC
            """,
            (user_id,),
        ).fetchall()
        assets = [_identity_row_to_plain_dict(row) for row in asset_rows]

    category_counts = _identity_category_counts(findings)
    risky_assets = [
        asset
        for asset in assets
        if str(asset.get("status") or "").lower() == "risky"
        or _identity_risk_rank(str(asset.get("last_risk_level") or "Low")) >= _identity_risk_rank("Medium")
    ]
    safe_assets = max(len(assets) - len(risky_assets), 0)
    protection_rate = round((safe_assets / len(assets)) * 100) if assets else None

    return {
        "total_scans": total_scans,
        "scan": scan,
        "findings": findings,
        "alerts": alerts,
        "assets": assets,
        "category_counts": category_counts,
        "source_coverage": _identity_source_coverage(scan) if scan else {},
        "monitored_assets_count": len(assets),
        "risky_assets_count": len(risky_assets),
        "clean_assets_count": safe_assets,
        "protection_rate": protection_rate,
    }


def _empty_identity_chatbot_context() -> dict:
    return {
        "total_scans": 0,
        "scan": {},
        "findings": [],
        "alerts": [],
        "assets": [],
        "category_counts": {
            "public_mention": 0,
            "possible_exposure": 0,
            "confirmed_exposure": 0,
            "confirmed_breach": 0,
        },
        "source_coverage": {},
        "monitored_assets_count": 0,
        "risky_assets_count": 0,
        "clean_assets_count": 0,
        "protection_rate": None,
    }


def _optional_identity_chatbot_user():
    token = _extract_access_token_from_request()
    if not token:
        return None
    try:
        _, user = _decode_auth_token(token)
    except Exception:
        logging.info("Identity chatbot request continued without valid auth token")
        return None
    return user


def _identity_format_sources(source_coverage: dict[str, object]) -> str:
    if not source_coverage:
        return "- Source coverage is unavailable."
    lines = []
    for name, value in source_coverage.items():
        if isinstance(value, dict):
            status = value.get("status") or "unavailable"
            reason = value.get("reason")
            suffix = f" ({reason})" if reason else ""
            lines.append(f"- {name}: **{status}**{suffix}")
        else:
            lines.append(f"- {name}: **{value or 'unavailable'}**")
    return "\n".join(lines)


def _identity_recommendations() -> str:
    return """Recommended next steps:

- Review the affected account or service named by the finding context.
- Change passwords on related services, especially reused passwords.
- Enable MFA on email, banking, social, and admin accounts.
- Remove exposed public data if it is under your control.
- Monitor future Identity Leak Monitor alerts.
- Re-scan monitored assets after remediation.
- Avoid reusing credentials across services."""


