def _identity_mask_asset_value(asset_type: object, value: object) -> str:
    text_value = safe_activity_str(value)
    if not text_value:
        return "Unavailable"
    if "@" in text_value:
        local, _, domain = text_value.partition("@")
        return f"{local[:2]}***@{domain}" if domain else f"{text_value[:2]}***"
    if str(asset_type or "").lower() == "domain":
        return text_value[:80]
    if len(text_value) <= 4:
        return text_value[0] + "***"
    return f"{text_value[:2]}***{text_value[-2:]}"


def _identity_counts_line(categories: dict) -> str:
    return (
        f"- Public Mention: **{_safe_int(categories.get('public_mention'), 0)}**\n"
        f"- Possible Exposure: **{_safe_int(categories.get('possible_exposure'), 0)}**\n"
        f"- Confirmed Exposure: **{_safe_int(categories.get('confirmed_exposure'), 0)}**\n"
        f"- Confirmed Breach: **{_safe_int(categories.get('confirmed_breach'), 0)}**"
    )


def _identity_target_type_and_mask(scan: dict | None) -> tuple[str, str | None]:
    scan = scan if isinstance(scan, dict) else {}
    for key in ("email", "username", "domain"):
        value = safe_activity_str(scan.get(key))
        if not value:
            continue
        if key == "email":
            return "email", mask_email(value)
        if key == "domain":
            return "domain", value[:80]
        return "username", _identity_mask_asset_value("username", value)
    return "unknown", None


def _identity_source_status_value(value: object) -> str:
    raw = value.get("status") if isinstance(value, dict) else value
    status = safe_activity_str(raw, "unavailable").strip().lower().replace("_", " ")
    if status in {"ok", "done", "completed", "success", "available", "checked"}:
        return "checked"
    if status in {"skipped", "skip", "disabled", "not configured", "unavailable"}:
        return "skipped" if status != "unavailable" else "unavailable"
    if any(token in status for token in ("fail", "error", "timeout", "rate limit", "blocked")):
        return "failed"
    return status or "unavailable"


def _identity_source_statuses_from_coverage(source_coverage: dict[str, object] | object) -> dict[str, str]:
    coverage = source_coverage if isinstance(source_coverage, dict) else {}
    statuses: dict[str, str] = {}
    for source in ("DuckDuckGo", "GitHub", "GitLab", "Stack Exchange", "LeakCheck"):
        if source in coverage:
            statuses[source] = _identity_source_status_value(coverage.get(source))
    return statuses


def _identity_safe_severity_counts(findings: list[dict]) -> dict[str, int]:
    counts = {"critical": 0, "high": 0, "medium": 0, "low": 0, "info": 0}
    for finding in findings:
        if not isinstance(finding, dict):
            continue
        severity = safe_activity_str(finding.get("severity"), "info").lower()
        if severity not in counts:
            severity = "info"
        counts[severity] += 1
    return counts


def _identity_safe_category_counts(findings: list[dict], base_counts: dict | None = None) -> dict[str, int]:
    counts = {
        "credential_exposure": _safe_int((base_counts or {}).get("confirmed_breach"), 0),
        "public_exposure": _safe_int((base_counts or {}).get("public_mention"), 0)
        + _safe_int((base_counts or {}).get("confirmed_exposure"), 0),
        "repository_exposure": 0,
        "paste_or_dump_reference": 0,
        "unknown": 0,
    }
    known_categories = {"public_mention", "possible_exposure", "confirmed_exposure", "confirmed_breach"}
    for finding in findings:
        if not isinstance(finding, dict):
            continue
        source = safe_activity_str(finding.get("source")).lower()
        text = " ".join(
            safe_activity_str(finding.get(key)).lower()
            for key in ("source", "category", "title")
        )
        category = safe_activity_str(finding.get("category"))
        if source in {"github", "gitlab"} or "github" in source or "gitlab" in source:
            counts["repository_exposure"] += 1
        if any(token in text for token in ("paste", "dump", "leak", "breach")):
            counts["paste_or_dump_reference"] += 1
        if category and category not in known_categories:
            counts["unknown"] += 1
    return counts


def _identity_top_findings_summary(findings: list[dict], limit: int = 5) -> list[dict[str, object]]:
    safe_items: list[dict[str, object]] = []
    for finding in findings:
        if not isinstance(finding, dict):
            continue
        category = safe_activity_str(finding.get("category"), "unknown")
        severity = safe_activity_str(finding.get("severity"), "unknown").lower()
        source = _chatbot_sanitize_text(finding.get("source")) or "Unknown"
        title = _chatbot_sanitize_text(finding.get("title")) or f"{category.replace('_', ' ').title()} finding"
        confirmed = category in {"confirmed_breach", "confirmed_exposure"}
        safe_items.append(
            {
                "source": source,
                "severity": severity,
                "category": category,
                "confirmed": confirmed,
                "safe_title": title[:160],
                "safe_reason": (
                    "Confirmed exposure/breach category."
                    if confirmed
                    else "Public or possible exposure signal that needs review."
                ),
            }
        )
        if len(safe_items) >= limit:
            break
    return safe_items


def _identity_risky_assets_summary(assets: list[dict], limit: int = 5) -> list[dict[str, object]]:
    items: list[dict[str, object]] = []
    for asset in assets:
        if not isinstance(asset, dict):
            continue
        risk_level = safe_activity_str(asset.get("last_risk_level"), "unknown")
        is_risky = str(asset.get("status") or "").lower() == "risky" or _identity_risk_rank(risk_level) >= _identity_risk_rank("Medium")
        if not is_risky:
            continue
        asset_type = safe_activity_str(asset.get("asset_type"), "unknown")
        items.append(
            {
                "asset": _identity_mask_asset_value(asset_type, asset.get("asset_value")),
                "asset_type": asset_type,
                "risk_level": risk_level,
                "finding_count": _safe_int(asset.get("last_findings_count"), 0),
                "reason": "Stored monitored asset is marked risky or has medium-or-higher last scan risk.",
            }
        )
        if len(items) >= limit:
            break
    return items


def _identity_build_unified_context(context: dict | None) -> dict[str, object]:
    context = context if isinstance(context, dict) else {}
    scan = context.get("scan") if isinstance(context.get("scan"), dict) else {}
    findings = [item for item in (context.get("findings") or []) if isinstance(item, dict)]
    alerts = [item for item in (context.get("alerts") or []) if isinstance(item, dict)]
    assets = [item for item in (context.get("assets") or []) if isinstance(item, dict)]
    has_data = bool(scan and scan.get("id"))
    target_type, masked_target = _identity_target_type_and_mask(scan)
    source_statuses = _identity_source_statuses_from_coverage(context.get("source_coverage"))
    severity_counts = _identity_safe_severity_counts(findings)
    category_counts = _identity_safe_category_counts(findings, context.get("category_counts") if isinstance(context.get("category_counts"), dict) else {})
    confirmed_findings = sum(
        1
        for finding in findings
        if safe_activity_str(finding.get("category")) in {"confirmed_breach", "confirmed_exposure"}
    )

    if not has_data:
        return {
            "has_data": False,
            "latest_scan_id": None,
            "latest_scan_status": "not_scanned",
            "latest_scan_at": None,
            "masked_target": None,
            "target_type": "unknown",
            "message": "Identity Leak has not been assessed yet because no Identity Leak scan has been completed.",
            "summary": {
                "total_scans": _safe_int(context.get("total_scans"), 0),
                "total_findings": 0,
                "confirmed_findings": 0,
                "alert_count": 0,
                "risk_level": "unknown",
                "risk_score": None,
                "protection_rate": context.get("protection_rate"),
            },
            "source_statuses": {},
            "sources_checked": [],
            "severity_counts": {"critical": 0, "high": 0, "medium": 0, "low": 0, "info": 0},
            "category_counts": {
                "credential_exposure": 0,
                "public_exposure": 0,
                "repository_exposure": 0,
                "paste_or_dump_reference": 0,
                "unknown": 0,
            },
            "top_findings_summary": [],
            "risky_assets_summary": _identity_risky_assets_summary(assets),
            "recommendations": ["Run an Identity Leak Monitor scan for an email, username, or domain."],
            "security_score_weight": SECURITY_SCORE_WEIGHT,
            "context_safe": True,
        }

    risk_level = safe_activity_str(scan.get("risk_level"), "unknown").lower()
    return {
        "has_data": True,
        "latest_scan_id": scan.get("id"),
        "latest_scan_status": safe_activity_str(scan.get("status"), "unknown"),
        "latest_scan_at": safe_activity_str(scan.get("completed_at") or scan.get("created_at")),
        "masked_target": masked_target,
        "target_type": target_type,
        "summary": {
            "total_scans": _safe_int(context.get("total_scans"), 0),
            "total_findings": _safe_int(scan.get("total_findings"), len(findings)),
            "confirmed_findings": confirmed_findings,
            "alert_count": len(alerts),
            "risk_level": risk_level,
            "risk_score": scan.get("risk_score") if scan.get("risk_score") is not None else None,
            "protection_rate": context.get("protection_rate"),
        },
        "source_statuses": source_statuses,
        "sources_checked": list(source_statuses.keys()),
        "severity_counts": severity_counts,
        "category_counts": category_counts,
        "top_findings_summary": _identity_top_findings_summary(findings),
        "risky_assets_summary": _identity_risky_assets_summary(assets),
        "recommendations": [
            "Review confirmed findings and verify affected accounts.",
            "Change passwords for affected accounts if exposure is confirmed.",
            "Use strong unique passwords and enable MFA.",
            "Review suspicious login activity.",
            "Avoid password reuse and re-run the scan after mitigation.",
        ],
        "security_score_weight": SECURITY_SCORE_WEIGHT,
        "scope_limit": "Current Identity Leak scanning uses public OSINT-like sources unless dark web integration is explicitly implemented.",
        "credential_leak_caution": "A finding does not automatically prove password exposure unless credential exposure or confirmed breach is explicitly confirmed.",
        "context_safe": True,
    }


def _identity_chatbot_answer(message: str, context: dict) -> str:
    intent = _identity_chatbot_intent(message)
    scan = context.get("scan") or {}
    findings = context.get("findings") or []
    categories = context.get("category_counts") or {}
    alerts = context.get("alerts") or []
    assets = context.get("assets") or []

    generic_answers = {
        "public_mention_definition": "Public Mention means your email, username, or domain appeared in a public source, but without confirmed leak or breach context. It is usually low risk unless combined with exposure keywords or confirmed breach data.",
        "possible_exposure_definition": "Possible Exposure means your identity appeared near suspicious keywords such as leak, breach, dump, exposed, database, credentials, token, or secret. It needs review but is not always a confirmed breach.",
        "confirmed_breach_definition": "Confirmed Breach means a breach metadata source, such as LeakCheck Public API, matched the email or username. The system stores only safe metadata summaries and does not store passwords or raw leaked data.",
        "scraping_vs_api": "Web scraping searches public pages and parses visible HTML text. API sources return structured results from official or public APIs. In this project, DuckDuckGo/public pages provide web-search context, while GitHub, GitLab, Stack Exchange, and LeakCheck provide structured source results. Both are combined to improve coverage.",
        "leakcheck_skipped": "LeakCheck Public API only supports email and username checks in this implementation. If the scan only contains a domain, LeakCheck is skipped because domains are not sent to LeakCheck Public API. If the stored source status says rate limit, timeout, or network error, treat it as unavailable and try again later.",
        "found_in_page_explanation": "Found In Page = No means the target may have appeared in the search result title/snippet or source metadata, but the scraper could not confirm it inside the page body. This can happen if the page blocks scraping, uses JavaScript, redirects, times out, or does not contain the target in visible HTML. These results have lower confidence.",
        "project_overview": """Identity Leak Monitor is the project module that checks whether a user's email, username, or domain appears in public exposure signals.

What we built:

- Manual identity scans for email, username, and domain targets.
- Scan My Identity and Scan All Assets workflows.
- Monitored assets add/delete support.
- Stored scan history with findings and source status.
- Finding categories: Public Mention, Possible Exposure, Confirmed Exposure, and Confirmed Breach.
- Risk score and risk level calculation.
- Identity alerts for risky scans.
- PDF report export.
- Notification Center, Monthly Reports, and User Activity Logs integration.
- This chatbot mode, which explains both stored scan results and the Identity module itself.""",
        "project_workflow": """Identity Leak Monitor workflow:

1. The user scans an email, username, or domain, or starts Scan All Assets.
2. The backend checks public/search sources and supported APIs.
3. Results are normalized into safe finding summaries.
4. Each finding is categorized as Public Mention, Possible Exposure, Confirmed Exposure, or Confirmed Breach.
5. The scan receives a risk score and risk level.
6. Risky results can generate Identity alerts and Notification Center entries.
7. The scan is saved so it can be reopened, exported as PDF, included in monthly reports, and shown in User Activity Logs.""",
        "project_risk_logic": """The Identity risk score is based on the type and strength of the stored findings.

General logic:

- Public Mention is usually low risk because it only confirms public appearance.
- Possible Exposure increases risk when the identity appears near suspicious keywords.
- Confirmed Exposure is stronger because exposure context was confirmed in page content.
- Confirmed Breach is the highest-signal category because breach metadata matched the identity.
- High or Critical alerts are generated when the score and categories indicate risky exposure.

Important: the system should only call something a confirmed breach when the finding category is **confirmed_breach**.""",
        "project_activity_logging": """Identity activity is connected to the unified User Activity Logs stream.

Tracked Identity actions include:

- Manual scan started and completed.
- Full asset scan started and completed.
- Identity alert generated.
- Confirmed breach detected.
- Monitored asset added or deleted.
- Saved scan viewed.
- PDF report downloaded.
- Identity chatbot question asked.

The logs are user-scoped and store safe summaries only, such as scan id, risk level, risk score, finding counts, and source names.""",
        "project_integrations": """Identity Leak Monitor is integrated with the wider Sentinel AI project:

- Notification Center shows high-signal Identity exposure alerts.
- Monthly Reports include Identity scan and exposure summaries.
- PDF export produces a scan-level Identity report.
- User Activity Logs record Identity actions beside Auth, PCAP, and Vault activity.
- The chatbot explains Identity results and module behavior from safe stored data.
- Identity Leak contributes 25% to the personal Security Score.
- PCAP Analyzer remains separate and is not included in Security Score.""",
        "project_data_model": """The Identity module uses stored data from these main tables:

- identity_scans: one row per scan, including target summary, risk score, risk level, source status, and totals.
- identity_findings: normalized findings linked to a scan, with category, source, severity, and safe evidence summary.
- identity_alerts: high-signal alerts generated from risky scans.
- identity_monitored_assets: saved emails, usernames, and domains that can be scanned repeatedly.

The chatbot reads these tables when authenticated, but it avoids exposing raw leaked data, passwords, tokens, or API keys.""",
    }

    if intent in generic_answers and not scan:
        return generic_answers[intent]

    no_scan_message = (
        "Identity Leak has not been assessed yet because you have not completed an Identity Leak scan. "
        "Run your first scan to check whether your email, username, or domain appears in public exposure sources."
    )

    if not scan and intent in {"latest_scan_summary", "identity_security_score", "identity_risks_found", "explain_findings", "risky_assets_summary"}:
        if intent == "identity_security_score":
            return (
                "Identity Leak has not been assessed yet because you have not completed an Identity Leak scan. "
                "When assessed, Identity Leak contributes 25% of the total Security Score. The other components are "
                "Password Checker 25%, File Vault 25%, and Phishing Scanner 25%. PCAP Analyzer is separate and is not "
                "included in Security Score."
            )
        if intent == "risky_assets_summary":
            return "The latest Identity context does not include risky asset-level details yet. Add monitored assets and run an Identity Leak scan to build this summary."
        return no_scan_message

    if not scan:
        prefix = "I do not have scan data yet, but here is the general guidance:\n\n"
        if intent == "explain_protection_rate":
            return (
                "**Protection Rate** is a percentage-style indicator for monitored Identity asset health.\n\n"
                "In this implementation, when monitored assets exist, it is calculated as:\n\n"
                "Protection Rate = Low-risk monitored assets / Total monitored assets x 100\n\n"
                "Current value: **Unavailable** because no Identity Leak scan has been completed yet or no monitored assets are available."
            )
        if intent == "explain_high_risk":
            return (
                "I cannot explain a high Identity risk level without scan findings. "
                "Identity Leak has not been assessed yet because you have not completed an Identity Leak scan."
            )
        if intent == "dark_web_scope":
            return (
                "Identity Leak has not been assessed yet because you have not completed an Identity Leak scan.\n\n"
                "Current Identity Leak scanning uses public OSINT-like sources unless dark web integration is explicitly implemented. "
                "It should not be treated as dark web coverage."
            )
        if intent == "password_leak_meaning":
            return (
                "Identity Leak has not been assessed yet because you have not completed an Identity Leak scan.\n\n"
                "Even when a finding exists, it does not automatically mean your password was leaked. A finding may only show that "
                "an email, username, or domain appeared in public exposure-related sources unless credential exposure is explicitly confirmed."
            )
        if intent in generic_answers:
            return prefix + generic_answers[intent]
        if intent in {"recommended_actions", "reduce_identity_risk"}:
            return prefix + """- Change exposed account passwords if you later find confirmed exposure.
- Enable MFA on important accounts.
- Avoid password reuse.
- Remove unnecessary public mentions if possible.
- Review public GitHub/GitLab repositories for exposed identifiers.
- Keep monitored assets updated.
- Run Scan All Assets regularly."""
        return no_scan_message

    scan_id = scan.get("id")
    risk_score = _safe_int(scan.get("risk_score"), 0)
    risk_level = str(scan.get("risk_level") or "Low")
    total_findings = _safe_int(scan.get("total_findings"), len(findings))
    confirmed_breaches = _safe_int(categories.get("confirmed_breach"), 0)
    confirmed_exposures = _safe_int(categories.get("confirmed_exposure"), 0)
    possible_exposures = _safe_int(categories.get("possible_exposure"), 0)
    public_mentions = _safe_int(categories.get("public_mention"), 0)

    high_critical_findings = sum(
        1
        for finding in findings
        if str(finding.get("severity") or "").lower() in {"high", "critical"}
    )
    risk_keyword_count = sum(1 for finding in findings if finding.get("risk_keyword_detected"))
    leakcheck_findings = [
        finding
        for finding in findings
        if "leakcheck" in str(finding.get("source") or "").lower()
    ]
    source_coverage = context.get("source_coverage") or {}
    checked_sources = scan.get("sources_checked") or "Unavailable"
    recommendation = safe_activity_str(scan.get("recommendation")) or "Review the results and keep monitoring your identity exposure."

    target_type, masked_target = _identity_target_type_and_mask(scan)
    source_statuses = _identity_source_statuses_from_coverage(context.get("source_coverage") or {})
    checked_source_names = ", ".join(source_statuses.keys()) if source_statuses else str(checked_sources)

    summary = f"""Identity scan **#{scan_id}** summary:

- Status: **{safe_activity_str(scan.get('status'), 'unknown')}**
- Target: **{masked_target or 'Unavailable'}** ({target_type})
- Risk score: **{risk_score}/100**
- Risk level: **{risk_level}**
- Total findings: **{total_findings}**
- Confirmed findings: **{confirmed_breaches + confirmed_exposures}**
- Alert count: **{len(alerts)}**
- Main categories:
{_identity_counts_line(categories)}
- Sources checked: **{checked_source_names}**

Short recommendation:

{recommendation}"""

    if total_findings <= 0:
        no_findings_summary = (
            "No confirmed Identity Leak findings were found in the latest scan based on the checked sources. "
            "This does not guarantee that no leaks exist anywhere, but no exposure was detected in the available sources."
        )
        if intent in {"latest_scan_summary", "explain_findings"}:
            return no_findings_summary

    if intent == "latest_scan_summary":
        return summary

    if intent == "identity_risks_found":
        if total_findings <= 0:
            return (
                "No confirmed Identity Leak findings were found in the latest scan based on the available sources. "
                "This does not guarantee that no leaks exist anywhere, but no exposure was detected in the checked sources."
            )
        severity_counts = _identity_safe_severity_counts(findings)
        safe_categories = _identity_safe_category_counts(findings, categories)
        top_items = _identity_top_findings_summary(findings, 5)
        top_lines = [
            f"- {item['source']}: **{item['severity']}**, {str(item['category']).replace('_', ' ')}"
            for item in top_items
        ] or ["- No safe finding-level summary is available."]
        return "\n".join(
            [
                "**Identity risks found**",
                "",
                f"- Risk level: **{risk_level}**",
                f"- Total findings: **{total_findings}**",
                f"- Confirmed findings: **{confirmed_breaches + confirmed_exposures}**",
                f"- Alert count: **{len(alerts)}**",
                "",
                "Severity counts:",
                *[f"- {name.title()}: **{count}**" for name, count in severity_counts.items()],
                "",
                "Category summary:",
                *[f"- {name.replace('_', ' ').title()}: **{count}**" for name, count in safe_categories.items()],
                "",
                "Top safe finding summaries:",
                *top_lines,
                "",
                "No raw leaked data, credentials, passwords, hashes, or scraped page content is shown here.",
            ]
        )

    if intent in generic_answers and intent not in {"leakcheck_skipped", "found_in_page_explanation"}:
        return generic_answers[intent]

    if intent == "sources_checked":
        return f"""Source coverage for scan **#{scan_id}**:

{_identity_format_sources(context.get('source_coverage') or {})}

Source meanings:

- DuckDuckGo: public web search and public page scraping
- GitHub: public repository/code exposure search
- GitLab: public project/code exposure search
- Stack Exchange: public technical/community mentions
- LeakCheck: free breach metadata check for email and username only

Dark web note: current Identity Leak scanning uses public OSINT-like sources unless dark web integration is explicitly implemented."""

    if intent == "dark_web_scope":
        return (
            "Current Identity Leak scan uses public OSINT-like sources unless dark web integration is explicitly implemented. "
            "It should not claim dark web coverage if the backend does not implement it. The checked source statuses in this scan are:\n\n"
            f"{_identity_format_sources(context.get('source_coverage') or {})}"
        )

    if intent == "password_leak_meaning":
        if confirmed_breaches:
            return (
                f"Not necessarily. This scan has **{confirmed_breaches} confirmed breach** finding(s), which means breach metadata matched "
                "the identifier, but the chatbot does not expose raw credentials or passwords. Change passwords on affected accounts, avoid reuse, "
                "and enable MFA."
            )
        return (
            "Not necessarily. A finding may indicate that your email, username, or domain appeared in public exposure-related sources. "
            "It does not automatically prove that your password was exposed unless the finding explicitly confirms credential leakage."
        )

    if intent == "identity_security_score":
        return (
            "Identity Leak contributes **25%** of the total Security Score. The full score is calculated from four equal components: "
            "Password Checker 25%, File Vault 25%, Phishing Scanner 25%, and Identity Leak 25%.\n\n"
            f"Your latest Identity Leak risk is **{risk_level}** with **{total_findings}** finding(s). The backend maps Identity Leak risk into "
            "the Identity component score; missing Identity scans stay **Not assessed yet** and are never replaced with a fake 50%. "
            "PCAP Analyzer is separate and is not included in Security Score."
        )

    if intent == "leakcheck_skipped":
        leakcheck_status = source_coverage.get("LeakCheck")
        extra = ""
        if isinstance(leakcheck_status, dict):
            status = leakcheck_status.get("status") or "unavailable"
            reason = leakcheck_status.get("reason")
            extra = f"\n\nStored LeakCheck status for this scan: **{status}**{f' - {reason}' if reason else ''}"
        elif leakcheck_status:
            extra = f"\n\nStored LeakCheck status for this scan: **{leakcheck_status}**"
        return generic_answers["leakcheck_skipped"] + extra

    if intent == "found_in_page_explanation":
        found_yes = sum(1 for finding in findings if finding.get("found_in_page"))
        found_no = max(len(findings) - found_yes, 0)
        return f"""{generic_answers["found_in_page_explanation"]}

For scan **#{scan_id}**:

- Found in page: **{found_yes}**
- Found in page = No: **{found_no}**"""

    if intent == "explain_protection_rate":
        rate = context.get("protection_rate")
        rate_text = f"{rate}%" if rate is not None else "Unavailable"
        return f"""**Protection Rate** summarizes monitored asset health.

Protection Rate = Low-risk monitored assets / Total monitored assets x 100

Current value: **{rate_text}**

- Safe/low-risk assets: **{context.get('clean_assets_count', 0)}**
- Risky assets: **{context.get('risky_assets_count', 0)}**
- Total monitored assets: **{context.get('monitored_assets_count', 0)}**

If you have no monitored assets, the current percentage is unavailable."""

    if intent == "risky_assets_summary":
        if not assets:
            return "No monitored Identity assets are stored for your account yet. Add an email, username, or domain to monitor asset safety."
        risky_assets = [
            asset
            for asset in assets
            if str(asset.get("status") or "").lower() == "risky"
            or _identity_risk_rank(str(asset.get("last_risk_level") or "Low")) >= _identity_risk_rank("Medium")
        ]
        risky_lines = []
        for asset in risky_assets[:5]:
            label = safe_activity_str(asset.get("label")) or _identity_mask_asset_value(asset.get("asset_type"), asset.get("asset_value"))
            masked = _identity_mask_asset_value(asset.get("asset_type"), asset.get("asset_value"))
            checked = safe_activity_str(asset.get("last_checked_at")) or "Unavailable"
            risky_lines.append(
                f"- {safe_activity_str(asset.get('asset_type'), 'asset')}: **{label}** ({masked}) - last risk **{asset.get('last_risk_level') or 'Unavailable'}**, checked **{checked}**"
            )
        risky_block = "\n".join(risky_lines) if risky_lines else "- No risky monitored assets are currently stored."
        return f"""Monitored asset summary:

- Total monitored assets: **{context.get('monitored_assets_count', 0)}**
- Risky assets: **{context.get('risky_assets_count', 0)}**
- Clean/low-risk assets: **{context.get('clean_assets_count', 0)}**

Risky assets:

{risky_block}"""

    if intent in {"recommended_actions", "reduce_identity_risk"}:
        return """Recommended next steps:

- Review findings and evidence links.
- Change passwords on affected services if a confirmed breach exists.
- Enable multi-factor authentication.
- Avoid password reuse.
- Remove unnecessary public exposure if possible.
- Review GitHub/GitLab repositories for exposed identifiers.
- Keep monitored assets updated.
- Re-scan monitored assets.
- Run Scan All Assets regularly.
- Watch future alerts."""

    if intent == "explain_high_risk":
        if risk_level.lower() == "low":
            return "Your latest scan is currently Low risk. No confirmed breach or strong exposure context was detected."

        reasons = []
        if confirmed_breaches:
            reasons.append(f"- **{confirmed_breaches} confirmed breach** finding(s) were found.")
        if confirmed_exposures:
            reasons.append(f"- **{confirmed_exposures} confirmed exposure** finding(s) were found.")
        if possible_exposures:
            reasons.append(f"- **{possible_exposures} possible exposure** finding(s) need review.")
        if high_critical_findings:
            reasons.append(f"- **{high_critical_findings} high/critical** finding(s) are present.")
        if leakcheck_findings:
            reasons.append("- LeakCheck returned structured breach metadata for at least one finding.")
        if risk_keyword_count:
            reasons.append(f"- **{risk_keyword_count}** finding(s) included exposure-related risk keywords.")
        if public_mentions and not any([confirmed_breaches, confirmed_exposures, possible_exposures]):
            reasons.append(f"- **{public_mentions} public mention** finding(s) were found, but public mentions alone are not leaks.")
        if not reasons:
            reasons.append("- The stored scan does not include detailed finding categories for this risk level.")
        return f"""Your risk level is **{risk_level}** with score **{risk_score}/100**.

Why:

{chr(10).join(reasons)}

Important: I only treat a finding as a confirmed breach when its stored category is **confirmed_breach**."""

    if intent == "alerts":
        if not alerts:
            return "No Identity alerts are stored for your account."
        alert_lines = [
            f"- Alert #{alert.get('id')}: **{alert.get('severity')}** for scan #{alert.get('scan_id')} - {alert.get('title')}"
            for alert in alerts[:5]
        ]
        return "Latest Identity alerts:\n\n" + "\n".join(alert_lines)

    if intent == "explain_findings":
        return f"""Finding categories:

- Public Mention: the identity appeared in a public source, but no leak context was confirmed.
- Possible Exposure: the identity appeared near suspicious exposure-related keywords.
- Confirmed Exposure: the identity was found in page content with exposure context.
- Confirmed Breach: a breach metadata source matched the identity.

For this scan, the category breakdown is:

{_identity_counts_line(categories)}"""

    return summary


def _optional_pcap_chatbot_user():
    try:
        return get_current_user()
    except Exception:
        logging.info("PCAP chatbot request continued without valid auth token")
        return None


def _pcap_empty_chatbot_context() -> dict:
    return {
        "job": None,
        "report": None,
        "summary": {},
        "threat_items": [],
        "attack_counts": {},
        "severity_counts": {},
        "top_ips": [],
        "protocols": [],
        "ports": [],
        "recommendations": [],
        "total_jobs": 0,
    }


def _pcap_job_sort_value(job_state) -> str:
    return (
        safe_activity_str(getattr(job_state, "finished_at", None))
        or safe_activity_str(getattr(job_state, "started_at", None))
        or safe_activity_str(getattr(job_state, "created_at", None))
    )


def _pcap_job_upload_name(job_state) -> str:
    upload_path = safe_activity_str(getattr(job_state, "upload_path", None))
    if not upload_path:
        return "PCAP file"
    try:
        return Path(upload_path).name
    except Exception:
        return upload_path[:120]


def _pcap_job_owned_by_user(job_state, user) -> bool:
    if user is None:
        return False
    owner_scope = _build_authenticated_user_scope(user)
    return (
        getattr(job_state, "owner_user_id", None) == getattr(user, "id", None)
        and safe_activity_str(getattr(job_state, "owner_user_scope", None)) == owner_scope
    )


def _pcap_chatbot_job_for_user(user, analysis_id: str | None, include_latest_analysis: bool):
    if user is None:
        return None

    normalized_analysis_id = safe_activity_str(analysis_id)
    if normalized_analysis_id:
        job_state = jobs.get(normalized_analysis_id)
        if job_state is not None and _pcap_job_owned_by_user(job_state, user):
            return job_state
        return None

    if not include_latest_analysis:
        return None

    owned_jobs = [
        job_state
        for job_state in jobs.list_recent(limit=0)
        if _pcap_job_owned_by_user(job_state, user)
    ]
    completed_with_report = [
        job_state
        for job_state in owned_jobs
        if safe_activity_str(getattr(job_state, "status", None)).lower() == "done"
        and _load_report_payload_for_job(job_state)
    ]
    if completed_with_report:
        return sorted(completed_with_report, key=_pcap_job_sort_value, reverse=True)[0]
    if owned_jobs:
        return sorted(owned_jobs, key=_pcap_job_sort_value, reverse=True)[0]
    return None


def _pcap_raw_item_attack_name(item: dict) -> str:
    return safe_activity_str(
        item.get("label")
        or item.get("attack_type")
        or item.get("ml_label")
        or item.get("top_attack")
        or item.get("name"),
        "Network anomaly",
    )


def _pcap_raw_item_severity(item: dict) -> str:
    return _normalize_dashboard_alert_severity(
        item.get("severity") or item.get("verdict") or item.get("risk_level")
    )


def _pcap_raw_item_confidence(item: dict) -> float:
    return max(
        0.0,
        min(
            1.0,
            _safe_float(
                item.get("threat_confidence"),
                _safe_float(item.get("confidence"), _safe_float(item.get("ml_confidence"), 0.0)),
            ),
        ),
    )


def _pcap_collect_threat_items(report: dict) -> list[dict[str, object]]:
    if not isinstance(report, dict):
        return []

    raw_items: list[dict] = []
    for key in ("alerts", "clusters"):
        values = report.get(key)
        if isinstance(values, list):
            raw_items.extend(item for item in values if isinstance(item, dict))

    if not raw_items:
        timeline = report.get("timeline") if isinstance(report.get("timeline"), list) else []
        for item in timeline[:2000]:
            if not isinstance(item, dict):
                continue
            verdict = safe_activity_str(item.get("verdict")).lower()
            confidence = _pcap_raw_item_confidence(item)
            ml_label = safe_activity_str(item.get("ml_label")).lower()
            if verdict not in {"", "normal", "benign", "safe"} or (
                ml_label not in {"", "benign", "normal"} and confidence > 0
            ):
                raw_items.append(item)

    normalized: list[dict[str, object]] = []
    for item in raw_items[:80]:
        dst_port = _safe_int(item.get("dst_port") or item.get("destination_port"), 0)
        normalized.append(
            {
                "name": _pcap_raw_item_attack_name(item),
                "severity": _pcap_raw_item_severity(item),
                "src_ip": safe_activity_str(item.get("source_ip") or item.get("src_ip")),
                "dst_ip": safe_activity_str(item.get("dest_ip") or item.get("dst_ip")),
                "protocol": safe_activity_str(
                    item.get("protocol")
                    or item.get("zeek_proto")
                    or item.get("proto")
                    or item.get("service")
                    or item.get("zeek_service")
                ),
                "dst_port": dst_port if dst_port > 0 else None,
                "confidence": _pcap_raw_item_confidence(item),
                "reason": safe_activity_str(item.get("reason") or item.get("explanation")),
                "count": _safe_int(item.get("count_flows") or item.get("count"), 1),
            }
        )
    return normalized


def _pcap_chatbot_context(user, analysis_id: str | None, include_latest_analysis: bool = True) -> dict:
    context = _pcap_empty_chatbot_context()
    if user is None:
        return context

    owned_jobs = [
        job_state
        for job_state in jobs.list_recent(limit=0)
        if _pcap_job_owned_by_user(job_state, user)
    ]
    context["total_jobs"] = len(owned_jobs)

    job_state = _pcap_chatbot_job_for_user(user, analysis_id, include_latest_analysis)
    if job_state is None:
        return context

    report = _load_report_payload_for_job(job_state) or {}
    summary = report.get("summary") if isinstance(report.get("summary"), dict) else {}
    threat_items = _pcap_collect_threat_items(report)

    attack_counter = Counter()
    severity_counter = Counter()
    ip_counter = Counter()
    protocol_counter = Counter()
    port_counter = Counter()
    for item in threat_items:
        attack_counter[safe_activity_str(item.get("name"), "Network anomaly")] += _safe_int(item.get("count"), 1)
        severity_counter[safe_activity_str(item.get("severity"), "info").lower()] += 1
        for key in ("src_ip", "dst_ip"):
            value = safe_activity_str(item.get(key))
            if value:
                ip_counter[value] += 1
        protocol = safe_activity_str(item.get("protocol")).upper()
        if protocol:
            protocol_counter[protocol] += 1
        dst_port = item.get("dst_port")
        if dst_port:
            port_counter[str(dst_port)] += 1

    report_severity_counts = (
        summary.get("severity_counts") if isinstance(summary.get("severity_counts"), dict) else {}
    )
    severity_counts = {
        "low": _safe_int(report_severity_counts.get("low"), severity_counter.get("low", 0)),
        "medium": _safe_int(report_severity_counts.get("medium"), severity_counter.get("medium", 0)),
        "high": _safe_int(report_severity_counts.get("high"), severity_counter.get("high", 0)),
        "critical": _safe_int(report_severity_counts.get("critical"), severity_counter.get("critical", 0)),
    }

    risk_per_ip = report.get("risk_per_ip") if isinstance(report.get("risk_per_ip"), list) else []
    top_ips: list[dict[str, object]] = []
    for item in risk_per_ip[:5]:
        if not isinstance(item, dict):
            continue
        ip_value = safe_activity_str(item.get("ip") or item.get("src_ip") or item.get("dst_ip"))
        if ip_value:
            top_ips.append(
                {
                    "ip": ip_value,
                    "role": safe_activity_str(item.get("role"), "host"),
                    "attack": safe_activity_str(item.get("top_attack") or item.get("attack_type")),
                    "risk": item.get("risk_score") or item.get("score") or item.get("risk"),
                }
            )
    if not top_ips:
        top_ips = [{"ip": ip, "count": count} for ip, count in ip_counter.most_common(5)]

    recommendations = report.get("recommendations")
    if not isinstance(recommendations, list):
        recommendations = []

    context.update(
        {
            "job": job_state,
            "report": report,
            "summary": summary,
            "threat_items": threat_items,
            "attack_counts": dict(attack_counter.most_common(8)),
            "severity_counts": severity_counts,
            "top_ips": top_ips,
            "protocols": [name for name, _count in protocol_counter.most_common(6)],
            "ports": [name for name, _count in port_counter.most_common(8)],
            "recommendations": recommendations[:6],
        }
    )
    return context


