    lower = message.lower().strip()
    if any(phrase in lower for phrase in ("لخص آخر تحليل pcap", "لخص اخر تحليل pcap", "summarize my latest pcap analysis")):
        return "latest_pcap_summary"
    if any(phrase in lower for phrase in ("إيه التهديدات", "ايه التهديدات", "التهديدات اللي ظهرت", "what threats were detected")):
        return "detected_threats"
    if any(phrase in lower for phrase in ("ليه ملف pcap ده خطر", "ليه pcap ده خطر", "why is this pcap risky")):
        return "explain_pcap_risk"
