def _list_admin_password_check_threats(
    user_by_id: dict[int, "User"],
    represented_password_check_ids: set[int],
    *,
    limit: int = 60,
) -> list[dict[str, object]]:
    try:
        records = (
            PasswordCheck.query.order_by(PasswordCheck.created_at.desc(), PasswordCheck.id.desc())
            .limit(max(1, min(int(limit or 60), 120)))
            .all()
        )
    except Exception:
        logging.exception("Failed to read Password Checker findings for admin threat feed")
        return []

    threats: list[dict[str, object]] = []
    for record in records:
        record_id = _safe_int(getattr(record, "id", None), 0)
        if record_id in represented_password_check_ids:
            continue
        risk = _password_admin_report_risk(record)
        breached = _password_admin_record_breached(record)
        strength = _password_admin_record_strength(record)
        if not (breached or risk in {"critical", "high"} or strength in {"very_weak", "weak"}):
            continue
        severity = "Critical" if breached else "High" if risk in {"critical", "high"} or strength == "very_weak" else "Medium"
        user_id = _safe_int(getattr(record, "user_id", None), 0)
        user = user_by_id.get(user_id)
        timestamp_dt = _as_utc_datetime(getattr(record, "created_at", None))
        timestamp = timestamp_dt.isoformat() if timestamp_dt else None
        masked_identifier = _mask_admin_identifier(getattr(user, "email", None))
        title = "Breached password finding detected" if breached else "Password hygiene risk detected"
        description = "Password Checker detected a breached or risky password result. Raw passwords and hashes are hidden."
        confidence = 92 if breached else 84 if severity == "High" else 68
        evidence = _sanitize_for_json(
            {
                "Password Check ID": record_id,
                "Risk Level": risk,
                "Strength Label": strength,
                "Breached": bool(breached),
                "Timestamp": timestamp,
            }
        )
        threats.append(
            {
                "id": f"password-check-{record_id}",
                "title": title,
                "description": description,
                "module": "Password Checker",
                "source_module": "Password Checker",
                "masked_user_identifier": masked_identifier,
                "affected_user_name": "Masked user",
                "affected_user_email": masked_identifier,
                "severity": severity,
                "status": _normalize_admin_threat_status(None, severity=severity, confidence=confidence),
                "confidence": confidence,
                "risk_score": confidence,
                "timestamp": timestamp,
                "summary": description,
                "allowed_actions": ["view_evidence", "acknowledge", "mark_false_positive"],
                "evidence_available": True,
                "threat_detected": severity in {"Critical", "High"},
                "linked_accounts_count": 0,
                "ip_address": None,
                "device_context": "Password Checker",
                "investigation_summary": description,
                "evidence": evidence,
                "audit_preview": [
                    {
                        "label": "Password finding recorded",
                        "actor": "Password Checker",
                        "createdAt": timestamp,
                    }
                ],
            }
        )
    return threats


def _build_demo_shared_admin_threats(
    users: list["User"], linked_accounts_by_user_id: dict[int, int]
) -> list[dict[str, object]]:
    module_cycle = [
        "Phishing Scanner",
        "Password Checker",
        "File Vault",
        "Identity Leak Monitor",
    ]
    title_map = {
        "Phishing Scanner": ("Phishing URL Detected", "Suspicious domain matched phishing heuristics during a user-facing scan."),
        "Password Checker": ("Password Leak Match", "A password or credential overlap was detected in breach monitoring data."),
        "File Vault": ("Malicious File Uploaded", "A protected file upload triggered malware signature and policy review signals."),
        "Identity Leak Monitor": ("Credentials Exposure", "Identity monitoring found a likely credential exposure associated with this account."),
    }
    now = datetime.now(UTC)
    alerts: list[dict[str, object]] = []
    for index, user in enumerate(users[:8]):
        module_name = module_cycle[index % len(module_cycle)]
        title, description = title_map[module_name]
        severity = "Critical" if index == 0 else "High" if index < 3 else "Medium" if index < 6 else "Low"
        confidence = 96 if index == 0 else 88 if index < 3 else 72 if index < 6 else 58
        created_at = (now - timedelta(hours=(index * 3) + 1)).isoformat().replace("+00:00", "Z")
        alerts.append(
            {
                "id": f"shared-demo-{index + 1}",
                "title": title,
                "description": description,
                "module": module_name,
                "source_module": module_name,
                "masked_user_identifier": _mask_admin_identifier(getattr(user, "email", None)),
                "affected_user_name": "Masked user",
                "affected_user_email": _mask_admin_identifier(getattr(user, "email", None)),
                "severity": severity,
                "status": "Acknowledged" if index % 3 == 0 else "False Positive" if index % 4 == 0 else "New",
                "confidence": confidence,
                "risk_score": confidence,
                "timestamp": created_at,
                "summary": description,
                "allowed_actions": _admin_alert_allowed_actions(module_name, severity, {}),
                "evidence_available": True,
                "threat_detected": severity in {"Critical", "High"},
                "linked_accounts_count": 0,
                "ip_address": f"10.24.{index + 10}.{index + 21}",
                "device_context": "Browser session telemetry" if module_name != "File Vault" else "Protected upload workflow",
                "investigation_summary": description,
                "evidence": {
                    "Matched Rules Count": 2 + index,
                    "Suspicious Indicators": 3 + index,
                    "Evidence Reference": f"sentinel-{module_name.lower().replace(' ', '-')}-{index + 1}",
                },
                "audit_preview": [
                    {"label": "Alert created", "actor": module_name, "createdAt": created_at},
                    {"label": "Assigned to admin", "actor": "Sentinel AI", "createdAt": created_at},
                ],
            }
        )
    return alerts


def _build_admin_threat_feed() -> list[dict[str, object]]:
    users = User.query.order_by(User.created_at.desc(), User.id.desc()).all()
    user_by_id = {int(user.id): user for user in users}
    linked_accounts_by_user_id = {
        int(user_id): int(count)
        for user_id, count in db.session.query(
            LinkedAccount.user_id, func.count(LinkedAccount.id)
        ).group_by(LinkedAccount.user_id)
    }

    alerts: list[dict[str, object]] = []
    represented_password_check_ids: set[int] = set()

    notifications = (
        UserNotification.query.order_by(UserNotification.created_at.desc(), UserNotification.id.desc())
        .limit(60)
        .all()
    )
    for notification in notifications:
        metadata = _notification_metadata_from_json(getattr(notification, "metadata_json", None))
        if not _is_notification_threat_candidate(notification, metadata):
            continue
        serialized_alert = _serialize_admin_notification_threat(
            notification, user_by_id, linked_accounts_by_user_id
        )
        notification_password_check_id = _safe_int(
            metadata.get("password_check_id") or metadata.get("source_id"), 0
        )
        if (
            notification_password_check_id > 0
            and _admin_threat_has_password_signal(
                getattr(notification, "type", None),
                getattr(notification, "title", None),
                getattr(notification, "body", None),
                metadata.get("module"),
                metadata.get("source_module"),
                metadata.get("event_type"),
            )
        ):
            represented_password_check_ids.add(notification_password_check_id)
        alerts.append(serialized_alert)

    alerts.extend(_list_admin_identity_threats(user_by_id, linked_accounts_by_user_id))
    alerts.extend(_list_admin_identity_finding_threats(user_by_id))

    pcap_alerts = (
        PcapAlertRecord.query.order_by(PcapAlertRecord.event_at.desc(), PcapAlertRecord.created_at.desc(), PcapAlertRecord.id.desc())
        .limit(60)
        .all()
    )
    for alert in pcap_alerts:
        metadata = _pcap_alert_metadata_from_json(getattr(alert, "metadata_json", None))
        password_check_id = _safe_int(metadata.get("password_check_id") or metadata.get("source_id"), 0)
        if (
            password_check_id > 0
            and _admin_threat_has_password_signal(
                getattr(alert, "source_type", None),
                getattr(alert, "job_id", None),
                getattr(alert, "risk_label", None),
                getattr(alert, "top_pattern", None),
                getattr(alert, "title", None),
                metadata.get("source_module"),
            )
        ):
            represented_password_check_ids.add(password_check_id)
    alerts.extend(
        _serialize_admin_pcap_threat(alert, user_by_id, linked_accounts_by_user_id)
        for alert in pcap_alerts
    )
    alerts.extend(_list_admin_password_check_threats(user_by_id, represented_password_check_ids))

    alerts.sort(
        key=lambda item: _parse_dashboard_alert_epoch(item.get("timestamp"), fallback=0.0),
        reverse=True,
    )
    return _apply_admin_threat_status_overrides(alerts)


def _read_admin_threat_status_overrides() -> dict[str, dict[str, object]]:
    try:
        if not ADMIN_THREAT_STATUS_OVERRIDES_PATH.exists():
            return {}
        with ADMIN_THREAT_STATUS_OVERRIDES_PATH.open("r", encoding="utf-8") as handle:
            payload = json.load(handle)
        return payload if isinstance(payload, dict) else {}
    except Exception:
        logging.exception("Failed to read admin threat status overrides")
        return {}


def _write_admin_threat_status_overrides(overrides: dict[str, dict[str, object]]) -> bool:
    try:
        ADMIN_THREAT_STATUS_OVERRIDES_PATH.parent.mkdir(parents=True, exist_ok=True)
        with ADMIN_THREAT_STATUS_OVERRIDES_PATH.open("w", encoding="utf-8") as handle:
            json.dump(overrides, handle, indent=2)
        return True
    except Exception:
        logging.exception("Failed to write admin threat status overrides")
        return False


def _apply_admin_threat_status_overrides(alerts: list[dict[str, object]]) -> list[dict[str, object]]:
    overrides = _read_admin_threat_status_overrides()
    if not overrides:
        return alerts
    for alert in alerts:
        alert_id = _safe_str(alert.get("id"))
        override = overrides.get(alert_id)
        if not isinstance(override, dict):
            continue
        status = _privacy_admin_status(override.get("status"))
        alert["status"] = status
        alert["admin_review"] = {
            "status": status,
            "reviewed_by": _safe_str(override.get("reviewed_by")) or None,
            "reviewed_at": _safe_str(override.get("reviewed_at")) or None,
            "previous_status": _safe_str(override.get("previous_status")) or None,
        }
    return alerts


def _filter_admin_threat_feed(alerts: list[dict[str, object]], args) -> list[dict[str, object]]:
    query = _safe_str(args.get("q")).lower()
    severity_filter = _safe_str(args.get("severity"))
    status_filter = _safe_str(args.get("status"))
    module_filter = _safe_str(args.get("module"))
    range_filter = _safe_str(args.get("range"), "7d").lower()
    now = datetime.now(UTC)

    filtered: list[dict[str, object]] = []
    for alert in alerts:
        if query:
            haystack = " ".join(
                [
                    _safe_str(alert.get("id")),
                    _safe_str(alert.get("title")),
                    _safe_str(alert.get("description")),
                    _safe_str(alert.get("source_module")),
                    _safe_str(alert.get("device_context")),
                    " ".join(str(value) for value in (alert.get("evidence") or {}).values()),
                ]
            ).lower()
            if query not in haystack:
                continue
        if severity_filter and severity_filter.lower() != "all" and _safe_str(alert.get("severity")) != severity_filter:
            continue
        if status_filter and status_filter.lower() != "all" and _safe_str(alert.get("status")) != status_filter:
            continue
        if module_filter and module_filter.lower() != "all" and _safe_str(alert.get("source_module")) != module_filter:
            continue

        if range_filter in {"24h", "7d", "30d"}:
            timestamp = _normalize_dashboard_alert_timestamp(alert.get("timestamp"))
            parsed = _as_utc_datetime(datetime.fromisoformat(timestamp.replace("Z", "+00:00"))) if timestamp else None
            if parsed is None:
                continue
            age_seconds = (now - parsed).total_seconds()
            max_seconds = 86400 if range_filter == "24h" else 604800 if range_filter == "7d" else 2592000
            if age_seconds > max_seconds:
                continue

        filtered.append(alert)

    return filtered


def _admin_threat_summary_payload(alerts: list[dict[str, object]]) -> dict[str, int]:
    today = datetime.now(UTC).date()
    resolved_today = 0
    for alert in alerts:
        timestamp = _normalize_dashboard_alert_timestamp(alert.get("timestamp"))
        if not timestamp:
            continue
        try:
            parsed = _as_utc_datetime(datetime.fromisoformat(timestamp.replace("Z", "+00:00")))
        except ValueError:
            parsed = None
        if parsed and parsed.date() == today and _safe_str(alert.get("status")) == "Acknowledged":
            resolved_today += 1

    return {
        "total_alerts": len(alerts),
        "critical_alerts": sum(1 for alert in alerts if _safe_str(alert.get("severity")) == "Critical"),
        "under_investigation": sum(1 for alert in alerts if _safe_str(alert.get("status")) == "Acknowledged"),
        "resolved_today": resolved_today,
    }


def _admin_threats_csv_response(alerts: list[dict[str, object]]):
    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow(
        [
            "Alert ID",
            "Title",
            "Description",
            "Source Module",
            "Severity",
            "Status",
            "Confidence",
            "Timestamp",
            "Device Context",
            "Investigation Summary",
        ]
    )
    for alert in alerts:
        writer.writerow(
            [
                _safe_str(alert.get("id")),
                _safe_str(alert.get("title")),
                _safe_str(alert.get("description")),
                _safe_str(alert.get("source_module")),
                _safe_str(alert.get("severity")),
                _safe_str(alert.get("status")),
                _safe_int(alert.get("confidence"), 0),
                _safe_str(alert.get("timestamp")),
                _safe_str(alert.get("device_context")),
                _safe_str(alert.get("investigation_summary")),
            ]
        )

    csv_bytes = output.getvalue().encode("utf-8-sig")
    output.close()
    response = make_response(csv_bytes)
    response.headers["Content-Type"] = "text/csv; charset=utf-8"
    response.headers["Content-Disposition"] = (
        f'attachment; filename="sentinel-threat-alerts-{datetime.now(UTC).strftime("%Y%m%d-%H%M%S")}.csv"'
    )
    return response


