def _ensure_admin_console_schema_initialized() -> None:
    global _admin_console_schema_initialized
    if _admin_console_schema_initialized:
        return

    with _admin_console_schema_lock:
        if _admin_console_schema_initialized:
            return

        db.create_all()
        inspector = inspect(db.engine)

        if inspector.has_table(User.__tablename__):
            existing_columns = {
                str(column.get("name") or "").strip()
                for column in inspector.get_columns(User.__tablename__)
            }
            alter_user_statements = []
            if "admin_role" not in existing_columns:
                alter_user_statements.append(
                    text(
                        "ALTER TABLE user ADD COLUMN admin_role VARCHAR(50) NOT NULL DEFAULT 'User'"
                    )
                )
            if "admin_status" not in existing_columns:
                alter_user_statements.append(
                    text(
                        "ALTER TABLE user ADD COLUMN admin_status VARCHAR(20) NOT NULL DEFAULT 'Active'"
                    )
                )
            if "created_at" not in existing_columns:
                alter_user_statements.append(
                    text("ALTER TABLE user ADD COLUMN created_at DATETIME")
                )
            if "updated_at" not in existing_columns:
                alter_user_statements.append(
                    text("ALTER TABLE user ADD COLUMN updated_at DATETIME")
                )
            if "last_login_at" not in existing_columns:
                alter_user_statements.append(
                    text("ALTER TABLE user ADD COLUMN last_login_at DATETIME")
                )
            if "invite_token" not in existing_columns:
                alter_user_statements.append(
                    text("ALTER TABLE user ADD COLUMN invite_token VARCHAR")
                )
            if "invite_expires_at" not in existing_columns:
                alter_user_statements.append(
                    text("ALTER TABLE user ADD COLUMN invite_expires_at DATETIME")
                )
            if "invite_accepted_at" not in existing_columns:
                alter_user_statements.append(
                    text("ALTER TABLE user ADD COLUMN invite_accepted_at DATETIME")
                )
            if "invite_require_2fa" not in existing_columns:
                alter_user_statements.append(
                    text("ALTER TABLE user ADD COLUMN invite_require_2fa BOOLEAN NOT NULL DEFAULT 0")
                )
            if "require_two_factor_enrollment" not in existing_columns:
                alter_user_statements.append(
                    text(
                        "ALTER TABLE user ADD COLUMN require_two_factor_enrollment BOOLEAN NOT NULL DEFAULT 0"
                    )
                )

            try:
                for statement in alter_user_statements:
                    db.session.execute(statement)
                if alter_user_statements:
                    db.session.commit()

                db.session.execute(
                    text(
                        "UPDATE user SET admin_role = 'User' WHERE admin_role IS NULL OR TRIM(admin_role) = ''"
                    )
                )
                db.session.execute(
                    text(
                        "UPDATE user SET admin_status = 'Active' WHERE admin_status IS NULL OR TRIM(admin_status) = ''"
                    )
                )
                db.session.execute(
                    text("UPDATE user SET created_at = CURRENT_TIMESTAMP WHERE created_at IS NULL")
                )
                db.session.execute(
                    text("UPDATE user SET updated_at = CURRENT_TIMESTAMP WHERE updated_at IS NULL")
                )
                db.session.execute(
                    text(
                        "UPDATE user SET invite_require_2fa = 0 WHERE invite_require_2fa IS NULL"
                    )
                )
                db.session.execute(
                    text(
                        "UPDATE user SET require_two_factor_enrollment = 0 WHERE require_two_factor_enrollment IS NULL"
                    )
                )
                db.session.commit()
            except Exception:
                db.session.rollback()
                logging.exception("Failed to ensure admin console user schema")
                raise

        if inspector.has_table(AdminAuditLog.__tablename__):
            existing_indexes = {
                str(index.get("name") or "").strip()
                for index in inspector.get_indexes(AdminAuditLog.__tablename__)
            }
            audit_index_statements = []
            audit_indexes = {
                "ix_admin_audit_log_actor_email": "actor_email",
                "ix_admin_audit_log_action_type": "action_type",
                "ix_admin_audit_log_module": "module",
                "ix_admin_audit_log_status": "status",
                "ix_admin_audit_log_severity": "severity",
                "ix_admin_audit_log_created_at": "created_at",
            }
            for index_name, column_name in audit_indexes.items():
                if index_name not in existing_indexes:
                    audit_index_statements.append(
                        text(f"CREATE INDEX {index_name} ON admin_audit_log ({column_name})")
                    )
            try:
                for statement in audit_index_statements:
                    db.session.execute(statement)
                if audit_index_statements:
                    db.session.commit()
            except Exception:
                db.session.rollback()
                logging.exception("Failed to ensure admin audit log indexes")
                raise

        _admin_console_schema_initialized = True


@app.before_request
def ensure_admin_console_schema_before_request():
    path = str(request.path or "").strip()
    if request.method == "OPTIONS":
        return None
    if not (
        path.startswith("/api/admin/")
        or path.startswith("/api/invitations/")
    ):
        return None

    try:
        _ensure_admin_console_schema_initialized()
    except Exception:
        logging.exception(
            "Failed to initialize admin console schema before request | path=%s",
            path,
        )
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Admin console storage could not be initialized.",
                }
            ),
            500,
        )

    return None


def build_analysis_notification_summary(report) -> str:
    if not isinstance(report, dict):
        return "Analysis completed."

    summary = report.get("summary") if isinstance(report.get("summary"), dict) else {}
    total_flows = _safe_int(summary.get("total_flows"), 0)
    alerts_count = _safe_int(summary.get("alerts_count"), 0)
    risk_level = str(summary.get("risk_level") or "Unknown").strip() or "Unknown"

    parts = []
    if total_flows > 0:
        parts.append(f"{total_flows} flows analyzed")
    if alerts_count >= 0:
        parts.append(f"{alerts_count} alert{'s' if alerts_count != 1 else ''} detected")
    parts.append(f"overall risk {risk_level}")

    message = "Analysis completed: " + ", ".join(parts) + "."

    clusters = report.get("clusters")
    if isinstance(clusters, list) and clusters:
        top_cluster = clusters[0] if isinstance(clusters[0], dict) else {}
        attack_type = str(top_cluster.get("attack_type") or "").strip()
        src_ip = str(top_cluster.get("src_ip") or "").strip()
        dst_ip = str(top_cluster.get("dst_ip") or "").strip()
        if attack_type:
            cluster_line = f"Top cluster: {attack_type}"
            if src_ip and dst_ip:
                cluster_line += f" from {src_ip} to {dst_ip}"
            elif src_ip:
                cluster_line += f" from {src_ip}"
            elif dst_ip:
                cluster_line += f" to {dst_ip}"
            message += f" {cluster_line}."

    return message


def _notification_email_smtp_configured() -> bool:
    return bool(
        SMTP_HOST
        and SMTP_PORT
        and SMTP_USERNAME
        and SMTP_PASSWORD
        and SMTP_FROM_EMAIL
    )


def _notification_email_safe_text(value: object, fallback: str = "") -> str:
    text_value = re.sub(r"\s+", " ", safe_activity_str(value, fallback)).strip()
    if not text_value:
        return fallback
    sensitive_patterns = [
        r"\bpassword\s*[:=]\s*\S+",
        r"\btoken\s*[:=]\s*\S+",
        r"\bapi[_ -]?key\s*[:=]\s*\S+",
        r"\bsecret\s*[:=]\s*\S+",
        r"\bcredential\s*[:=]\s*\S+",
    ]
    if any(re.search(pattern, text_value, flags=re.IGNORECASE) for pattern in sensitive_patterns):
        return "A security notification was created. Open your Sentinel AI dashboard to review full details."
    return text_value[:800]


def _notification_email_subject(title: object) -> str:
    safe_title = _notification_email_safe_text(title, "Security notification")[:140]
    clean_title = safe_title.replace("_", " ").replace("-", " ")
    clean_title = re.sub(r"\s+", " ", clean_title).strip()
    clean_title = clean_title.title() if clean_title else "Security Notification"
    return f"[Sentinel AI] {clean_title}"


def _notification_email_module_name(notification: "UserNotification", metadata: dict) -> str:
    candidates = [
        metadata.get("source_module"),
        metadata.get("module"),
        getattr(notification, "type", None),
    ]
    for candidate in candidates:
        value = safe_activity_str(candidate).replace("_", " ").strip()
        if value:
            return value.title()[:80]
    return ""


def _build_notification_email_bodies(notification: "UserNotification") -> tuple[str, str]:
    metadata = _notification_metadata_from_json(getattr(notification, "metadata_json", None))
    title = _notification_email_safe_text(getattr(notification, "title", None), "Security notification")
    display_title = re.sub(r"\s+", " ", title.replace("_", " ").replace("-", " ")).strip()
    display_title = display_title[:1].upper() + display_title[1:] if display_title else "Security notification"
    body = _notification_email_safe_text(
        getattr(notification, "body", None),
        "Open your Sentinel AI dashboard to review this notification.",
    )
    module_name = _notification_email_module_name(notification, metadata)
    severity = safe_activity_str(getattr(notification, "severity", None)).title()
    severity_key = severity.lower()
    severity_styles = {
        "critical": ("#fecaca", "#7f1d1d", "#ef4444"),
        "error": ("#fecaca", "#7f1d1d", "#ef4444"),
        "high": ("#fed7aa", "#7c2d12", "#f97316"),
        "warning": ("#fde68a", "#713f12", "#f59e0b"),
        "medium": ("#fde68a", "#713f12", "#f59e0b"),
        "low": ("#bbf7d0", "#064e3b", "#22c55e"),
        "success": ("#bbf7d0", "#064e3b", "#22c55e"),
        "info": ("#bae6fd", "#0c4a6e", "#38bdf8"),
    }
    severity_text_color, severity_bg, severity_accent = severity_styles.get(
        severity_key,
        ("#bae6fd", "#0c4a6e", "#38bdf8"),
    )
    created_at = getattr(notification, "created_at", None)
    if created_at:
        try:
            timestamp = _to_utc_aware(created_at).isoformat()
        except Exception:
            timestamp = safe_activity_str(created_at)
    else:
        timestamp = ""

    text_lines = [
        display_title,
        "",
        f"Module: {module_name}" if module_name else "",
        f"Severity: {severity}" if severity else "",
        f"Time: {timestamp}" if timestamp else "",
        "",
        body,
        "",
        "Open your Sentinel AI dashboard to review full details.",
        "",
        "This is an automated security notification from Sentinel AI.",
    ]
    text_body = "\n".join(line for line in text_lines if line != "")
    severity_badge = (
        f'<span style="display:inline-block;padding:7px 12px;border-radius:999px;'
        f'background:{severity_bg};color:{severity_text_color};font-size:12px;'
        f'font-weight:700;letter-spacing:0.08em;text-transform:uppercase;">{escape(severity)}</span>'
        if severity
        else ""
    )
    module_chip = (
        f'<span style="display:inline-block;padding:7px 12px;border-radius:999px;'
        f'background:#0f2742;color:#bae6fd;border:1px solid rgba(56,189,248,0.22);'
        f'font-size:12px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;">{escape(module_name)}</span>'
        if module_name
        else ""
    )
    time_row = (
        f'<tr><td style="padding:8px 0;color:#94a3b8;font-size:13px;width:90px;">Time</td>'
        f'<td style="padding:8px 0;color:#e2e8f0;font-size:14px;">{escape(timestamp)}</td></tr>'
        if timestamp
        else ""
    )
    html_body = f"""
    <html>
      <body style="margin:0;padding:0;background:#020817;font-family:Arial,Helvetica,sans-serif;color:#e2e8f0;">
        <div style="background:#020817;padding:28px 16px;">
          <div style="max-width:640px;margin:0 auto;border-radius:22px;overflow:hidden;border:1px solid rgba(56,189,248,0.18);background:#071426;">
            <div style="padding:26px 28px;background:linear-gradient(135deg,#082f49,#0f172a 64%,#111827);border-bottom:1px solid rgba(56,189,248,0.16);">
              <div style="font-size:22px;font-weight:800;letter-spacing:0.02em;color:#f8fafc;">Sentinel AI</div>
              <div style="margin-top:6px;font-size:13px;font-weight:700;letter-spacing:0.14em;text-transform:uppercase;color:#38bdf8;">Security Notification</div>
            </div>
            <div style="padding:28px;">
              <div style="width:42px;height:4px;border-radius:999px;background:{severity_accent};margin-bottom:18px;"></div>
              <h1 style="margin:0;color:#f8fafc;font-size:24px;line-height:1.28;font-weight:800;">{escape(display_title)}</h1>
              <div style="margin-top:16px;">
                {severity_badge}
                <span style="display:inline-block;width:8px;"></span>
                {module_chip}
              </div>
              <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:22px;border-collapse:collapse;">
                {time_row}
              </table>
              <div style="margin-top:18px;padding:18px 20px;border-radius:16px;background:#0f1f33;border:1px solid rgba(148,163,184,0.12);">
                <div style="font-size:12px;font-weight:700;letter-spacing:0.12em;text-transform:uppercase;color:#94a3b8;margin-bottom:8px;">Message</div>
                <p style="margin:0;color:#dbeafe;font-size:15px;line-height:1.65;">{escape(body)}</p>
              </div>
              <div style="margin-top:22px;padding:16px 18px;border-radius:14px;background:#082f49;border:1px solid rgba(56,189,248,0.26);color:#e0f2fe;font-size:14px;line-height:1.55;">
                Open your Sentinel AI dashboard to review full details.
              </div>
            </div>
            <div style="padding:18px 28px;border-top:1px solid rgba(148,163,184,0.12);background:#050f1f;color:#94a3b8;font-size:12px;line-height:1.55;">
              This is an automated security notification from Sentinel AI.
            </div>
          </div>
        </div>
      </body>
    </html>
    """.strip()
    return text_body, html_body


def send_notification_email_best_effort(user, notification) -> bool:
    """Best-effort email side effect for newly-created in-app notifications."""
    try:
        app.logger.warning("[NotificationEmail] send_notification_email_best_effort entered")
        recipient = safe_activity_str(getattr(user, "email", None)).strip() if user else ""
        masked_recipient = mask_email(recipient) if recipient else ""
        smtp_password_placeholder_values = {
            "YOUR_NEW_GMAIL_APP_PASSWORD",
            "PUT_NEW_GMAIL_APP_PASSWORD_HERE",
            "NEW_GMAIL_APP_PASSWORD_HERE",
        }
        smtp_password_is_placeholder = SMTP_PASSWORD.strip() in smtp_password_placeholder_values
        app.logger.warning(
            "[NotificationEmail] config state | enabled=%s smtp_host_present=%s smtp_port=%s smtp_use_tls=%s "
            "smtp_username_exists=%s smtp_password_exists=%s smtp_password_placeholder=%s "
            "smtp_from_email_exists=%s recipient=%s user_email_missing=%s",
            bool(EMAIL_NOTIFICATIONS_ENABLED),
            bool(SMTP_HOST),
            SMTP_PORT,
            bool(SMTP_USE_TLS),
            bool(SMTP_USERNAME),
            bool(SMTP_PASSWORD),
            bool(smtp_password_is_placeholder),
            bool(SMTP_FROM_EMAIL),
            masked_recipient or "missing",
            not bool(recipient),
        )

        if not EMAIL_NOTIFICATIONS_ENABLED:
            app.logger.warning("[NotificationEmail] Notification email skipped: EMAIL_NOTIFICATIONS_ENABLED is not true")
            return False
        if not user or not notification:
            app.logger.warning(
                "[NotificationEmail] Notification email skipped: user_or_notification_missing user_exists=%s notification_exists=%s",
                bool(user),
                bool(notification),
            )
            return False
        if not _is_email_notification_enabled_for_user(user):
            app.logger.warning(
                "[NotificationEmail] Notification email skipped: user email notifications disabled | user_id=%s recipient=%s",
                getattr(user, "id", None),
                masked_recipient or "missing",
            )
            return False

        if not recipient:
            app.logger.warning("[NotificationEmail] Notification email skipped: user.email is missing")
            return False
        if smtp_password_is_placeholder:
            app.logger.warning("[NotificationEmail] Notification email skipped: SMTP_PASSWORD appears to be placeholder")
            return False
        if not _notification_email_smtp_configured():
            missing_keys = [
                key
                for key, exists in (
                    ("SMTP_HOST", bool(SMTP_HOST)),
                    ("SMTP_PORT", bool(SMTP_PORT)),
                    ("SMTP_USERNAME", bool(SMTP_USERNAME)),
                    ("SMTP_PASSWORD", bool(SMTP_PASSWORD)),
                    ("SMTP_FROM_EMAIL", bool(SMTP_FROM_EMAIL)),
                )
                if not exists
            ]
            app.logger.warning(
                "[NotificationEmail] Notification email skipped: missing SMTP config | missing=%s",
                ",".join(missing_keys) or "unknown",
            )
            return False

        subject = _notification_email_subject(getattr(notification, "title", None))
        text_body, html_body = _build_notification_email_bodies(notification)
        safe_from_name = re.sub(r"[\r\n<>]+", "", SMTP_FROM_NAME).strip()[:80] or "Sentinel AI"
        safe_from_email = re.sub(r"[\r\n]+", "", SMTP_FROM_EMAIL).strip()
        safe_recipient = re.sub(r"[\r\n]+", "", recipient).strip()

        message = MIMEMultipart("alternative")
        message["Subject"] = subject
        message["From"] = f"{safe_from_name} <{safe_from_email}>"
        message["To"] = safe_recipient
        message.attach(MIMEText(text_body, "plain", "utf-8"))
        message.attach(MIMEText(html_body, "html", "utf-8"))

        app.logger.warning(
            "[NotificationEmail] connecting to SMTP host | notification_id=%s user_id=%s recipient=%s "
            "smtp_host_exists=%s smtp_port=%s smtp_use_tls=%s from_email_exists=%s",
            getattr(notification, "id", None),
            getattr(user, "id", None),
            masked_recipient,
            bool(SMTP_HOST),
            SMTP_PORT,
            bool(SMTP_USE_TLS),
            bool(safe_from_email),
        )
        with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=SMTP_TIMEOUT_SECONDS) as server:
            if SMTP_USE_TLS:
                app.logger.warning(
                    "[NotificationEmail] starting TLS | notification_id=%s user_id=%s",
                    getattr(notification, "id", None),
                    getattr(user, "id", None),
                )
                server.starttls()
            app.logger.warning(
                "[NotificationEmail] logging into SMTP | notification_id=%s user_id=%s "
                "smtp_username_exists=%s smtp_password_exists=%s",
                getattr(notification, "id", None),
                getattr(user, "id", None),
                bool(SMTP_USERNAME),
                bool(SMTP_PASSWORD),
            )
            server.login(SMTP_USERNAME, SMTP_PASSWORD)
            app.logger.warning(
                "[NotificationEmail] sending message | notification_id=%s user_id=%s recipient=%s from_email_exists=%s",
                getattr(notification, "id", None),
                getattr(user, "id", None),
                masked_recipient,
                bool(safe_from_email),
            )
            server.sendmail(safe_from_email, [safe_recipient], message.as_string())
        app.logger.warning(
            "[NotificationEmail] email sent successfully | notification_id=%s user_id=%s recipient=%s",
            getattr(notification, "id", None),
            getattr(user, "id", None),
            masked_recipient,
        )
        return True
    except Exception as exc:
        app.logger.warning(
            "[NotificationEmail] email delivery failed safely | notification_id=%s user_id=%s "
            "exception_class=%s safe_message=%s",
            getattr(notification, "id", None),
            getattr(user, "id", None),
            exc.__class__.__name__,
            _friendly_smtp_error(exc),
        )
        return False


def _build_job_notification_metadata(job_state, report=None, extra=None) -> dict:
    metadata = {
        "job_id": getattr(job_state, "job_id", None),
    }
    if getattr(job_state, "status", None):
        metadata["job_status"] = job_state.status

    if isinstance(report, dict):
        summary = (
            report.get("summary") if isinstance(report.get("summary"), dict) else {}
        )
        clusters = (
            report.get("clusters") if isinstance(report.get("clusters"), list) else []
        )
        metadata["risk_level"] = str(summary.get("risk_level") or "Normal")
        metadata["alerts_count"] = _safe_int(summary.get("alerts_count"), 0)
        metadata["total_flows"] = _safe_int(summary.get("total_flows"), 0)
        metadata["suspicious_count"] = _safe_int(summary.get("suspicious"), 0)
        metadata["malicious_count"] = _safe_int(summary.get("malicious"), 0)
        metadata["overall_risk"] = _safe_float(summary.get("overall_risk"), 0.0)
        if clusters:
            top_cluster = clusters[0] if isinstance(clusters[0], dict) else {}
            metadata["top_attack_type"] = str(top_cluster.get("attack_type") or "")
            metadata["top_src_ip"] = str(top_cluster.get("src_ip") or "")
            metadata["top_dst_ip"] = str(top_cluster.get("dst_ip") or "")

    if isinstance(extra, dict):
        metadata.update(extra)
    return metadata


def _build_report_alert_signal_context(report) -> dict:
    summary = report.get("summary") if isinstance(report, dict) else {}
    summary = summary if isinstance(summary, dict) else {}
    alerts = report.get("alerts") if isinstance(report, dict) else []
    alerts = alerts if isinstance(alerts, list) else []

    severity_counts = Counter()
    for item in alerts:
        if not isinstance(item, dict):
            continue
        severity = str(item.get("severity") or "").strip().title()
        if severity:
            severity_counts[severity] += 1

    critical_count = int(severity_counts.get("Critical", 0))
    high_count = int(severity_counts.get("High", 0))
    medium_count = int(severity_counts.get("Medium", 0))

    return {
        "risk_level": str(summary.get("risk_level") or "Normal").strip() or "Normal",
        "alerts_count": _safe_int(summary.get("alerts_count"), len(alerts)),
        "suspicious_count": _safe_int(
            summary.get("suspicious"), medium_count + high_count + critical_count
        ),
        "malicious_count": _safe_int(
            summary.get("malicious"), high_count + critical_count
        ),
        "critical_count": critical_count,
        "high_count": high_count,
        "medium_count": medium_count,
    }


def create_user_notification(
    user_id,
    type,
    title,
    body,
    *,
    severity=NOTIFICATION_SEVERITY_INFO,
    job_id=None,
    metadata=None,
):
    if not user_id:
        return None

    _ensure_notification_schema_initialized()

    normalized_metadata = metadata.copy() if isinstance(metadata, dict) else {}
    normalized_type = _normalize_notification_type(type, normalized_metadata)
    normalized_severity = _normalize_notification_severity(
        severity,
        type=normalized_type,
        metadata=normalized_metadata,
    )
    normalized_job_id = (
        str(job_id or normalized_metadata.get("job_id") or "").strip() or None
    )
    if normalized_job_id:
        normalized_metadata["job_id"] = normalized_job_id

    if normalized_job_id:
        existing = (
            UserNotification.query.filter_by(
                user_id=int(user_id),
                type=normalized_type,
                job_id=normalized_job_id,
            )
            .order_by(UserNotification.created_at.desc(), UserNotification.id.desc())
            .first()
        )
        if existing:
            return existing

    notification = UserNotification(
        user_id=int(user_id),
        type=normalized_type,
        severity=normalized_severity,
        title=str(title or "").strip()[:200],
        body=str(body or "").strip(),
        job_id=normalized_job_id,
        metadata_json=_notification_metadata_to_json(normalized_metadata),
        is_read=False,
    )
    db.session.add(notification)
    db.session.commit()
    notification_module = safe_activity_str(
        normalized_metadata.get("module") or normalized_metadata.get("source_module") or normalized_type
    )
    app.logger.warning(
        "[NotificationEmail] notification committed; attempting email delivery | notification_id=%s user_id=%s type=%s module=%s",
        getattr(notification, "id", None),
        user_id,
        normalized_type,
        notification_module,
    )
    try:
        owner = db.session.get(User, int(user_id))
        app.logger.warning(
            "[NotificationEmail] calling send_notification_email_best_effort | notification_id=%s user_id=%s type=%s module=%s",
            getattr(notification, "id", None),
            user_id,
            normalized_type,
            notification_module,
        )
        send_notification_email_best_effort(owner, notification)
    except Exception as exc:
        app.logger.warning(
            "[NotificationEmail] email side effect failed safely | notification_id=%s user_id=%s exception_class=%s safe_message=%s",
            getattr(notification, "id", None),
            user_id,
            exc.__class__.__name__,
            _friendly_smtp_error(exc),
        )
    return notification


def _password_notification_now() -> datetime:
    return datetime.now(UTC)


def _password_notification_score(record) -> int:
    try:
        return max(0, min(5, int(getattr(record, "score", 0) or 0)))
    except (TypeError, ValueError):
        return 0


def _password_notification_breach_count(record) -> int:
    try:
        return max(0, int(getattr(record, "breach_count", 0) or 0))
    except (TypeError, ValueError):
        return 0


def _password_notification_verdict(record) -> str:
    return str(getattr(record, "verdict", "") or "").strip().lower()


def _password_notification_is_risky(record) -> bool:
    return (
        _password_notification_breach_count(record) > 0
        or _password_notification_verdict(record) == "breached"
        or _password_notification_score(record) <= 1
    )


def _recent_password_notification_exists(
    user_id: int,
    event_type: str,
    window_minutes: int,
    password_check_id: int | None = None,
) -> bool:
    if not user_id or not event_type:
        return False

    query = UserNotification.query.filter(
        UserNotification.user_id == int(user_id),
        UserNotification.type == NOTIFICATION_TYPE_PASSWORD_SECURITY,
    )
    if not password_check_id:
        since = _password_notification_now() - timedelta(minutes=max(int(window_minutes or 1), 1))
        query = query.filter(UserNotification.created_at >= since)

    recent = query.order_by(UserNotification.created_at.desc(), UserNotification.id.desc()).limit(20).all()
    for notification in recent:
        metadata = _notification_metadata_from_json(notification.metadata_json)
        if str(metadata.get("event_type") or "") != event_type:
            continue
        if password_check_id:
            try:
                if int(metadata.get("password_check_id") or 0) == int(password_check_id):
                    return True
            except (TypeError, ValueError):
                continue
        else:
            return True
    return False


def _should_send_password_email_alert(user_id: int, event_type: str) -> bool:
    fingerprint = f"{int(user_id)}|{event_type}"
    now = time.monotonic()
    cooldown_seconds = max(PASSWORD_EMAIL_ALERT_COOLDOWN_MINUTES, 1) * 60

    with _password_email_alert_lock:
        last_sent = _password_email_alert_state.get(fingerprint, 0.0)
        if now - last_sent < cooldown_seconds:
            return False

        _password_email_alert_state[fingerprint] = now
        if len(_password_email_alert_state) > 1024:
            cutoff = now - (cooldown_seconds * 2)
            stale_keys = [
                key
                for key, sent_at in _password_email_alert_state.items()
                if sent_at < cutoff
            ]
            for key in stale_keys[:512]:
                _password_email_alert_state.pop(key, None)
        return True


def _send_password_security_email(user, event_type: str, title: str, body: str) -> bool:
    if EMAIL_NOTIFICATIONS_ENABLED:
        return False
    if not PASSWORD_EMAIL_ALERTS_ENABLED:
        return False
    if not _is_email_notification_enabled_for_user(user):
        return False
    recipient = _safe_str(getattr(user, "email", None)).lower()
    if not recipient:
        return False
    if not _should_send_password_email_alert(int(user.id), event_type):
        return False

    detected_at = _password_notification_now().strftime("%Y-%m-%d %H:%M:%S UTC")
    subject = "[Sentinel AI] Password Security Alert"
    text_body = (
        "Password Security Alert\n\n"
        f"Event: {title}\n"
        f"Details: {body}\n"
        f"Detected at: {detected_at}\n\n"
        "Recommendation:\n"
        "Change any reused or weak password immediately, use a unique strong password, "
        "and enable multi-factor authentication where available.\n"
    )
    html_body = f"""
    <div style="font-family:Arial,sans-serif;background:#020617;color:#e2e8f0;padding:24px;border-radius:12px">
      <h2 style="color:#f87171;margin-top:0">{escape(title)}</h2>
      <p>{escape(body)}</p>
      <p style="color:#94a3b8">Detected at: {escape(detected_at)}</p>
      <p style="margin-top:18px;color:#cbd5e1">
        Recommendation: change any reused or weak password immediately, use a unique strong password,
        and enable multi-factor authentication where available.
      </p>
    </div>
    """
    return _send_email_message(recipient, subject, text_body, html_body)


def _create_password_security_notification(
    user,
    *,
    event_type: str,
    title: str,
    body: str,
    severity_label: str,
    notification_severity: str,
    record,
    extra_metadata: dict | None = None,
) -> UserNotification | None:
    user_id = int(getattr(user, "id", 0) or 0)
    if not user_id:
        return None
    try:
        password_check_id = int(getattr(record, "id", 0) or 0)
    except (TypeError, ValueError):
        password_check_id = 0

    if _recent_password_notification_exists(
        user_id,
        event_type,
        PASSWORD_NOTIFICATION_COOLDOWN_MINUTES,
        password_check_id or None,
    ):
        return None

    metadata = {
        "module": "password",
        "event_type": event_type,
        "severity_label": severity_label,
        "score": _password_notification_score(record),
        "breach_count": _password_notification_breach_count(record),
        "verdict": _password_notification_verdict(record),
        "password_check_id": password_check_id,
    }
    if isinstance(extra_metadata, dict):
        metadata.update(extra_metadata)

    notification = create_user_notification(
        user_id,
        NOTIFICATION_TYPE_PASSWORD_SECURITY,
        title,
        body,
        severity=notification_severity,
        metadata=metadata,
    )

    return notification


def process_password_check_notifications(user, record) -> list[UserNotification]:
    """Create privacy-safe password notifications from saved check metadata only."""
    created: list[UserNotification] = []
    if not user or not record:
        return created

    try:
        user_id = int(user.id)
        score = _password_notification_score(record)
        breach_count = _password_notification_breach_count(record)
        verdict = _password_notification_verdict(record)

        if breach_count > 0 or verdict == "breached":
            notification = _create_password_security_notification(
                user,
                event_type="breached_password_detected",
                title="Breached password detected",
                body="Your password was found in known public breaches. Change it immediately and avoid reuse.",
                severity_label="high",
                notification_severity=NOTIFICATION_SEVERITY_CRITICAL,
                record=record,
            )
            if notification:
                created.append(notification)

        if score <= 1:
            notification = _create_password_security_notification(
                user,
                event_type="very_weak_password_score",
                title="Very weak password score",
                body="Your password security score is critically low.",
                severity_label="medium",
                notification_severity=NOTIFICATION_SEVERITY_WARNING,
                record=record,
            )
            if notification:
                created.append(notification)

        previous = (
            PasswordCheck.query.filter(
                PasswordCheck.user_id == user_id,
                PasswordCheck.id != int(getattr(record, "id", 0) or 0),
            )
            .order_by(PasswordCheck.created_at.desc(), PasswordCheck.id.desc())
            .first()
        )
        previous_score = _password_notification_score(previous) if previous else None
        if (
            previous_score is not None
            and previous_score <= 2
            and score >= 4
            and breach_count == 0
            and verdict != "breached"
        ):
            notification = _create_password_security_notification(
                user,
                event_type="password_security_improvement",
                title="Password security improved",
                body="Your password hygiene score has improved.",
                severity_label="low",
                notification_severity=NOTIFICATION_SEVERITY_INFO,
                record=record,
                extra_metadata={"previous_score": previous_score},
            )
            if notification:
                created.append(notification)

        since = _password_notification_now() - timedelta(hours=24)
        recent_records = (
            PasswordCheck.query.filter(
                PasswordCheck.user_id == user_id,
                PasswordCheck.created_at >= since,
            )
            .order_by(PasswordCheck.created_at.desc(), PasswordCheck.id.desc())
            .limit(10)
            .all()
        )
        recent_risky_count = sum(1 for item in recent_records if _password_notification_is_risky(item))
        if recent_risky_count >= 3:
            notification = _create_password_security_notification(
                user,
                event_type="repeated_risky_password_behavior",
                title="Repeated risky password behavior",
                body="Multiple unsafe password checks were detected recently.",
                severity_label="high",
                notification_severity=NOTIFICATION_SEVERITY_CRITICAL,
                record=record,
                extra_metadata={"recent_risky_count": int(recent_risky_count), "window_hours": 24},
            )
            if notification:
                created.append(notification)

    except Exception:
        logging.exception(
            "Failed to process password security notifications for user_id=%s",
            getattr(user, "id", None),
        )

    return created


def create_password_checker_security_alert(user, record) -> Optional[PcapAlertRecord]:
    """Best-effort Recent Security Alerts entry from saved password metadata only."""
    if not user or not record:
        return None

    try:
        user_id = int(getattr(user, "id", 0) or 0)
        password_check_id = int(getattr(record, "id", 0) or 0)
    except (TypeError, ValueError):
        return None

    if user_id <= 0 or password_check_id <= 0:
        return None

    try:
        score = _password_notification_score(record)
        breach_count = _password_notification_breach_count(record)
        verdict = _password_notification_verdict(record)
        strength_label = _safe_str(getattr(record, "strength_label", None))
        strength_key = strength_label.strip().lower()
        breached = breach_count > 0 or verdict == "breached"
        very_weak = score <= 1 or strength_key in {"very weak", "very_weak", "critical"}
        weak = score <= 2 or strength_key == "weak"

        if breached:
            severity = "Critical"
            title = "Breached Password Detected"
            message = (
                "A password check found that the submitted password appears in known "
                "breach data. The password should be changed immediately."
            )
            risk_level = "Critical"
        elif very_weak:
            severity = "High"
            title = "Password Hygiene Risk Detected"
            message = (
                "A password check detected critically weak password hygiene. Improve "
                "password length, complexity, and uniqueness."
            )
            risk_level = "High"
        elif weak:
            severity = "Medium"
            title = "Weak Password Detected"
            message = (
                "A password check detected weak password hygiene. Improve password "
                "length, complexity, and uniqueness."
            )
            risk_level = "Medium"
        else:
            return None

        _ensure_pcap_alert_schema_initialized()

        alert_key = f"password-checker:{user_id}:{password_check_id}"
        existing = PcapAlertRecord.query.filter_by(
            user_id=user_id,
            alert_key=alert_key,
        ).first()
        if existing:
            return existing

        checked_at = getattr(record, "created_at", None)
        checked_at_utc = _as_utc_datetime(checked_at) or datetime.now(UTC)
        owner_scope = _build_authenticated_user_scope(user)
        metadata = _sanitize_for_json(
            {
                "owner_scope": owner_scope,
                "source_module": "password_checker",
                "source_id": password_check_id,
                "password_check_id": password_check_id,
                "checked_at": checked_at_utc.isoformat(),
                "strength_label": strength_label or None,
                "risk_level": risk_level,
                "breached": bool(breached),
            }
        )

        alert_record = PcapAlertRecord(
            user_id=user_id,
            job_id=f"password-check-{password_check_id}",
            alert_key=alert_key,
            source_type="password_checker",
            type="pcap_alert",
            title=title,
            message=message,
            severity=_normalize_dashboard_alert_severity(severity),
            status="new",
            risk_label="passwords",
            threats_count=1,
            flows_analyzed=0,
            top_pattern="Password Checker",
            filename=None,
            attack_type="Password Hygiene",
            protocol="Account",
            src_ip=None,
            dst_ip=None,
            event_at=checked_at_utc,
            metadata_json=json.dumps(metadata),
        )
        db.session.add(alert_record)
        db.session.commit()
        return alert_record
    except Exception:
        db.session.rollback()
        logging.exception("Failed to create password checker security alert")
        return None


def create_security_audit_log(user_id, action, details=None):
    if not user_id or not action:
        return None

    _ensure_auth_security_schema_initialized()
    entry = SecurityAuditLog(
        user_id=int(user_id),
        action=str(action).strip()[:80],
        details_json=_notification_metadata_to_json(
            details if isinstance(details, dict) else {}
        ),
    )
    db.session.add(entry)
    db.session.flush()
    return entry


def create_security_hub_alert(
    user_id,
    *,
    title,
    message,
    severity="high",
    category="Account Protection",
    source_type="account_protection",
    metadata=None,
):
    if not user_id:
        return None

    _ensure_pcap_alert_schema_initialized()
    normalized_metadata = metadata.copy() if isinstance(metadata, dict) else {}
    event_at = _as_utc_datetime(datetime.now(UTC))
    event_stamp = event_at.isoformat() if event_at else datetime.now(UTC).isoformat()
    alert_key = hashlib.sha256(
        f"emergency-mode|{int(user_id)}|{title}|{event_stamp}".encode("utf-8")
    ).hexdigest()[:140]
    alert_record = PcapAlertRecord(
        user_id=int(user_id),
        job_id=f"security-{uuid.uuid4().hex[:16]}",
        alert_key=alert_key,
        source_type=str(source_type).strip()[:40] or "account_protection",
        type="pcap_alert",
        title=str(title or "").strip()[:200],
        message=str(message or "").strip(),
        severity=_normalize_dashboard_alert_severity(severity),
        status="new",
        risk_label=str(category or "Account Protection").strip()[:50],
        threats_count=1,
        flows_analyzed=0,
        top_pattern="Emergency Mode",
        filename=None,
        attack_type="Emergency Mode",
        protocol="Account",
        src_ip=request.remote_addr,
        dst_ip=None,
        event_at=event_at,
        metadata_json=_notification_metadata_to_json(normalized_metadata),
    )
    db.session.add(alert_record)
    db.session.flush()
    return alert_record


def _build_failure_notification_body(job_state, error_text) -> str:
    upload_name = (
        Path(job_state.upload_path).name
        if getattr(job_state, "upload_path", None)
        else "analysis job"
    )
    error_lines = [
        line.strip() for line in str(error_text or "").splitlines() if line.strip()
    ]
    detail = error_lines[-1] if error_lines else "Unexpected processing error."
    return f"Analysis failed for {upload_name}: {detail}"


def _create_job_started_notification(job_state):
    if not getattr(job_state, "owner_user_id", None):
        return None
    upload_name = (
        Path(job_state.upload_path).name
        if getattr(job_state, "upload_path", None)
        else "PCAP capture"
    )
    return create_user_notification(
        job_state.owner_user_id,
        NOTIFICATION_TYPE_JOB_STARTED,
        "PCAP analysis started",
        f"Queued analysis for {upload_name}. We'll notify you when results are ready.",
        severity=NOTIFICATION_SEVERITY_INFO,
        job_id=getattr(job_state, "job_id", None),
        metadata=_build_job_notification_metadata(job_state),
    )


def _create_job_completed_notifications(job_state, report):
    if not getattr(job_state, "owner_user_id", None):
        return

    summary_text = build_analysis_notification_summary(report)
    signal_context = _build_report_alert_signal_context(report)
    metadata = _build_job_notification_metadata(job_state, report, extra=signal_context)
    job_id = getattr(job_state, "job_id", None)

    create_user_notification(
        job_state.owner_user_id,
        NOTIFICATION_TYPE_JOB_COMPLETED,
        "PCAP analysis completed",
        summary_text,
        severity=NOTIFICATION_SEVERITY_SUCCESS,
        job_id=job_id,
        metadata=metadata,
    )

    create_user_notification(
        job_state.owner_user_id,
        NOTIFICATION_TYPE_REPORT_READY,
        "PCAP report ready",
        "Report JSON is ready for export.",
        severity=NOTIFICATION_SEVERITY_SUCCESS,
        job_id=job_id,
        metadata={**metadata, "artifact_type": "report"},
    )

    if bool(getattr(job_state, "evidence_dir", None)):
        create_user_notification(
            job_state.owner_user_id,
            NOTIFICATION_TYPE_EVIDENCE_READY,
            "PCAP evidence ready",
            "Zeek evidence bundle is ready for export.",
            severity=NOTIFICATION_SEVERITY_INFO,
            job_id=job_id,
            metadata={**metadata, "artifact_type": "evidence"},
        )

    critical_detected = _safe_int(signal_context.get("critical_count"), 0) > 0 or (
        str(signal_context.get("risk_level") or "").strip().lower() == "critical"
        and _safe_int(signal_context.get("malicious_count"), 0) > 0
    )
    suspicious_detected = (
        _safe_int(signal_context.get("suspicious_count"), 0) > 0
        or _safe_int(signal_context.get("malicious_count"), 0) > 0
    )

    if critical_detected:
        create_user_notification(
            job_state.owner_user_id,
            NOTIFICATION_TYPE_CRITICAL_DETECTED,
            "Critical threat activity detected",
            summary_text,
            severity=NOTIFICATION_SEVERITY_CRITICAL,
            job_id=job_id,
            metadata=metadata,
        )
        user = User.query.get(int(job_state.owner_user_id))
        _send_security_event_telegram_notification(
            title="Critical threat activity detected",
            body=summary_text,
            user=user,
            severity="Critical",
            category="Security Alert",
            extra_lines=[
                f"Job ID: {job_id or 'n/a'}",
                f"Risk level: {str(signal_context.get('risk_level') or 'Critical')}",
            ],
        )
    elif suspicious_detected:
        create_user_notification(
            job_state.owner_user_id,
            NOTIFICATION_TYPE_SUSPICIOUS_DETECTED,
            "Suspicious network activity detected",
            summary_text,
            severity=NOTIFICATION_SEVERITY_WARNING,
            job_id=job_id,
            metadata=metadata,
        )
        high_detected = (
            _safe_int(signal_context.get("high_count"), 0) > 0
            or str(signal_context.get("risk_level") or "").strip().lower() == "high"
        )
        if high_detected:
            user = User.query.get(int(job_state.owner_user_id))
            _send_security_event_telegram_notification(
                title="High-risk network activity detected",
                body=summary_text,
                user=user,
                severity="High",
                category="Security Alert",
                extra_lines=[
                    f"Job ID: {job_id or 'n/a'}",
                    f"Risk level: {str(signal_context.get('risk_level') or 'High')}",
                ],
            )


def _create_job_failed_notification(job_state, error_text):
    if not getattr(job_state, "owner_user_id", None):
        return None
    return create_user_notification(
        job_state.owner_user_id,
        NOTIFICATION_TYPE_JOB_FAILED,
        "PCAP analysis failed",
        _build_failure_notification_body(job_state, error_text),
        severity=NOTIFICATION_SEVERITY_ERROR,
        job_id=getattr(job_state, "job_id", None),
        metadata=_build_job_notification_metadata(
            job_state, extra={"error": str(error_text or "")}
        ),
    )


def _notify_job_success(job_state, report):
    with app.app_context():
        try:
            owner_user_id = _safe_int(getattr(job_state, "owner_user_id", None), 0)
            upload_name = (
                Path(job_state.upload_path).name
                if getattr(job_state, "upload_path", None)
                else str(getattr(job_state, "job_id", "pcap"))
            )
            summary = report.get("summary") if isinstance(report, dict) else {}
            summary = summary if isinstance(summary, dict) else {}
            alerts_count = _safe_int(summary.get("alerts_count"), 0)
            suspicious_count = _safe_int(summary.get("suspicious"), 0)
            malicious_count = _safe_int(summary.get("malicious"), 0)
            total_flows = _safe_int(summary.get("total_flows"), 0)
            risk_level = str(summary.get("risk_level") or "Normal").strip() or "Normal"
            overall_risk = _safe_float(summary.get("overall_risk"), 0.0)
            normalized_risk_score = clamp_risk_score(overall_risk * 100)
            has_threat_signal = any(
                value > 0 for value in (alerts_count, suspicious_count, malicious_count)
            ) or risk_level.lower() not in {"normal", "safe", "low"}

            if owner_user_id > 0:
                _log_pcap_analysis_activity(
                    action_type="pcap_analysis_completed",
                    user_id=owner_user_id,
                    job_id=str(job_state.job_id),
                    upload_name=upload_name,
                    file_hash=getattr(job_state, "file_hash", None),
                    description=build_analysis_notification_summary(report),
                    status=STATUS_SUCCESS,
                    severity=SEVERITY_MEDIUM if not has_threat_signal else SEVERITY_HIGH,
                    risk_score=normalized_risk_score,
                    is_suspicious=has_threat_signal,
                    metadata={
                        "risk_level": risk_level,
                        "alerts_count": alerts_count,
                        "suspicious_count": suspicious_count,
                        "malicious_count": malicious_count,
                        "total_flows": total_flows,
                    },
                    commit=False,
                )
                _log_pcap_analysis_activity(
                    action_type=(
                        "pcap_threat_detected"
                        if has_threat_signal
                        else "pcap_safe_result_recorded"
                    ),
                    user_id=owner_user_id,
                    job_id=str(job_state.job_id),
                    upload_name=upload_name,
                    file_hash=getattr(job_state, "file_hash", None),
                    description=(
                        "Threat-related indicators were produced by the completed PCAP analysis."
                        if has_threat_signal
                        else "The completed PCAP analysis concluded without elevated threat indicators."
                    ),
                    status=STATUS_WARNING if has_threat_signal else STATUS_SUCCESS,
                    severity=SEVERITY_HIGH if has_threat_signal else SEVERITY_LOW,
                    risk_score=normalized_risk_score,
                    is_suspicious=has_threat_signal,
                    metadata={
                        "risk_level": risk_level,
                        "alerts_count": alerts_count,
                        "suspicious_count": suspicious_count,
                        "malicious_count": malicious_count,
                    },
                    commit=False,
                )
                db.session.commit()
        except Exception:
            db.session.rollback()
            logging.exception(
                "Failed to record centralized PCAP success activity for job %s",
                getattr(job_state, "job_id", None),
            )
        try:
            _persist_pcap_alert_records(job_state, report)
        except Exception:
            logging.exception(
                "Failed to persist PCAP alert records for job %s", job_state.job_id
            )
        try:
            _create_job_completed_notifications(job_state, report)
        except Exception:
            logging.exception(
                "Failed to create completion notifications for job %s", job_state.job_id
            )
        try:
            _send_pcap_completion_email(job_state, report)
        except Exception:
            logging.exception(
                "Failed to send PCAP completion email for job %s", job_state.job_id
            )
        try:
            _send_pcap_completion_telegram(job_state, report)
        except Exception:
            logging.exception(
                "Failed to send PCAP completion Telegram for job %s",
                job_state.job_id,
            )
        try:
            if getattr(job_state, "owner_user_id", None):
                gamification_service.record_analysis_completion(
                    int(job_state.owner_user_id),
                    str(job_state.job_id),
                    getattr(job_state, "file_hash", None),
                    report,
                    upload_name=(
                        Path(job_state.upload_path).name
                        if getattr(job_state, "upload_path", None)
                        else None
                    ),
                )
        except Exception:
            logging.exception(
                "Failed to record gamification completion events for job %s",
                job_state.job_id,
            )


def _notify_job_failure(job_state, error_text):
    with app.app_context():
        try:
            owner_user_id = _safe_int(getattr(job_state, "owner_user_id", None), 0)
            if owner_user_id > 0:
                _log_pcap_analysis_activity(
                    action_type="pcap_analysis_failed",
                    user_id=owner_user_id,
                    job_id=str(job_state.job_id),
                    upload_name=(
                        Path(job_state.upload_path).name
                        if getattr(job_state, "upload_path", None)
                        else str(getattr(job_state, "job_id", "pcap"))
                    ),
                    file_hash=getattr(job_state, "file_hash", None),
                    description=_summarize_job_error(error_text)
                    or "The PCAP analysis pipeline ended in a failure state.",
                    status=STATUS_FAILED,
                    severity=SEVERITY_HIGH,
                    risk_score=72,
                    is_suspicious=True,
                    metadata={"error": _summarize_job_error(error_text) or str(error_text or "")},
                    commit=True,
                )
        except Exception:
            db.session.rollback()
            logging.exception(
                "Failed to record centralized PCAP failure activity for job %s",
                getattr(job_state, "job_id", None),
            )
        try:
            _create_job_failed_notification(job_state, error_text)
        except Exception:
            logging.exception(
                "Failed to create failure notifications for job %s", job_state.job_id
            )
        try:
            if getattr(job_state, "owner_user_id", None):
                gamification_service.record_analysis_failure(
                    int(job_state.owner_user_id),
                    str(job_state.job_id),
                    getattr(job_state, "file_hash", None),
                    error_text,
                )
        except Exception:
            logging.exception(
                "Failed to record gamification failure event for job %s",
                job_state.job_id,
            )


