def send_email(to_address, subject, html_body, text_body=None):
    smtp_host = app.config["MAIL_SERVER"]
    smtp_port = app.config["MAIL_PORT"]
    smtp_user = app.config["MAIL_USERNAME"]
    smtp_pass = app.config["MAIL_PASSWORD"]
    smtp_from = app.config.get("MAIL_DEFAULT_SENDER") or smtp_user
    use_ssl = bool(app.config.get("MAIL_USE_SSL"))
    use_tls = bool(app.config.get("MAIL_USE_TLS"))

    msg = MIMEMultipart("alternative")
    msg["Subject"] = subject
    msg["From"] = smtp_from
    msg["To"] = to_address

    if text_body:
        text_part = MIMEText(text_body, "plain", "utf-8")
        msg.attach(text_part)

    html_part = MIMEText(html_body, "html", "utf-8")
    msg.attach(html_part)

    smtp_client = smtplib.SMTP_SSL if use_ssl else smtplib.SMTP
    with smtp_client(smtp_host, smtp_port) as server:
        if use_tls and not use_ssl:
            server.starttls()
        server.login(smtp_user, smtp_pass)
        server.sendmail(smtp_user, to_address, msg.as_bytes())


def _friendly_smtp_error(exc: Exception) -> str:
    if isinstance(exc, smtplib.SMTPAuthenticationError):
        return (
            "SMTP authentication failed. For Gmail, use a valid 16-character App Password "
            "for MAIL_PASSWORD and make sure 2-Step Verification is enabled on the sender account."
        )
    if isinstance(exc, smtplib.SMTPRecipientsRefused):
        return "SMTP rejected the recipient email address."
    if isinstance(exc, smtplib.SMTPSenderRefused):
        return "SMTP rejected the sender address. Check MAIL_DEFAULT_SENDER and MAIL_USERNAME."
    if isinstance(exc, smtplib.SMTPConnectError):
        return "SMTP connection failed. Check MAIL_SERVER, MAIL_PORT, TLS/SSL settings, and network access."
    if isinstance(exc, smtplib.SMTPException):
        return f"SMTP delivery failed: {str(exc)[:180]}"
    return f"Email delivery failed: {str(exc)[:180]}"


def _telegram_default_chat_id(settings: dict | None = None) -> str:
    settings = settings or {}
    return str(
        settings.get("telegramChatId")
        or os.getenv("ADMIN_TELEGRAM_CHAT_ID", "")
        or os.getenv("TELEGRAM_CHAT_ID", "")
        or ""
    ).strip()


def _telegram_has_bot_token() -> bool:
    return bool(str(os.getenv("TELEGRAM_BOT_TOKEN", "") or "").strip())


def _telegram_is_configured(settings: dict | None = None) -> bool:
    return bool(_telegram_has_bot_token() and _telegram_default_chat_id(settings))


def _send_telegram_notification_result(message: str, chat_id_override: str | None = None) -> dict:
    bot_token = str(os.getenv("TELEGRAM_BOT_TOKEN", "") or "").strip()
    chat_id = str(chat_id_override or _telegram_default_chat_id() or "").strip()
    normalized_message = str(message or "").strip()

    if not bot_token:
        return {"success": False, "error": "TELEGRAM_BOT_TOKEN is not configured."}
    if not chat_id:
        return {"success": False, "error": "Telegram chat ID is not configured."}
    if not normalized_message:
        return {"success": False, "error": "Telegram message is empty."}

    url = f"https://api.telegram.org/bot{bot_token}/sendMessage"
    payload = {
        "chat_id": chat_id,
        "text": normalized_message,
        "parse_mode": "HTML",
        "disable_web_page_preview": True,
    }

    try:
        response = requests.post(
            url,
            json=payload,
            timeout=TELEGRAM_REQUEST_TIMEOUT,
        )
        if response.ok:
            return {"success": True, "error": ""}

        failure = f"Telegram API returned HTTP {response.status_code}."
        logging.warning(
            "Telegram notification failed | status=%s | body=%s",
            response.status_code,
            (response.text or "")[:300],
        )
        return {"success": False, "error": failure}
    except requests.Timeout:
        logging.warning("Telegram notification timed out")
        return {"success": False, "error": "Telegram request timed out."}
    except requests.RequestException:
        logging.exception("Telegram notification request failed")
        return {"success": False, "error": "Telegram request failed."}
    except Exception:
        logging.exception("Unexpected Telegram notification failure")
        return {"success": False, "error": "Unexpected Telegram notification failure."}


def send_telegram_notification(message: str, chat_id_override: str | None = None) -> bool:
    return bool(
        _send_telegram_notification_result(message, chat_id_override=chat_id_override).get(
            "success"
        )
    )


def _format_telegram_message(title: str, body: str, extra_lines=None) -> str:
    lines = [
        f"<b>{escape(str(title or '').strip() or 'Sentinel AI Notification')}</b>",
        escape(str(body or "").strip()),
    ]

    for line in extra_lines or []:
        normalized = str(line or "").strip()
        if normalized:
            lines.append(escape(normalized))

    return "\n".join(line for line in lines if line)


def _send_security_event_telegram_notification(
    *,
    title: str,
    body: str,
    user=None,
    severity: str | None = None,
    category: str | None = None,
    extra_lines=None,
) -> bool:
    """
    Send security event notifications via Telegram to admin/security team only.
    
    Telegram notifications are restricted to admin-level alerts and critical events,
    and are sent to the admin Telegram chat ID configured in admin settings,
    not to individual user accounts.
    """
    # Only send Telegram for high-priority admin/security-team alerts.
    severity_level = str(severity or "").strip().lower()
    is_high_priority = severity_level in {"critical", "high"}
    if not is_high_priority:
        logging.info(
            "Telegram notification skipped: severity=%s (only high/critical events sent to admin)",
            severity,
        )
        return False

    notification_settings = _read_admin_notification_control_settings()
    if not bool(notification_settings.get("telegramEnabled", True)):
        logging.info(
            "Telegram notification skipped: admin has disabled Telegram notifications"
        )
        return False

    details = []
    if user is not None:
        user_email = str(getattr(user, "email", "") or "").strip()
        if user_email:
            details.append(f"Triggered by: {user_email}")
    if severity:
        details.append(f"Severity: {severity}")
    if category:
        details.append(f"Category: {category}")
    details.extend(extra_lines or [])

    # Send to the admin/security-team destination, not to individual user accounts.
    admin_chat_id = _telegram_default_chat_id(notification_settings)
    return send_telegram_notification(
        _format_telegram_message(title, body, details),
        chat_id_override=admin_chat_id if admin_chat_id else None,
    )


def _mask_channel_value(value: str | None, *, visible_prefix: int = 3, visible_suffix: int = 2) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""

    if len(raw) <= visible_prefix + visible_suffix:
        return raw

    masked_length = max(3, len(raw) - visible_prefix - visible_suffix)
    return f"{raw[:visible_prefix]}{'*' * masked_length}{raw[-visible_suffix:]}"


def _mail_is_configured() -> bool:
    required = ("MAIL_SERVER", "MAIL_USERNAME", "MAIL_PASSWORD")
    return all(str(app.config.get(key) or "").strip() for key in required)


def _is_email_notification_enabled_for_user(user) -> bool:
    if user is None:
        return False
    return bool(getattr(user, "email_notifications_enabled", True))


def _is_telegram_notification_enabled_for_user(user) -> bool:
    if user is None:
        return False
    return bool(getattr(user, "telegram_notifications_enabled", True))


def _serialize_user_settings_payload(user, auth_flags=None) -> dict:
    auth_flags = auth_flags or _user_auth_flags(user)
    return {
        "id": user.id,
        "email": user.email,
        "full_name": user.full_name,
        "phone": str(getattr(user, "phone", "") or "").strip(),
        "job_title": str(getattr(user, "job_title", "") or "").strip(),
        "company": str(getattr(user, "company", "") or "").strip(),
        "is_email_verified": auth_flags["email_verified"],
        "email_notifications_enabled": _is_email_notification_enabled_for_user(user),
        "is_two_factor_enabled": auth_flags["two_factor_enabled"],
        "two_factor_setup_complete": auth_flags["two_factor_setup_complete"],
        "auto_lock_minutes": int(getattr(user, "auto_lock_minutes", 15) or 15),
        "session_timeout_minutes": int(
            getattr(user, "session_timeout_minutes", 30) or 30
        ),
    }


def _normalize_linked_account_email(value: str | None) -> str:
    return str(value or "").strip().lower()


def _is_valid_linked_account_email(value: str | None) -> bool:
    normalized = _normalize_linked_account_email(value)
    return bool(
        normalized
        and len(normalized) <= 255
        and re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", normalized)
    )


def _normalize_linked_account_type(value: str | None) -> Optional[str]:
    normalized = str(value or "").strip().lower()
    if normalized in VALID_LINKED_ACCOUNT_TYPES:
        return normalized
    return None


def _normalize_linked_account_status(value: str | None) -> Optional[str]:
    normalized = str(value or "").strip().lower()
    if normalized in VALID_LINKED_ACCOUNT_STATUSES:
        return normalized
    return None


def _linked_account_iso(dt_value) -> Optional[str]:
    normalized = _to_utc_aware(dt_value)
    return normalized.isoformat() if normalized else None


def _latest_linked_account_access_at(user_id: int, email_normalized: str):
    normalized_email = _normalize_linked_account_email(email_normalized)
    if user_id <= 0 or not normalized_email:
        return None

    latest_event = (
        UserActivityLog.query.filter(UserActivityLog.user_id == int(user_id))
        .filter(
            or_(
                func.lower(UserActivityLog.target_label) == normalized_email,
                func.lower(UserActivityLog.target_id) == normalized_email,
            )
        )
        .order_by(UserActivityLog.created_at.desc())
        .first()
    )
    return getattr(latest_event, "created_at", None) if latest_event else None


def _get_user_linked_accounts(user_id: int) -> list[LinkedAccount]:
    return (
        LinkedAccount.query.filter_by(user_id=int(user_id))
        .order_by(
            LinkedAccount.account_type.asc(),
            LinkedAccount.created_at.asc(),
            LinkedAccount.id.asc(),
        )
        .all()
    )


def _sync_primary_account_for_user(user_id: int) -> None:
    accounts = _get_user_linked_accounts(user_id)
    if not accounts:
        return

    primary_accounts = [
        account
        for account in accounts
        if _normalize_linked_account_type(account.account_type)
        == LINKED_ACCOUNT_TYPE_PRIMARY
    ]
    if len(primary_accounts) == 1:
        return

    primary_account = primary_accounts[0] if primary_accounts else accounts[0]
    for account in accounts:
        account.account_type = (
            LINKED_ACCOUNT_TYPE_PRIMARY
            if account.id == primary_account.id
            else LINKED_ACCOUNT_TYPE_SECONDARY
        )


def _create_linked_account_verification_state() -> tuple[str, datetime]:
    return secrets.token_urlsafe(32), datetime.now(UTC) + timedelta(hours=24)


def _is_linked_account_verified(account: LinkedAccount, user: User | None = None) -> bool:
    if account is None:
        return False

    normalized_account_email = _normalize_linked_account_email(account.email_normalized)
    normalized_user_email = _normalize_linked_account_email(
        getattr(user, "email", "") if user is not None else ""
    )
    if normalized_account_email and normalized_account_email == normalized_user_email:
        return bool(user and getattr(user, "is_email_verified", False))

    return (
        _normalize_linked_account_status(account.verification_status)
        == LINKED_ACCOUNT_STATUS_VERIFIED
    )


def _linked_account_matches_login_identifier(
    user: User | None, login_identifier: str | None
) -> LinkedAccount | None:
    normalized_email = _normalize_linked_account_email(login_identifier)
    if user is None or not getattr(user, "id", None) or not normalized_email:
        return None

    return LinkedAccount.query.filter_by(
        user_id=int(user.id), email_normalized=normalized_email
    ).first()


def _login_identifier_belongs_to_user(user: User | None, login_identifier: str | None) -> bool:
    normalized_email = _normalize_linked_account_email(login_identifier)
    if user is None or not normalized_email:
        return False

    if normalized_email == _normalize_linked_account_email(getattr(user, "email", "")):
        return True

    linked_account = _linked_account_matches_login_identifier(user, normalized_email)
    return linked_account is not None and _is_linked_account_verified(linked_account, user)


def _resolve_login_user_and_account(
    login_identifier: str | None,
) -> tuple[User | None, LinkedAccount | None]:
    normalized_email = _normalize_linked_account_email(login_identifier)
    if not normalized_email:
        return None, None

    user = User.query.filter_by(email=normalized_email).first()
    if user is not None:
        linked_account = _linked_account_matches_login_identifier(user, normalized_email)
        return user, linked_account

    linked_account = LinkedAccount.query.filter_by(email_normalized=normalized_email).first()
    if linked_account is None:
        return None, None

    user = User.query.filter_by(id=int(linked_account.user_id)).first()
    if user is None:
        return None, None

    return user, linked_account


def _update_linked_account_last_access(
    user: User | None, login_identifier: str | None
) -> LinkedAccount | None:
    linked_account = _linked_account_matches_login_identifier(user, login_identifier)
    if linked_account is None:
        return None

    linked_account.last_access_at = datetime.now(UTC)
    linked_account.updated_at = datetime.now(UTC)
    return linked_account


def _find_linked_identity_conflict(
    owner_user_id: int, email_normalized: str, exclude_account_id: int | None = None
) -> str | None:
    normalized_email = _normalize_linked_account_email(email_normalized)
    if owner_user_id <= 0 or not normalized_email:
        return None

    existing_user = User.query.filter(
        func.lower(User.email) == normalized_email, User.id != int(owner_user_id)
    ).first()
    if existing_user is not None:
        return "This email already belongs to another Sentinel AI account."

    existing_link = LinkedAccount.query.filter(
        LinkedAccount.email_normalized == normalized_email,
        LinkedAccount.user_id != int(owner_user_id),
    )
    if exclude_account_id is not None:
        existing_link = existing_link.filter(LinkedAccount.id != int(exclude_account_id))

    if existing_link.first() is not None:
        return "This email is already linked to another Sentinel AI account."

    return None


def _send_linked_account_verification_email(linked_account: LinkedAccount, owner_user: User) -> None:
    if linked_account is None or owner_user is None:
        return

    token = str(linked_account.verification_token or "").strip()
    if not token:
        return

    verify_link = f"{FRONTEND_BASE_URL}/verify-email?token={token}"
    linked_email = str(linked_account.email or "").strip()
    owner_email = str(getattr(owner_user, "email", "") or "").strip()
    expires_at = _to_utc_aware(linked_account.verification_expires_at) or (
        datetime.now(UTC) + timedelta(hours=24)
    )
    expires_label = expires_at.strftime("%b %d, %Y %I:%M %p UTC")

    text_body = f"""
Hello,

You've been invited to use {linked_email} as a linked sign-in email for your Sentinel AI account.

Verify this linked email to sign in with the same account security profile:
{verify_link}

This verification link expires on {expires_label}.
Primary account: {owner_email or "Sentinel AI account"}

If you did not expect this message, you can ignore it and the linked email will remain inactive.
""".strip()

    html_body = f"""
    <div style="font-family: Arial, sans-serif; background:#0f172a; color:#e5eefc; padding:32px;">
      <div style="max-width:640px; margin:0 auto; background:linear-gradient(180deg, rgba(15,23,42,0.98), rgba(10,15,28,0.98)); border:1px solid rgba(96,165,250,0.18); border-radius:24px; padding:32px;">
        <div style="font-size:13px; letter-spacing:0.2em; text-transform:uppercase; color:#38bdf8; margin-bottom:12px;">Sentinel AI</div>
        <h1 style="margin:0 0 12px; font-size:28px; line-height:1.2; color:#ffffff;">Verify your linked sign-in email</h1>
        <p style="margin:0 0 16px; color:#cbd5e1; line-height:1.8;">
          <strong>{linked_email}</strong> was added to your Sentinel AI account and can be used to sign in after verification.
        </p>
        <p style="margin:0 0 24px; color:#94a3b8; line-height:1.8;">
          Primary account owner: <strong>{owner_email or "Sentinel AI account"}</strong><br />
          This link expires on <strong>{expires_label}</strong>.
        </p>
        <a href="{verify_link}" style="display:inline-block; padding:14px 22px; border-radius:14px; background:linear-gradient(90deg,#2563eb,#22d3ee); color:#02111f; font-weight:700; text-decoration:none;">Verify linked email</a>
        <p style="margin:24px 0 0; color:#64748b; line-height:1.8;">
          If you did not expect this message, you can safely ignore it. The linked email will remain pending until verified.
        </p>
      </div>
    </div>
    """

    send_email(
        to_address=linked_email,
        subject="Verify your linked Sentinel AI email",
        html_body=html_body,
        text_body=text_body,
    )


def _serialize_linked_account(account: LinkedAccount, user: User) -> dict:
    normalized_account_email = _normalize_linked_account_email(account.email_normalized)
    normalized_user_email = _normalize_linked_account_email(getattr(user, "email", ""))
    is_current_auth_email = normalized_account_email == normalized_user_email
    account_type = (
        _normalize_linked_account_type(account.account_type)
        or LINKED_ACCOUNT_TYPE_SECONDARY
    )
    verification_status = (
        LINKED_ACCOUNT_STATUS_VERIFIED
        if is_current_auth_email and bool(getattr(user, "is_email_verified", False))
        else _normalize_linked_account_status(account.verification_status)
        or LINKED_ACCOUNT_STATUS_PENDING
    )
    two_factor_enabled = (
        bool(getattr(user, "is_two_factor_enabled", False))
        if is_current_auth_email
        else bool(account.two_factor_enabled)
    )
    last_access_at = account.last_access_at or _latest_linked_account_access_at(
        int(user.id), normalized_account_email
    )

    return {
        "id": int(account.id),
        "email": str(account.email or "").strip(),
        "email_normalized": normalized_account_email,
        "account_type": account_type,
        "verification_status": verification_status,
        "is_verified": verification_status == LINKED_ACCOUNT_STATUS_VERIFIED,
        "two_factor_enabled": two_factor_enabled,
        "last_access_at": _linked_account_iso(last_access_at),
        "created_at": _linked_account_iso(account.created_at),
        "updated_at": _linked_account_iso(account.updated_at),
        "is_primary": account_type == LINKED_ACCOUNT_TYPE_PRIMARY,
        "is_current_auth_email": is_current_auth_email,
        "can_edit_two_factor": not is_current_auth_email,
        "can_edit_verification": False,
        "can_resend_verification": (
            not is_current_auth_email
            and verification_status == LINKED_ACCOUNT_STATUS_PENDING
        ),
        "can_delete": account_type != LINKED_ACCOUNT_TYPE_PRIMARY,
        "delete_block_reason": (
            "The current primary account must be replaced before it can be removed."
            if account_type == LINKED_ACCOUNT_TYPE_PRIMARY
            else None
        ),
    }


def _ensure_default_linked_account_for_user(user: User) -> None:
    if user is None or not getattr(user, "id", None):
        return

    existing = LinkedAccount.query.filter_by(user_id=int(user.id)).count()
    if existing > 0:
        _sync_primary_account_for_user(int(user.id))
        db.session.commit()
        return

    normalized_email = _normalize_linked_account_email(getattr(user, "email", ""))
    if not normalized_email:
        return

    default_account = LinkedAccount(
        user_id=int(user.id),
        email=str(getattr(user, "email", "") or "").strip(),
        email_normalized=normalized_email,
        account_type=LINKED_ACCOUNT_TYPE_PRIMARY,
        verification_status=(
            LINKED_ACCOUNT_STATUS_VERIFIED
            if bool(getattr(user, "is_email_verified", False))
            else LINKED_ACCOUNT_STATUS_PENDING
        ),
        verification_token=None,
        verification_expires_at=None,
        two_factor_enabled=bool(getattr(user, "is_two_factor_enabled", False)),
        last_access_at=_latest_linked_account_access_at(int(user.id), normalized_email),
    )
    db.session.add(default_account)
    db.session.commit()


def _linked_accounts_payload_for_user(user: User) -> list[dict]:
    _ensure_default_linked_account_for_user(user)
    accounts = _get_user_linked_accounts(int(user.id))
    return [_serialize_linked_account(account, user) for account in accounts]


def _get_top_cluster_email_context(report) -> dict:
    clusters = report.get("clusters") if isinstance(report, dict) else []
    clusters = clusters if isinstance(clusters, list) else []
    if not clusters:
        return {}

    top_cluster = clusters[0] if isinstance(clusters[0], dict) else {}
    return {
        "attack_type": str(top_cluster.get("attack_type") or "").strip(),
        "src_ip": str(
            top_cluster.get("source_ip") or top_cluster.get("src_ip") or ""
        ).strip(),
        "dst_ip": str(
            top_cluster.get("dest_ip") or top_cluster.get("dst_ip") or ""
        ).strip(),
        "count_flows": _safe_int(top_cluster.get("count_flows"), 0),
        "max_threat_confidence": _safe_float(
            top_cluster.get("max_threat_confidence")
            or top_cluster.get("max_confidence"),
            0.0,
        ),
    }


def _build_pcap_job_url(job_state) -> Optional[str]:
    job_id = str(getattr(job_state, "job_id", "") or "").strip()
    frontend_base = str(FRONTEND_BASE_URL or "").strip().rstrip("/")
    if not frontend_base or not job_id:
        return None
    return f"{frontend_base}/pcap-analyzer?job={quote(job_id)}"


def _build_pcap_completion_email_payload(
    user, job_state, report
) -> tuple[str, str, str]:
    summary = report.get("summary") if isinstance(report, dict) else {}
    summary = summary if isinstance(summary, dict) else {}

    user_name = (
        str(getattr(user, "full_name", "") or "").strip()
        or str(getattr(user, "email", "") or "Sentinel user").strip()
    )
    job_id = str(getattr(job_state, "job_id", "") or "").strip() or "unknown"
    risk_level = str(summary.get("risk_level") or "Normal").strip() or "Normal"
    total_flows = _safe_int(summary.get("total_flows"), 0)
    alerts_count = _safe_int(summary.get("alerts_count"), 0)
    suspicious_count = _safe_int(summary.get("suspicious"), 0)
    malicious_count = _safe_int(summary.get("malicious"), 0)
    overall_risk = _safe_float(summary.get("overall_risk"), 0.0)
    evidence_available = bool(getattr(job_state, "evidence_dir", None))
    summary_text = build_analysis_notification_summary(report)
    top_cluster = _get_top_cluster_email_context(report)
    job_url = _build_pcap_job_url(job_state)

    cluster_text = "No promoted attack cluster was identified in this run."
    cluster_html = (
        '<div style="color:#94a3b8;font-size:14px;line-height:1.7;">'
        "No promoted attack cluster was identified in this run."
        "</div>"
    )
    if top_cluster.get("attack_type"):
        attack_type = escape(str(top_cluster.get("attack_type") or ""))
        src_ip = escape(str(top_cluster.get("src_ip") or ""))
        dst_ip = escape(str(top_cluster.get("dst_ip") or ""))
        raw_attack_type = str(top_cluster.get("attack_type") or "")
        raw_src_ip = str(top_cluster.get("src_ip") or "")
        raw_dst_ip = str(top_cluster.get("dst_ip") or "")
        flow_count = _safe_int(top_cluster.get("count_flows"), 0)
