def _create_jwt_token(user_id, expires_delta, auth_state=FULL_AUTH_STATE, extra=None):
    exp = datetime.now(UTC) + expires_delta
    payload = {"sub": str(user_id), "exp": exp, "auth_state": auth_state}
    if extra:
        payload.update(extra)
    return jwt.encode(payload, JWT_SECRET, algorithm=JWT_ALGO)


def create_access_token(user_id):
    user = User.query.get(int(user_id))
    session_version = _get_user_session_version(user)
    return _create_jwt_token(
        user_id,
        timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES),
        auth_state=FULL_AUTH_STATE,
        extra={"session_version": session_version},
    )


def create_pending_2fa_token(user_id, auth_state, expires_minutes, extra=None):
    return _create_jwt_token(
        user_id,
        timedelta(minutes=expires_minutes),
        auth_state=auth_state,
        extra=extra,
    )


