def create_refresh_token(user_id):
    token = secrets.token_urlsafe(64)
    exp = datetime.now(UTC) + timedelta(days=REFRESH_TOKEN_EXPIRE_DAYS)
    user_agent = str(request.headers.get("User-Agent") or "").strip()[:300]

    rt = RefreshToken(
        user_id=user_id,
        token=token,
        expires_at=exp,
        user_agent=user_agent or None,
    )
    db.session.add(rt)
    db.session.commit()

    return token


def set_cookie(response, name, value, max_age):
    response.set_cookie(
        name,
        value,
        max_age=max_age,
        httponly=True,
        secure=bool(app.config.get("SESSION_COOKIE_SECURE", False)),
        samesite="Lax",
        path="/",
    )


def clear_auth_cookies(response):
    response.delete_cookie("access_token", path="/")
    response.delete_cookie("refresh_token", path="/")


def clear_pending_2fa_cookie(response):
    response.delete_cookie(PENDING_2FA_TOKEN_COOKIE, path="/")


def _record_successful_login_timestamp(user: User | None, sign_in_email: str | None = None) -> None:
    if user is None:
        return
    try:
        user.last_login_at = datetime.now(UTC)
        user.updated_at = datetime.now(UTC)
        _update_linked_account_last_access(user, sign_in_email or getattr(user, "email", ""))
        db.session.commit()
    except Exception:
        db.session.rollback()
        logging.exception(
            "Failed to update last login timestamp | user_id=%s",
            getattr(user, "id", None),
        )


def _issue_full_auth_response(user, message=None, sign_in_email=None):
    user_agent = str(request.headers.get("User-Agent") or "").strip()[:300]
    current_device_fingerprint = _request_device_fingerprint()
    normalized_sign_in_email = _normalize_linked_account_email(
        sign_in_email or getattr(user, "email", "")
    )
    prior_login_count = (
        RefreshToken.query.filter_by(user_id=int(user.id), user_agent=user_agent or None)
        .count()
        if user_agent
        else 0
    )
    is_new_device = prior_login_count == 0

    access_token = create_access_token(user.id)
    refresh_token = create_refresh_token(user.id)

    try:
        user.last_login_at = datetime.now(UTC)
        user.updated_at = datetime.now(UTC)
        access_account = _update_linked_account_last_access(user, normalized_sign_in_email)
        log_user_event(
            user_id=user.id,
            module=MODULE_AUTH,
            action_type="login_success",
            title=USER_ACTIVITY_LABELS["login_success"],
            description="Account authentication completed successfully.",
            status=STATUS_SUCCESS,
            severity=SEVERITY_LOW if not is_new_device else SEVERITY_MEDIUM,
            is_sensitive=True,
            is_suspicious=is_new_device,
            target_type="account",
            target_id=normalized_sign_in_email or str(user.id),
            target_label=normalized_sign_in_email
            or str(getattr(user, "email", "") or "").strip()
            or "Account",
            metadata_json={
                "device_label": _request_device_label(),
                "device_fingerprint": current_device_fingerprint,
                "user_agent": user_agent,
                "login_flow": "2fa" if message else "password",
                "new_device": bool(is_new_device),
                "sign_in_email": normalized_sign_in_email
                or str(getattr(user, "email", "") or "").strip(),
                "linked_account_id": int(access_account.id) if access_account else None,
            },
        )
        if is_new_device:
            log_user_event(
                user_id=user.id,
                module=MODULE_AUTH,
                action_type="new_device_login",
                title=USER_ACTIVITY_LABELS["new_device_login"],
                description="A successful sign-in was observed from a device that has not been seen before.",
                status=STATUS_WARNING,
                severity=SEVERITY_HIGH,
                is_sensitive=True,
                is_suspicious=True,
                target_type="device",
                target_id=current_device_fingerprint,
                target_label=_request_device_label(),
                metadata_json={
                    "device_label": _request_device_label(),
                    "device_fingerprint": current_device_fingerprint,
                    "user_agent": user_agent,
                },
            )
        db.session.commit()
    except Exception:
        db.session.rollback()
        logging.exception("Failed to record login activity for user_id=%s", user.id)

    payload = {
        "success": True,
        "requires_2fa": False,
        "requires_2fa_setup": False,
        "pending_2fa": False,
        "email": normalized_sign_in_email
        or str(getattr(user, "email", "") or "").strip(),
        "token": access_token,
        "refresh_token": refresh_token,
    }
    if message:
        payload["message"] = message

    resp = jsonify(payload)
    set_cookie(resp, "access_token", access_token, ACCESS_TOKEN_EXPIRE_MINUTES * 60)
    set_cookie(resp, "refresh_token", refresh_token, REFRESH_TOKEN_EXPIRE_DAYS * 86400)
    clear_pending_2fa_cookie(resp)
    return resp


def _complete_flask_login_session_after_2fa(user):
    pending_session_user_id = session.get("pending_2fa_user_id")
    if pending_session_user_id is None:
        return (
            jsonify({"success": False, "message": "Pending 2FA session required"}),
            401,
        )
    if int(pending_session_user_id) != int(user.id):
        return (
            jsonify({"success": False, "message": "Pending 2FA session mismatch"}),
            403,
        )

    remember_after_2fa = bool(session.get("remember_after_2fa"))
    session.clear()
    session.permanent = remember_after_2fa
    session["user_id"] = int(user.id)
    return None


