@app.route("/api/auth/signup", methods=["POST"])
def signup():
    data = request.get_json() or {}

    full_name = data.get("fullName", "").strip()
    email = data.get("email", "").strip().lower()
    password = data.get("password", "")

    if not full_name or not email or not password:
        return jsonify({"success": False, "message": "Missing fields"}), 400

    if User.query.filter_by(email=email).first():
        return jsonify({"success": False, "message": "Email already exists"}), 409

    password_hash = generate_password_hash(password)

    verification_token = secrets.token_urlsafe(32)
    verification_exp = datetime.now(UTC) + timedelta(hours=24)

    user = User(
        full_name=full_name,
        phone=None,
        email=email,
        password_hash=password_hash,
        is_email_verified=False,
        email_verification_token=verification_token,
        email_verification_expires_at=verification_exp,
    )

    db.session.add(user)
    db.session.commit()

    email_sent = False
    email_delivery_error = None
    try:
        send_verification_email(user.email, verification_token)
        email_sent = True
    except smtplib.SMTPAuthenticationError:
        email_delivery_error = "SMTP authentication failed"
        logging.exception("Failed to send signup verification email: SMTP authentication failed")
    except Exception:
        email_delivery_error = "Verification email could not be sent"
        logging.exception("Failed to send signup verification email")

    message = (
        "Verification email sent"
        if email_sent
        else "Account created, but the verification email could not be sent. Check SMTP settings."
    )
    return (
        jsonify(
            {
                "success": True,
                "message": message,
                "email_sent": email_sent,
                "email_delivery_error": email_delivery_error,
            }
        ),
        201,
    )


@app.route("/api/auth/login", methods=["POST"])
def login():
    data = request.get_json() or {}

    email = _normalize_linked_account_email(data.get("email", ""))
    password = data.get("password", "")
    remember_requested = bool(data.get("remember") or data.get("rememberMe"))

    user, linked_account = _resolve_login_user_and_account(email)

    if not user or not check_password_hash(user.password_hash, password):
        if user:
            try:
                log_user_event(
                    user_id=user.id,
                    module=MODULE_AUTH,
                    action_type="login_failed",
                    title=USER_ACTIVITY_LABELS["login_failed"],
                    description="A login attempt failed because the supplied credentials were not accepted.",
                    status=STATUS_FAILED,
                    severity=SEVERITY_MEDIUM,
                    is_sensitive=True,
                    is_suspicious=True,
                    target_type="account",
                    target_id=str(user.id),
                    target_label=str(user.email or "").strip() or "Account",
                    metadata_json={
                        "reason": "invalid_credentials",
                        "device_label": _request_device_label(),
                        "device_fingerprint": _request_device_fingerprint(),
                        "user_agent": str(request.headers.get("User-Agent") or "")[:300],
                    },
                )

                failed_count = _recent_user_activity_count(
                    user.id, "login_failed", within_minutes=15
                )
                suspicious_recent_count = _recent_user_activity_count(
                    user.id, "suspicious_login_detected", within_minutes=15
                )
                if failed_count >= 3 and suspicious_recent_count == 0:
                    log_user_event(
                        user_id=user.id,
                        module=MODULE_AUTH,
                        action_type="suspicious_login_detected",
                        title=USER_ACTIVITY_LABELS["suspicious_login_detected"],
                        description="Multiple failed login attempts were detected in a short period.",
                        status=STATUS_WARNING,
                        severity=SEVERITY_CRITICAL,
                        risk_score=min(100, 45 + failed_count * 10),
                        is_sensitive=True,
                        is_suspicious=True,
                        target_type="account",
                        target_id=str(user.id),
                        target_label=str(user.email or "").strip() or "Account",
                        metadata_json={
                            "reason": "repeated_failed_logins",
                            "failed_attempts_last_15m": failed_count,
                            "device_fingerprint": _request_device_fingerprint(),
                            "device_label": _request_device_label(),
                        },
                    )
                    create_user_notification(
                        user.id,
                        "suspicious_login_detected",
                        "Critical suspicious login activity detected",
                        "Multiple failed login attempts were detected on your account in a short period.",
                        severity=NOTIFICATION_SEVERITY_CRITICAL,
                        metadata={
                            "reason": "repeated_failed_logins",
                            "failed_attempts_last_15m": failed_count,
                            "device_fingerprint": _request_device_fingerprint(),
                            "device_label": _request_device_label(),
                        },
                    )
                db.session.commit()
            except Exception:
                db.session.rollback()
                logging.exception(
                    "Failed to record failed login activity for user_id=%s", user.id
                )
        return jsonify({"success": False, "message": "Invalid credentials"}), 401

    if linked_account is not None and not _is_linked_account_verified(linked_account, user):
        return (
            jsonify(
                {
                    "success": False,
                    "message": "This linked email is still pending verification. Open the verification email first, then sign in with the same password.",
                }
            ),
            403,
        )

    if _is_user_locked(user):
        return (
            jsonify(
                {
                    "success": False,
                    "message": "This account is locked. Contact an administrator.",
                }
            ),
            423,
        )

    _, security_error = _enforce_user_security_state(user)
    if security_error:
        return security_error

    if not user.is_email_verified:
        return jsonify({"success": False, "message": "Email not verified"}), 403

    if is_two_factor_required(user):
        session.clear()
        session.permanent = False
        session["pending_2fa_user_id"] = int(user.id)
        session["remember_after_2fa"] = remember_requested

        if not is_two_factor_setup_complete(user):
            pending_token = create_pending_2fa_token(
                user.id,
                PENDING_2FA_SETUP_STATE,
                PENDING_2FA_SETUP_EXPIRE_MINUTES,
            )
            resp = jsonify(
                {
                    "success": True,
                    "requires_2fa": False,
                    "requires_2fa_setup": True,
                    "pending_2fa": True,
                    "pending_token": pending_token,
                    "email": email or user.email,
                }
            )
            clear_auth_cookies(resp)
            set_cookie(
                resp,
                PENDING_2FA_TOKEN_COOKIE,
                pending_token,
                PENDING_2FA_SETUP_EXPIRE_MINUTES * 60,
            )
            return resp

        pending_token = create_pending_2fa_token(
            user.id,
            PENDING_2FA_LOGIN_STATE,
            PENDING_2FA_LOGIN_EXPIRE_MINUTES,
        )
        resp = jsonify(
            {
                "success": True,
                "requires_2fa": True,
                "requires_2fa_setup": False,
                "pending_2fa": True,
                "pending_token": pending_token,
                "email": email or user.email,
            }
        )
        clear_auth_cookies(resp)
        set_cookie(
            resp,
            PENDING_2FA_TOKEN_COOKIE,
            pending_token,
            PENDING_2FA_LOGIN_EXPIRE_MINUTES * 60,
        )
        return resp

    resp = _issue_full_auth_response(user, sign_in_email=email or user.email)
    resp.headers["Access-Control-Allow-Credentials"] = "true"
    resp.headers["Access-Control-Allow-Origin"] = _response_allow_origin()
    return resp


@app.route("/api/auth/2fa/verify-login", methods=["POST"])
def verify_2fa_login():
    data = request.get_json() or {}
    code = data.get("code", "").strip()
    email = _normalize_linked_account_email(data.get("email", ""))
    user, _, auth_error = _get_pending_2fa_context({PENDING_2FA_LOGIN_STATE})
    if auth_error:
        return auth_error
    if email and not _login_identifier_belongs_to_user(user, email):
        return (
            jsonify({"success": False, "message": "Pending 2FA session mismatch"}),
            403,
        )
    if not user.two_factor_secret or not user.is_two_factor_enabled:
        return jsonify({"success": False, "message": "2FA not enabled"}), 400

    totp = pyotp.TOTP(user.two_factor_secret)

    if not totp.verify(code, valid_window=1):
        return jsonify({"success": False, "message": "Invalid 2FA code"}), 401

    session_error = _complete_flask_login_session_after_2fa(user)
    if session_error:
        return session_error

    resp = _issue_full_auth_response(
        user,
        message="2FA login successful",
        sign_in_email=email or user.email,
    )
    resp.headers["Access-Control-Allow-Credentials"] = "true"
    resp.headers["Access-Control-Allow-Origin"] = _response_allow_origin()
    return resp


@app.route("/api/auth/verify-email-token")
def verify_email():
    token = request.args.get("token", "")

    if not token:
        logging.warning("/api/auth/verify-email-token: No token provided")
        return jsonify({"success": False, "message": "No token provided"}), 400

    user = User.query.filter_by(email_verification_token=token).first()
    linked_account = None
    if not user:
        linked_account = LinkedAccount.query.filter_by(verification_token=token).first()
    if not user and not linked_account:
        logging.warning(
            f"/api/auth/verify-email-token: Token not found - {token[:20] if len(token) > 20 else token}..."
        )
        return (
            jsonify(
                {
                    "success": False,
                    "message": "This verification link is invalid or has already been used. Please sign up again or contact support.",
                }
            ),
            400,
        )

    if linked_account is not None:
        owner_user = User.query.filter_by(id=int(linked_account.user_id)).first()
        if owner_user is None:
            return (
                jsonify(
                    {
                        "success": False,
                        "message": "Linked account owner could not be found.",
                    }
                ),
                404,
            )

        expires_at = _to_utc_aware(linked_account.verification_expires_at)
        if expires_at and datetime.now(UTC) > expires_at:
            logging.warning(
                "Linked account verification token expired for email=%s",
                linked_account.email,
            )
            return (
                jsonify(
                    {
                        "success": False,
                        "message": "Verification link has expired. Please request a new one from Settings.",
                    }
                ),
                400,
            )

        if _is_linked_account_verified(linked_account, owner_user):
            response_payload = {
                "success": True,
                "email": str(linked_account.email or "").strip() or owner_user.email,
                "message": "Linked email already verified",
                "requires_2fa_setup": bool(
                    is_two_factor_required(owner_user)
                    and not is_two_factor_setup_complete(owner_user)
                ),
            }
        else:
            linked_account.verification_status = LINKED_ACCOUNT_STATUS_VERIFIED
            linked_account.verification_token = None
            linked_account.verification_expires_at = None
            linked_account.updated_at = datetime.now(UTC)
            linked_account.last_access_at = linked_account.last_access_at or datetime.now(UTC)
            db.session.commit()

            logging.info(
                "Successfully verified linked account email=%s for user_id=%s",
                linked_account.email,
                owner_user.id,
            )
            response_payload = {
                "success": True,
                "email": str(linked_account.email or "").strip() or owner_user.email,
                "message": "Linked email verified successfully",
                "requires_2fa_setup": bool(
                    is_two_factor_required(owner_user)
                    and not is_two_factor_setup_complete(owner_user)
                ),
            }

        if is_two_factor_required(owner_user) and not is_two_factor_setup_complete(owner_user):
            pending_token = create_pending_2fa_token(
                owner_user.id,
                PENDING_2FA_SETUP_STATE,
                PENDING_2FA_SETUP_EXPIRE_MINUTES,
            )
            response_payload.update(
                {
                    "pending_2fa": True,
                    "pending_token": pending_token,
                    "requires_2fa_setup": True,
                }
            )
            resp = jsonify(response_payload)
            clear_auth_cookies(resp)
            set_cookie(
                resp,
                PENDING_2FA_TOKEN_COOKIE,
                pending_token,
                PENDING_2FA_SETUP_EXPIRE_MINUTES * 60,
            )
            return resp

        resp = jsonify(response_payload)
        clear_pending_2fa_cookie(resp)
        return resp

    if user.email_verification_expires_at:
        expires_at = user.email_verification_expires_at
        if expires_at.tzinfo is None:
            expires_at = expires_at.replace(tzinfo=UTC)
        if datetime.now(UTC) > expires_at:
            logging.warning(
                f"/api/auth/verify-email-token: Token expired for user {user.email}"
            )
            return (
                jsonify(
                    {
                        "success": False,
                        "message": "Verification link has expired. Please request a new one.",
                    }
                ),
                400,
            )

    if user.is_email_verified:
        logging.info(
            f"/api/auth/verify-email-token: User {user.email} already verified"
        )
        resp = jsonify(
            {
                "success": True,
                "email": user.email,
                "message": "Email already verified",
                "requires_2fa_setup": bool(
                    is_two_factor_required(user)
                    and not is_two_factor_setup_complete(user)
                ),
            }
        )
        if is_two_factor_required(user) and not is_two_factor_setup_complete(user):
            pending_token = create_pending_2fa_token(
                user.id,
                PENDING_2FA_SETUP_STATE,
                PENDING_2FA_SETUP_EXPIRE_MINUTES,
            )
            resp = jsonify(
                {
                    "success": True,
                    "email": user.email,
                    "message": "Email already verified",
                    "requires_2fa_setup": True,
                    "pending_2fa": True,
                    "pending_token": pending_token,
                }
            )
            clear_auth_cookies(resp)
            set_cookie(
                resp,
                PENDING_2FA_TOKEN_COOKIE,
                pending_token,
                PENDING_2FA_SETUP_EXPIRE_MINUTES * 60,
            )
        else:
            clear_pending_2fa_cookie(resp)
        return resp

    user.is_email_verified = True
    user.email_verification_token = None
    user.email_verification_expires_at = None
    db.session.commit()

    logging.info(
        f"/api/auth/verify-email-token: Successfully verified email for {user.email}"
    )
    if is_two_factor_required(user) and not is_two_factor_setup_complete(user):
        pending_token = create_pending_2fa_token(
            user.id,
            PENDING_2FA_SETUP_STATE,
            PENDING_2FA_SETUP_EXPIRE_MINUTES,
        )
        resp = jsonify(
            {
                "success": True,
                "email": user.email,
                "requires_2fa_setup": True,
                "pending_2fa": True,
                "pending_token": pending_token,
            }
        )
        clear_auth_cookies(resp)
        set_cookie(
            resp,
            PENDING_2FA_TOKEN_COOKIE,
            pending_token,
            PENDING_2FA_SETUP_EXPIRE_MINUTES * 60,
        )
        return resp

    resp = jsonify({"success": True, "email": user.email, "requires_2fa_setup": False})
    clear_pending_2fa_cookie(resp)
    return resp


@app.route("/api/auth/verify-2fa", methods=["POST"])
def verify_2fa():
    data = request.get_json() or {}
    code = data.get("code", "").strip()
    email = _normalize_linked_account_email(data.get("email", ""))
    user, _, auth_error = _get_pending_2fa_context({PENDING_2FA_LOGIN_STATE})
    if auth_error:
        return auth_error
    if email and not _login_identifier_belongs_to_user(user, email):
        return (
            jsonify({"success": False, "message": "Pending 2FA session mismatch"}),
            403,
        )
    if not user.two_factor_secret or not user.is_two_factor_enabled:
        return jsonify({"success": False, "message": "2FA not enabled"}), 400

    totp = pyotp.TOTP(user.two_factor_secret)
    if not totp.verify(code, valid_window=1):
        return jsonify({"success": False, "message": "Invalid code"}), 401

    session_error = _complete_flask_login_session_after_2fa(user)
    if session_error:
        return session_error

    resp = _issue_full_auth_response(user, sign_in_email=email or user.email)
    return resp


