@app.route("/api/auth/refresh", methods=["POST"])
def refresh():
    refresh_token = request.cookies.get("refresh_token")
    if not refresh_token:
        return jsonify({"success": False, "message": "Invalid refresh token"}), 401

    stored = RefreshToken.query.filter_by(token=refresh_token).first()
    if not stored:
        return jsonify({"success": False, "message": "Invalid refresh token"}), 401

    expires_at = _as_utc_datetime(stored.expires_at)
    if expires_at and expires_at < datetime.now(UTC):
        db.session.delete(stored)
        db.session.commit()
        return jsonify({"success": False, "message": "Expired"}), 401

    user = User.query.get(stored.user_id)
    if (
        not user
        or not user.is_email_verified
        or (is_two_factor_required(user) and not is_two_factor_setup_complete(user))
    ):
        db.session.delete(stored)
        db.session.commit()
        resp = jsonify({"success": False, "message": "Re-authentication required"})
        clear_auth_cookies(resp)
        clear_pending_2fa_cookie(resp)
        return resp, 401

    secured_user, security_error = _enforce_user_security_state(user)
    if security_error:
        try:
            db.session.delete(stored)
            db.session.commit()
        except Exception:
            db.session.rollback()
            logging.exception("Failed to remove blocked refresh token during refresh")
        return security_error

    user = secured_user

    new_refresh = create_refresh_token(stored.user_id)
    new_access = create_access_token(stored.user_id)

    db.session.delete(stored)
    db.session.commit()

    resp = jsonify({"success": True})
    set_cookie(resp, "access_token", new_access, ACCESS_TOKEN_EXPIRE_MINUTES * 60)
    set_cookie(resp, "refresh_token", new_refresh, REFRESH_TOKEN_EXPIRE_DAYS * 86400)
    clear_pending_2fa_cookie(resp)
    return resp


@app.route("/api/auth/me", methods=["GET"])
def get_me():
    user, auth_error = require_full_auth_user()
    if auth_error:
        auth_header = request.headers.get("Authorization", "")
        access_token_cookie = request.cookies.get("access_token")

        logging.warning(
            f"/api/auth/me: Authentication failed. Auth header present: {bool(auth_header)}, Cookie present: {bool(access_token_cookie)}"
        )
        if auth_header:
            logging.warning(
                f"/api/auth/me: Auth header starts with Bearer: {auth_header.startswith('Bearer ')}"
            )
        return auth_error

    logging.info(f"/api/auth/me: User authenticated - {user.email}")
    auth_flags = _user_auth_flags(user)
    return jsonify(
        {
            "success": True,
            "user": _serialize_user_settings_payload(user, auth_flags),
        }
    )


@app.route("/api/auth/logout", methods=["POST"])
def logout():
    user = get_current_user()
    refresh_token = request.cookies.get("refresh_token")
    if refresh_token:
        stored = RefreshToken.query.filter_by(token=refresh_token).first()
        if stored:
            db.session.delete(stored)
            db.session.commit()

    if user:
        try:
            log_user_event(
                user_id=user.id,
                module=MODULE_AUTH,
                action_type="logout",
                title=USER_ACTIVITY_LABELS["logout"],
                description="The active session was signed out from the dashboard.",
                status=STATUS_INFO,
                severity=SEVERITY_LOW,
                is_sensitive=True,
                target_type="session",
                target_id=_request_session_id(),
                target_label=_request_device_label(),
                metadata_json={
                    "device_label": _request_device_label(),
                    "device_fingerprint": _request_device_fingerprint(),
                },
                commit=True,
            )
        except Exception:
            db.session.rollback()
            logging.exception("Failed to record logout activity for user_id=%s", user.id)

    resp = jsonify({"success": True})
    session.clear()
    clear_auth_cookies(resp)
    clear_pending_2fa_cookie(resp)
    return resp


