@app.route("/api/settings/security", methods=["PATCH", "POST"])
def update_security_settings():
    user, auth_error = require_full_auth_user()
    if auth_error:
        return auth_error

    data = request.get_json(silent=True) or {}

    auto_lock_minutes = data.get("auto_lock_minutes")
    session_timeout_minutes = data.get("session_timeout_minutes")
    two_factor_enabled = data.get("two_factor_enabled")

    if auto_lock_minutes is None or session_timeout_minutes is None:
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Auto-lock and session timeout values are required.",
                }
            ),
            400,
        )

    try:
        auto_lock_minutes = int(auto_lock_minutes)
        session_timeout_minutes = int(session_timeout_minutes)
    except (TypeError, ValueError):
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Security timing values must be numbers.",
                }
            ),
            400,
        )

    if auto_lock_minutes not in {5, 15, 30, 60}:
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Auto-lock value is invalid.",
                }
            ),
            400,
        )

    if session_timeout_minutes not in {15, 30, 60, 120}:
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Session timeout value is invalid.",
                }
            ),
            400,
        )

    if not isinstance(two_factor_enabled, bool):
        two_factor_enabled = bool(getattr(user, "is_two_factor_enabled", False))

    if two_factor_enabled and not is_two_factor_setup_complete(user):
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Two-factor authentication must be configured before it can be enabled.",
                }
            ),
            400,
        )

    user.auto_lock_minutes = auto_lock_minutes
    user.session_timeout_minutes = session_timeout_minutes
    user.is_two_factor_enabled = bool(two_factor_enabled)

    try:
        create_security_audit_log(
            user.id,
            "security_settings_updated",
            {
                "auto_lock_minutes": auto_lock_minutes,
                "session_timeout_minutes": session_timeout_minutes,
                "two_factor_enabled": bool(two_factor_enabled),
                "remote_addr": str(request.remote_addr or ""),
                "user_agent": str(request.headers.get("User-Agent") or "")[:300],
            },
        )
        log_user_event(
            user_id=user.id,
            module=MODULE_AUTH,
            action_type="profile_updated",
            title="Security settings updated",
            description="Security preferences were updated for the active account.",
            status=STATUS_SUCCESS,
            severity=SEVERITY_MEDIUM,
            is_sensitive=True,
            target_type="security_settings",
            target_id=str(user.id),
            target_label=str(user.email or "").strip() or "Account security",
            metadata_json={
                "auto_lock_minutes": auto_lock_minutes,
                "session_timeout_minutes": session_timeout_minutes,
                "two_factor_enabled": bool(two_factor_enabled),
                "device_label": _request_device_label(),
            },
        )
        db.session.commit()
    except Exception:
        db.session.rollback()
        logging.exception("Failed to update security settings for user_id=%s", user.id)
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Security settings could not be updated.",
                }
            ),
            500,
        )

    return jsonify(
        {
            "success": True,
            "message": "Security settings updated successfully.",
            "user": _serialize_user_settings_payload(user),
        }
    )


@app.route("/api/settings/password", methods=["PATCH", "POST"])
def update_password_settings():
    user, auth_error = require_full_auth_user()
    if auth_error:
        return auth_error

    data = request.get_json(silent=True) or {}
    current_password = str(data.get("current_password") or "")
    new_password = str(data.get("new_password") or "")
    confirm_password = str(data.get("confirm_password") or "")

    if not current_password or not new_password or not confirm_password:
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Current password, new password, and confirmation are required.",
                }
            ),
            400,
        )

    if not check_password_hash(user.password_hash, current_password):
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Current password is incorrect.",
                }
            ),
            400,
        )

    if new_password != confirm_password:
        return (
            jsonify(
                {
                    "success": False,
                    "message": "New password confirmation does not match.",
                }
            ),
            400,
        )

    if len(new_password) < 8:
        return (
            jsonify(
                {
                    "success": False,
                    "message": "New password must be at least 8 characters long.",
                }
            ),
            400,
        )

    if check_password_hash(user.password_hash, new_password):
        return (
            jsonify(
                {
                    "success": False,
                    "message": "New password must be different from the current password.",
                }
            ),
            400,
        )

    user.password_hash = generate_password_hash(new_password)

    try:
        db.session.add(
            PasswordHistory(
                user_id=int(user.id),
                password_hash=user.password_hash,
                partial_password=(new_password[:2] + "***" + new_password[-2:])
                if len(new_password) >= 4
                else "***",
                breach_count=0,
                status="Safe",
            )
        )
        create_security_audit_log(
            user.id,
            "password_changed",
            {
                "remote_addr": str(request.remote_addr or ""),
                "user_agent": str(request.headers.get("User-Agent") or "")[:300],
            },
        )
        log_user_event(
            user_id=user.id,
            module=MODULE_AUTH,
            action_type="password_changed",
            title=USER_ACTIVITY_LABELS["password_changed"],
            description="The account password was updated from the security settings page.",
            status=STATUS_SUCCESS,
            severity=SEVERITY_MEDIUM,
            is_sensitive=True,
            target_type="account",
            target_id=str(user.id),
            target_label=str(user.email or "").strip() or "Account",
            metadata_json={"device_label": _request_device_label()},
        )
        db.session.commit()
    except Exception:
        db.session.rollback()
        logging.exception("Failed to update password for user_id=%s", user.id)
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Password could not be updated.",
                }
            ),
            500,
        )

    return jsonify(
        {
            "success": True,
            "message": "Password updated successfully.",
        }
    )


