@app.route("/api/settings/linked-accounts", methods=["POST"])
def create_linked_account_settings():
    user, auth_error = require_full_auth_user()
    if auth_error:
        return auth_error

    data = request.get_json(silent=True) or {}
    raw_email = str(data.get("email") or "").strip()
    email_normalized = _normalize_linked_account_email(raw_email)
    requested_type = _normalize_linked_account_type(data.get("account_type"))

    if not _is_valid_linked_account_email(raw_email):
        return (
            jsonify(
                {
                    "success": False,
                    "message": "A valid email address is required.",
                }
            ),
            400,
        )

    try:
        _ensure_default_linked_account_for_user(user)
    except Exception:
        db.session.rollback()
        logging.exception(
            "Failed to ensure default linked account before create for user_id=%s",
            user.id,
        )
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Linked account setup could not be initialized.",
                }
            ),
            500,
        )

    duplicate = LinkedAccount.query.filter_by(
        user_id=int(user.id), email_normalized=email_normalized
    ).first()
    if duplicate is not None:
        return (
            jsonify(
                {
                    "success": False,
                    "message": "This email is already linked to your account.",
                }
            ),
            409,
        )

    ownership_conflict = _find_linked_identity_conflict(int(user.id), email_normalized)
    if ownership_conflict:
        return jsonify({"success": False, "message": ownership_conflict}), 409

    existing_count = LinkedAccount.query.filter_by(user_id=int(user.id)).count()
    final_type = (
        LINKED_ACCOUNT_TYPE_PRIMARY
        if existing_count == 0 or requested_type == LINKED_ACCOUNT_TYPE_PRIMARY
        else requested_type or LINKED_ACCOUNT_TYPE_SECONDARY
    )
    new_account = LinkedAccount(
        user_id=int(user.id),
        email=raw_email,
        email_normalized=email_normalized,
        account_type=final_type,
        verification_status=LINKED_ACCOUNT_STATUS_PENDING,
        verification_token=None,
        verification_expires_at=None,
        two_factor_enabled=False,
        last_access_at=None,
    )
    verification_token, verification_exp = _create_linked_account_verification_state()
    new_account.verification_token = verification_token
    new_account.verification_expires_at = verification_exp

    try:
        db.session.add(new_account)
        db.session.flush()

        if final_type == LINKED_ACCOUNT_TYPE_PRIMARY:
            (
                LinkedAccount.query.filter(
                    LinkedAccount.user_id == int(user.id),
                    LinkedAccount.id != int(new_account.id),
                    LinkedAccount.account_type == LINKED_ACCOUNT_TYPE_PRIMARY,
                ).update(
                    {"account_type": LINKED_ACCOUNT_TYPE_SECONDARY},
                    synchronize_session=False,
                )
            )

        create_security_audit_log(
            user.id,
            "linked_account_created",
            {
                "linked_email": raw_email,
                "account_type": final_type,
                "remote_addr": str(request.remote_addr or ""),
            },
        )
        log_user_event(
            user_id=user.id,
            module=MODULE_AUTH,
            action_type="profile_updated",
            title="Linked account added",
            description="A linked account was added from the settings page.",
            status=STATUS_SUCCESS,
            severity=SEVERITY_LOW,
            is_sensitive=True,
            target_type="linked_account",
            target_id=str(new_account.id),
            target_label=raw_email,
            metadata_json={
                "linked_email": raw_email,
                "account_type": final_type,
                "verification_status": LINKED_ACCOUNT_STATUS_PENDING,
            },
        )
        db.session.commit()
    except Exception:
        db.session.rollback()
        logging.exception(
            "Failed to create linked account | user_id=%s | email=%s",
            user.id,
            raw_email,
        )
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Linked account could not be created.",
                }
            ),
            500,
        )

    verification_notice = "Verification email sent to the linked address."
    if _mail_is_configured():
        try:
            _send_linked_account_verification_email(new_account, user)
        except Exception:
            logging.exception(
                "Failed to send linked account verification email | user_id=%s | linked_account_id=%s",
                user.id,
                new_account.id,
            )
            verification_notice = (
                "Linked account added, but the verification email could not be sent."
            )
    else:
        verification_notice = (
            "Linked account added. SMTP is not configured, so verification email was not sent."
        )

    return jsonify(
        {
            "success": True,
            "message": f"Linked account added successfully. {verification_notice}",
            "account": _serialize_linked_account(new_account, user),
            "accounts": _linked_accounts_payload_for_user(user),
        }
    )


@app.route("/api/settings/linked-accounts/<int:account_id>", methods=["PUT"])
def update_linked_account_settings(account_id: int):
    user, auth_error = require_full_auth_user()
    if auth_error:
        return auth_error

    data = request.get_json(silent=True) or {}
    account = LinkedAccount.query.filter_by(
        id=int(account_id), user_id=int(user.id)
    ).first()
    if account is None:
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Linked account was not found.",
                }
            ),
            404,
        )

    raw_email = str(data.get("email") or account.email or "").strip()
    email_normalized = _normalize_linked_account_email(raw_email)
    original_is_current_auth_email = (
        _normalize_linked_account_email(account.email_normalized)
        == _normalize_linked_account_email(user.email)
    )
    if not _is_valid_linked_account_email(raw_email):
        return (
            jsonify(
                {
                    "success": False,
                    "message": "A valid email address is required.",
                }
            ),
            400,
        )

    if original_is_current_auth_email and email_normalized != _normalize_linked_account_email(user.email):
        return (
            jsonify(
                {
                    "success": False,
                    "message": "The active sign-in email cannot be changed from linked account management.",
                }
            ),
            400,
        )

    duplicate = (
        LinkedAccount.query.filter_by(
            user_id=int(user.id), email_normalized=email_normalized
        )
        .filter(LinkedAccount.id != int(account.id))
        .first()
    )
    if duplicate is not None:
        return (
            jsonify(
                {
                    "success": False,
                    "message": "This email is already linked to your account.",
                }
            ),
            409,
        )

    ownership_conflict = _find_linked_identity_conflict(
        int(user.id), email_normalized, exclude_account_id=int(account.id)
    )
    if ownership_conflict:
        return jsonify({"success": False, "message": ownership_conflict}), 409

    requested_type = _normalize_linked_account_type(data.get("account_type"))
    if requested_type is None:
        requested_type = (
            _normalize_linked_account_type(account.account_type)
            or LINKED_ACCOUNT_TYPE_SECONDARY
        )

    requested_two_factor = data.get("two_factor_enabled")
    is_current_auth_email = original_is_current_auth_email
    email_changed = email_normalized != _normalize_linked_account_email(account.email_normalized)

    if (
        _normalize_linked_account_type(account.account_type) == LINKED_ACCOUNT_TYPE_PRIMARY
        and requested_type != LINKED_ACCOUNT_TYPE_PRIMARY
    ):
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Promote another linked account to Primary before changing this one.",
                }
            ),
            400,
        )

    account.email = raw_email
    account.email_normalized = email_normalized
    account.account_type = requested_type

    if not is_current_auth_email and email_changed:
        verification_token, verification_exp = _create_linked_account_verification_state()
        account.verification_status = LINKED_ACCOUNT_STATUS_PENDING
        account.verification_token = verification_token
        account.verification_expires_at = verification_exp

    if not is_current_auth_email and isinstance(requested_two_factor, bool):
        account.two_factor_enabled = requested_two_factor

    account.updated_at = datetime.now(UTC)

    try:
        if requested_type == LINKED_ACCOUNT_TYPE_PRIMARY:
            (
                LinkedAccount.query.filter(
                    LinkedAccount.user_id == int(user.id),
                    LinkedAccount.id != int(account.id),
                    LinkedAccount.account_type == LINKED_ACCOUNT_TYPE_PRIMARY,
                ).update(
                    {"account_type": LINKED_ACCOUNT_TYPE_SECONDARY},
                    synchronize_session=False,
                )
            )

        _sync_primary_account_for_user(int(user.id))
        create_security_audit_log(
            user.id,
            "linked_account_updated",
            {
                "linked_account_id": int(account.id),
                "linked_email": raw_email,
                "account_type": requested_type,
            },
        )
        log_user_event(
            user_id=user.id,
            module=MODULE_AUTH,
            action_type="profile_updated",
            title="Linked account updated",
            description="A linked account was updated from the settings page.",
            status=STATUS_SUCCESS,
            severity=SEVERITY_LOW,
            is_sensitive=True,
            target_type="linked_account",
            target_id=str(account.id),
            target_label=raw_email,
            metadata_json={
                "linked_email": raw_email,
                "account_type": requested_type,
                "verification_status": account.verification_status,
                "two_factor_enabled": bool(account.two_factor_enabled),
            },
        )
        db.session.commit()
    except Exception:
        db.session.rollback()
        logging.exception(
            "Failed to update linked account | user_id=%s | account_id=%s",
            user.id,
            account_id,
        )
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Linked account could not be updated.",
                }
            ),
            500,
        )

    update_notice = "Linked account updated successfully."
    if not is_current_auth_email and email_changed:
        if _mail_is_configured():
            try:
                _send_linked_account_verification_email(account, user)
                update_notice = (
                    "Linked account updated successfully. A new verification email was sent."
                )
            except Exception:
                logging.exception(
                    "Failed to send linked account verification email after update | user_id=%s | account_id=%s",
                    user.id,
                    account.id,
                )
                update_notice = (
                    "Linked account updated, but the verification email could not be sent."
                )
        else:
            update_notice = (
                "Linked account updated. SMTP is not configured, so verification email was not sent."
            )

    return jsonify(
        {
            "success": True,
            "message": update_notice,
            "account": _serialize_linked_account(account, user),
            "accounts": _linked_accounts_payload_for_user(user),
        }
    )


@app.route("/api/settings/linked-accounts/<int:account_id>", methods=["DELETE"])
def delete_linked_account_settings(account_id: int):
    user, auth_error = require_full_auth_user()
    if auth_error:
        return auth_error

    account = LinkedAccount.query.filter_by(
        id=int(account_id), user_id=int(user.id)
    ).first()
    if account is None:
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Linked account was not found.",
                }
            ),
            404,
        )

    account_count = LinkedAccount.query.filter_by(user_id=int(user.id)).count()
    if account_count <= 1:
        return (
            jsonify(
                {
                    "success": False,
                    "message": "You cannot delete your only linked account.",
                }
            ),
            400,
        )

    if _normalize_linked_account_type(account.account_type) == LINKED_ACCOUNT_TYPE_PRIMARY:
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Promote another linked account to Primary before deleting this one.",
                }
            ),
            400,
        )

    removed_email = str(account.email or "").strip()

    try:
        db.session.delete(account)
        create_security_audit_log(
            user.id,
            "linked_account_deleted",
            {
                "linked_account_id": int(account_id),
                "linked_email": removed_email,
            },
        )
        log_user_event(
            user_id=user.id,
            module=MODULE_AUTH,
            action_type="profile_updated",
            title="Linked account deleted",
            description="A linked account was removed from the settings page.",
            status=STATUS_SUCCESS,
            severity=SEVERITY_MEDIUM,
            is_sensitive=True,
            target_type="linked_account",
            target_id=str(account_id),
            target_label=removed_email,
            metadata_json={"linked_email": removed_email},
        )
        db.session.commit()
    except Exception:
        db.session.rollback()
        logging.exception(
            "Failed to delete linked account | user_id=%s | account_id=%s",
            user.id,
            account_id,
        )
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Linked account could not be deleted.",
                }
            ),
            500,
        )

    return jsonify(
        {
            "success": True,
            "message": "Linked account deleted successfully.",
            "accounts": _linked_accounts_payload_for_user(user),
        }
    )


@app.route("/api/settings/linked-accounts/<int:account_id>/send-verification", methods=["POST"])
def resend_linked_account_verification_settings(account_id: int):
    user, auth_error = require_full_auth_user()
    if auth_error:
        return auth_error

    account = LinkedAccount.query.filter_by(
        id=int(account_id), user_id=int(user.id)
    ).first()
    if account is None:
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Linked account was not found.",
                }
            ),
            404,
        )

    if _normalize_linked_account_email(account.email_normalized) == _normalize_linked_account_email(user.email):
        return (
            jsonify(
                {
                    "success": False,
                    "message": "The authenticated sign-in email does not use linked-account verification.",
                }
            ),
            400,
        )

    if _is_linked_account_verified(account, user):
        return (
            jsonify(
                {
                    "success": False,
                    "message": "This linked account is already verified.",
                }
            ),
            400,
        )

    verification_token, verification_exp = _create_linked_account_verification_state()
    account.verification_status = LINKED_ACCOUNT_STATUS_PENDING
    account.verification_token = verification_token
    account.verification_expires_at = verification_exp
    account.updated_at = datetime.now(UTC)

    try:
        db.session.commit()
    except Exception:
        db.session.rollback()
        logging.exception(
            "Failed to prepare linked account verification resend | user_id=%s | account_id=%s",
            user.id,
            account_id,
        )
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Verification email could not be prepared.",
                }
            ),
            500,
        )

    if not _mail_is_configured():
        return (
            jsonify(
                {
                    "success": False,
                    "message": "SMTP is not configured, so verification email cannot be sent right now.",
                    "accounts": _linked_accounts_payload_for_user(user),
                }
            ),
            503,
        )

    try:
        _send_linked_account_verification_email(account, user)
    except Exception:
        logging.exception(
            "Failed to resend linked account verification email | user_id=%s | account_id=%s",
            user.id,
            account_id,
        )
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Verification email could not be sent.",
                    "accounts": _linked_accounts_payload_for_user(user),
                }
            ),
            500,
        )

    return jsonify(
        {
            "success": True,
            "message": "Verification email sent successfully.",
            "account": _serialize_linked_account(account, user),
            "accounts": _linked_accounts_payload_for_user(user),
        }
    )


