@app.route("/api/security/emergency-mode", methods=["POST"])
def activate_emergency_mode():
    user, auth_error = require_full_auth_user()
    if auth_error:
        return auth_error

    panic_until = datetime.now(UTC) + timedelta(minutes=PANIC_MODE_DURATION_MINUTES)
    previous_session_version = _get_user_session_version(user)
    new_session_version = previous_session_version + 1
    revoked_refresh_tokens = (
        RefreshToken.query.filter_by(user_id=int(user.id)).delete(synchronize_session=False)
    )

    user.session_version = new_session_version
    user.panic_mode_enabled = True
    user.panic_mode_until = panic_until
    user.panic_mode_reason = "User activated Emergency Mode from the dashboard."
    user.panic_mode_activated_at = datetime.now(UTC)

    alert_title = "Emergency Mode Activated"
    alert_message = (
        "User activated Emergency Mode. All active sessions were revoked and the "
        "account was temporarily protected."
    )
    audit_details = {
        "action": PANIC_MODE_ACTION,
        "session_version_before": previous_session_version,
        "session_version_after": new_session_version,
        "panic_mode_until": panic_until.isoformat(),
        "revoked_refresh_tokens": int(revoked_refresh_tokens or 0),
        "remote_addr": str(request.remote_addr or ""),
        "user_agent": str(request.headers.get("User-Agent") or "")[:300],
    }

    try:
        create_security_hub_alert(
            user.id,
            title=alert_title,
            message=alert_message,
            severity="high",
            category="Account Protection",
            metadata={
                **audit_details,
                "category": "Account Protection",
                "title": alert_title,
                "description": alert_message,
            },
        )
        create_user_notification(
            user.id,
            "critical_detected",
            alert_title,
            alert_message,
            severity=NOTIFICATION_SEVERITY_CRITICAL,
            metadata={
                **audit_details,
                "category": "Account Protection",
                "title": alert_title,
                "description": alert_message,
            },
        )
        create_security_audit_log(user.id, PANIC_MODE_ACTION, audit_details)
        _send_security_event_telegram_notification(
            title=alert_title,
            body=alert_message,
            user=user,
            severity="High",
            category="Account Protection",
            extra_lines=[
                f"Protection active until: {panic_until.isoformat()}",
                f"Revoked sessions: {int(revoked_refresh_tokens or 0)}",
            ],
        )
        db.session.commit()
    except Exception:
        db.session.rollback()
        logging.exception("Failed to activate Emergency Mode for user_id=%s", user.id)
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Emergency Mode could not be activated. Please try again.",
                }
            ),
            500,
        )

    resp = jsonify(
        {
            "success": True,
            "message": "Emergency Mode activated. All sessions were signed out and the account is temporarily protected.",
            "panic_mode_until": panic_until.isoformat(),
        }
    )
    clear_auth_cookies(resp)
    clear_pending_2fa_cookie(resp)
    return resp


