@app.route("/api/admin/notifications/telegram/test", methods=["POST"])
@app.route("/api/admin/notification-control/telegram/test", methods=["POST"])
@admin_auth_required
def admin_test_telegram_notification():
    """Test Telegram notification channel for admin/security team only."""
    notification_settings = _read_admin_notification_control_settings()
    data = request.get_json(silent=True) or {}
    recipient = data.get("recipient") if isinstance(data.get("recipient"), dict) else {}
    recipient_chat_id = str(recipient.get("telegram_chat_id") or "").strip()
    telegram_chat_id = recipient_chat_id or _telegram_default_chat_id(notification_settings)

    if not _telegram_has_bot_token():
        return jsonify({"success": False, "message": "TELEGRAM_BOT_TOKEN is not configured."}), 503
    
    if not bool(notification_settings.get("telegramEnabled", True)):
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Telegram notifications are disabled in admin preferences.",
                }
            ),
            400,
        )

    if not telegram_chat_id:
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Telegram chat ID is not configured for the selected admin recipient or ADMIN_TELEGRAM_CHAT_ID fallback.",
                }
            ),
            400,
        )

    result = _send_telegram_notification_result(
        _format_telegram_message(
            "Sentinel AI Admin Test Alert",
            "Telegram notification channel is working.",
            ["Sentinel AI Admin Test Alert: Telegram notification channel is working."],
        ),
        chat_id_override=telegram_chat_id,
    )
    
    if not result.get("success"):
        return (
            jsonify(
                {
                    "success": False,
                    "message": result.get("error") or "Telegram notification could not be sent.",
                }
            ),
            502,
        )

    return jsonify(
        {
            "success": True,
            "message": "Telegram test notification sent successfully.",
        }
    )


@app.route("/api/admin/notification-control/status", methods=["GET"])
@admin_auth_required
def admin_notification_control_status():
    current_admin = getattr(g, "current_admin", {}) or {}
    admin_email = str(current_admin.get("email") or "").strip()
    settings = _read_admin_notification_control_settings()
    last_tests = settings.get("lastTests") if isinstance(settings.get("lastTests"), dict) else {}
    telegram_configured = _telegram_is_configured(settings)
    return jsonify(
        {
            "success": True,
            "recipient": {
                "id": "current-admin",
                "name": admin_email.split("@", 1)[0].replace(".", " ").title() if admin_email else "Admin",
                "role": "Admin",
                "email": admin_email,
                "telegram_chat_id": _telegram_default_chat_id(settings) if telegram_configured else "",
            },
            "channels": [
                {
                    "id": "email",
                    "enabled": bool(_mail_is_configured()) and bool(settings.get("emailEnabled", True)),
                    "connected": bool(_mail_is_configured()),
                    "status": "connected" if _mail_is_configured() else "not_configured",
                    "provider": "SMTP",
                    "lastTestAt": last_tests.get("email"),
                },
                {
                    "id": "telegram",
                    "enabled": bool(telegram_configured) and bool(settings.get("telegramEnabled", True)),
                    "connected": bool(telegram_configured),
                    "status": "connected" if telegram_configured else "not_configured",
                    "provider": "Telegram Bot",
                    "description": "Send high-priority security alerts to the admin or security response team through the configured Telegram bot.",
                    "lastTestAt": last_tests.get("telegram"),
                },
            ],
            "settings": settings,
        }
    )


ADMIN_NOTIFICATION_CONTROL_SETTINGS_PATH = BASE_DIR / "instance" / "admin_notification_control_settings.json"
ADMIN_THREAT_STATUS_OVERRIDES_PATH = BASE_DIR / "instance" / "admin_threat_status_overrides.json"


def _default_admin_notification_control_settings() -> dict:
    return {
        "severityFilter": "medium-above",
        "frequency": "hourly",
        "emailEnabled": True,
        "telegramEnabled": True,
        "telegramPhone": "",
        "telegramChatId": _telegram_default_chat_id(),
        "lastTests": {
            "email": None,
            "telegram": None,
        },
        "silentHours": {
            "enabled": True,
            "from": "23:00",
            "to": "08:00",
            "allowCritical": True,
            "timezone": "Local system time",
        },
    }


def _read_admin_notification_control_settings() -> dict:
    defaults = _default_admin_notification_control_settings()
    try:
        if ADMIN_NOTIFICATION_CONTROL_SETTINGS_PATH.exists():
            with ADMIN_NOTIFICATION_CONTROL_SETTINGS_PATH.open("r", encoding="utf-8") as handle:
                payload = json.load(handle)
            if isinstance(payload, dict):
                silent_hours = payload.get("silentHours") if isinstance(payload.get("silentHours"), dict) else {}
                return {
                    **defaults,
                    **payload,
                    "silentHours": {
                        **defaults["silentHours"],
                        **silent_hours,
                    },
                }
    except Exception:
        logging.exception("Failed to read admin notification control settings")
    return defaults


def _normalize_admin_notification_control_settings(payload: dict) -> dict:
    defaults = _default_admin_notification_control_settings()
    allowed_severity = {"critical", "high-critical", "medium-above", "all"}
    allowed_frequency = {"instant", "15-minutes", "hourly", "daily", "weekly"}
    silent_hours = payload.get("silentHours") if isinstance(payload.get("silentHours"), dict) else {}
    last_tests = payload.get("lastTests") if isinstance(payload.get("lastTests"), dict) else {}

    severity_filter = str(payload.get("severityFilter") or defaults["severityFilter"]).strip()
    frequency = str(payload.get("frequency") or defaults["frequency"]).strip()

    return {
        "severityFilter": severity_filter if severity_filter in allowed_severity else defaults["severityFilter"],
        "frequency": frequency if frequency in allowed_frequency else defaults["frequency"],
        "emailEnabled": bool(payload.get("emailEnabled", defaults["emailEnabled"])),
        "telegramEnabled": bool(payload.get("telegramEnabled", defaults["telegramEnabled"])),
        "telegramPhone": "",
        "telegramChatId": str(payload.get("telegramChatId") or defaults["telegramChatId"]).strip()[:80],
        "lastTests": {
            "email": str(last_tests.get("email") or "").strip() or None,
            "telegram": str(last_tests.get("telegram") or "").strip() or None,
        },
        "silentHours": {
            "enabled": bool(silent_hours.get("enabled", defaults["silentHours"]["enabled"])),
            "from": str(silent_hours.get("from") or defaults["silentHours"]["from"]).strip()[:5],
            "to": str(silent_hours.get("to") or defaults["silentHours"]["to"]).strip()[:5],
            "allowCritical": bool(silent_hours.get("allowCritical", defaults["silentHours"]["allowCritical"])),
            "timezone": str(silent_hours.get("timezone") or defaults["silentHours"]["timezone"]).strip(),
        },
    }


def _write_admin_notification_control_settings(settings: dict) -> bool:
    try:
        ADMIN_NOTIFICATION_CONTROL_SETTINGS_PATH.parent.mkdir(parents=True, exist_ok=True)
        with ADMIN_NOTIFICATION_CONTROL_SETTINGS_PATH.open("w", encoding="utf-8") as handle:
            json.dump(settings, handle, indent=2)
        return True
    except Exception:
        logging.exception("Failed to save admin notification control settings")
        return False


@app.route("/api/admin/notification-control/settings", methods=["GET", "PATCH", "POST"])
@admin_auth_required
def admin_notification_control_settings():
    if request.method == "GET":
        return jsonify({"success": True, "settings": _read_admin_notification_control_settings()})

    data = request.get_json(silent=True) or {}
    settings = _normalize_admin_notification_control_settings(data)
    if not _write_admin_notification_control_settings(settings):
        return jsonify({"success": False, "message": "Notification settings could not be saved."}), 500

    return jsonify({"success": True, "settings": settings})


@app.route("/api/admin/notification-control/test", methods=["POST"])
@admin_auth_required
def admin_notification_control_test():
    data = request.get_json(silent=True) or {}
    recipient = data.get("recipient") if isinstance(data.get("recipient"), dict) else {}
    channel = str(data.get("channel") or "").strip().lower()
    severity = str(data.get("severity") or "Critical").strip() or "Critical"
    recipient_name = str(recipient.get("name") or "Admin").strip()
    recipient_email = str(recipient.get("email") or "").strip()
    recipient_telegram_chat_id = str(recipient.get("telegram_chat_id") or "").strip()
    notification_settings = _read_admin_notification_control_settings()

    if channel not in {"email", "telegram"}:
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Only Email and Telegram notification tests are supported.",
                }
            ),
            400,
        )

    title = f"Sentinel AI {severity} Test Notification"
    text_body = (
        f"Hello {recipient_name},\n\n"
        "This is a real test notification from the Sentinel AI Notification Control Center.\n"
        f"Channel: {channel.title()}\n"
        f"Severity: {severity}\n"
        f"Time: {datetime.now(UTC).isoformat()}\n"
    )
    html_body = f"""
    <div style="font-family:Arial,sans-serif;line-height:1.55;color:#0f172a">
      <h2>{escape(title)}</h2>
      <p>Hello {escape(recipient_name)},</p>
      <p>This is a real test notification from the Sentinel AI Notification Control Center.</p>
      <p><strong>Channel:</strong> {escape(channel.title())}<br>
      <strong>Severity:</strong> {escape(severity)}</p>
    </div>
    """

    try:
        if channel == "email":
            if not bool(notification_settings.get("emailEnabled", True)):
                return jsonify({"success": False, "message": "Email notifications are disabled in admin preferences."}), 400
            if not recipient_email:
                return (
                    jsonify({"success": False, "message": "Recipient email is required."}),
                    400,
                )
            if not _mail_is_configured():
                return (
                    jsonify(
                        {
                            "success": False,
                            "message": "Email is not configured on the server.",
                        }
                    ),
                    503,
                )
            send_email(recipient_email, title, html_body, text_body)
        else:
            if not bool(notification_settings.get("telegramEnabled", True)):
                return jsonify({"success": False, "message": "Telegram notifications are disabled in admin preferences."}), 400
            destination_chat_id = (
                recipient_telegram_chat_id
                if recipient_telegram_chat_id and recipient_telegram_chat_id != "Configured server chat"
                else _telegram_default_chat_id(notification_settings)
            )
            if not _telegram_has_bot_token():
                return jsonify({"success": False, "message": "TELEGRAM_BOT_TOKEN is not configured."}), 503
            if not destination_chat_id:
                return (
                    jsonify(
                        {
                            "success": False,
                            "message": "Telegram chat ID is not configured for the selected admin recipient or ADMIN_TELEGRAM_CHAT_ID fallback.",
                        }
                    ),
                    400,
                )
            result = _send_telegram_notification_result(
                _format_telegram_message(
                    title,
                    "This is a real test notification from the Sentinel AI Notification Control Center.",
                    [f"Recipient: {recipient_name}", f"Severity: {severity}"],
                ),
                chat_id_override=destination_chat_id,
            )
            if not result.get("success"):
                return (
                    jsonify(
                        {
                            "success": False,
                            "message": result.get("error") or "Telegram notification could not be sent.",
                        }
                    ),
                    502,
                )

        tested_at = datetime.now(UTC).isoformat()
        latest_settings = _read_admin_notification_control_settings()
        latest_last_tests = latest_settings.get("lastTests") if isinstance(latest_settings.get("lastTests"), dict) else {}
        latest_settings["lastTests"] = {
            **latest_last_tests,
            channel: tested_at,
        }
        _write_admin_notification_control_settings(
            _normalize_admin_notification_control_settings(latest_settings)
        )

        return jsonify(
            {
                "success": True,
                "message": f"{channel.title()} test notification sent successfully.",
                "tested_at": tested_at,
            }
        )
    except Exception as exc:
        logging.exception("Admin notification control test failed")
        return (
            jsonify(
                {
                    "success": False,
                    "message": f"{channel.title()} test notification failed: {_friendly_smtp_error(exc) if channel == 'email' else str(exc)[:180]}",
                }
            ),
            500,
        )


