@app.route("/notifications", methods=["GET"])
def list_notifications():
    user, auth_error = require_notification_user()
    if auth_error:
        return auth_error

    limit = _parse_positive_int(request.args.get("limit"), 20)
    limit = 20 if limit is None else min(limit, 100)
    offset = _parse_nonnegative_int(request.args.get("offset"), 0)

    app_notifications = (
        UserNotification.query.filter_by(user_id=user.id)
        .order_by(UserNotification.created_at.desc(), UserNotification.id.desc())
        .limit(min(250, limit + offset + 50))
        .all()
    )
    identity_alerts = list_identity_web_alerts(user.id, limit=min(250, limit + offset + 50))
    notifications = [_serialize_notification(n) for n in app_notifications]
    notifications.extend(_serialize_identity_alert_notification(alert, user.id) for alert in identity_alerts)
    notifications.sort(key=_notification_created_sort_key, reverse=True)
    paged_notifications = notifications[offset : offset + limit]
    return jsonify(
        {
            "notifications": paged_notifications,
            "unread_count": _notification_unread_count(user.id),
            "count": len(paged_notifications),
            "limit": limit,
            "offset": offset,
            "user_id": user.id,
            "scope": "user",
        }
    )


