def _extract_notification_ids_from_request() -> tuple[list[int], list[int]]:
    data = request.get_json(silent=True) or {}
    ids: list[int] = []
    identity_ids: list[int] = []

    def collect(raw_id) -> None:
        raw_text = str(raw_id or "").strip()
        if raw_text.startswith("identity-"):
            parsed_identity = _parse_positive_int(raw_text.replace("identity-", "", 1), None)
            if parsed_identity is not None:
                identity_ids.append(int(parsed_identity))
            return

        parsed = _parse_positive_int(raw_id, None)
        if parsed is not None:
            ids.append(int(parsed))

    single_id = data.get("id")
    if single_id not in (None, ""):
        collect(single_id)

    raw_ids = data.get("ids")
    if isinstance(raw_ids, list):
        for item in raw_ids:
            collect(item)

    return sorted(set(ids)), sorted(set(identity_ids))


def _mark_notification_ids_read(
    user_id: int, notification_ids: list[int]
) -> tuple[int, list[UserNotification]]:
    if not notification_ids:
        return 0, []

    notifications = (
        UserNotification.query.filter(
            UserNotification.user_id == user_id,
            UserNotification.id.in_(notification_ids),
        )
        .order_by(UserNotification.created_at.desc(), UserNotification.id.desc())
        .all()
    )
    updated = 0
    for notification in notifications:
        if not notification.is_read:
            notification.is_read = True
            updated += 1

    if updated:
        db.session.commit()

    return updated, notifications


@app.route("/notifications/read", methods=["POST"])
def mark_notifications_read():
    user, auth_error = require_notification_user()
    if auth_error:
        return auth_error

    notification_ids, identity_alert_ids = _extract_notification_ids_from_request()
    if not notification_ids and not identity_alert_ids:
        return jsonify({"error": "Notification id required"}), 400

    updated, notifications = _mark_notification_ids_read(user.id, notification_ids)
    identity_updated = mark_identity_web_alerts_read(user.id, identity_alert_ids)
    if identity_updated:
        _record_identity_alert_review_gamification(user.id, identity_alert_ids)
    if not notifications and not identity_updated:
        return jsonify({"error": "Notification not found"}), 404

    return jsonify(
        {
            "success": True,
            "updated": int(updated or 0) + int(identity_updated or 0),
            "notifications": [_serialize_notification(n) for n in notifications],
            "unread_count": _notification_unread_count(user.id),
        }
    )


