def _parse_activity_date_bound(raw_value, *, end_of_day: bool = False):
    text_value = str(raw_value or "").strip()
    if not text_value:
        return None

    try:
        parsed = datetime.fromisoformat(text_value.replace("Z", "+00:00"))
    except ValueError:
        try:
            parsed = datetime.strptime(text_value, "%Y-%m-%d")
        except ValueError:
            return None

    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=UTC)
    else:
        parsed = parsed.astimezone(UTC)

    if len(text_value) <= 10 and end_of_day:
        parsed = parsed.replace(hour=23, minute=59, second=59, microsecond=999999)
    elif len(text_value) <= 10:
        parsed = parsed.replace(hour=0, minute=0, second=0, microsecond=0)

    return parsed


def _apply_activity_log_filters(query, *, user_id: int):
    query = query.filter(UserActivityLog.user_id == int(user_id))

    module_value = str(request.args.get("module") or "").strip().lower()
    if module_value:
        query = query.filter(UserActivityLog.module == normalize_activity_module(module_value))

    action_value = str(request.args.get("action_type") or "").strip().lower()
    if action_value:
        query = query.filter(
            UserActivityLog.action_type == normalize_activity_action_type(action_value)
        )

    status_value = str(request.args.get("status") or "").strip().lower()
    if status_value:
        query = query.filter(UserActivityLog.status == normalize_activity_status(status_value))

    severity_value = str(request.args.get("severity") or "").strip().lower()
    if severity_value:
        query = query.filter(
            UserActivityLog.severity == normalize_activity_severity(severity_value)
        )

    start_date = _parse_activity_date_bound(request.args.get("start_date"))
    if start_date is not None:
        query = query.filter(UserActivityLog.created_at >= start_date)

    end_date = _parse_activity_date_bound(request.args.get("end_date"), end_of_day=True)
    if end_date is not None:
        query = query.filter(UserActivityLog.created_at <= end_date)

    suspicious_only = str(request.args.get("suspicious_only") or "").strip().lower()
    if suspicious_only in {"1", "true", "yes"}:
        query = query.filter(UserActivityLog.is_suspicious.is_(True))

    search_value = str(request.args.get("search") or "").strip()
    if search_value:
        pattern = f"%{search_value}%"
        query = query.filter(
            or_(
                UserActivityLog.title.ilike(pattern),
                UserActivityLog.description.ilike(pattern),
                UserActivityLog.target_label.ilike(pattern),
                UserActivityLog.action_type.ilike(pattern),
                UserActivityLog.event_id.ilike(pattern),
            )
        )

    return query


@app.route("/api/activity-logs/me", methods=["GET"])
def list_my_activity_logs():
    user, auth_error = require_full_auth_user()
    if auth_error:
        return auth_error
    _identity_backfill_activity_logs(user.id)

    limit = _parse_positive_int(request.args.get("limit"), 20)
    limit = 20 if limit is None else min(limit, 100)
    offset = _parse_nonnegative_int(request.args.get("offset"), 0)

    base_query = _apply_activity_log_filters(UserActivityLog.query, user_id=user.id)
    total = base_query.count()
    records = (
        base_query.order_by(
            UserActivityLog.created_at.desc(),
            UserActivityLog.id.desc(),
        )
        .offset(offset)
        .limit(limit)
        .all()
    )

    return jsonify(
        {
            "logs": [
                _serialize_user_activity_log(record, include_metadata=False)
                for record in records
            ],
            "count": len(records),
            "total": total,
            "limit": limit,
            "offset": offset,
            "user_id": user.id,
        }
    )


