def _generate_monthly_report_for_user(
    user,
    report_month_key: Optional[str] = None,
    generation_mode: Optional[str] = None,
):
    normalized_mode = str(generation_mode or "").strip().lower()
    if report_month_key:
        normalized = normalize_report_month(report_month_key)
    elif normalized_mode == "current_month":
        normalized = compute_current_reporting_month()
    else:
        normalized = compute_reporting_month()
    if normalized is None:
        raise ValueError("Invalid report month")

    return generate_and_store_monthly_security_report(
        user=user,
        report_month=normalized,
        base_dir=BASE_DIR,
        monthly_report_model=MonthlySecurityReport,
        db_session=db.session,
        pcap_alert_query=_query_user_pcap_alert_records,
        list_recent_jobs=lambda: jobs.list_recent(limit=0),
        load_report_payload_for_job=_load_report_payload_for_job,
        render_pdf=render_monthly_security_report_pdf,
        create_notification=create_user_notification,
        activity_log_query=_query_user_activity_log_records,
        password_check_query=_query_user_password_check_records,
    )



GOOGLE_DRIVE_SCOPES = ("https://www.googleapis.com/auth/drive.file",)


def _google_drive_uploads_configured() -> bool:
    return bool(
        GOOGLE_DRIVE_UPLOADS_ENABLED
        and GOOGLE_DRIVE_SERVICE_ACCOUNT_FILE
        and GOOGLE_DRIVE_FOLDER_ID
    )


def _get_google_drive_service():
    if not _google_drive_uploads_configured():
        raise RuntimeError(
            "Google Drive upload is not configured. Check GOOGLE_DRIVE_UPLOADS_ENABLED, GOOGLE_DRIVE_SERVICE_ACCOUNT_FILE, and GOOGLE_DRIVE_FOLDER_ID."
        )

    credentials_path = Path(GOOGLE_DRIVE_SERVICE_ACCOUNT_FILE).expanduser()
    if not credentials_path.is_absolute():
        credentials_path = (BASE_DIR / credentials_path).resolve()

    if not credentials_path.exists():
        raise FileNotFoundError(
            f"Google Drive service account file was not found: {credentials_path}"
        )

    credentials = service_account.Credentials.from_service_account_file(
        str(credentials_path),
        scopes=list(GOOGLE_DRIVE_SCOPES),
    )
    return build_google_service("drive", "v3", credentials=credentials, cache_discovery=False)


def _upload_file_to_google_drive(*, file_path: Path, filename: str, description: str = "") -> dict:
    if not file_path.exists() or not file_path.is_file():
        raise FileNotFoundError("Report PDF file was not found.")

    service = _get_google_drive_service()

    metadata = {
        "name": filename,
        "parents": [GOOGLE_DRIVE_FOLDER_ID],
        "description": description,
        "mimeType": "application/pdf",
    }
    media = MediaFileUpload(str(file_path), mimetype="application/pdf", resumable=False)

    uploaded = (
        service.files()
        .create(
            body=metadata,
            media_body=media,
            fields="id,name,webViewLink,webContentLink",
        )
        .execute()
    )

    if GOOGLE_DRIVE_MAKE_PUBLIC:
        service.permissions().create(
            fileId=uploaded["id"],
            body={"type": "anyone", "role": "reader"},
            fields="id",
        ).execute()
        uploaded = (
            service.files()
            .get(fileId=uploaded["id"], fields="id,name,webViewLink,webContentLink")
            .execute()
        )

    return {
        "file_id": uploaded.get("id"),
        "name": uploaded.get("name"),
        "web_view_link": uploaded.get("webViewLink"),
        "web_content_link": uploaded.get("webContentLink"),
    }


def _find_monthly_report_pdf_path(report_month: str) -> Path | None:
    normalized = normalize_report_month(report_month)
    if normalized is None:
        return None

    output_dir = BASE_DIR / "reports" / "monthly"
    candidates = [
        output_dir / f"sentinel-monthly-security-report-{normalized.month_key}.pdf",
        output_dir / f"monthly-security-report-{normalized.month_key}.pdf",
        output_dir / f"{normalized.month_key}.pdf",
    ]

    for candidate in candidates:
        if candidate.exists() and candidate.is_file():
            return candidate

    # Fallback: find any PDF containing the month key.
    for candidate in output_dir.glob(f"*{normalized.month_key}*.pdf"):
        if candidate.is_file():
            return candidate

    return None



