@app.route("/api/reports/monthly/<report_month>/upload-drive", methods=["POST"])
def upload_monthly_report_to_drive(report_month):
    user, auth_error = require_full_auth_user()
    if auth_error:
        return auth_error

    normalized = normalize_report_month(report_month)
    if normalized is None:
        return jsonify({"error": "Invalid report month"}), 400

    if not GOOGLE_DRIVE_UPLOADS_ENABLED:
        return jsonify({"error": "Google Drive upload is disabled in .env"}), 400

    try:
        # Ensure the report exists and has a PDF.
        report_payload = _get_monthly_report_payload_for_user(user.id, normalized.month_key)
        if not isinstance(report_payload, dict):
            return jsonify({"error": "Monthly report was not found. Generate it first."}), 404

        pdf_path = _find_monthly_report_pdf_path(normalized.month_key)

        if pdf_path is None:
            # Generate/store a fresh report PDF if the file is missing.
            generated_record = _generate_monthly_report_for_user(
                user,
                normalized.month_key,
            )
            pdf_candidate = getattr(generated_record, "pdf_path", None)
            pdf_path = Path(pdf_candidate) if pdf_candidate else _find_monthly_report_pdf_path(normalized.month_key)

        if pdf_path is None or not pdf_path.exists():
            return jsonify({"error": "Report PDF is not available. Generate or download the PDF first."}), 404

        filename = f"sentinel-monthly-security-report-{normalized.month_key}.pdf"
        uploaded = _upload_file_to_google_drive(
            file_path=pdf_path,
            filename=filename,
            description=f"Sentinel AI monthly security report for {normalized.month_key}",
        )

        return jsonify(
            {
                "status": "success",
                "report_month": normalized.month_key,
                "drive_file": uploaded,
                "drive_link": uploaded.get("web_view_link"),
            }
        )
    except Exception as exc:
        logging.exception(
            "Failed to upload monthly report to Google Drive | user_id=%s | report_month=%s",
            getattr(user, "id", None),
            normalized.month_key,
        )
        return jsonify({"error": str(exc)}), 500


