@app.route("/api/auth/2fa/setup")
def setup_2fa():
    email = _normalize_linked_account_email(request.args.get("email", ""))
    user, _, auth_error = _get_pending_2fa_context({PENDING_2FA_SETUP_STATE})
    if auth_error:
        return auth_error
    if email and not _login_identifier_belongs_to_user(user, email):
        return (
            jsonify({"success": False, "message": "Pending 2FA session mismatch"}),
            403,
        )
    if not user.is_email_verified:
        return jsonify({"success": False, "message": "User not verified"}), 400
    if user.is_two_factor_enabled and user.two_factor_secret:
        return jsonify({"success": False, "message": "2FA already enabled"}), 409

    if user.two_factor_secret:
        secret = user.two_factor_secret
    else:
        secret = pyotp.random_base32()
        user.two_factor_secret = secret
        user.is_two_factor_enabled = False
        db.session.commit()

    totp = pyotp.TOTP(secret)
    otp_uri = totp.provisioning_uri(name=user.email, issuer_name="Sentinel AI")

    qr = qrcode.QRCode(box_size=6, border=2)
    qr.add_data(otp_uri)
    qr.make(fit=True)
    img = qr.make_image(fill_color="black", back_color="white")
    buf = io.BytesIO()
    img.save(buf, format="PNG")
    b64 = base64.b64encode(buf.getvalue()).decode()

    return jsonify(
        {
            "success": True,
            "secret": secret,
            "qr_image_url": f"data:image/png;base64,{b64}",
        }
    )


@app.route("/api/auth/2fa/verify-setup", methods=["POST"])
def verify_2fa_setup():
    data = request.get_json() or {}

    email = _normalize_linked_account_email(data.get("email", ""))
    code = data.get("code", "").strip()
    user, _, auth_error = _get_pending_2fa_context({PENDING_2FA_SETUP_STATE})
    if auth_error:
        return auth_error
    if email and not _login_identifier_belongs_to_user(user, email):
        return (
            jsonify({"success": False, "message": "Pending 2FA session mismatch"}),
            403,
        )
    if not user.two_factor_secret:
        return jsonify({"success": False, "message": "2FA setup not initialized"}), 400

    totp = pyotp.TOTP(user.two_factor_secret)

    if not totp.verify(code, valid_window=1):
        return jsonify({"success": False, "message": "Invalid code"}), 400

    user.is_two_factor_enabled = True
    user.require_two_factor_enrollment = False
    db.session.commit()

    resp = jsonify(
        {
            "success": True,
            "message": "2FA enabled. Please sign in to complete authentication.",
        }
    )
    session.clear()
    clear_auth_cookies(resp)
    clear_pending_2fa_cookie(resp)
    return resp


