@app.route("/api/contact/support", methods=["POST"])
@limiter.limit("5/minute")
def submit_contact_support():
    try:
        data = request.get_json(silent=True) or {}
        if not isinstance(data, dict):
            return _contact_validation_error("Invalid request payload.")

        honeypot = _clean_contact_text(
            data.get("honeypot") or data.get("company") or data.get("website"),
            120,
        )
        if honeypot:
            return _contact_validation_error("Unable to submit this request.", status_code=400)

        full_name = _clean_contact_text(data.get("full_name"), CONTACT_FIELD_LIMITS["full_name"])
        email = _clean_contact_text(data.get("email"), CONTACT_FIELD_LIMITS["email"]).lower()
        category = _clean_contact_text(data.get("category"), CONTACT_FIELD_LIMITS["category"])
        subject = _clean_contact_text(data.get("subject"), CONTACT_FIELD_LIMITS["subject"])
        message = _clean_contact_text(data.get("message"), CONTACT_FIELD_LIMITS["message"])

        if not full_name:
            return _contact_validation_error("Full name is required.", "full_name")
        if not email:
            return _contact_validation_error("Email is required.", "email")
        if not CONTACT_EMAIL_RE.fullmatch(email):
            return _contact_validation_error("A valid email address is required.", "email")
        if category not in CONTACT_SUPPORT_CATEGORIES:
            return _contact_validation_error("A valid support category is required.", "category")
        if not subject:
            return _contact_validation_error("Subject is required.", "subject")
        if not message:
            return _contact_validation_error("Message is required.", "message")
        if len(message) < 10:
            return _contact_validation_error("Message must be at least 10 characters.", "message")

        _ensure_contact_message_schema_initialized()
        contact_message = ContactMessage(
            full_name=full_name,
            email=email,
            category=category,
            subject=subject,
            message=message,
            status="new",
        )
        db.session.add(contact_message)
        db.session.commit()

        email_sent = False
        try:
            email_sent = _send_contact_support_email(
                full_name=full_name,
                email=email,
                category=category,
                subject=subject,
                message=message,
            )
        except Exception:
            logging.exception("Failed to email contact support message")

        return jsonify(
            {
                "success": True,
                "message": "Your message has been sent successfully.",
                "email_sent": email_sent,
            }
        ), 201
    except Exception:
        db.session.rollback()
        logging.exception("Failed to submit contact support message")
        return jsonify(
            {
                "success": False,
                "message": "We could not send your message. Please try again.",
            }
        ), 500


