@app.route("/api/scan/<int:asset_id>", methods=["POST"])
def scan_asset(asset_id):
    user = get_current_user()
    if not user:
        return jsonify({"error": "Unauthorized"}), 401

    conn = get_conn()
    cursor = conn.cursor()
    try:
        cursor.execute(
            "SELECT id, asset, asset_type FROM monitored_assets WHERE id=? AND user_id=?",
            (asset_id, user.id),
        )
        row = cursor.fetchone()
        if not row:
            return jsonify({"error": "Asset not found"}), 404
        asset_row = {"id": row[0], "asset": row[1], "asset_type": row[2]}
        status, matches = perform_scan_for_asset(asset_row, user.id)
        save_scan_result(asset_row["id"], status, matches)
        return jsonify({"status": status, "matches": matches})
    finally:
        cursor.close()
        conn.close()


