@app.route("/api/check", methods=["POST"])
@limiter.limit("20/minute")
def check_asset():
    user = get_current_user()
    if not user:
        return jsonify({"error": "Unauthorized"}), 401

    data = request.get_json(force=True, silent=True) or {}

    q_raw = data.get("query", "")
    q = q_raw.strip()

    if not q:
        return jsonify({"error": "query is required"}), 400

    q_type = detect_type(q)
    conn = get_conn()
    cursor = conn.cursor()
    try:
        cursor.execute(
            "SELECT id FROM monitored_assets WHERE user_id=? AND asset=? AND asset_type=?",
            (user.id, q, q_type),
        )
        row = cursor.fetchone()
        if row:
            asset_id = row[0]
        else:
            now = datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S")
            cursor.execute(
                "INSERT INTO monitored_assets (user_id, asset, asset_type, auto_scan, enabled, last_checked, last_status, last_matches, updated_at) "
                "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (user.id, q, q_type, 0, 1, None, None, 0, now),
            )
            asset_id = cursor.lastrowid
            conn.commit()
    finally:
        cursor.close()
        conn.close()

    asset_row = {"id": asset_id, "user_id": user.id, "asset": q, "asset_type": q_type}

    status, matches = perform_scan_for_asset(asset_row, user.id)
    save_scan_result(asset_row["id"], status, matches)
    # save_scan_result(user.id, q, q_type, status, matches)

    return (
        jsonify(
            {
                "query": q,
                "type": q_type,
                "status": status,
                "count": len(matches),
                "matches": matches,
            }
        ),
        200,
    )


def _identity_web_now() -> str:
    return datetime.now(UTC).replace(microsecond=0).isoformat()


def _identity_validate_asset(asset_type: str, asset_value: str) -> tuple[str | None, str | None]:
    normalized_type = str(asset_type or "").strip().lower()
    normalized_value = str(asset_value or "").strip()
    if normalized_type not in {"email", "username", "domain"}:
        return None, "asset_type must be one of email, username, or domain"
    if normalized_type == "email":
        normalized_value = normalized_value.lower()
        if "@" not in normalized_value or normalized_value.startswith("@") or normalized_value.endswith("@"):
            return None, "email asset_value must contain a valid @ address"
    elif normalized_type == "domain":
        if normalized_value.lower().startswith(("http://", "https://")):
            return None, "domain asset_value must not include http:// or https://"
        normalized_value = normalized_value.lower().removeprefix("www.").strip("/")
        if not normalized_value or "/" in normalized_value or "." not in normalized_value:
            return None, "domain asset_value must be a bare domain like example.com"
    elif not normalized_value:
        return None, "username asset_value is required"
    return normalized_value, None


def _identity_scan_payload_for_asset(asset: dict) -> dict:
    asset_type = asset.get("asset_type")
    asset_value = asset.get("asset_value")
    return {
        "email": asset_value if asset_type == "email" else None,
        "username": asset_value if asset_type == "username" else None,
        "domain": asset_value if asset_type == "domain" else None,
    }


def _identity_risk_rank(level: str | None) -> int:
    return {"low": 0, "medium": 1, "high": 2, "critical": 3}.get(str(level or "Low").lower(), 0)


def _identity_current_user_id_response() -> tuple[int | None, object | None]:
    user = get_current_user()
    user_id = _safe_int(getattr(user, "id", None), 0) if user is not None else 0
    if not user_id:
        return None, (jsonify({"error": "Authentication required"}), 401)
    return user_id, None


def _identity_asset_is_risky(asset: dict) -> bool:
    level = str(asset.get("last_risk_level") or "Low").lower()
    return level in {"medium", "high", "critical"} or int(asset.get("exposure_findings_count") or 0) > 0


def _identity_protection_breakdown(user_id: int) -> dict:
    assets = list_identity_assets(user_id)
    total = len(assets)
    risky = sum(1 for asset in assets if _identity_asset_is_risky(asset))
    safe = total - risky
    rate = round((safe / total) * 100) if total else 0
    return {"safe": safe, "risky": risky, "total": total, "rate": rate}


def _pdf_text(value: object, limit: int = 500) -> str:
    cleaned = re.sub(r"\s+", " ", str(value or "-")).strip()
    if len(cleaned) <= limit:
        return cleaned
    return f"{cleaned[: limit - 3].rstrip()}..."


def _identity_scan_pdf(scan: dict, findings: list[dict], user_id: int) -> io.BytesIO:
    styles = getSampleStyleSheet()
    title_style = ParagraphStyle(
        "SentinelTitle",
        parent=styles["Title"],
        textColor=colors.HexColor("#0F172A"),
        fontName="Helvetica-Bold",
        fontSize=20,
        leading=24,
    )
    heading_style = ParagraphStyle(
        "SentinelHeading",
        parent=styles["Heading2"],
        textColor=colors.HexColor("#1E3A8A"),
        fontName="Helvetica-Bold",
        fontSize=12,
        leading=15,
        spaceBefore=10,
    )
    body_style = ParagraphStyle(
        "SentinelBody",
        parent=styles["BodyText"],
        fontName="Helvetica",
        fontSize=8,
        leading=10,
    )
    small_style = ParagraphStyle(
        "SentinelSmall",
        parent=styles["BodyText"],
        fontName="Helvetica",
        fontSize=7,
        leading=9,
        textColor=colors.HexColor("#334155"),
    )

    protection = _identity_protection_breakdown(user_id)
    history = list_identity_web_scans(user_id, 10)
    alerts = list_identity_web_alerts(user_id, 10)
    generated_at = _identity_web_now()
    scan_id = scan.get("scan_id") or scan.get("id") or "report"

    buffer = io.BytesIO()
    doc = SimpleDocTemplate(
        buffer,
        pagesize=landscape(A4),
        rightMargin=0.35 * inch,
        leftMargin=0.35 * inch,
        topMargin=0.35 * inch,
        bottomMargin=0.35 * inch,
        title=f"Identity Leak Monitor Report #{scan_id}",
    )

    story = [
        Paragraph("Identity Leak Monitor Report", title_style),
        Paragraph(f"Generated date/time: {_pdf_text(generated_at)}", small_style),
        Spacer(1, 0.12 * inch),
    ]

    summary_rows = [
        ["Email", _pdf_text(scan.get("email"))],
        ["Username", _pdf_text(scan.get("username"))],
        ["Domain", _pdf_text(scan.get("domain"))],
        ["Risk Score", _pdf_text(scan.get("risk_score", 0))],
        ["Risk Level", _pdf_text(scan.get("risk_level", "Low"))],
        ["Protection Rate", f"{protection['rate']}%"],
        ["Safe / Risky / Total Assets", f"{protection['safe']} / {protection['risky']} / {protection['total']}"],
    ]
    summary_table = PdfTable(summary_rows, colWidths=[1.7 * inch, 4.2 * inch])
    summary_table.setStyle(
        TableStyle(
            [
                ("BACKGROUND", (0, 0), (0, -1), colors.HexColor("#E0F2FE")),
                ("TEXTCOLOR", (0, 0), (0, -1), colors.HexColor("#0F172A")),
                ("FONTNAME", (0, 0), (0, -1), "Helvetica-Bold"),
                ("GRID", (0, 0), (-1, -1), 0.25, colors.HexColor("#CBD5E1")),
                ("VALIGN", (0, 0), (-1, -1), "TOP"),
                ("FONTSIZE", (0, 0), (-1, -1), 8),
                ("ROWBACKGROUNDS", (1, 0), (-1, -1), [colors.white, colors.HexColor("#F8FAFC")]),
            ]
        )
    )
    story.extend([Paragraph("Scan Summary", heading_style), summary_table])

    source_status = scan.get("source_status") or {}
    source_rows = [["Source", "Status"]]
    for key, label in [
        ("duckduckgo", "DuckDuckGo"),
        ("github", "GitHub"),
        ("gitlab", "GitLab"),
        ("stackexchange", "Stack Exchange"),
        ("leakcheck", "LeakCheck"),
    ]:
        value = source_status.get(key)
        if isinstance(value, dict):
            value = f"{value.get('status', 'unknown')} - {value.get('reason', '')}".strip(" -")
        source_rows.append([label, _pdf_text(value or "not checked")])
    source_table = PdfTable(source_rows, colWidths=[1.6 * inch, 2.2 * inch])
    source_table.setStyle(_identity_pdf_table_style(header_color="#DBEAFE"))
    story.extend([Spacer(1, 0.08 * inch), Paragraph("Sources Checked", heading_style), source_table])

    story.extend(
        [
            Spacer(1, 0.08 * inch),
            Paragraph("Recommendation", heading_style),
            Paragraph(_pdf_text(scan.get("recommendation") or "No confirmed public exposure was found. Continue periodic monitoring.", 900), body_style),
        ]
    )

    story.append(Paragraph("Findings", heading_style))
    if findings:
        finding_rows = [["Source", "Category", "Severity", "Matched Field", "Matched Value", "Evidence", "Found In Page", "Confidence", "Link"]]
        for finding in findings:
            finding_rows.append(
                [
                    Paragraph(_pdf_text(finding.get("source"), 90), small_style),
                    Paragraph(_pdf_text(finding.get("category"), 80), small_style),
                    Paragraph(_pdf_text(finding.get("severity"), 40), small_style),
                    Paragraph(_pdf_text(finding.get("matched_field"), 50), small_style),
                    Paragraph(_pdf_text(finding.get("matched_value"), 80), small_style),
                    Paragraph(_pdf_text(finding.get("evidence"), 260), small_style),
                    "Yes" if finding.get("found_in_page") else "No",
                    f"{int(finding.get('confidence') or 0)}%",
                    Paragraph(_pdf_text(finding.get("url"), 140), small_style),
                ]
            )
        findings_table = PdfTable(
            finding_rows,
            repeatRows=1,
            colWidths=[0.85 * inch, 0.9 * inch, 0.65 * inch, 0.75 * inch, 1.0 * inch, 2.3 * inch, 0.75 * inch, 0.65 * inch, 1.8 * inch],
        )
        findings_table.setStyle(_identity_pdf_table_style(header_color="#FEE2E2"))
        story.append(findings_table)
    else:
        story.append(Paragraph("No confirmed exposure findings were detected for this scan.", body_style))

    history_rows = [["Scan", "Target", "Risk", "Findings", "Created"]]
    for item in history:
        history_rows.append(
            [
                f"#{item.get('id') or item.get('scan_id')}",
                _pdf_text(" / ".join(str(item.get(key) or "") for key in ("email", "username", "domain")).strip(" / "), 140),
                _pdf_text(item.get("risk_level")),
                _pdf_text(item.get("total_findings", 0)),
                _pdf_text(item.get("created_at"), 80),
            ]
        )
    history_table = PdfTable(history_rows, repeatRows=1, colWidths=[0.7 * inch, 2.4 * inch, 0.8 * inch, 0.8 * inch, 1.8 * inch])
    history_table.setStyle(_identity_pdf_table_style(header_color="#E0E7FF"))
    story.extend([Spacer(1, 0.08 * inch), Paragraph("Scan History Summary", heading_style), history_table])

    alert_rows = [["Alert", "Severity", "Created"]]
    for alert in alerts:
        alert_rows.append([Paragraph(_pdf_text(alert.get("title"), 180), small_style), _pdf_text(alert.get("severity")), _pdf_text(alert.get("created_at"), 80)])
    alert_table = PdfTable(alert_rows, repeatRows=1, colWidths=[3.4 * inch, 0.9 * inch, 1.8 * inch])
    alert_table.setStyle(_identity_pdf_table_style(header_color="#FFEDD5"))
    story.extend([Spacer(1, 0.08 * inch), Paragraph("Alerts Summary", heading_style), alert_table])

    story.extend(
        [
            Spacer(1, 0.14 * inch),
            Paragraph("Generated by Sentinel AI - Identity Leak Monitor", small_style),
        ]
    )

    doc.build(story)
    buffer.seek(0)
    return buffer


def _identity_pdf_table_style(header_color: str = "#E2E8F0") -> TableStyle:
    return TableStyle(
        [
            ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor(header_color)),
            ("TEXTCOLOR", (0, 0), (-1, 0), colors.HexColor("#0F172A")),
            ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
            ("FONTSIZE", (0, 0), (-1, -1), 7),
            ("GRID", (0, 0), (-1, -1), 0.25, colors.HexColor("#CBD5E1")),
            ("VALIGN", (0, 0), (-1, -1), "TOP"),
            ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#F8FAFC")]),
            ("LEFTPADDING", (0, 0), (-1, -1), 4),
            ("RIGHTPADDING", (0, 0), (-1, -1), 4),
        ]
    )


@app.route("/api/identity/web-scan", methods=["POST"])
def identity_web_scan():
    user_id, auth_error = _identity_current_user_id_response()
    if auth_error:
        return auth_error
    data = request.get_json(force=True, silent=True) or {}
    email = str(data.get("email") or "").strip()
    username = str(data.get("username") or "").strip()
    domain = str(data.get("domain") or "").strip()

    if not any([email, username, domain]):
        return jsonify({"error": "At least one of email, username, or domain is required"}), 400

    created_at = _identity_web_now()
    scan_id = create_identity_web_scan(email, username, domain, created_at, user_id)
    target_label = _identity_safe_target(email, username, domain)
    _identity_log_event(
        user_id,
        "identity_scan_started",
        title="Identity scan started",
        description="A manual identity exposure scan was started.",
        status=STATUS_INFO,
        severity=SEVERITY_MEDIUM,
        target_type="identity_scan",
        target_id=str(scan_id),
        target_label=target_label,
        metadata_json={"scan_id": scan_id},
    )

    try:
        result = run_identity_web_scan(email=email, username=username, domain=domain)
        result["scan_id"] = scan_id
        completed_at = _identity_web_now()
        complete_identity_web_scan(scan_id, result, completed_at, user_id)
        findings = result.get("findings") or []
        save_identity_web_findings(scan_id, findings, completed_at, user_id)
        alert_id = create_identity_web_alert(
            scan_id,
            str(result.get("risk_level") or "Low"),
            int(result.get("total_findings") or 0),
            completed_at,
            user_id,
        )
        email_status = _send_identity_alert_email(
            alert_id,
            user_id,
            {"scan_id": scan_id, "email": email, "username": username, "domain": domain},
            result,
            findings,
        )
        _identity_log_scan_completed(user_id, scan_id, result, target_label)
        _identity_log_alerts(user_id, alert_id, scan_id, result, findings)
        _record_identity_scan_gamification(user_id, scan_id, result, target_label)
        result["created_at"] = created_at
        result["completed_at"] = completed_at
        result["email_status"] = email_status
        return jsonify(result), 200
    except ValueError as exc:
        fail_identity_web_scan(scan_id, str(exc), _identity_web_now(), user_id)
        return jsonify({"error": str(exc), "scan_id": scan_id}), 400
    except Exception:
        logging.exception("Identity Leak Monitor public web scan failed")
        fail_identity_web_scan(scan_id, "Public web scan failed. Please try again later.", _identity_web_now(), user_id)
        return jsonify({"error": "Public web scan failed. Please try again later.", "scan_id": scan_id}), 502


