@app.route("/api/identity/full-scan-assets", methods=["POST"])
def identity_full_scan_assets():
    user_id, auth_error = _identity_current_user_id_response()
    if auth_error:
        return auth_error
    assets = list_identity_assets(user_id)
    if not assets:
        return jsonify({"status": "empty", "message": "No monitored assets found. Add assets first."}), 200

    _identity_log_event(
        user_id,
        "identity_full_asset_scan_started",
        title="Identity full asset scan started",
        description="A scan was started for all monitored identity assets.",
        status=STATUS_INFO,
        severity=SEVERITY_MEDIUM,
        target_type="identity_assets",
        target_label=f"{len(assets)} monitored assets",
        metadata_json={"total_assets": len(assets)},
    )

    results = []
    total_findings = 0
    risky_assets = 0
    highest_risk_level = "Low"

    try:
        for asset in assets:
            payload = _identity_scan_payload_for_asset(asset)
            created_at = _identity_web_now()
            scan_id = create_identity_web_scan(payload["email"], payload["username"], payload["domain"], created_at, user_id)
            result = run_identity_web_scan(**payload)
            result["scan_id"] = scan_id
            completed_at = _identity_web_now()
            complete_identity_web_scan(scan_id, result, completed_at, user_id)
            findings = result.get("findings") or []
            save_identity_web_findings(scan_id, findings, completed_at, user_id)
            alert_id = create_identity_web_alert(
                scan_id,
                str(result.get("risk_level") or "Low"),
                int(result.get("total_findings") or 0),
                completed_at,
                user_id,
            )
            email_status = _send_identity_alert_email(
                alert_id,
                user_id,
                {"scan_id": scan_id, **payload},
                result,
                findings,
            )
            update_identity_asset_scan_result(asset["id"], scan_id, result, completed_at, user_id)
            asset_target = _identity_safe_target(asset.get("asset_type"), asset.get("asset_value"))
            _identity_log_scan_completed(user_id, scan_id, result, asset_target)
            _identity_log_alerts(user_id, alert_id, scan_id, result, findings)
            _record_identity_scan_gamification(user_id, scan_id, result, asset_target)

            level = str(result.get("risk_level") or "Low")
            findings_count = int(result.get("total_findings") or 0)
            total_findings += findings_count
            if _identity_risk_rank(level) >= _identity_risk_rank("Medium"):
                risky_assets += 1
            if _identity_risk_rank(level) > _identity_risk_rank(highest_risk_level):
                highest_risk_level = level

            results.append(
                {
                    "asset_id": asset["id"],
                    "asset_type": asset["asset_type"],
                    "asset_value": asset["asset_value"],
                    "scan_id": scan_id,
                    "risk_score": int(result.get("risk_score") or 0),
                    "risk_level": level,
                    "total_findings": findings_count,
                    "email_status": email_status,
                    "completed_at": completed_at,
                }
            )
    except Exception:
        logging.exception("Identity Leak Monitor full asset scan failed")
        return jsonify({"error": "Full asset scan failed. Please try again later."}), 502

    total_assets_scanned = len(results)
    _identity_log_event(
        user_id,
        "identity_full_asset_scan_completed",
        title="Identity full asset scan completed",
        description="All monitored identity assets were scanned.",
        status=STATUS_SUCCESS,
        severity=_identity_severity_from_risk_level(highest_risk_level),
        target_type="identity_assets",
        target_label=f"{total_assets_scanned} monitored assets",
        is_suspicious=_identity_risk_rank(highest_risk_level) >= _identity_risk_rank("High"),
        metadata_json={
            "total_assets_scanned": total_assets_scanned,
            "risky_assets": risky_assets,
            "clean_assets": total_assets_scanned - risky_assets,
            "total_findings": total_findings,
            "highest_risk_level": highest_risk_level,
        },
    )
    return jsonify(
        {
            "status": "completed",
            "total_assets_scanned": total_assets_scanned,
            "risky_assets": risky_assets,
            "clean_assets": total_assets_scanned - risky_assets,
            "total_findings": total_findings,
            "highest_risk_level": highest_risk_level,
            "results": results,
        }
    ), 200


