CHATBOT_LLM_MODULES = {
    "general",
    "pcap",
    "identity",
    "password",
    "phishing",
    "file_vault",
    "reports",
    "security_score",
}


def _normalize_chatbot_llm_module(value: object) -> str:
    normalized = safe_activity_str(value, "general").strip().lower().replace("-", "_")
    aliases = {
        "vault": "file_vault",
        "file": "file_vault",
        "files": "file_vault",
        "identity leak": "identity",
        "score": "security_score",
        "security score": "security_score",
        "risk score": "security_score",
        "security": "security_score",
        "report": "reports",
        "export": "reports",
        "reports center": "reports",
        "pcap_analyzer": "pcap",
        "identity_leak": "identity",
        "leaked_identity": "identity",
        "data_leak": "identity",
        "breach": "identity",
        "exposed_email": "identity",
        "exposed_username": "identity",
        "exposed_domain": "identity",
        "leaked_email": "identity",
        "dark_web": "identity",
        "osint": "identity",
        "public_exposure": "identity",
        "github_leak": "identity",
        "duckduckgo_leak": "identity",
        "leaks": "identity",
        "passwords": "password",
        "password_checker": "password",
        "password checker": "password",
        "password security": "password",
        "phishing_scanner": "phishing",
    }
    normalized = aliases.get(normalized, normalized)
    return normalized if normalized in CHATBOT_LLM_MODULES else "general"


def mask_email(email: object) -> str:
    value = safe_activity_str(email)
    if not value or "@" not in value:
        return ""
    local, _, domain = value.partition("@")
    if not domain:
        return f"{local[:2]}***"
    return f"{local[:2]}***@{domain[:80]}"


def mask_phone(phone: object) -> str:
    digits = re.sub(r"\D+", "", safe_activity_str(phone))
    if len(digits) < 4:
        return "***"
    return f"***{digits[-4:]}"


def mask_secret(value: object) -> str:
    text_value = safe_activity_str(value)
    if not text_value:
        return ""
    if "@" in text_value:
        return mask_email(text_value)
    if re.fullmatch(r"[\d\s()+-]{7,}", text_value):
        return mask_phone(text_value)
    if len(text_value) <= 6:
        return "***"
    return f"{text_value[:2]}***{text_value[-2:]}"


def _chatbot_sanitize_text(value: object) -> str:
    text_value = safe_activity_str(value)
    if not text_value:
        return ""
    text_value = re.sub(
        r"([A-Za-z0-9._%+-]{1,80})@([A-Za-z0-9.-]{1,120}\.[A-Za-z]{2,})",
        lambda match: mask_email(match.group(0)),
        text_value,
    )
    text_value = re.sub(
        r"(?<!\w)(?:\+?\d[\d\s().-]{6,}\d)(?!\w)",
        lambda match: mask_phone(match.group(0)),
        text_value,
    )
    return text_value[:500]


def _chatbot_empty_context(module: str, summary: str | None = None) -> dict[str, object]:
    return {
        "module": module,
        "available": False,
        "summary": summary or "No data is available for this module yet.",
        "risk_level": "Unknown",
        "evidence": [],
        "recommendations": [],
    }


def _chatbot_context_from_security_payload(module: str, payload: dict | None) -> dict[str, object]:
    if not isinstance(payload, dict):
        return _chatbot_empty_context(module)
    status = safe_activity_str(payload.get("status"), "unknown")
    risk_level = {
        "safe": "Low",
        "warning": "Medium",
        "risky": "High",
        "unknown": "Unknown",
    }.get(status.lower(), "Unknown")
    summary = _chatbot_sanitize_text(payload.get("summary")) or "No data is available for this module yet."
    recommendation = _chatbot_sanitize_text(payload.get("recommendation"))
    module_score = _safe_int(payload.get("module_score"), 0)
    evidence = []
    if module_score > 0:
        evidence.append(f"Module score: {module_score}/100")
    if status:
        evidence.append(f"Status: {status}")
    return {
        "module": module,
        "available": status.lower() != "unknown" or bool(module_score),
        "summary": summary,
        "risk_level": risk_level,
        "evidence": evidence,
        "recommendations": [recommendation] if recommendation else [],
    }


