def filter_user_facing_report_exports(export_formats) -> dict[str, list[str]]:
    if not isinstance(export_formats, dict):
        return {}

    filtered: dict[str, list[str]] = {}
    for raw_name, raw_formats in export_formats.items():
        raw_key = safe_activity_str(raw_name).strip().lower()
        if not raw_key or "admin" in raw_key:
            continue

        normalized_key = REPORT_EXPORT_ALIASES.get(raw_key)
        if not normalized_key:
            continue

        allowed_formats = USER_FACING_REPORT_EXPORT_FORMATS.get(normalized_key, [])
        candidate_formats = raw_formats if isinstance(raw_formats, (list, tuple, set)) else []
        safe_formats = []
        for item in candidate_formats:
            fmt = safe_activity_str(item).strip().lower()
            if fmt and fmt in allowed_formats and "admin" not in fmt:
                safe_formats.append(fmt)
        filtered[normalized_key] = safe_formats

    return filtered


def _pcap_default_recommendations(risk_level: object) -> list[str]:
    normalized = safe_activity_str(risk_level, "Unknown").lower()
    if normalized == "critical":
        return [
            "Review critical and high severity alerts first.",
            "Inspect top detections and repeated attack families.",
            "Review suspicious and malicious flows.",
            "Check top source and destination IPs if available.",
            "Export the PCAP report for documentation.",
            "Compare ML labels with heuristic reasons before final judgment.",
            "If Zeek enrichment is enabled, review conn/dns/http/ssl evidence.",
            "Escalate critical findings to the admin/security analyst.",
        ]
    if normalized == "high":
        return [
            "Review high severity alerts first.",
            "Look for repeated suspicious behavior across detections, source IPs, and destination IPs.",
            "Review suspicious and malicious flows before taking action.",
            "Compare ML labels with heuristic reasons and available evidence.",
            "Export the PCAP report for documentation and follow-up.",
            "Escalate high-risk findings if they affect important systems.",
        ]
    if normalized == "medium":
        return [
            "Investigate medium severity alerts and repeated patterns.",
            "Monitor the involved hosts and services for recurrence.",
            "Use confidence, heuristic reasons, and severity together before deciding.",
            "Export or preserve the report for comparison with future analyses.",
        ]
    return [
        "Preserve the PCAP report as a baseline reference.",
        "Continue monitoring for new suspicious or malicious flows.",
        "Re-run analysis if new evidence or a larger capture becomes available.",
    ]


def _pcap_report_sections_available(report: dict) -> dict[str, object]:
    if not isinstance(report, dict):
        return {}
    sections: dict[str, object] = {}
    for key in ("meta", "summary"):
        sections[key] = isinstance(report.get(key), dict)
    for key in ("clusters", "alerts", "timeline", "risk_per_ip"):
        value = report.get(key)
        sections[key] = len(value) if isinstance(value, list) else 0
    sections["evidence_details"] = bool(
        report.get("evidence")
        or report.get("evidence_details")
        or report.get("evidence_summary")
    )
    meta = report.get("meta") if isinstance(report.get("meta"), dict) else {}
    sections["base_vs_enriched_comparison"] = bool(
        report.get("comparison")
        or meta.get("comparison")
        or meta.get("base_vs_enriched_comparison")
    )
    return sections


def _pcap_raw_report_items(report: dict) -> list[dict]:
    if not isinstance(report, dict):
        return []
    raw_items: list[dict] = []
    for key in ("alerts", "clusters"):
        values = report.get(key)
        if isinstance(values, list):
            raw_items.extend(item for item in values if isinstance(item, dict))
    timeline = report.get("timeline")
    if isinstance(timeline, list):
        raw_items.extend(item for item in timeline[:120] if isinstance(item, dict))
    return raw_items[:180]


def _pcap_item_label(item: dict) -> str:
    return _chatbot_sanitize_text(
        item.get("label")
        or item.get("attack_type")
        or item.get("ml_label")
        or item.get("top_attack")
        or item.get("name")
        or "Network anomaly"
    )


def _pcap_item_reason(item: dict) -> str:
    return _chatbot_sanitize_text(
        item.get("heuristic_reason")
        or item.get("validation_reason")
        or item.get("reason")
        or item.get("explanation")
        or item.get("support_reason")
    )


def _pcap_item_ml_label(item: dict) -> str:
    return _chatbot_sanitize_text(item.get("ml_label") or item.get("label") or item.get("attack_type"))


def _pcap_item_src_ip(item: dict) -> str:
    return safe_activity_str(item.get("source_ip") or item.get("src_ip") or item.get("id.orig_h"))


def _pcap_item_dst_ip(item: dict) -> str:
    return safe_activity_str(item.get("dest_ip") or item.get("dst_ip") or item.get("destination_ip") or item.get("id.resp_h"))


def _pcap_item_port(item: dict) -> int | None:
    port = _safe_int(item.get("dst_port") or item.get("destination_port") or item.get("id.resp_p"), 0)
    return port if port > 0 else None


