def _pcap_chatbot_normalize_severity(value: object) -> str:
    normalized = safe_activity_str(value).strip().lower()
    if normalized in {"critical", "high", "medium", "low", "info"}:
        return normalized
    if normalized in {"warning", "informational"}:
        return "info" if normalized == "informational" else "low"
    if normalized in {"normal", "safe", "benign", ""}:
        return "info"
    return normalized or "info"


def _pcap_chatbot_severity_rank(value: object) -> int:
    return {"critical": 5, "high": 4, "medium": 3, "low": 2, "info": 1}.get(
        _pcap_chatbot_normalize_severity(value),
        0,
    )


def _pcap_chatbot_ip_role(roles: set[str]) -> str:
    if "source" in roles and "destination" in roles:
        return "mixed"
    if "source" in roles:
        return "source"
    if "destination" in roles:
        return "destination"
    return "unknown"


def _pcap_chatbot_is_interesting_flow(item: dict) -> bool:
    verdict = safe_activity_str(item.get("verdict") or item.get("severity")).lower()
    label = safe_activity_str(item.get("ml_label") or item.get("attack_type") or item.get("label")).lower()
    confidence = _pcap_raw_item_confidence(item)
    if verdict not in {"", "normal", "benign", "safe"}:
        return True
    if label and label not in {"benign", "normal", "safe"}:
        return True
    return confidence > 0


def _pcap_chatbot_label_from_item(item: dict) -> str:
    return _humanize_pcap_attack_label(
        item.get("attack_type")
        or item.get("ml_label")
        or item.get("label")
        or item.get("top_attack")
        or item.get("name")
        or "Network anomaly"
    )


def _pcap_chatbot_reason_from_item(item: dict) -> str:
    return _chatbot_sanitize_text(
        item.get("reason")
        or item.get("validation_reason")
        or item.get("heuristic_reason")
        or item.get("explanation")
    )


def _pcap_build_top_threats(report: dict, context: dict | None = None) -> list[dict[str, object]]:
    if not isinstance(report, dict):
        return []
    context = context if isinstance(context, dict) else {}
    summary = report.get("summary") if isinstance(report.get("summary"), dict) else {}
    threat_counter: dict[str, dict[str, object]] = {}

    def add(name: object, *, count: object = 1, severity: object = None, reason: object = None) -> None:
        label = _humanize_pcap_attack_label(name)
        if not label or label.lower() in {"benign", "normal", "safe", "unknown"}:
            return
        item = threat_counter.setdefault(
            label,
            {
                "name": label,
                "count": 0,
                "severity": "info",
                "reason": "",
            },
        )
        item["count"] = _safe_int(item.get("count"), 0) + max(1, _safe_int(count, 1))
        if _pcap_chatbot_severity_rank(severity) > _pcap_chatbot_severity_rank(item.get("severity")):
            item["severity"] = _pcap_chatbot_normalize_severity(severity)
        if not item.get("reason") and reason:
            item["reason"] = _chatbot_sanitize_text(reason)[:180]

    top_risk = summary.get("top_risk") if isinstance(summary.get("top_risk"), dict) else {}
    if top_risk:
        add(
            top_risk.get("name"),
            count=top_risk.get("count") or 1,
            severity=top_risk.get("severity") or summary.get("risk_level"),
            reason=summary.get("security_summary"),
        )

    clusters = report.get("clusters") if isinstance(report.get("clusters"), list) else []
    for item in clusters[:80]:
        if isinstance(item, dict):
            add(
                item.get("attack_type") or item.get("ml_label"),
                count=item.get("count_flows") or item.get("count") or 1,
                severity=item.get("severity"),
                reason=item.get("reason"),
            )

    alerts = report.get("alerts") if isinstance(report.get("alerts"), list) else []
    for item in alerts[:120]:
        if isinstance(item, dict):
            add(
                item.get("ml_label") or item.get("attack_type") or item.get("type"),
                count=item.get("count_flows") or item.get("count") or 1,
                severity=item.get("severity") or item.get("verdict"),
                reason=item.get("reason"),
            )

    if not threat_counter:
        timeline = report.get("timeline") if isinstance(report.get("timeline"), list) else []
        for item in timeline[:500]:
            if isinstance(item, dict) and _pcap_chatbot_is_interesting_flow(item):
                add(
                    item.get("ml_label"),
                    count=1,
                    severity=item.get("verdict"),
                    reason=item.get("reason"),
                )

    if not threat_counter:
        for name, count in (context.get("attack_counts") or {}).items():
            add(name, count=count, severity=summary.get("risk_level"))

    return sorted(
        threat_counter.values(),
        key=lambda item: (_pcap_chatbot_severity_rank(item.get("severity")), _safe_int(item.get("count"), 0)),
        reverse=True,
    )[:8]


def _pcap_build_top_alerts(report: dict) -> list[dict[str, object]]:
    if not isinstance(report, dict):
        return []
    alerts = report.get("alerts") if isinstance(report.get("alerts"), list) else []
    rows: list[dict[str, object]] = []
    for item in alerts[:10]:
        if not isinstance(item, dict):
            continue
        rows.append(
            {
                "type": _pcap_chatbot_label_from_item(item),
                "severity": _pcap_chatbot_normalize_severity(item.get("severity") or item.get("verdict")),
                "confidence": round(_pcap_raw_item_confidence(item), 4) if _pcap_raw_item_confidence(item) > 0 else None,
                "reason": _pcap_chatbot_reason_from_item(item)[:220],
                "src_ip": _pcap_item_src_ip(item) or None,
                "dst_ip": _pcap_item_dst_ip(item) or None,
            }
        )
    return rows


def _pcap_ip_summary_from_records(records: list[dict], source: str) -> dict[str, object]:
    ip_rows: dict[str, dict[str, object]] = {}

    def add_ip(ip: str, role: str, item: dict) -> None:
        if not ip:
            return
        severity = _pcap_chatbot_normalize_severity(item.get("severity") or item.get("verdict"))
        label = _pcap_chatbot_label_from_item(item)
        entry = ip_rows.setdefault(
            ip,
            {
                "ip": ip,
                "roles": set(),
                "alert_count": 0,
                "severity_counts": {"critical": 0, "high": 0, "medium": 0, "low": 0, "info": 0},
                "detections": Counter(),
                "max_severity": "info",
                "reason": "",
            },
        )
        entry["roles"].add(role)
        entry["alert_count"] = _safe_int(entry.get("alert_count"), 0) + max(1, _safe_int(item.get("count_flows") or item.get("count"), 1))
        counts = entry["severity_counts"]
        counts[severity] = _safe_int(counts.get(severity), 0) + 1
        entry["detections"][label] += 1
        if _pcap_chatbot_severity_rank(severity) > _pcap_chatbot_severity_rank(entry.get("max_severity")):
            entry["max_severity"] = severity
        reason = _pcap_chatbot_reason_from_item(item)
        if reason and not entry.get("reason"):
            entry["reason"] = reason[:180]

    for item in records:
        if not isinstance(item, dict):
            continue
        src_ip = _pcap_item_src_ip(item)
        dst_ip = _pcap_item_dst_ip(item)
        add_ip(src_ip, "source", item)
        add_ip(dst_ip, "destination", item)

    top_ips = []
    for entry in ip_rows.values():
        detections = [
            name
            for name, _count in entry["detections"].most_common(4)
            if name and name.lower() not in {"benign", "normal", "safe"}
        ]
        top_ips.append(
            {
                "ip": entry["ip"],
                "role": _pcap_chatbot_ip_role(entry["roles"]),
                "risk_level": entry["max_severity"],
                "alert_count": _safe_int(entry.get("alert_count"), 0),
                "severity_counts": entry["severity_counts"],
                "top_detection_types": detections,
                "reason": entry.get("reason") or (
                    "Repeated non-benign flow observations were present in the latest report."
                    if source == "flows"
                    else "IP appeared in promoted PCAP findings."
                ),
            }
        )

    top_ips.sort(
        key=lambda item: (
            _pcap_chatbot_severity_rank(item.get("risk_level")),
            _safe_int(item.get("alert_count"), 0),
        ),
        reverse=True,
    )
    return {
        "available": bool(top_ips),
        "source": source if top_ips else "unavailable",
        "top_ips": top_ips[:8],
    }


def _pcap_build_ip_review_summary(report: dict, context: dict | None = None) -> dict[str, object]:
    if not isinstance(report, dict):
        return {"available": False, "source": "unavailable", "top_ips": []}
    risk_per_ip = report.get("risk_per_ip") if isinstance(report.get("risk_per_ip"), list) else []
    if risk_per_ip:
        rows = []
        for item in risk_per_ip[:8]:
            if not isinstance(item, dict):
                continue
            ip = safe_activity_str(item.get("ip") or item.get("src_ip") or item.get("dst_ip"))
            if not ip:
                continue
            risk_score = _safe_float(item.get("ip_risk_score") or item.get("risk_score") or item.get("score"), 0.0)
            risk_level = (
                safe_activity_str(item.get("top_severity") or item.get("risk_level")).lower()
                or ("critical" if risk_score >= 85 else "high" if risk_score >= 70 else "medium" if risk_score >= 40 else "low")
            )
            rows.append(
                {
                    "ip": ip,
                    "role": safe_activity_str(item.get("role"), "unknown"),
                    "risk_level": _pcap_chatbot_normalize_severity(risk_level),
                    "alert_count": _safe_int(item.get("threat_count") or item.get("suspicious_count"), 0),
                    "severity_counts": {},
                    "top_detection_types": [safe_activity_str(item.get("top_attack"))] if safe_activity_str(item.get("top_attack")) else [],
                    "reason": f"IP-level risk score {round(risk_score, 1)}/100 from report risk_per_ip.",
                }
            )
        if rows:
            return {"available": True, "source": "risk_per_ip", "top_ips": rows}

    alerts = report.get("alerts") if isinstance(report.get("alerts"), list) else []
    alert_records = [item for item in alerts if isinstance(item, dict) and (_pcap_item_src_ip(item) or _pcap_item_dst_ip(item))]
    if alert_records:
        return _pcap_ip_summary_from_records(alert_records, "alerts")

    timeline = report.get("timeline") if isinstance(report.get("timeline"), list) else []
    flow_records = [
        item
        for item in timeline[:2000]
        if isinstance(item, dict) and _pcap_chatbot_is_interesting_flow(item) and (_pcap_item_src_ip(item) or _pcap_item_dst_ip(item))
    ]
    if flow_records:
        return _pcap_ip_summary_from_records(flow_records, "flows")

    clusters = report.get("clusters") if isinstance(report.get("clusters"), list) else []
    cluster_records = [item for item in clusters if isinstance(item, dict) and (_pcap_item_src_ip(item) or _pcap_item_dst_ip(item))]
    if cluster_records:
        return _pcap_ip_summary_from_records(cluster_records, "clusters")

    context = context if isinstance(context, dict) else {}
    top_ips = context.get("top_ips") if isinstance(context.get("top_ips"), list) else []
    if top_ips:
        rows = []
        for item in top_ips[:8]:
            if not isinstance(item, dict):
                continue
            ip = safe_activity_str(item.get("ip"))
            if not ip:
                continue
            rows.append(
                {
                    "ip": ip,
                    "role": safe_activity_str(item.get("role"), "unknown"),
                    "risk_level": "info",
                    "alert_count": _safe_int(item.get("count"), 1),
                    "severity_counts": {},
                    "top_detection_types": [safe_activity_str(item.get("attack"))] if safe_activity_str(item.get("attack")) else [],
                    "reason": "IP appeared in chatbot top host summary.",
                }
            )
        if rows:
            return {"available": True, "source": "top_ips", "top_ips": rows}

    return {"available": False, "source": "unavailable", "top_ips": []}


def _pcap_build_unified_context(context: dict, summary: dict, report: dict) -> dict[str, object]:
    job_state = context.get("job") if isinstance(context, dict) else None
    report = report if isinstance(report, dict) else {}
    report_summary = report.get("summary") if isinstance(report.get("summary"), dict) else {}
    meta = report.get("meta") if isinstance(report.get("meta"), dict) else {}
    severity_raw = report_summary.get("severity_counts") if isinstance(report_summary.get("severity_counts"), dict) else summary.get("severity_counts") or {}
    severity_counts = {
        "critical": _safe_int(severity_raw.get("critical") or severity_raw.get("Critical"), 0),
        "high": _safe_int(severity_raw.get("high") or severity_raw.get("High"), 0),
        "medium": _safe_int(severity_raw.get("medium") or severity_raw.get("Medium"), 0),
        "low": _safe_int(severity_raw.get("low") or severity_raw.get("Low"), 0),
        "info": _safe_int(severity_raw.get("info") or severity_raw.get("Info"), 0),
    }
    total_alerts = _safe_int(report_summary.get("alerts_count") or summary.get("alerts_count"), 0)
    suspicious = _safe_int(report_summary.get("suspicious") or summary.get("suspicious"), 0)
    malicious = _safe_int(report_summary.get("malicious") or summary.get("malicious"), 0)
    risk_level = safe_activity_str(report_summary.get("risk_level") or summary.get("risk_level"), "unknown")
    top_threats = _pcap_build_top_threats(report, context)
    top_alerts = _pcap_build_top_alerts(report)
    ip_review_summary = _pcap_build_ip_review_summary(report, context)
    has_report = bool(report and summary.get("analysis_id"))
    is_clean = None
    if has_report:
        is_clean = total_alerts <= 0 and suspicious <= 0 and malicious <= 0 and _pcap_chatbot_severity_rank(risk_level) <= 2
    return {
        "has_latest_report": has_report,
        "latest_job_id": safe_activity_str(summary.get("analysis_id")) or None,
        "latest_report_id": safe_activity_str(summary.get("analysis_id")) or None,
        "status": safe_activity_str(summary.get("status") or getattr(job_state, "status", None), "unknown"),
        "analyzed_at": safe_activity_str(getattr(job_state, "finished_at", None) or meta.get("generated_at")) or None,
        "filename": _chatbot_sanitize_text(summary.get("filename")) or None,
        "summary": {
            "total_flows": _safe_int(report_summary.get("total_flows") or summary.get("total_flows"), 0) if has_report else None,
            "suspicious_flows": suspicious if has_report else None,
            "malicious_flows": malicious if has_report else None,
            "total_alerts": total_alerts if has_report else None,
            "risk_level": risk_level,
            "overall_risk": report_summary.get("overall_risk") if has_report else None,
            "security_score": report_summary.get("security_score") if has_report else None,
            "is_clean": is_clean,
        },
        "severity_counts": severity_counts,
        "top_threats": top_threats,
        "top_alerts": top_alerts,
        "ip_review_summary": ip_review_summary,
        "pipeline_summary": {"steps": PCAP_CHATBOT_PIPELINE_STEPS},
        "scoring_summary": {
            "available": True,
            "explanation": "PCAP uses the implemented scorer/reporter logic only: ML score, heuristic score, support level, validation/suppression, final verdict, overall_risk, and report security_score.",
        },
        "context_safe": True,
    }


def _pcap_debug_context_from_safe_context(safe_context: dict) -> dict[str, object]:
    pcap_context = safe_context.get("pcap_context") if isinstance(safe_context.get("pcap_context"), dict) else {}
    summary = pcap_context.get("summary") if isinstance(pcap_context.get("summary"), dict) else {}
    ip_summary = pcap_context.get("ip_review_summary") if isinstance(pcap_context.get("ip_review_summary"), dict) else {}
    top_ips = ip_summary.get("top_ips") if isinstance(ip_summary.get("top_ips"), list) else []
    return {
        "module": "pcap",
        "has_latest_report": bool(pcap_context.get("has_latest_report")),
        "latest_job_id": pcap_context.get("latest_job_id"),
        "status": pcap_context.get("status"),
        "risk_level": summary.get("risk_level"),
        "total_alerts": summary.get("total_alerts"),
        "severity_counts": pcap_context.get("severity_counts") or {},
        "top_threats_count": len(pcap_context.get("top_threats") or []),
        "has_ip_review_summary": bool(ip_summary.get("available")),
        "ip_summary_source": safe_activity_str(ip_summary.get("source"), "unavailable"),
        "top_ips_count": len(top_ips),
        "top_ips_preview": [
            {
                "ip": safe_activity_str(item.get("ip")),
                "risk_level": safe_activity_str(item.get("risk_level"), "unknown"),
                "alert_count": _safe_int(item.get("alert_count"), 0),
            }
            for item in top_ips[:5]
            if isinstance(item, dict)
        ],
        "context_safe": True,
    }


def _pcap_dynamic_report_details(report: dict, context: dict) -> dict[str, object]:
    raw_items = _pcap_raw_report_items(report)
    threat_items = context.get("threat_items") or []
    confidence_values = []
    ml_labels = Counter()
    heuristic_reasons = []
    top_flows = []
    source_counter = Counter()
    destination_counter = Counter()

    for item in raw_items:
        confidence = _pcap_raw_item_confidence(item)
        if confidence > 0:
            confidence_values.append(confidence)
        ml_label = _pcap_item_ml_label(item)
        if ml_label:
            ml_labels[ml_label] += 1
        reason = _pcap_item_reason(item)
        if reason and reason not in heuristic_reasons:
            heuristic_reasons.append(reason)
        src_ip = _pcap_item_src_ip(item)
        dst_ip = _pcap_item_dst_ip(item)
        if src_ip:
            source_counter[src_ip] += 1
        if dst_ip:
            destination_counter[dst_ip] += 1
        if len(top_flows) < 8:
            top_flows.append(
                {
                    "label": _pcap_item_label(item),
                    "severity": _pcap_raw_item_severity(item),
                    "confidence": round(confidence, 4) if confidence > 0 else None,
                    "source_ip": src_ip or None,
                    "destination_ip": dst_ip or None,
                    "destination_port": _pcap_item_port(item),
                    "protocol": safe_activity_str(
                        item.get("protocol")
                        or item.get("zeek_proto")
                        or item.get("proto")
                        or item.get("service")
                        or item.get("zeek_service")
                    ) or None,
                    "reason": reason or None,
                }
            )

    if not top_flows:
        for item in threat_items[:8]:
            if not isinstance(item, dict):
                continue
            src_ip = safe_activity_str(item.get("src_ip"))
            dst_ip = safe_activity_str(item.get("dst_ip"))
            if src_ip:
                source_counter[src_ip] += _safe_int(item.get("count"), 1)
            if dst_ip:
                destination_counter[dst_ip] += _safe_int(item.get("count"), 1)
            confidence = _safe_float(item.get("confidence"), 0.0)
            if confidence > 0:
                confidence_values.append(confidence)
            top_flows.append(
                {
                    "label": _chatbot_sanitize_text(item.get("name")) or "Network anomaly",
                    "severity": safe_activity_str(item.get("severity"), "info"),
                    "confidence": round(confidence, 4) if confidence > 0 else None,
                    "source_ip": src_ip or None,
                    "destination_ip": dst_ip or None,
                    "destination_port": item.get("dst_port"),
                    "protocol": safe_activity_str(item.get("protocol")) or None,
                    "reason": _chatbot_sanitize_text(item.get("reason")) or None,
                }
            )

    confidence_summary = {
        "available": bool(confidence_values),
        "min": round(min(confidence_values), 4) if confidence_values else None,
        "max": round(max(confidence_values), 4) if confidence_values else None,
        "average": round(sum(confidence_values) / len(confidence_values), 4) if confidence_values else None,
        "count": len(confidence_values),
    }
    top_source_ips = [{"ip": ip, "count": count} for ip, count in source_counter.most_common(5)]
    top_destination_ips = [{"ip": ip, "count": count} for ip, count in destination_counter.most_common(5)]
    ip_details_available = bool(top_source_ips or top_destination_ips or context.get("top_ips"))

    return {
        "top_source_ips_in_alerts": top_source_ips,
        "top_destination_ips_in_alerts": top_destination_ips,
        "top_risky_flows": top_flows,
        "confidence_summary": confidence_summary,
        "ml_labels": [{"label": label, "count": count} for label, count in ml_labels.most_common(8)],
        "heuristic_reasons": heuristic_reasons[:8],
        "ip_details_available": ip_details_available,
        "ip_summary": (
            "Per-IP alert details are available in the latest context."
            if ip_details_available
            else "The latest context does not include per-IP alert details."
        ),
    }


def _safe_pcap_llm_context(user, user_id: int | None) -> dict[str, object]:
    static_context = PCAP_STATIC_MODULE_KNOWLEDGE
    scoring_logic = _pcap_scoring_logic_context()
    if user is None:
        context = _chatbot_empty_context("pcap", "No authenticated PCAP analysis data is available yet.")
        context.update(
            {
                "available": True,
                "dynamic_context_available": False,
                "static_context_available": True,
                "static_module_knowledge": static_context,
                "pcap_scoring_logic": scoring_logic,
                "ip_details_available": False,
                "ip_summary": "The latest context does not include per-IP alert details.",
                "pcap_context": _pcap_build_unified_context({}, {}, {}),
            }
        )
        return context
    try:
        context = _pcap_chatbot_context(user, None, True)
        summary = _pcap_context_summary(context)
        if not summary.get("analysis_id"):
            empty_context = _chatbot_empty_context("pcap")
            empty_context.update(
                {
                    "available": True,
                    "dynamic_context_available": False,
                    "static_context_available": True,
                    "static_module_knowledge": static_context,
                    "pcap_scoring_logic": scoring_logic,
                    "ip_details_available": False,
                    "ip_summary": "The latest context does not include per-IP alert details.",
                    "pcap_context": _pcap_build_unified_context(context, {}, {}),
                }
            )
            return empty_context
        severity_counts = summary.get("severity_counts") or {}
        risk_level = safe_activity_str(summary.get("risk_level"), "Unknown")
        job_state = context.get("job")
        report = context.get("report") or {}
        report_meta = report.get("meta") if isinstance(report.get("meta"), dict) else {}
        report_summary = report.get("summary") if isinstance(report.get("summary"), dict) else {}
        module_contract = report.get("module_contract") if isinstance(report.get("module_contract"), dict) else {}
        dynamic_details = _pcap_dynamic_report_details(report, context)
        unified_context = _pcap_build_unified_context(context, summary, report)
        top_risky_ips = context.get("top_ips") or []
        evidence = [
            f"Analysis ID: {summary.get('analysis_id')}",
            f"Status: {summary.get('status')}",
            f"Filename: {_chatbot_sanitize_text(summary.get('filename')) or 'Unavailable'}",
            f"Created at: {safe_activity_str(getattr(job_state, 'created_at', None) or getattr(job_state, 'started_at', None)) or 'Unavailable'}",
            f"Completed at: {safe_activity_str(getattr(job_state, 'finished_at', None) or getattr(job_state, 'completed_at', None)) or 'Unavailable'}",
            f"Total flows: {_safe_int(summary.get('total_flows'), 0)}",
            f"Alerts: {_safe_int(summary.get('alerts_count'), 0)}",
            f"Suspicious flows: {_safe_int(summary.get('suspicious'), 0)}",
            f"Malicious flows: {_safe_int(summary.get('malicious'), 0)}",
        ]
        attacks = summary.get("attack_counts") or {}
        if attacks:
            evidence.append(
                "Top detections: "
                + ", ".join(f"{safe_activity_str(name)} ({_safe_int(count, 0)})" for name, count in list(attacks.items())[:5])
            )
        if severity_counts:
            evidence.append(
                "Severity counts: "
                + ", ".join(f"{safe_activity_str(name)}={_safe_int(count, 0)}" for name, count in severity_counts.items())
            )
        report_recommendations = [
            _chatbot_sanitize_text(item)
            for item in (context.get("recommendations") or [])[:5]
            if _chatbot_sanitize_text(item)
        ]
        recommendations = report_recommendations or _pcap_default_recommendations(risk_level)
        return {
            "module": "pcap",
            "available": True,
            "dynamic_context_available": True,
            "static_context_available": True,
            "summary": (
                f"Latest PCAP analysis risk is {risk_level}. "
                f"Alerts: {_safe_int(summary.get('alerts_count'), 0)}."
            ),
            "risk_level": risk_level,
            "dynamic_analysis": {
                "analysis_id": safe_activity_str(summary.get("analysis_id")),
                "status": safe_activity_str(summary.get("status")),
                "filename": _chatbot_sanitize_text(summary.get("filename")) or None,
                "created_at": safe_activity_str(getattr(job_state, "created_at", None) or getattr(job_state, "started_at", None)) or None,
                "completed_at": safe_activity_str(getattr(job_state, "finished_at", None) or getattr(job_state, "completed_at", None)) or None,
                "total_flows": _safe_int(summary.get("total_flows"), 0),
                "alert_count": _safe_int(summary.get("alerts_count"), 0),
                "suspicious_flows": _safe_int(summary.get("suspicious"), 0),
                "malicious_flows": _safe_int(summary.get("malicious"), 0),
                "risk_level": risk_level,
                "top_detections": [
                    {"name": safe_activity_str(name), "count": _safe_int(count, 0)}
                    for name, count in list((summary.get("attack_counts") or {}).items())[:8]
                ],
                "severity_counts": severity_counts,
                "top_risky_ips": top_risky_ips[:5],
                "top_source_ips_in_alerts": dynamic_details["top_source_ips_in_alerts"],
                "top_destination_ips_in_alerts": dynamic_details["top_destination_ips_in_alerts"],
                "top_risky_flows": dynamic_details["top_risky_flows"],
                "confidence_summary": dynamic_details["confidence_summary"],
                "ml_labels": dynamic_details["ml_labels"],
                "heuristic_reasons": dynamic_details["heuristic_reasons"],
                "zeek_evidence_available": bool(
                    report_meta.get("zeek_evidence_available")
                    or report_meta.get("zeek_enrichment_succeeded")
                    or getattr(job_state, "evidence_dir", None)
                ),
                "zeek_requested": report_meta.get("zeek_requested"),
                "analysis_mode": safe_activity_str(report_meta.get("analysis_mode")) or None,
                "report_sections_available": _pcap_report_sections_available(report),
                "score_fields_available": {
                    "overall_risk": report_summary.get("overall_risk"),
                    "security_score": report_summary.get("security_score"),
                    "security_score_level": report_summary.get("security_score_level"),
                    "risk_display": report_summary.get("risk_display"),
                    "risk_context_label": report_summary.get("risk_context_label"),
                    "score_explanation": report_summary.get("score_explanation"),
                    "module_contract_supporting_metrics": module_contract.get("supporting_metrics")
                    if isinstance(module_contract.get("supporting_metrics"), dict)
                    else None,
                },
                "pcap_context": unified_context,
                "ip_details_available": dynamic_details["ip_details_available"],
                "ip_summary": dynamic_details["ip_summary"],
            },
            "pcap_context": unified_context,
            "static_module_knowledge": static_context,
            "pcap_scoring_logic": scoring_logic,
            "ip_details_available": dynamic_details["ip_details_available"],
            "ip_summary": dynamic_details["ip_summary"],
            "evidence": evidence,
            "recommendations": recommendations,
        }
    except Exception:
        logging.exception("Safe PCAP chatbot context failed | user_id=%s", user_id)
        context = _chatbot_empty_context("pcap")
        context.update(
            {
                "available": True,
                "dynamic_context_available": False,
                "static_context_available": True,
                "static_module_knowledge": static_context,
                "pcap_scoring_logic": scoring_logic,
                "ip_details_available": False,
                "ip_summary": "The latest context does not include per-IP alert details.",
                "pcap_context": _pcap_build_unified_context({}, {}, {}),
            }
        )
        return context


def _safe_identity_llm_context(user_id: int | None) -> dict[str, object]:
    static_context = IDENTITY_STATIC_MODULE_KNOWLEDGE
    if not user_id:
        context = _chatbot_empty_context(
            "identity",
            "Identity Leak has not been assessed yet because the user has not completed an Identity Leak scan.",
        )
        context.update(
            {
                "available": True,
                "dynamic_context_available": False,
                "static_context_available": True,
                "static_module_knowledge": static_context,
                "recommendations": [
                    "Run an Identity Leak Monitor scan for an email, username, or domain.",
                    "Review confirmed findings before changing account credentials.",
                    "Enable MFA and avoid password reuse on important accounts.",
                ],
            }
        )
        context["identity_context"] = _identity_build_unified_context(_empty_identity_chatbot_context())
        context["identity_safe_summary"] = _identity_safe_summary_from_context(context)
        return context
    try:
        context = _identity_chatbot_context(int(user_id), None, True)
        scan = context.get("scan") or {}
        if not scan:
            empty_context = _chatbot_empty_context(
                "identity",
                "Identity Leak has not been assessed yet because the user has not completed an Identity Leak scan.",
            )
            empty_context.update(
                {
                    "available": True,
                    "dynamic_context_available": False,
                    "static_context_available": True,
                    "static_module_knowledge": static_context,
                    "recommendations": [
                        "Run an Identity Leak Monitor scan for an email, username, or domain.",
                        "Add monitored assets so future exposure can be reviewed.",
                        "Use MFA and unique passwords before exposure is confirmed.",
                    ],
                }
            )
            empty_context["total_scans"] = _safe_int(context.get("total_scans"), 0)
            empty_context["identity_context"] = _identity_build_unified_context(context)
            empty_context["identity_safe_summary"] = _identity_safe_summary_from_context(empty_context)
            return empty_context
        risk_level = safe_activity_str(scan.get("risk_level"), "Unknown")
        risk_score = _safe_int(scan.get("risk_score"), 0)
        categories = context.get("category_counts") or {}
        findings = context.get("findings") or []
        alerts = context.get("alerts") or []
        source_coverage = context.get("source_coverage") or {}
        target_type = "unknown"
        masked_target = "Unavailable"
        for key in ("email", "username", "domain"):
            value = safe_activity_str(scan.get(key))
            if value:
                target_type = key
                masked_target = (
                    mask_email(value)
                    if key == "email"
                    else value[:2] + "***" + value[-2:]
                    if key == "username" and len(value) > 4
                    else value[:80]
                    if key == "domain"
                    else mask_secret(value)
                )
                break
        severity_counts = Counter()
        safe_findings = []
        confirmed_findings = 0
        for finding in findings:
            if not isinstance(finding, dict):
                continue
            category = safe_activity_str(finding.get("category"))
            severity = safe_activity_str(finding.get("severity"), "unknown").lower()
            if severity:
                severity_counts[severity] += 1
            if category in {"confirmed_breach", "confirmed_exposure"}:
                confirmed_findings += 1
            if len(safe_findings) < 5:
                safe_findings.append(
                    {
                        "source": _chatbot_sanitize_text(finding.get("source")),
                        "category": category,
                        "severity": severity or "unknown",
                        "title": _chatbot_sanitize_text(finding.get("title"))[:160],
                    }
                )
        source_status = []
        if isinstance(source_coverage, dict):
            for name, value in source_coverage.items():
                status = value.get("status") if isinstance(value, dict) else value
                source_status.append(
                    {
                        "source": _chatbot_sanitize_text(name),
                        "status": safe_activity_str(status, "unavailable"),
                    }
                )
        evidence = [
            f"Latest scan ID: {scan.get('id')}",
            f"Scan status: {safe_activity_str(scan.get('status'), 'unknown')}",
            f"Scan time: {safe_activity_str(scan.get('completed_at') or scan.get('created_at'), 'Unavailable')}",
            f"Target type: {target_type}",
            f"Masked target: {masked_target}",
            f"Risk score: {risk_score}/100",
            f"Risk level: {risk_level}",
            f"Total findings: {_safe_int(scan.get('total_findings'), 0)}",
            f"Confirmed findings: {confirmed_findings}",
            f"Sources checked: {_safe_int(scan.get('sources_checked'), 0)}",
            "Finding categories: "
            + ", ".join(f"{safe_activity_str(name)}={_safe_int(count, 0)}" for name, count in categories.items()),
            "Severity counts: "
            + ", ".join(f"{safe_activity_str(name)}={_safe_int(count, 0)}" for name, count in severity_counts.items()),
            f"Alert count: {len(alerts)}",
            f"Monitored assets: {_safe_int(context.get('monitored_assets_count'), 0)}",
            f"Risky assets: {_safe_int(context.get('risky_assets_count'), 0)}",
        ]
        evidence.extend(
            " - ".join(str(part) for part in [item.get("source"), item.get("category"), item.get("severity"), item.get("title")] if part)
            for item in safe_findings
        )
        recommendations = [
            "Review confirmed findings and verify the affected account or identifier.",
            "Change affected passwords and check password reuse.",
            "Enable MFA on important accounts.",
            "Monitor suspicious login attempts.",
            "Export/report findings for documentation.",
        ] if _identity_risk_rank(risk_level) >= _identity_risk_rank("High") else [
            "Review exposure findings and remove unnecessary public data where possible.",
            "Use unique passwords and MFA on important accounts.",
            "Re-scan monitored assets after remediation.",
        ]
        payload = {
            "module": "identity",
            "available": True,
            "dynamic_context_available": True,
            "static_context_available": True,
            "summary": (
                f"Latest identity scan risk is {risk_level} with "
                f"{_safe_int(scan.get('total_findings'), 0)} finding(s)."
            ),
            "risk_level": risk_level,
            "dynamic_identity": {
                "latest_scan_id": scan.get("id"),
                "scan_status": safe_activity_str(scan.get("status"), "unknown"),
                "scan_datetime": safe_activity_str(scan.get("completed_at") or scan.get("created_at")),
                "target_type": target_type,
                "masked_target": masked_target,
                "total_findings": _safe_int(scan.get("total_findings"), 0),
                "confirmed_findings": confirmed_findings,
                "risk_level": risk_level,
                "risk_score": risk_score,
                "sources_checked": _safe_int(scan.get("sources_checked"), 0),
                "source_status": source_status,
                "severity_counts": dict(severity_counts),
                "alert_count": len(alerts),
                "safe_findings": safe_findings,
                "category_counts": categories,
            },
            "total_scans": _safe_int(context.get("total_scans"), 0),
            "static_module_knowledge": static_context,
            "evidence": evidence,
            "recommendations": recommendations,
        }
        payload["identity_context"] = _identity_build_unified_context(context)
        payload["identity_safe_summary"] = _identity_safe_summary_from_context(payload)
        return payload
    except Exception:
        logging.exception("Safe Identity chatbot context failed | user_id=%s", user_id)
        context = _chatbot_empty_context(
            "identity",
            "Identity Leak has not been assessed yet because the user has not completed an Identity Leak scan.",
        )
        context.update(
            {
                "available": True,
                "dynamic_context_available": False,
                "static_context_available": True,
                "static_module_knowledge": static_context,
                "recommendations": ["Run an Identity Leak Monitor scan and review confirmed findings first."],
            }
        )
        context["identity_context"] = _identity_build_unified_context(_empty_identity_chatbot_context())
        context["identity_safe_summary"] = _identity_safe_summary_from_context(context)
        return context


def _identity_source_status_maps(source_status: list[dict[str, object]] | object) -> tuple[list[str], dict[str, str]]:
    sources: list[str] = []
    statuses: dict[str, str] = {}
    if not isinstance(source_status, list):
        return sources, statuses
    for item in source_status:
        if not isinstance(item, dict):
            continue
        source = _chatbot_sanitize_text(item.get("source"))
        status = safe_activity_str(item.get("status"), "unavailable")
        if source:
            sources.append(source)
            statuses[source] = status
    return sources, statuses


def _identity_safe_summary_from_context(identity_context: dict[str, object] | None) -> dict[str, object]:
    context = identity_context if isinstance(identity_context, dict) else {}
    unified = context.get("identity_context") if isinstance(context.get("identity_context"), dict) else {}
    if unified:
        summary = unified.get("summary") if isinstance(unified.get("summary"), dict) else {}
        return {
            "module": "identity",
            "has_data": bool(unified.get("has_data")),
            "status": "assessed" if unified.get("has_data") else "not_scanned_yet",
            "not_assessed_reason": None if unified.get("has_data") else "The user has not completed an Identity Leak scan.",
            "latest_scan_id": unified.get("latest_scan_id"),
            "latest_scan_status": safe_activity_str(unified.get("latest_scan_status"), "not_scanned"),
            "latest_scan_at": unified.get("latest_scan_at"),
            "masked_target": unified.get("masked_target"),
            "target_type": unified.get("target_type"),
            "total_scans": _safe_int(summary.get("total_scans"), 0),
            "total_findings": _safe_int(summary.get("total_findings"), 0),
            "confirmed_findings": _safe_int(summary.get("confirmed_findings"), 0),
            "alert_count": _safe_int(summary.get("alert_count"), 0),
            "risk_level": safe_activity_str(summary.get("risk_level"), "unknown"),
            "risk_score": summary.get("risk_score"),
            "protection_rate": summary.get("protection_rate"),
            "sources_checked": unified.get("sources_checked") if isinstance(unified.get("sources_checked"), list) else [],
            "source_statuses": unified.get("source_statuses") if isinstance(unified.get("source_statuses"), dict) else {},
            "severity_counts": unified.get("severity_counts") if isinstance(unified.get("severity_counts"), dict) else {},
            "category_counts": unified.get("category_counts") if isinstance(unified.get("category_counts"), dict) else {},
            "risky_assets_count": len(unified.get("risky_assets_summary") or []),
            "security_score_weight": SECURITY_SCORE_WEIGHT,
            "score_component_note": "Identity Leak contributes 25% to Security Score when assessed. PCAP Analyzer is separate and not included.",
            "scope_limit": "Current Identity Leak scan uses public OSINT-like sources unless dark web integration is explicitly implemented.",
            "credential_leak_caution": "A finding does not automatically prove password exposure unless credential leakage or confirmed breach is explicitly confirmed in the safe context.",
            "recommendations": [
                _chatbot_sanitize_text(item)
                for item in (unified.get("recommendations") or [])[:6]
                if _chatbot_sanitize_text(item)
            ],
            "context_safe": True,
        }
    dynamic = context.get("dynamic_identity") if isinstance(context.get("dynamic_identity"), dict) else {}
    source_names, source_statuses = _identity_source_status_maps(dynamic.get("source_status"))
    has_data = bool(context.get("dynamic_context_available") and dynamic.get("latest_scan_id"))
    return {
        "module": "identity",
        "has_data": has_data,
        "status": "assessed" if has_data else "not_scanned_yet",
        "not_assessed_reason": None if has_data else "The user has not completed an Identity Leak scan.",
        "latest_scan_id": dynamic.get("latest_scan_id") if has_data else None,
        "latest_scan_status": safe_activity_str(dynamic.get("scan_status"), "not_scanned") if has_data else "not_scanned",
        "latest_scan_at": safe_activity_str(dynamic.get("scan_datetime")) if has_data else None,
        "masked_target": dynamic.get("masked_target") if has_data else None,
        "total_scans": _safe_int(context.get("total_scans"), 0),
        "total_findings": _safe_int(dynamic.get("total_findings"), 0) if has_data else 0,
        "confirmed_findings": _safe_int(dynamic.get("confirmed_findings"), 0) if has_data else 0,
        "alert_count": _safe_int(dynamic.get("alert_count"), 0) if has_data else 0,
        "risk_level": safe_activity_str(dynamic.get("risk_level"), "unknown") if has_data else "unknown",
        "risk_score": dynamic.get("risk_score") if has_data else None,
        "sources_checked": source_names,
        "source_statuses": source_statuses,
        "severity_counts": dynamic.get("severity_counts") if isinstance(dynamic.get("severity_counts"), dict) else {},
        "category_counts": dynamic.get("category_counts") if isinstance(dynamic.get("category_counts"), dict) else {},
        "security_score_weight": SECURITY_SCORE_WEIGHT,
        "score_component_note": "Identity Leak contributes 25% to Security Score when assessed. PCAP Analyzer is separate and not included.",
        "scope_limit": "Current Identity Leak scan uses public OSINT-like sources unless dark web integration is explicitly implemented.",
        "credential_leak_caution": "A finding does not automatically prove password exposure unless credential leakage or confirmed breach is explicitly confirmed in the safe context.",
        "recommendations": [
            _chatbot_sanitize_text(item)
            for item in (context.get("recommendations") or [])[:6]
            if _chatbot_sanitize_text(item)
        ],
        "context_safe": True,
    }


def _identity_safe_debug_context(user_id: int | None) -> dict[str, object]:
    context = _safe_identity_llm_context(user_id)
    summary = _identity_safe_summary_from_context(context)
    return {
        "module": "identity",
        **summary,
    }


def _safe_security_score_llm_context(user_id: int | None, module: str = "security_score") -> dict[str, object]:
    static_context = SECURITY_SCORE_STATIC_MODULE_KNOWLEDGE
    allowed_score_modules = {"password", "vault", "phishing", "identity"}
    component_labels = {
        "password": "Password Checker",
        "vault": "File Vault",
        "phishing": "Phishing Scanner",
        "identity": "Identity Leak",
    }
    if not user_id:
        context = _chatbot_empty_context(module, "No dynamic Security Score data is available yet.")
        context.update(
            {
                "available": True,
                "dynamic_context_available": False,
                "static_context_available": True,
                "static_module_knowledge": static_context,
                "recommendations": [
                    "Run the connected modules so Sentinel AI can calculate component health.",
                    "Focus on weak passwords, encrypted file storage, phishing warnings, and identity exposure.",
                ],
            }
        )
        return context
    try:
        payload = _build_security_score_payload(int(user_id))
        modules = payload.get("components") or payload.get("modules") or {}
        component_scores = []
        overall = payload.get("score")
        status = safe_activity_str(payload.get("status"), "Unknown")
        
        if overall is None:
            evidence = [
                "Status: Not assessed yet",
                "Message: Complete your first checks to calculate your Security Score."
            ]
            summary_text = "Security Score is not assessed yet because the user has not completed enough module activity."
        else:
            evidence = [
                f"Overall score: {_safe_int(overall, 0)}/100",
                f"Overall status: {status}",
            ]
            summary_text = f"Overall security score is {_safe_int(overall, 0)}/100 ({status})."

        recommendations = []
        for name, item in modules.items():
            if not isinstance(item, dict):
                continue
            module_key = safe_activity_str(name)
            if module_key not in allowed_score_modules:
                continue
            score = item.get("score")
            status = safe_activity_str(item.get("status"), "unknown")
            available = bool(item.get("available"))
            component = {
                "component": component_labels.get(module_key, module_key.title()),
                "module_key": module_key,
                "score": score,
                "status": status,
                "weight": _safe_int(item.get("weight"), SECURITY_SCORE_WEIGHT),
                "weighted_score": _safe_float(item.get("weighted_score"), 0.0) if available else None,
                "summary": _chatbot_sanitize_text(item.get("summary")),
                "recommendation": _chatbot_sanitize_text(item.get("recommendation")),
                "available": available,
            }
            component_scores.append(component)
            if available:
                evidence.append(f"{component['component']}: score {score}/100, status {status}, weight {component['weight']}%")
            else:
                evidence.append(f"{component['component']}: {status.replace('_', ' ')}")
                
            recommendation = _chatbot_sanitize_text(item.get("recommendation"))
            if recommendation:
                recommendations.append(f"{component['component']}: {recommendation}")
        missing_components = [
            component_labels[key]
            for key in sorted(allowed_score_modules - {safe_activity_str(item.get("module_key")) for item in component_scores})
        ]
        available_scores = [item for item in component_scores if item.get("available")]
        strongest = max(available_scores, key=lambda item: _safe_int(item.get("score"), 0), default=None)
        weakest = min(available_scores, key=lambda item: _safe_int(item.get("score"), 0), default=None)
        if weakest:
            recommendations.insert(0, f"Focus on weakest component first: {weakest.get('component')}.")
        recommendations.extend(
            [
                "Improve weak or reused passwords.",
                "Encrypt sensitive files in the File Vault.",
                "Review phishing warnings before interacting with links.",
                "Resolve identity leak findings and re-scan.",
            ]
        )
        return {
            "module": module,
            "available": bool(available_scores),
            "dynamic_context_available": True,
            "static_context_available": True,
            "summary": summary_text,
            "risk_level": safe_activity_str(payload.get("status"), "Unknown"),
            "dynamic_security_score": {
                "overall_score_percentage": overall,
                "score_status": safe_activity_str(payload.get("status"), "Unknown"),
                "component_scores": component_scores,
                "component_weights": {item["component"]: item["weight"] for item in component_scores},
                "missing_or_incomplete_components": missing_components
                + [item["component"] for item in component_scores if not item.get("available")],
                "last_updated": safe_activity_str(payload.get("generated_at")),
                "strongest_component": strongest,
                "weakest_component": weakest,
                "excluded_modules": [
                    "PCAP Analyzer is a separate network-risk module and is not part of this score."
                ],
            },
            "static_module_knowledge": static_context,
            "evidence": evidence,
            "recommendations": recommendations[:8],
        }
    except Exception:
        logging.exception("Safe Security Score chatbot context failed | user_id=%s", user_id)
        context = _chatbot_empty_context(module, "No dynamic Security Score data is available yet.")
        context.update(
            {
                "available": False,
                "dynamic_context_available": False,
                "static_context_available": True,
                "static_module_knowledge": static_context,
                "recommendations": ["Use Password Checker, File Vault, Phishing Scanner, and Identity Leak to improve the score."],
            }
        )
        return context


def _safe_reports_llm_context(user_id: int | None, user=None) -> dict[str, object]:
    static_context = REPORTS_STATIC_MODULE_KNOWLEDGE
    supported_export_formats = filter_user_facing_report_exports(
        {
            "pcap_user_report": ["json"],
            "pcap_evidence": ["zip"],
            "monthly_security_report": ["pdf"] if callable(render_monthly_security_report_pdf) else [],
        }
    )
    context = {
        **_chatbot_empty_context("reports", "No dynamic Reports Center data is available yet."),
        "available": True,
        "dynamic_context_available": False,
        "static_context_available": True,
        "static_module_knowledge": static_context,
        "dynamic_reports": {
            "available_report_categories": [
                "Security Score Summary",
                "Identity Leak Summary",
                "Phishing Summary if implemented",
                "Password Checker Summary if implemented",
                "File Vault Summary if implemented",
                "PCAP Analysis Summary as a separate network-traffic report if implemented or connected",
            ],
            "supported_export_formats": supported_export_formats,
            "pdf_availability_note": "Monthly security report PDF rendering is available when the report renderer is enabled.",
            "export_visibility": "Available export options depend on the report type and your permissions.",
        },
        "recommendations": [
            "Open or generate the latest report.",
            "Export important findings for documentation.",
            "Review recent reports before security review decisions.",
            "Review separate module reports before taking action.",
            "Use PCAP reports separately when reviewing network traffic evidence.",
        ],
    }
    if not user_id:
        return context
    try:
        score_context = _safe_security_score_llm_context(user_id, "security_score")
        latest_pcap = _safe_pcap_llm_context(user, user_id) if user is not None else _chatbot_empty_context("pcap")
        latest_identity = _safe_identity_llm_context(user_id)
        recent_monthly_reports = []
        try:
            reports = (
                MonthlySecurityReport.query
                .filter(MonthlySecurityReport.user_id == int(user_id))
                .order_by(MonthlySecurityReport.created_at.desc(), MonthlySecurityReport.id.desc())
                .limit(5)
                .all()
            )
            for report in reports:
                recent_monthly_reports.append(
                    {
                        "id": getattr(report, "id", None),
                        "report_month": safe_activity_str(getattr(report, "report_month", "")),
                        "report_year": getattr(report, "report_year", None),
                        "status": safe_activity_str(getattr(report, "status", "unknown")),
                        "created_at": safe_activity_str(getattr(report, "created_at", "")),
                        "updated_at": safe_activity_str(getattr(report, "updated_at", "")),
                        "pdf_available": bool(safe_activity_str(getattr(report, "pdf_path", ""))),
                        "details_available": bool(safe_activity_str(getattr(report, "report_payload_json", ""))),
                    }
                )
        except Exception:
            logging.exception("Monthly reports context read failed | user_id=%s", user_id)

        context["dynamic_context_available"] = any(
            [
                bool(recent_monthly_reports),
                bool(latest_pcap.get("dynamic_context_available")),
                bool(latest_identity.get("dynamic_context_available")),
                bool(score_context.get("dynamic_context_available")),
            ]
        )
        context["summary"] = (
            "The Reports & Export Center is used to review, summarize, and export security activity "
            "from connected modules."
        )
        context["dynamic_reports"].update(
            {
                "supported_export_formats": filter_user_facing_report_exports(
                    context["dynamic_reports"].get("supported_export_formats")
                ),
                "connected_modules": {
                    "security_score": bool(score_context.get("dynamic_context_available")),
                    "identity_leak": bool(latest_identity.get("dynamic_context_available")),
                    "pcap_analysis": bool(latest_pcap.get("dynamic_context_available")),
                    "phishing": "available where implemented",
                    "password_checker": "available where implemented",
                    "file_vault": "available where implemented",
                },
                "module_report_summaries": {
                    "security_score_summary": {
                        "available": bool(score_context.get("dynamic_context_available")),
                        "summary": _chatbot_sanitize_text(score_context.get("summary")),
                    },
                    "identity_leak_summary": {
                        "available": bool(latest_identity.get("dynamic_context_available")),
                        "summary": _chatbot_sanitize_text(latest_identity.get("summary")),
                        "latest_scan_id": ((latest_identity.get("dynamic_identity") or {}).get("latest_scan_id") if isinstance(latest_identity.get("dynamic_identity"), dict) else None),
                        "evidence_available": bool((latest_identity.get("dynamic_identity") or {}).get("safe_findings")) if isinstance(latest_identity.get("dynamic_identity"), dict) else False,
                        "safe_summary": _identity_safe_summary_from_context(latest_identity),
                        "not_available_reason": (
                            None
                            if latest_identity.get("dynamic_context_available")
                            else "Identity Leak report is not available yet because the user has not completed an Identity Leak scan."
                        ),
                    },
                    "pcap_analysis_summary": {
                        "available": bool(latest_pcap.get("dynamic_context_available")),
                        "summary": _chatbot_sanitize_text(latest_pcap.get("summary")),
                        "analysis_id": ((latest_pcap.get("dynamic_analysis") or {}).get("analysis_id") if isinstance(latest_pcap.get("dynamic_analysis"), dict) else None),
                        "evidence_available": bool((latest_pcap.get("dynamic_analysis") or {}).get("report_sections_available")) if isinstance(latest_pcap.get("dynamic_analysis"), dict) else False,
                        "separate_report_category": True,
                    },
                },
                "recent_exports_or_reports": recent_monthly_reports,
                "recent_reports_count": len(recent_monthly_reports),
                "latest_report_status": recent_monthly_reports[0].get("status") if recent_monthly_reports else "unavailable",
                "latest_report_datetime": recent_monthly_reports[0].get("updated_at") or recent_monthly_reports[0].get("created_at") if recent_monthly_reports else None,
                "evidence_details_available": any(
                    [
                        bool(recent_monthly_reports and recent_monthly_reports[0].get("details_available")),
                        bool((latest_pcap.get("dynamic_analysis") or {}).get("report_sections_available")) if isinstance(latest_pcap.get("dynamic_analysis"), dict) else False,
                        bool((latest_identity.get("dynamic_identity") or {}).get("safe_findings")) if isinstance(latest_identity.get("dynamic_identity"), dict) else False,
                    ]
                ),
            }
        )
        context["evidence"] = [
            f"Latest generated report: {'available' if recent_monthly_reports else 'not available'}",
            "Export formats: PCAP user report JSON, PCAP evidence ZIP, and monthly PDF when available to users. Other options depend on report type and permissions.",
            f"Recent exports: {'available' if recent_monthly_reports else 'no recent exports'}",
            "Connected modules: Security Score, Identity Leak, and PCAP Analysis where data is available; Phishing, Password Checker, and File Vault summaries where implemented.",
            "PCAP Analysis Summary is treated as a separate network-traffic report category, not part of Security Score.",
        ]
        return context
    except Exception:
        logging.exception("Safe Reports chatbot context failed | user_id=%s", user_id)
        return context


def get_chatbot_security_context(user_id: int | None, module: str, user=None) -> dict[str, object]:
    module = _normalize_chatbot_llm_module(module)
    if module == "pcap":
        return _safe_pcap_llm_context(user, user_id)
    if module == "identity":
        return _safe_identity_llm_context(user_id)
    if module == "security_score" or module == "general":
        context = _safe_security_score_llm_context(user_id, module)
        identity_context = _safe_identity_llm_context(user_id)
        identity_summary = _identity_safe_summary_from_context(identity_context)
        context["identity_leak_summary"] = identity_summary
        context["connected_safe_contexts"] = {
            **(context.get("connected_safe_contexts") if isinstance(context.get("connected_safe_contexts"), dict) else {}),
            "identity": identity_summary,
        }
        return context
    if module == "reports":
        return _safe_reports_llm_context(user_id, user=user)
    if not user_id:
        return _chatbot_empty_context(module, f"No authenticated {module.replace('_', ' ')} data is available yet.")

    try:
        if module == "password":
            return _chatbot_context_from_security_payload("password", _score_password_module(int(user_id)))
        if module == "phishing":
            return _chatbot_context_from_security_payload("phishing", _score_phishing_module(int(user_id)))
        if module == "file_vault":
            context = _chatbot_context_from_security_payload("file_vault", _score_vault_module(int(user_id)))
            try:
                vault_result = _analyze_vault_behavior_for_user(int(user_id))
                evidence = list(context.get("evidence") or [])
                evidence.extend(
                    [
                        f"Vault AI risk score: {_safe_int(vault_result.get('risk_score'), 0)}/100",
                        f"Active risks: {len(vault_result.get('risks') or [])}",
                        f"Wrong password attempts: {_safe_int((vault_result.get('activity_counts') or {}).get('wrong_password_attempts'), 0)}",
                    ]
                )
                context["evidence"] = evidence
                if vault_result.get("recommendation"):
                    context["recommendations"] = [_chatbot_sanitize_text(vault_result.get("recommendation"))]
            except Exception:
                logging.exception("Optional Vault AI context failed | user_id=%s", user_id)
            return context
    except Exception:
        logging.exception("Safe chatbot context failed | user_id=%s | module=%s", user_id, module)
    return _chatbot_empty_context(module)


def _chatbot_detect_intent(message: str, module: str) -> str:
    text = _chatbot_normalized_message(message)
    module = _normalize_chatbot_llm_module(module)

    if module == "password":
        password_exact_intents = [
            (("how can i make my password stronger", "make my password stronger", "stronger password"), "password_strength_advice"),
            (("was my password breached", "is my password breached", "breached password"), "password_breach_guidance"),
            (("what does password risk mean", "password risk mean", "password risk"), "password_risk_explanation"),
            (("explain my latest password check", "latest password check", "password check"), "password_latest_check"),
            (("what should i do after a breached password", "after a breached password"), "password_breach_next_steps"),
            (("how is password strength calculated", "password strength calculated", "strength calculated"), "password_score_explanation"),
            (("what is password reuse risk", "password reuse risk", "reuse risk"), "password_reuse_risk"),
            (("how can i improve my password score", "improve my password score", "password score"), "password_score_explanation"),
            (("is my password history safe", "password history safe", "password history"), "password_history_explanation"),
            (("why should i use mfa", "why should i use 2fa", "use mfa", "use 2fa"), "password_mfa_advice"),
        ]
        for phrases, intent_name in password_exact_intents:
            if any(phrase in text for phrase in phrases):
                return intent_name
        if "breach" in text or "compromised" in text or "leaked" in text or "exposed" in text or "pwned" in text:
            return "password_breach_guidance"
        if "reuse" in text or "reused" in text:
            return "password_reuse_risk"
        if "history" in text or "previous checks" in text:
            return "password_history_explanation"
        if "score" in text or "strength" in text or "entropy" in text or "calculate" in text:
            return "password_score_explanation"
        if "mfa" in text or "2fa" in text or "multi-factor" in text or "two-factor" in text:
            return "password_mfa_advice"
        if "store" in text or "stored" in text or "privacy" in text or "raw password" in text:
            return "password_privacy"
        if "risk" in text or "weak" in text:
            return "password_risk_explanation"
        return "password_strength_advice"

    if module == "pcap":
        pcap_exact_intents = [
            (("summarize my latest pcap analysis", "لخص آخر تحليل pcap", "لخص اخر تحليل pcap"), "pcap_summary"),
            (("what threats were detected", "إيه التهديدات", "ايه التهديدات", "التهديدات اللي ظهرت"), "pcap_threats"),
            (("why is this pcap risky", "ليه ملف pcap ده خطر", "ليه pcap ده خطر"), "pcap_risky"),
            (("explain the severity", "اشرحلي severity", "اشرح severity"), "pcap_severity"),
            (("what should i do next", "أعمل إيه بعد كده", "اعمل ايه بعد كده"), "pcap_next_steps"),
            (("which ips should i review", "what ips are suspicious", "top suspicious hosts", "أراجع أنهي ips", "اراجع انهي ips"), "pcap_ip_review"),
            (("what is a suspicious flow", "يعني إيه suspicious flow", "يعني ايه suspicious flow"), "pcap_suspicious_flow"),
            (("what does confidence mean", "يعني إيه confidence", "يعني ايه confidence"), "pcap_confidence"),
            (("ml vs heuristics", "الفرق بين ml و heuristics"), "pcap_ml_vs_heuristics"),
            (("was the latest pcap clean", "هل آخر pcap clean", "هل اخر pcap clean"), "pcap_clean"),
            (("explain the pcap analyzer project module", "اشرحلي موديول pcap analyzer"), "pcap_module_explanation"),
            (("how does the pcap pipeline work", "البايبلاين بيشتغل إزاي", "البايبلاين بيشتغل ازاي"), "pcap_pipeline"),
            (("what does the pcap report contain", "التقرير بيحتوي على إيه", "التقرير بيحتوي على ايه"), "pcap_report_contents"),
            (("how pcap connects to logs and reports", "pcap مرتبط بالتقارير واللوجز"), "pcap_logs_reports_connection"),
        ]
        for phrases, intent_name in pcap_exact_intents:
            if any(phrase in text for phrase in phrases):
                return intent_name
        if any(phrase in text for phrase in ("score", "scoring", "calculated", "calculation", "risk score", "final scoring")):
            return "scoring_logic"
        if "pipeline" in text or "workflow" in text or "how does pcap" in text or "how pcap" in text:
            return "pipeline"
        if "ml vs" in text or "heuristic" in text or "machine learning" in text:
            return "ml_vs_heuristics"
        if "confidence" in text:
            return "confidence_meaning"
        if "what should i do" in text or "next" in text or "recommend" in text:
            return "next_steps"
        if "ip" in text or "address" in text or "review" in text and "which" in text:
            return "ips_to_review"
        if "report" in text or "contain" in text or "contents" in text:
            return "report_contents"
        if "why" in text or "risky" in text or "risk" in text or "dangerous" in text:
            return "risky_reason"
        return "latest_summary"

    if module == "security_score":
        if "improve" in text or "increase" in text or "raise" in text or "fix" in text or "recommend" in text:
            return "improve_score"
        if "weakest" in text or "lowest" in text or "worst" in text:
            return "weakest_component"
        if "strongest" in text or "best" in text or "highest" in text:
            return "strongest_component"
        if "calculate" in text or "calculated" in text or "method" in text or "weight" in text or "25" in text:
            return "calculation_method"
        if "breakdown" in text or "component" in text:
            return "component_breakdown"
        if "why" in text or "low" in text or "high" in text or "risk" in text or "meaning" in text:
            return "risk_interpretation"
        return "explain_score"

    if module == "reports":
        if "export" in text or "download" in text or "csv" in text or "pdf" in text:
            return "export_options"
        if "latest" in text or "recent" in text or "summarize" in text or "summary" in text:
            return "latest_reports"
        if "admin" in text or "audit" in text or "decision" in text or "help" in text or "document" in text:
            return "report_usage"
        if "evidence" in text or "detail" in text:
            return "report_evidence"
        if "connected" in text or "module" in text:
            return "connected_modules"
        if "contain" in text or "include" in text or "reports center" in text:
            return "report_center_explanation"
        if "available reports" in text or "report categories" in text or ("what" in text and ("reports" in text or "available" in text)):
            return "available_reports"
        return "report_center_explanation"

    return "general"


def _chatbot_response_guidance(module: str, intent: str) -> str:
    if module == "pcap":
        return {
            "scoring_logic": (
                "Explain only the implemented PCAP scoring logic from pcap_scoring_logic. Mention actual functions "
                "and fields. Do not invent thresholds or formulas. State that PCAP score is separate from the user Security Score."
            ),
            "pcap_summary": "Summarize pcap_context latest report status, risk, flows, alerts, severity counts, clean status, and top threats only.",
            "pcap_threats": "Use pcap_context.top_threats and top_alerts. If none are confirmed, say no confirmed/promoted threats were detected.",
            "pcap_risky": "Explain risk using critical/high alerts, suspicious/malicious flows, repeated detections, risky IPs, and high confidence alerts from pcap_context only.",
            "pcap_severity": "Explain severity meanings and map the actual pcap_context.severity_counts.",
            "pcap_next_steps": "Give practical investigation steps using top threats and ip_review_summary if available.",
            "pcap_ip_review": "Use pcap_context.ip_review_summary.top_ips. If top_ips is empty or unavailable, explain that IP-level detail is not available instead of inventing IPs.",
            "pcap_suspicious_flow": "Define suspicious flow simply using ML, heuristics, ports, rates, failed connections, scan-like behavior, and evidence.",
            "pcap_confidence": "Explain confidence as strength of detection evidence, not proof by itself.",
            "pcap_ml_vs_heuristics": "Compare ML and heuristic detection and explain hybrid final decisions.",
            "pcap_clean": "Use pcap_context.summary.is_clean and alert/suspicious counts. Do not overclaim.",
            "pcap_module_explanation": "Explain the PCAP Analyzer project module and what it produces.",
            "pcap_pipeline": "Use pcap_context.pipeline_summary.steps.",
            "pcap_report_contents": "List report sections present in context: summary, alerts, severity, detections, IP summary, timeline, clusters, evidence if available.",
            "pcap_logs_reports_connection": "Explain PCAP connection to alerts, activity logs, Reports Center, exports, and chatbot. Clarify PCAP is not Security Score.",
        }.get(intent, "Answer the PCAP question using pcap_context only. Do not invent alerts, IPs, scores, threats, or raw payloads.")
    if module == "security_score":
        return {
            "explain_score": "Return overall score, status, short meaning, component breakdown, and one PCAP-separate clarification.",
            "improve_score": "Return prioritized recommendations only, focused on weakest or unknown components. Do not repeat the full summary.",
            "weakest_component": "Return the weakest component, why it is weak or unknown, and one action to improve it.",
            "strongest_component": "Return the strongest component and what it indicates.",
            "calculation_method": "Explain the implemented/intended 25% component weighting: Password, File Vault, Phishing, Identity. PCAP is excluded.",
            "component_breakdown": "Return only the four Security Score components and their available scores/statuses.",
            "risk_interpretation": "Explain why the score status is low/medium/high and the focused next steps.",
        }.get(intent, "Answer the selected Security Score intent without including PCAP as a component.")
    if module == "reports":
        return {
            "available_reports": "List report categories only. Include PCAP as a separate network-traffic report category if connected. Do not show Security Score component breakdown.",
            "latest_reports": "Summarize latest report status/date and short summary per connected report area. Keep PCAP separate.",
            "export_options": "Return user-facing implemented export formats only. Do not include restricted exports or restricted labels.",
            "report_center_explanation": "Explain Reports & Export Center, categories, documentation/evidence purpose, and security review support. Do not mention restricted functionality.",
            "report_usage": "Use neutral wording. Focus on documentation, trend review, incident review, available evidence export, and security review decision support.",
            "report_evidence": "Explain evidence/details availability by report area without inventing exports or IDs.",
            "connected_modules": "List connected modules from context and planned/implemented report areas separately.",
        }.get(intent, "Answer as Reports Center, not as Security Score.")
    if module == "password":
        return {
            "password_strength_advice": "Give password-strength guidance using safe context only. Never ask for or repeat raw passwords.",
            "password_breach_guidance": "Explain breached or compromised password response. Do not claim breach status unless safe context explicitly supports it.",
            "password_breach_next_steps": "Give immediate next steps: change the password, replace reused copies, enable MFA/2FA, and review account activity.",
            "password_risk_explanation": "Explain password risk in terms of weak patterns, reuse, entropy, breach exposure, and account impact.",
            "password_score_explanation": "Explain score or strength from available context only. Do not invent score values or scoring formulas.",
            "password_reuse_risk": "Explain why password reuse increases blast radius and recommend unique passwords with a password manager.",
            "password_history_explanation": "Discuss password history using safe metadata only. Never expose raw passwords.",
            "password_privacy": "Explain the privacy rule: raw passwords must not be echoed, logged, or stored in chatbot responses.",
            "password_mfa_advice": "Explain MFA/2FA as an extra control that limits damage if a password is guessed, reused, or exposed.",
            "password_latest_check": "Summarize only safe Password Checker context. If live details are unavailable, say so and point to the dashboard/history.",
        }.get(intent, "Answer as Password Checker using safe context only. Never request, echo, log, or store raw passwords.")
    return "Answer the specific user question using the selected module context."


def _ollama_fallback_reason(exc: Exception) -> str:
    message = safe_activity_str(exc).lower()
    if "timed out" in message or "timeout" in message:
        return "ollama_timeout"
    if "not running" in message or "connection" in message or "refused" in message:
        return "ollama_not_running"
    if "model" in message and ("missing" in message or "not found" in message):
        return "ollama_model_missing"
    if "invalid" in message or "empty response" in message:
        return "invalid_ollama_response"
    return "ollama_error"


CHATBOT_LLM_CACHE_TTL_SECONDS = 10 * 60
CHATBOT_LLM_CACHE_MAX_ENTRIES = 256
_chatbot_llm_cache_lock = threading.Lock()
_chatbot_llm_cache: dict[tuple[object, str, str, str, str, str, str, str], dict[str, object]] = {}


def _chatbot_normalized_message(value: object) -> str:
    return re.sub(r"\s+", " ", safe_activity_str(value).lower()).strip()


def _chatbot_message_cache_hash(message: str) -> str:
    normalized = _chatbot_normalized_message(message)
    return hashlib.sha256(normalized.encode("utf-8")).hexdigest()


def _chatbot_context_analysis_id(module: str, safe_context: dict) -> str:
    if not isinstance(safe_context, dict):
        return ""
    if module == "reports":
        return "reports_user_facing_v2"
    if module != "pcap":
        return ""
    dynamic = safe_context.get("dynamic_analysis")
    if isinstance(dynamic, dict):
        return safe_activity_str(dynamic.get("analysis_id"))
    return ""


def _chatbot_llm_cache_key(
    user_id: int | None,
    module: str,
    message: str,
    safe_context: dict,
    intent: str = "",
    selected_provider: str = "auto",
    provider: str = "ollama",
    model: str = "",
) -> tuple[object, str, str, str, str, str, str, str]:
    return (
        int(user_id) if user_id else "anonymous",
        module,
        safe_activity_str(intent) or "general",
        _chatbot_message_cache_hash(message),
        safe_activity_str(selected_provider, "auto"),
        safe_activity_str(provider, "ollama"),
        safe_activity_str(model),
        _chatbot_context_analysis_id(module, safe_context),
    )


def _chatbot_get_cached_llm_response(cache_key: tuple[object, str, str, str, str, str, str, str]) -> dict[str, object] | None:
    now = time.time()
    with _chatbot_llm_cache_lock:
        cached = _chatbot_llm_cache.get(cache_key)
        if not cached:
            return None
        expires_at = _safe_float(cached.get("expires_at"), 0.0)
        if expires_at <= now:
            _chatbot_llm_cache.pop(cache_key, None)
            return None
        return dict(cached.get("payload") or {})


def _chatbot_store_cached_llm_response(cache_key: tuple[object, str, str, str, str, str, str, str], payload: dict[str, object]) -> None:
    now = time.time()
    with _chatbot_llm_cache_lock:
        expired_keys = [
            key
            for key, value in _chatbot_llm_cache.items()
            if _safe_float(value.get("expires_at"), 0.0) <= now
        ]
        for key in expired_keys:
            _chatbot_llm_cache.pop(key, None)
        if len(_chatbot_llm_cache) >= CHATBOT_LLM_CACHE_MAX_ENTRIES:
            oldest_key = min(
                _chatbot_llm_cache,
                key=lambda key: _safe_float(_chatbot_llm_cache[key].get("created_at"), 0.0),
            )
            _chatbot_llm_cache.pop(oldest_key, None)
        _chatbot_llm_cache[cache_key] = {
            "created_at": now,
            "expires_at": now + CHATBOT_LLM_CACHE_TTL_SECONDS,
            "payload": dict(payload),
        }


def _fallback_pcap_scoring_answer(safe_context: dict) -> str:
    scoring = safe_context.get("pcap_scoring_logic") if isinstance(safe_context, dict) else None
