def is_password_fallback_context(module, message) -> bool:
    normalized_module = safe_activity_str(module).strip().lower().replace("-", "_")
    if normalized_module in {"password", "passwords", "password_checker", "password_security", "password security"}:
        return True

    text = _chatbot_normalized_message(message)
    if not text:
        return False

    keyword_patterns = [
        r"\bpasswords?\b",
        r"\bweak password\b",
        r"\bstrong password\b",
        r"\bbreached\b",
        r"\bcompromised\b",
        r"\breused\b",
        r"\breuse\b",
        r"\bpassword history\b",
        r"\bprevious checks\b",
        r"\bpassword score\b",
        r"\bpassword checker\b",
        r"\bpassphrase\b",
        r"\bmfa\b",
        r"\b2fa\b",
    ]
    return any(re.search(pattern, text) for pattern in keyword_patterns)


def build_password_rule_based_fallback(message, safe_context: dict | None = None) -> str:
    text = _chatbot_normalized_message(message)
    context = safe_context if isinstance(safe_context, dict) else {}
    summary = _chatbot_sanitize_text(context.get("summary"))
    risk_level = safe_activity_str(context.get("risk_level"))
    evidence = [
        _chatbot_sanitize_text(item)
        for item in (context.get("evidence") or [])[:4]
        if _chatbot_sanitize_text(item)
    ]
    recommendations = [
        _chatbot_sanitize_text(item)
        for item in (context.get("recommendations") or [])[:4]
        if _chatbot_sanitize_text(item)
    ]

    def context_lines() -> list[str]:
        lines: list[str] = []
        if summary:
            lines.extend(["", "Available safe context:", f"- {summary}"])
        if risk_level:
            lines.append(f"- Risk level: {risk_level}")
        if evidence:
            lines.extend([f"- {item}" for item in evidence])
        if recommendations:
            lines.extend(["", "Context recommendations:", *[f"- {item}" for item in recommendations]])
        return lines

    pasted_password_patterns = [
        r"\bcheck (this|my) password\b",
        r"\bis (this|my) password\b",
        r"\bpassword\s*[:=]\s*\S+",
        r"\bmy password is\b",
        r"\brate (this|my) password\b",
    ]
    if any(re.search(pattern, text) for pattern in pasted_password_patterns):
        return "\n".join(
            [
                "**Password safety guidance**",
                "",
                "For safety, do not paste real passwords into chat. Use the Password Checker tool instead.",
                "",
                "General guidance:",
                "- Use a long, unique passphrase for each account.",
                "- Avoid names, birthdays, email addresses, usernames, or other personal information.",
                "- Do not reuse passwords across services.",
                "- Store passwords in a reputable password manager.",
                "- Enable MFA/2FA wherever it is available.",
            ]
        )

    if "mfa" in text or "2fa" in text or "multi-factor" in text or "two-factor" in text:
        return "\n".join(
            [
                "**MFA/2FA guidance**",
                "",
                "MFA/2FA adds a second proof of identity so a stolen, guessed, reused, or exposed password is less likely to be enough by itself.",
                "",
                "Recommended action:",
                "- Enable MFA/2FA on email, banking, cloud, admin, and social accounts first.",
                "- Prefer authenticator apps, security keys, or passkeys where available.",
                "- Keep backup codes somewhere protected.",
                "- Still use unique strong passwords; MFA is not a replacement for password hygiene.",
            ]
        )

    if any(term in text for term in ("store", "stored", "save", "saved", "privacy", "raw password", "echo")):
        return "\n".join(
            [
                "**Password privacy**",
                "",
                "Raw passwords should never be stored or echoed back in chat.",
                "This fallback answer does not store, check, or repeat raw passwords.",
                "",
                "For exact project behavior, use the Password Checker tool and review the implementation/documentation. I will not invent storage details that are not guaranteed by the current code path.",
            ]
        )

    if any(term in text for term in ("history", "previous checks")):
        return "\n".join(
            [
                "**Password Checker history**",
                "",
                "Fallback mode cannot access or list your full password history.",
                "Open the Password Checker dashboard/history for exact stored metadata and previous check results.",
                *context_lines(),
                "",
                "General guidance:",
                "- Treat reused or weak passwords as high priority.",
                "- Replace exposed or repeated passwords with unique passphrases.",
                "- Enable MFA/2FA on important accounts.",
            ]
        )

    if any(term in text for term in ("score", "password score", "strength calculated", "entropy", "calculate", "calculated")):
        return "\n".join(
            [
                "**Password strength and score**",
                "",
                "Fallback mode cannot calculate an exact password score or entropy value from chat.",
                "Use the Password Checker tool for the exact score and any available breach-style exposure result.",
                *context_lines(),
                "",
                "In general, stronger passwords are longer, unique, less predictable, and not reused across services.",
            ]
        )

    if any(term in text for term in ("breached", "compromised", "leaked", "exposed", "pwned")):
        return "\n".join(
            [
                "**Breached or compromised password guidance**",
                "",
                "Fallback mode cannot confirm breach status by itself.",
                "Use the Password Checker tool for safe checking.",
                *context_lines(),
                "",
                "If a password is breached or compromised:",
                "- Change it immediately.",
                "- Change it everywhere it was reused.",
                "- Enable MFA/2FA on affected accounts.",
                "- Watch for suspicious login activity.",
                "- Store the replacement in a password manager.",
            ]
        )

    if "reuse" in text or "reused" in text:
        return "\n".join(
            [
                "**Password reuse risk**",
                "",
                "Password reuse is risky because one exposed password can unlock multiple accounts.",
                "If a password was reused, replace it everywhere it was used and make every replacement unique.",
                *context_lines(),
                "",
                "Use a password manager to generate and store unique credentials, then enable MFA/2FA on important accounts.",
            ]
        )

    if "risk" in text or "weak" in text:
        return "\n".join(
            [
                "**Password risk meaning**",
                "",
                "Password risk usually comes from weak patterns, short length, predictable words, personal details, reuse, or breach-style exposure.",
                *context_lines(),
                "",
                "Practical hardening steps:",
                "- Replace weak or reused passwords with long unique passphrases.",
                "- Avoid names, birthdays, usernames, email addresses, and common substitutions.",
                "- Store unique passwords in a password manager.",
                "- Enable MFA/2FA wherever possible.",
            ]
        )

    return "\n".join(
        [
            "**Strong password guidance**",
            "",
            "- Use a long, unique passphrase for every account.",
            "- Avoid personal information such as names, birthdays, usernames, emails, or phone numbers.",
            "- Do not reuse passwords across websites or apps.",
            "- Use a reputable password manager to generate and store unique passwords.",
            "- Enable MFA/2FA wherever possible.",
            "- Use the Password Checker tool for safe checking instead of pasting real passwords into chat.",
            *context_lines(),
        ]
    )


def _rule_based_llm_chatbot_answer(message: str, module: str, user, user_id: int | None, safe_context: dict) -> str:
    module = _normalize_chatbot_llm_module(module)
    intent = safe_activity_str((safe_context or {}).get("detected_intent")) or _chatbot_detect_intent(message, module)
    if module == "security_score":
        return _fallback_security_score_answer(intent, safe_context or {})
    if module == "reports":
        return _fallback_reports_answer(intent, safe_context or {})
    if module == "pcap":
        if intent == "scoring_logic":
            return _fallback_pcap_scoring_answer(safe_context or {})
        try:
            return _pcap_chatbot_answer(message, _pcap_chatbot_context(user, None, True))
        except Exception:
            logging.exception("Rule-based PCAP chatbot fallback failed | user_id=%s", user_id)
            return _pcap_no_analysis_answer()
    if module == "identity":
        try:
            context = _identity_chatbot_context(int(user_id), None, True) if user_id else _empty_identity_chatbot_context()
            return _identity_chatbot_answer(message, context)
        except Exception:
            logging.exception("Rule-based Identity chatbot fallback failed | user_id=%s", user_id)
            return (
                "Identity Leak has not been assessed yet because you have not completed an Identity Leak scan. "
                "Run your first scan to check whether your email, username, or domain appears in public exposure sources."
            )
    if is_password_fallback_context(module, message):
        return build_password_rule_based_fallback(message, safe_context or {})

    summary = safe_activity_str(safe_context.get("summary"), "No data is available for this module yet.")
    risk_level = safe_activity_str(safe_context.get("risk_level"), "Unknown")
    evidence = [safe_activity_str(item) for item in (safe_context.get("evidence") or [])[:5] if safe_activity_str(item)]
    recommendations = [
        _chatbot_sanitize_text(item)
        for item in (safe_context.get("recommendations") or [])[:5]
        if _chatbot_sanitize_text(item)
    ]
    lines = [
        f"**{module.replace('_', ' ').title()} summary**",
        "",
        summary,
        "",
        f"Risk level: **{risk_level}**",
    ]
    if evidence:
        lines.extend(["", "Evidence:", *[f"- {item}" for item in evidence]])
    else:
        lines.extend(["", "No evidence is available for this module yet."])
    if recommendations:
        lines.extend(["", "Recommended next steps:", *[f"- {item}" for item in recommendations]])
    else:
        lines.extend(["", "Recommended next step: run or open this module so Sentinel AI has data to explain."])
    return "\n".join(lines)


def _log_chatbot_llm_activity(
    user_id: int | None,
    module: str,
    provider_used: str,
    fallback_used: bool,
    response_time_ms: int,
    fallback_reason: str | None = None,
) -> None:
    if not user_id:
        return
    try:
        log_user_event(
            user_id=int(user_id),
            module=MODULE_AI,
            action_type="chatbot_llm_question",
            title="Chatbot question answered",
            description="A chatbot question was answered by the configured provider or safe fallback.",
            status=STATUS_INFO,
            severity=SEVERITY_LOW,
            target_type="chatbot",
            target_label=module.replace("_", " ").title(),
            metadata_json={
                "module": module,
                "provider_used": provider_used,
                "fallback_used": bool(fallback_used),
                "fallback_reason": fallback_reason,
                "response_time_ms": int(response_time_ms),
            },
            commit=True,
        )
    except Exception:
        db.session.rollback()
        logging.exception("Failed to record chatbot LLM activity | user_id=%s | module=%s", user_id, module)


def _chatbot_debug_context_development_mode() -> bool:
    return bool(
        FLASK_DEBUG_MODE
        or bool(getattr(app, "debug", False))
        or safe_activity_str(os.getenv("FLASK_ENV")).lower() == "development"
        or safe_activity_str(os.getenv("APP_ENV")).lower() == "development"
    )


@app.route("/api/chatbot/debug-context", methods=["GET"])
def chatbot_debug_context():
    if not _chatbot_debug_context_development_mode():
        return jsonify({"error": "Not found"}), 404

    user, auth_error = require_full_auth_user()
    if auth_error:
        return auth_error

    module = _normalize_chatbot_llm_module(request.args.get("module"))
    try:
        if module == "identity":
            context = _identity_safe_debug_context(int(user.id))
        elif module == "pcap":
            context = _pcap_debug_context_from_safe_context(
                get_chatbot_security_context(int(user.id), module, user=user)
            )
        else:
            context = get_chatbot_security_context(int(user.id), module, user=user)
    except Exception:
        logging.exception("Chatbot debug context failed | user_id=%s | module=%s", getattr(user, "id", None), module)
        context = _chatbot_empty_context(module, "No data is available for this module yet.")

    context["debug_only"] = True
    context["context_safe"] = True
    return jsonify(context), 200


