@app.route("/api/chatbot/llm", methods=["POST"])
def chatbot_llm():
    started_at = time.perf_counter()
    data = request.get_json(silent=True) or {}
    message = safe_activity_str(data.get("message"))
    module = _normalize_chatbot_llm_module(data.get("module"))
    selected_provider = normalize_chatbot_provider_preference(data.get("provider_preference"))
    if not message:
        return jsonify({"error": "Message is required"}), 400

    user = None
    try:
        user = get_current_user()
    except Exception:
        logging.info("LLM chatbot request continued without valid auth token")
    user_id = int(user.id) if user is not None and getattr(user, "id", None) else None

    safe_context = get_chatbot_security_context(user_id, module, user=user)
    detected_intent = _chatbot_detect_intent(message, module)
    if isinstance(safe_context, dict):
        safe_context["detected_intent"] = detected_intent
        safe_context["response_guidance"] = _chatbot_response_guidance(module, detected_intent)
    cached = False
    cached_payload = None
    cache_key = None
    provider_attempts: list[dict[str, object]] = []

    for candidate_provider in chatbot_provider_attempt_order(selected_provider):
        if candidate_provider == "fallback":
            continue
        candidate_model = safe_activity_str(chatbot_provider_model(candidate_provider))
        candidate_key = _chatbot_llm_cache_key(
            user_id,
            module,
            message,
            safe_context,
            detected_intent,
            selected_provider,
            candidate_provider,
            candidate_model,
        )
        cached_payload = _chatbot_get_cached_llm_response(candidate_key)
        if cached_payload:
            cache_key = candidate_key
            cached = True
            break

    if cached_payload:
        reply = safe_activity_str(cached_payload.get("answer") or cached_payload.get("reply"))
        provider_used = safe_activity_str(cached_payload.get("provider") or cached_payload.get("provider_used"), "ollama")
        model_used = cached_payload.get("model")
        fallback_reason = None
        provider_attempts = [
            {
                "provider": provider_used,
                "ok": True,
                "reason": None,
            }
        ]
    else:
        def fallback_answer() -> str:
            return _rule_based_llm_chatbot_answer(message, module, user, user_id, safe_context)

        routed_result = route_chatbot_llm(message, module, safe_context, selected_provider, fallback_answer)
        reply = safe_activity_str(routed_result.get("answer") or routed_result.get("reply"))
        provider_used = safe_activity_str(routed_result.get("provider"), "fallback")
        model_used = routed_result.get("model")
        fallback_reason = (
            safe_activity_str(routed_result.get("fallback_reason"))
            if routed_result.get("fallback_reason") is not None
            else None
        )
        if (
            safe_activity_str(routed_result.get("provider"), "fallback") == "fallback"
            and is_password_fallback_context(module, message)
        ):
            fallback_reason = "password_rule_based_fallback"
        provider_attempts = [
            {
                "provider": safe_activity_str(item.get("provider")),
                "ok": bool(item.get("ok")),
                "reason": safe_activity_str(item.get("reason")) if item.get("reason") is not None else None,
            }
            for item in (routed_result.get("provider_attempts") or [])
            if isinstance(item, dict)
        ]

    response_time_ms = int((time.perf_counter() - started_at) * 1000)
    context_available = bool(safe_context.get("available"))
    if cached and cached_payload:
        response_time_ms = _safe_int(cached_payload.get("response_time_ms"), response_time_ms)
        context_available = bool(cached_payload.get("context_available", context_available))
    fallback_used = provider_used == "fallback"
    if provider_used in {"ollama", "gemini"} and not fallback_used and not cached:
        cache_key = _chatbot_llm_cache_key(
            user_id,
            module,
            message,
            safe_context,
            detected_intent,
            selected_provider,
            provider_used,
            safe_activity_str(model_used),
        )
        _chatbot_store_cached_llm_response(
            cache_key,
            {
                "answer": reply,
                "reply": reply,
                "provider": provider_used,
                "provider_used": provider_used,
                "model": model_used,
                "selected_provider": selected_provider,
                "response_time_ms": response_time_ms,
                "context_available": context_available,
            },
        )
    _log_chatbot_llm_activity(user_id, module, provider_used, fallback_used, response_time_ms, fallback_reason)
    return jsonify(
        {
            "answer": reply,
            "reply": reply,
            "provider": provider_used,
            "provider_used": provider_used,
            "selected_provider": selected_provider,
            "model": model_used if provider_used in {"ollama", "gemini"} and not fallback_used else None,
            "fallback_used": bool(fallback_used),
            "fallback_reason": fallback_reason,
            "provider_attempts": provider_attempts,
            "cached": bool(cached),
            "module": module,
            "response_time_ms": response_time_ms,
            "context_available": context_available,
            "context_used": context_available,
        }
    ), 200


@app.route("/api/chatbot/pcap", methods=["POST"])
def pcap_chatbot():
    data = request.get_json(silent=True) or {}
    message = safe_activity_str(data.get("message"))
    if not message:
        return jsonify({"error": "Message is required"}), 400

    analysis_id = safe_activity_str(data.get("analysis_id") or data.get("job_id")) or None
    include_latest_analysis = str(
        data.get("include_latest_analysis", "true")
    ).strip().lower() not in {"0", "false", "no"}

    try:
        user = _optional_pcap_chatbot_user()
        context = _pcap_chatbot_context(user, analysis_id, include_latest_analysis)
        answer = _pcap_chatbot_answer(message, context)
        context_summary = _pcap_context_summary(context)
        response_analysis_id = analysis_id or context_summary.get("analysis_id")

        if user is not None:
            try:
                log_user_event(
                    user_id=int(user.id),
                    module=MODULE_PCAP,
                    action_type="pcap_chatbot_question",
                    title="PCAP chatbot question asked",
                    description="A question was asked in PCAP Analyzer chatbot mode.",
                    status=STATUS_INFO,
                    severity=SEVERITY_LOW,
                    target_type="pcap_job" if response_analysis_id else "pcap_chatbot",
                    target_id=response_analysis_id,
                    target_label=(
                        f"PCAP analysis {response_analysis_id}"
                        if response_analysis_id
                        else "PCAP chatbot"
                    ),
                    metadata_json={
                        "message_preview": _identity_safe_preview(message, 120),
                        "analysis_id": response_analysis_id,
                    },
                    commit=True,
                )
            except Exception:
                db.session.rollback()
                logging.exception(
                    "Failed to record PCAP chatbot activity | user_id=%s | analysis_id=%s",
                    getattr(user, "id", None),
                    response_analysis_id,
                )

        return jsonify(
            {
                "answer": answer,
                "mode": "pcap",
                "analysis_id": response_analysis_id,
                "context_used": bool(context_summary.get("analysis_id")),
                "context": context_summary,
            }
        ), 200
    except Exception as exc:
        logging.exception(
            "PCAP chatbot failed | analysis_id=%s | message_preview=%s",
            analysis_id,
            _identity_safe_preview(message, 80),
        )
        return jsonify(
            {
                "answer": _pcap_no_analysis_answer(),
                "mode": "pcap",
                "analysis_id": analysis_id,
                "context_used": False,
                "error": "PCAP chatbot could not build analysis context.",
                "message": str(exc)[:300],
            }
        ), 200


@app.route("/api/chatbot/identity", methods=["POST"])
def identity_chatbot():
    data = request.get_json(silent=True) or {}
    message = safe_activity_str(data.get("message"))
    if not message:
        return jsonify({"error": "Message is required"}), 400

    scan_id = _parse_positive_int(data.get("scan_id"), None)
    include_latest_scan = str(data.get("include_latest_scan", "true")).strip().lower() not in {
        "0",
        "false",
        "no",
    }

    try:
        user = _optional_identity_chatbot_user()
        context = (
            _identity_chatbot_context(int(user.id), scan_id, include_latest_scan)
            if user is not None
            else _empty_identity_chatbot_context()
        )
        answer = _identity_chatbot_answer(message, context)
        context_summary = {
            "total_scans": context.get("total_scans", 0),
            "latest_scan_id": (context.get("scan") or {}).get("id"),
            "risk_score": (context.get("scan") or {}).get("risk_score"),
            "risk_level": (context.get("scan") or {}).get("risk_level"),
            "total_findings": (context.get("scan") or {}).get("total_findings"),
            "category_counts": context.get("category_counts") or {},
            "monitored_assets_count": context.get("monitored_assets_count", 0),
            "risky_assets_count": context.get("risky_assets_count", 0),
            "protection_rate": context.get("protection_rate"),
        }
        if user is not None:
            _identity_log_event(
                int(user.id),
                "identity_chatbot_question",
                title="Identity chatbot question asked",
                description="A question was asked in Identity Leak Monitor chatbot mode.",
                status=STATUS_INFO,
                severity=SEVERITY_LOW,
                target_type="identity_scan" if context_summary.get("latest_scan_id") else "identity_chatbot",
                target_id=str(context_summary.get("latest_scan_id") or "") or None,
                target_label=(
                    f"Scan #{context_summary.get('latest_scan_id')}"
                    if context_summary.get("latest_scan_id")
                    else "Identity chatbot"
                ),
                metadata_json={
                    "message_preview": _identity_safe_preview(message, 120),
                    "scan_id": scan_id or context_summary.get("latest_scan_id"),
                },
            )
        response_scan_id = scan_id or context_summary.get("latest_scan_id")
        return jsonify(
            {
                "answer": answer,
                "mode": "identity",
                "scan_id": response_scan_id,
                "context_used": bool(context_summary.get("latest_scan_id")),
                "context": context_summary,
            }
        ), 200
    except Exception as exc:
        logging.exception(
            "Identity chatbot failed | scan_id=%s | message_preview=%s",
            scan_id,
            _identity_safe_preview(message, 80),
        )
        return jsonify(
            {
                "answer": "No Identity Leak Monitor scans were found yet. Run your first scan, then I can explain the risk level, findings, and recommended actions.",
                "mode": "identity",
                "scan_id": scan_id,
                "context_used": False,
                "error": "Identity chatbot could not build scan context.",
                "message": str(exc)[:300],
            }
        ), 200


