# 5.1) ADMIN CONSOLE ROUTES
# ========================================


@app.route("/api/admin/auth/login", methods=["POST"])
def admin_console_login():
    data = request.get_json(silent=True) or {}
    email = _normalize_linked_account_email(data.get("email", ""))
    password = str(data.get("password") or "")

    if not email or not password:
        return jsonify({"success": False, "message": "Email and password are required."}), 400

    env_admin_credentials_match = bool(
        _admin_credentials_configured()
        and email == ADMIN_EMAIL
        and hmac.compare_digest(password, ADMIN_PASSWORD)
    )
    user, _ = _resolve_login_user_and_account(email)
    if user is None and env_admin_credentials_match:
        now = datetime.now(UTC)
        user = User(
            email=email,
            password_hash=generate_password_hash(password),
            full_name="Admin",
            is_email_verified=True,
            invite_require_2fa=True,
            require_two_factor_enrollment=True,
            is_two_factor_enabled=False,
            two_factor_secret=None,
            admin_role="Admin",
            admin_status="Active",
            created_at=now,
            updated_at=now,
        )
        db.session.add(user)
        try:
            db.session.commit()
        except Exception:
            db.session.rollback()
            logging.exception("Failed to bootstrap configured admin user | email=%s", email)
            return jsonify({"success": False, "message": "Admin account could not be initialized."}), 500

    database_password_valid = bool(
        user is not None
        and getattr(user, "password_hash", None)
        and check_password_hash(user.password_hash, password)
    )
    env_admin_password_valid = bool(
        user is not None
        and env_admin_credentials_match
    )

    if user is not None and (database_password_valid or env_admin_password_valid):
        if _normalize_admin_role(getattr(user, "admin_role", "User")) != "Admin":
            log_admin_action(
                {"email": email, "name": str(getattr(user, "full_name", "") or "")},
                "admin_login",
                "Blocked non-admin console login",
                "Admin Authentication",
                target_type="admin_session",
                target_label=email,
                status="failed",
                severity="high",
                metadata={"reason": "missing_admin_role"},
                request=request,
            )
            return (
                jsonify(
                    {
                        "success": False,
                        "message": "This account does not have administrative access.",
                    }
                ),
                403,
            )
        if _normalize_admin_status(getattr(user, "admin_status", "Active")) != "Active":
            log_admin_action(
                user,
                "admin_login",
                "Blocked locked admin console login",
                "Admin Authentication",
                target_type="admin_session",
                target_label=email,
                status="failed",
                severity="critical",
                metadata={"reason": "admin_account_locked"},
                request=request,
            )
            return jsonify({"success": False, "message": "This admin account is locked."}), 423
        if not bool(getattr(user, "is_email_verified", False)):
            log_admin_action(
                user,
                "admin_login",
                "Blocked unverified admin console login",
                "Admin Authentication",
                target_type="admin_session",
                target_label=email,
                status="failed",
                severity="high",
                metadata={"reason": "email_not_verified"},
                request=request,
            )
            return jsonify({"success": False, "message": "Verify your email before using the admin console."}), 403
        if is_two_factor_required(user):
            if not is_two_factor_setup_complete(user):
                pending_token = create_pending_2fa_token(
                    user.id,
                    PENDING_2FA_SETUP_STATE,
                    PENDING_2FA_SETUP_EXPIRE_MINUTES,
                )
                resp = jsonify(
                    {
                        "success": True,
                        "email": str(getattr(user, "email", "") or "").strip().lower(),
                        "full_name": str(getattr(user, "full_name", "") or "").strip(),
                        "requires_2fa": False,
                        "requires_2fa_setup": True,
                        "pending_token": pending_token,
                    }
                )
                clear_auth_cookies(resp)
                set_cookie(
                    resp,
                    PENDING_2FA_TOKEN_COOKIE,
                    pending_token,
                    PENDING_2FA_SETUP_EXPIRE_MINUTES * 60,
                )
                return resp

            pending_token = create_pending_2fa_token(
                user.id,
                PENDING_2FA_LOGIN_STATE,
                PENDING_2FA_LOGIN_EXPIRE_MINUTES,
            )
            resp = jsonify(
                {
                    "success": True,
                    "email": str(getattr(user, "email", "") or "").strip().lower(),
                    "full_name": str(getattr(user, "full_name", "") or "").strip(),
                    "requires_2fa": True,
                    "requires_2fa_setup": False,
                    "pending_token": pending_token,
                }
            )
            clear_auth_cookies(resp)
            set_cookie(
                resp,
                PENDING_2FA_TOKEN_COOKIE,
                pending_token,
                PENDING_2FA_LOGIN_EXPIRE_MINUTES * 60,
            )
            return resp

        _record_successful_login_timestamp(user, email)
        log_admin_action(
            user,
            "admin_login",
            "Admin signed in",
            "Admin Authentication",
            target_type="admin_session",
            target_label=str(getattr(user, "email", "") or "").strip().lower(),
            status="success",
            severity="medium",
            metadata={
                "credential_source": "environment" if env_admin_password_valid else "database",
                "two_factor": False,
            },
            request=request,
        )
        return jsonify(
            {
                "success": True,
                "email": str(getattr(user, "email", "") or "").strip().lower(),
                "full_name": str(getattr(user, "full_name", "") or "").strip(),
                "token": create_admin_access_token(
                    str(getattr(user, "email", "") or "").strip().lower(),
                    user,
                ),
            }
        )

    log_admin_action(
        {"email": email, "name": email},
        "admin_login",
        "Failed admin sign-in attempt",
        "Admin Authentication",
        target_type="admin_session",
        target_label=email,
        status="failed",
        severity="high",
        metadata={"reason": "invalid_credentials"},
        request=request,
    )
    return jsonify({"success": False, "message": "Invalid admin credentials."}), 401


@app.route("/api/admin/auth/verify-2fa", methods=["POST"])
def admin_console_verify_2fa():
    data = request.get_json() or {}
    code = str(data.get("code") or "").strip()
    email = _normalize_linked_account_email(data.get("email", ""))
    user, _, auth_error = _get_pending_2fa_context({PENDING_2FA_LOGIN_STATE})
    if auth_error:
        return auth_error
    if email and str(getattr(user, "email", "") or "").strip().lower() != email:
        return jsonify({"success": False, "message": "Pending 2FA session mismatch"}), 403
    if _normalize_admin_role(getattr(user, "admin_role", "User")) != "Admin":
        return jsonify({"success": False, "message": "This account does not have administrative access."}), 403
    if not user.two_factor_secret or not user.is_two_factor_enabled:
        return jsonify({"success": False, "message": "2FA not enabled"}), 400

    totp = pyotp.TOTP(user.two_factor_secret)
    if not totp.verify(code, valid_window=1):
        log_admin_action(
            user,
            "admin_login",
            "Failed admin 2FA verification",
            "Admin Authentication",
            target_type="admin_session",
            target_label=email,
            status="failed",
            severity="high",
            metadata={"reason": "invalid_2fa_code"},
            request=request,
        )
        return jsonify({"success": False, "message": "Invalid 2FA code"}), 401

    _record_successful_login_timestamp(user, email or getattr(user, "email", ""))
    log_admin_action(
        user,
        "admin_login",
        "Admin signed in with 2FA",
        "Admin Authentication",
        target_type="admin_session",
        target_label=str(getattr(user, "email", "") or "").strip().lower(),
        status="success",
        severity="medium",
        metadata={"two_factor": True},
        request=request,
    )
    resp = jsonify(
        {
            "success": True,
            "email": str(getattr(user, "email", "") or "").strip().lower(),
            "full_name": str(getattr(user, "full_name", "") or "").strip(),
            "token": create_admin_access_token(
                str(getattr(user, "email", "") or "").strip().lower(),
                user,
            ),
        }
    )
    clear_pending_2fa_cookie(resp)
    return resp


@app.route("/api/admin/users", methods=["GET"])
@admin_auth_required
def admin_list_users():
    query = str(request.args.get("q") or "").strip().lower()
    status = _normalize_admin_user_filter_status(request.args.get("status") or "all")
    role = _normalize_admin_role(request.args.get("role") or "all")
    include_all_status = str(request.args.get("status") or "").strip().lower() in {
        "",
        "all",
    }
    include_all_roles = str(request.args.get("role") or "").strip().lower() in {
        "",
        "all",
    }

    serialized_users = [
        _serialize_admin_user_security(user)
        for user in User.query.order_by(User.id.desc()).all()
    ]

    if query:
        serialized_users = [
            user
            for user in serialized_users
            if query in str(user.get("name") or "").lower()
            or query in str(user.get("email") or "").lower()
            or query in str(user.get("status") or "").lower()
            or query in str(user.get("risk_level") or "").lower()
        ]
    if not include_all_status:
        serialized_users = [
            user for user in serialized_users if user.get("status") == status
        ]
    if not include_all_roles:
        serialized_users = [user for user in serialized_users if user.get("role") == role]

    return jsonify({"success": True, "users": serialized_users})


