def admin_audit_threat_action():
    data = request.get_json(silent=True) or {}
    alert_id = _safe_str(data.get("alert_id"))
    module_name = _safe_str(data.get("module"), "Threat Management")
    action = _safe_str(data.get("action"), "alert_viewed")
    previous_status = _safe_str(data.get("previous_status"))
    new_status = _safe_str(data.get("new_status"))
    current_admin = getattr(g, "current_admin", None) or {}
    admin_label = _safe_str(current_admin.get("email") or current_admin.get("name"), "Admin")
    reviewed_at = datetime.now(UTC).isoformat()
    if alert_id and action in {"acknowledged", "marked_false_positive"}:
        overrides = _read_admin_threat_status_overrides()
        overrides[alert_id] = {
            "status": "False Positive" if action == "marked_false_positive" else "Acknowledged",
            "previous_status": previous_status,
            "reviewed_by": admin_label,
            "reviewed_at": reviewed_at,
            "action": action,
        }
        _write_admin_threat_status_overrides(overrides)
    action_labels = {
        "evidence_viewed": "Viewed limited alert evidence",
        "report_viewed": "Viewed privacy-safe alert report",
        "acknowledged": "Acknowledged admin security event",
        "marked_false_positive": "Marked admin security event false positive",
        "alert_viewed": "Viewed admin security event",
    }
    log_admin_action(
        current_admin,
        action if action in action_labels else "alert_viewed",
        action_labels.get(action, "Viewed admin security event"),
        module_name or "Threat Management",
        target_type="admin_security_event",
        target_id=alert_id or None,
        target_label=alert_id or "security event",
        status="success",
        severity="medium",
        metadata={
            "alert_id": alert_id,
            "module": module_name,
            "action": action,
            "previous_status": previous_status,
            "new_status": new_status,
            "reviewed_by": admin_label,
            "reviewed_at": reviewed_at,
            "privacy_model": "masked_admin_monitoring",
        },
        request=request,
    )
    return jsonify({"success": True})


