def _identity_admin_sources_from_scan(scan_row, finding_sources: list[str] | None = None) -> list[str]:
    sources: set[str] = set()
    for source in finding_sources or []:
        cleaned = _safe_str(source).strip()
        if cleaned:
            sources.add(cleaned)
    try:
        source_status = json.loads(scan_row["source_status"] or "{}")
    except Exception:
        source_status = {}
    if isinstance(source_status, dict):
        for key, value in source_status.items():
            status = value.get("status") if isinstance(value, dict) else value
            if _safe_str(status).lower() not in {"", "not checked", "skipped", "disabled"}:
                sources.add(str(key).replace("_", " ").title())
    return sorted(sources) or ["Identity scan"]


def _identity_admin_masked_identifier(scan_row) -> str:
    keys = set(scan_row.keys()) if hasattr(scan_row, "keys") else set()
    for key in ("email", "username", "domain"):
        value = _safe_str(scan_row[key] if key in keys else "")
        if value:
            return _mask_admin_identifier(value)
    return "Unavailable"


def _identity_admin_report_status(scan_row) -> str:
    keys = set(scan_row.keys()) if hasattr(scan_row, "keys") else set()
    status = _safe_str(scan_row["status"] if "status" in keys else "").lower()
    if status in {"completed", "failed", "running", "queued"}:
        return status
    if "completed_at" in keys and scan_row["completed_at"]:
        return "completed"
    return status or "unknown"


def _identity_admin_no_filter(value) -> str:
    normalized = _safe_str(value).strip().lower()
    if normalized in {"", "all", "all sources", "all formats", "all findings", "any", "none"}:
        return ""
    return normalized


def _identity_admin_alert_findings_count(alert_row) -> int:
    keys = set(alert_row.keys()) if hasattr(alert_row, "keys") else set()
    for key in ("findings_count", "total_findings"):
        if key in keys:
            count = _safe_int(alert_row[key], 0)
            if count > 0:
                return count
    message = _safe_str(alert_row["message"] if "message" in keys else "")
    match = re.search(r"returned\s+(\d+)\s+(?:public\s+exposure\s+)?finding", message, re.IGNORECASE)
    return _safe_int(match.group(1), 0) if match else 0


def _identity_admin_evidence_rows(
    conn,
    scan_id: int,
    user_id: int | None = None,
    *,
    limit: int = 5,
    alert_row=None,
) -> list[dict[str, object]]:
    params: list[object] = [scan_id]
    user_clause = ""
    if user_id is not None and user_id > 0:
        user_clause = "AND user_id=?"
        params.append(user_id)
    params.append(max(1, min(limit, 10)))
    rows = conn.execute(
        f"""
        SELECT source, title, url, evidence, category, severity, detected_at, confidence
        FROM identity_findings
        WHERE scan_id=?
        {user_clause}
        ORDER BY confidence DESC, id DESC
        LIMIT ?
        """,
        tuple(params),
    ).fetchall()
    evidence = [
        {
            "source_name": _safe_str(row["source"], "Unknown source"),
            "evidence_title": _safe_str(row["title"], "Identity exposure evidence"),
            "url": _safe_str(row["url"]),
            "snippet": _safe_str(row["evidence"]),
            "query_triggered": "Hidden for privacy",
            "match_reason": _safe_str(row["category"] or row["severity"], "Public exposure signal"),
            "generated_at": _safe_str(row["detected_at"]) or None,
        }
        for row in rows
    ]
    if evidence or alert_row is None:
        return evidence
    keys = set(alert_row.keys()) if hasattr(alert_row, "keys") else set()
    return [
        {
            "source_name": "Identity Leak Monitor",
            "evidence_title": _safe_str(alert_row["title"] if "title" in keys else "", "Identity exposure alert"),
            "url": "",
            "snippet": _safe_str(alert_row["message"] if "message" in keys else "", "Identity exposure was detected for this scan."),
            "query_triggered": "Hidden for privacy",
            "match_reason": _safe_str(alert_row["severity"] if "severity" in keys else "", "Identity exposure signal"),
            "generated_at": _safe_str(alert_row["created_at"] if "created_at" in keys else "") or None,
        }
    ]


def _identity_admin_report_payload(args) -> dict[str, object]:
    risk_filter = _identity_admin_no_filter(args.get("risk_level"))
    status_filter = _identity_admin_no_filter(args.get("status"))
    source_filter = _identity_admin_no_filter(args.get("source"))
    findings_filter = _identity_admin_no_filter(args.get("findings_count"))
    date_from = _safe_str(args.get("date_from"))
    date_to = _safe_str(args.get("date_to"))

    try:
        with get_identity_web_connection() as conn:
            scan_count = _safe_int(conn.execute("SELECT COUNT(*) AS count FROM identity_scans").fetchone()["count"], 0)
            finding_count = _safe_int(conn.execute("SELECT COUNT(*) AS count FROM identity_findings").fetchone()["count"], 0)
            alert_count = _safe_int(conn.execute("SELECT COUNT(*) AS count FROM identity_alerts").fetchone()["count"], 0)
            logging.info(
                "Admin Identity Leak report DB=%s scans=%s findings=%s alerts=%s",
                IDENTITY_WEB_DB_PATH,
                scan_count,
                finding_count,
                alert_count,
            )
            scan_rows = conn.execute(
                """
                SELECT identity_scans.*,
                       COALESCE(finding_totals.findings_count, 0) AS findings_count,
                       finding_totals.finding_sources
                FROM identity_scans
                LEFT JOIN (
                    SELECT scan_id,
                           COUNT(*) AS findings_count,
                           GROUP_CONCAT(DISTINCT source) AS finding_sources
                    FROM identity_findings
                    GROUP BY scan_id
                ) AS finding_totals
                  ON finding_totals.scan_id = identity_scans.id
                ORDER BY datetime(COALESCE(identity_scans.completed_at, identity_scans.created_at)) DESC,
                         identity_scans.id DESC
                """
            ).fetchall()
            alert_rows = conn.execute(
                """
                SELECT identity_alerts.*,
                       identity_scans.email,
                       identity_scans.username,
                       identity_scans.domain,
                       identity_scans.status AS scan_status,
                       identity_scans.risk_score,
                       identity_scans.risk_level,
                       identity_scans.total_findings,
                       identity_scans.completed_at,
                       identity_scans.source_status,
                       COALESCE(finding_totals.findings_count, 0) AS findings_count,
                       finding_totals.finding_sources
                FROM identity_alerts
                LEFT JOIN identity_scans
                  ON identity_scans.id = identity_alerts.scan_id
                LEFT JOIN (
                    SELECT scan_id,
                           COUNT(*) AS findings_count,
                           GROUP_CONCAT(DISTINCT source) AS finding_sources
                    FROM identity_findings
                    GROUP BY scan_id
                ) AS finding_totals
                  ON finding_totals.scan_id = identity_alerts.scan_id
                ORDER BY datetime(identity_alerts.created_at) DESC,
                         identity_alerts.id DESC
                """
            ).fetchall()

            reports: list[dict[str, object]] = []
            all_sources: set[str] = set()
            severity_order = {"critical": 4, "high": 3, "medium": 2, "low": 1, "unknown": 0}

            def append_report(row, *, from_alert: bool = False) -> None:
                generated_at = _safe_str(
                    (row["completed_at"] if "completed_at" in row.keys() else None)
                    or (row["created_at"] if "created_at" in row.keys() else None)
                ) or None
                row_status = _safe_str(row["scan_status"] if from_alert and "scan_status" in row.keys() else "").lower()
                if not row_status:
                    row_status = _identity_admin_report_status(row) if not from_alert else "completed"
                risk_level = _safe_str(row["risk_level"] if "risk_level" in row.keys() else "", "").lower()
                if not risk_level:
                    risk_level = _safe_str(row["severity"] if "severity" in row.keys() else "Low", "Low").lower()
                risk_score = _safe_int(row["risk_score"] if "risk_score" in row.keys() else 0, 0)
                findings_count = (
                    _identity_admin_alert_findings_count(row)
                    if from_alert
                    else _safe_int(row["findings_count"] or row["total_findings"], 0)
                )
                sources = _identity_admin_sources_from_scan(
                    row,
                    [_safe_str(source) for source in _safe_str(row["finding_sources"]).split(",") if _safe_str(source)],
                )
                if from_alert and sources == ["Identity scan"]:
                    sources = ["Identity Leak Monitor"]
                all_sources.update(sources)

                if risk_filter and risk_level != risk_filter:
                    return
                if status_filter and row_status != status_filter:
                    return
                if source_filter and not any(source_filter in source.lower() for source in sources):
                    return
                if findings_filter == "with_findings" and findings_count <= 0:
                    return
                if findings_filter == "no_findings" and findings_count > 0:
                    return
                if date_from and generated_at and generated_at[:10] < date_from:
                    return
                if date_to and generated_at and generated_at[:10] > date_to:
                    return

                reports.append(
                    {
                        "scan_id": str(row["scan_id"] if from_alert else row["id"]),
                        "masked_identifier": _identity_admin_masked_identifier(row),
                        "status": row_status,
                        "risk_level": risk_level,
                        "risk_score": risk_score,
                        "findings_count": findings_count,
                        "sources": sources,
                        "generated_at": generated_at,
                        "report_available": row_status == "completed" or findings_count > 0 or from_alert,
                        "evidence": _identity_admin_evidence_rows(
                            conn,
                            _safe_int(row["scan_id"] if from_alert else row["id"], 0),
                            _safe_int(row["user_id"], 0),
                            alert_row=row if from_alert else None,
                        ),
                    }
                )

            for row in scan_rows:
                append_report(row)
            if not scan_rows:
                for row in alert_rows:
                    append_report(row, from_alert=True)
            else:
                known_scan_ids = {_safe_int(row["id"], 0) for row in scan_rows}
                for row in alert_rows:
                    if _safe_int(row["scan_id"], 0) not in known_scan_ids:
                        append_report(row, from_alert=True)

            total_scans = len(scan_rows) if scan_rows else len({row["scan_id"] for row in alert_rows})
            total_findings = (
                sum(_safe_int(row["findings_count"] or row["total_findings"], 0) for row in scan_rows)
                if scan_rows
                else sum(_identity_admin_alert_findings_count(row) for row in alert_rows)
            )
            critical_scans = (
                sum(1 for row in scan_rows if _safe_str(row["risk_level"]).lower() == "critical")
                if scan_rows
                else sum(1 for row in alert_rows if _safe_str(row["severity"]).lower() == "critical")
            )
            highest = "unknown"
            source_rows = scan_rows if scan_rows else alert_rows
            for row in source_rows:
                level = _safe_str(row["risk_level"] if "risk_level" in row.keys() else row["severity"], "unknown").lower()
                if severity_order.get(level, 0) > severity_order.get(highest, 0):
                    highest = level
            latest_row = source_rows[0] if source_rows else None
            latest_generated = (
                reports[0]["generated_at"]
                if reports
                else (
                    _safe_str(
                        (latest_row["completed_at"] if "completed_at" in latest_row.keys() else None)
                        or latest_row["created_at"]
                    )
                    if latest_row
                    else None
                )
            )
            logging.info("Admin Identity Leak report recent_reports=%s", len(reports[:50]))

            return {
                "report_name": "Identity Leak Summary",
                "status": "active",
                "last_generated": latest_generated,
                "supported_formats": ["pdf", "csv"],
                "total_scans": total_scans,
                "total_findings": total_findings,
                "critical_scans": critical_scans,
                "highest_severity": highest,
                "latest_risk_score": _safe_int(latest_row["risk_score"], 0) if latest_row and "risk_score" in latest_row.keys() else 0,
                "sources_used": sorted(all_sources),
                "evidence_available": any(_safe_int(report.get("findings_count"), 0) > 0 or report.get("evidence") for report in reports),
                "report_available": any(bool(report.get("report_available")) for report in reports),
                "recent_reports": reports[:50],
            }
    except Exception:
        logging.exception("Failed to build admin Identity Leak report")
        return {
            "report_name": "Identity Leak Summary",
            "status": "active",
            "last_generated": None,
            "supported_formats": ["pdf", "csv"],
            "total_scans": 0,
            "total_findings": 0,
            "critical_scans": 0,
            "highest_severity": "unknown",
            "latest_risk_score": 0,
            "sources_used": [],
            "evidence_available": False,
            "report_available": False,
            "recent_reports": [],
        }


def admin_identity_report_summary():
    return jsonify({"success": True, "report": _identity_admin_report_payload(request.args)})


def admin_identity_report_export():
    export_format = _safe_str(request.args.get("format"), "csv").lower()
    if export_format != "csv":
        return jsonify({"success": False, "message": "Identity PDF export is not available yet."}), 400
    report = _identity_admin_report_payload(request.args)
    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow(["scan_id", "masked_identifier", "risk_level", "risk_score", "findings_count", "sources", "generated_at", "status"])
    for item in report.get("recent_reports", []):
        if not isinstance(item, dict):
            continue
        writer.writerow(
            [
                _safe_str(item.get("scan_id")),
                _safe_str(item.get("masked_identifier")),
                _safe_str(item.get("risk_level")),
                _safe_int(item.get("risk_score"), 0),
                _safe_int(item.get("findings_count"), 0),
                "; ".join(_safe_str(source) for source in item.get("sources", []) if _safe_str(source)),
                _safe_str(item.get("generated_at")),
                _safe_str(item.get("status")),
            ]
        )
    response = make_response(output.getvalue().encode("utf-8-sig"))
    response.headers["Content-Type"] = "text/csv; charset=utf-8"
    response.headers["Content-Disposition"] = 'attachment; filename="identity-leak-summary.csv"'
    return response


def _password_admin_report_risk(record) -> str:
    breach_count = _safe_int(getattr(record, "breach_count", 0), 0)
    verdict = _safe_str(getattr(record, "verdict", "")).lower()
    strength = _safe_str(getattr(record, "strength_label", "")).lower()
    score = _safe_int(getattr(record, "score", 0), 0)

    if breach_count > 0 or verdict == "breached":
        return "critical"
    if strength in {"very weak", "very_weak", "critical"} or score <= 1:
        return "high"
    if strength == "weak" or score <= 2:
        return "medium"
    return "low"


def _password_admin_no_filter(value) -> str:
    normalized = _safe_str(value).strip().lower()
    return "" if normalized in {"", "all", "any", "none", "null", "undefined"} else normalized


def _password_admin_strength_filter_value(value) -> str:
    normalized = _password_admin_no_filter(value).replace("-", "_").replace(" ", "_")
    aliases = {
        "veryweak": "very_weak",
        "very_weak": "very_weak",
        "critical": "very_weak",
        "weak": "weak",
        "medium": "medium",
        "moderate": "medium",
        "strong": "strong",
    }
    return aliases.get(normalized, normalized)


def _password_admin_record_strength(record) -> str:
    strength = _safe_str(getattr(record, "strength_label", "")).strip().lower()
    score = _safe_int(getattr(record, "score", 0), 0)
    normalized = strength.replace("-", "_").replace(" ", "_")
    if normalized in {"very_weak", "critical"} or score <= 1:
        return "very_weak"
    if normalized == "weak" or score <= 2:
        return "weak"
    if normalized in {"medium", "moderate"} or score == 3:
        return "medium"
    if normalized == "strong" or score >= 4:
        return "strong"
    return normalized or "unknown"


def _password_admin_record_breached(record) -> bool:
    return (
        _safe_int(getattr(record, "breach_count", 0), 0) > 0
        or _safe_str(getattr(record, "verdict", "")).lower() == "breached"
    )


def _password_admin_apply_filters(records, args) -> list:
    risk_filter = _password_admin_no_filter(args.get("password_risk"))
    strength_filter = _password_admin_strength_filter_value(args.get("password_strength"))
    breach_filter = _password_admin_no_filter(args.get("breach_status")).replace("-", "_")

    valid_risks = {"critical", "high", "medium", "low"}
    valid_strengths = {"very_weak", "weak", "medium", "strong"}
    valid_breach_statuses = {"breached", "not_breached"}

    if risk_filter and risk_filter not in valid_risks:
        risk_filter = ""
    if strength_filter and strength_filter not in valid_strengths:
        strength_filter = ""
    if breach_filter and breach_filter not in valid_breach_statuses:
        breach_filter = ""

    if not (risk_filter or strength_filter or breach_filter):
        return records

    filtered = []
    for record in records:
        if risk_filter and _password_admin_report_risk(record) != risk_filter:
            continue
        if strength_filter and _password_admin_record_strength(record) != strength_filter:
            continue

        breached = _password_admin_record_breached(record)
        if breach_filter == "breached" and not breached:
            continue
        if breach_filter == "not_breached" and breached:
            continue

        filtered.append(record)

    return filtered


def _password_admin_empty_report() -> dict[str, object]:
    generated_at = datetime.now(UTC).isoformat()
    return {
        "report_name": "Password Risk Summary",
        "status": "active",
        "generated_at": generated_at,
        "last_generated": None,
        "supported_formats": ["csv"],
        "data_source": "password_checker",
        "summary": {
            "total_checks": 0,
            "breached_findings": 0,
            "weak_findings": 0,
            "strong_safe_checks": 0,
            "latest_check_at": None,
        },
        "risk_distribution": {"critical": 0, "high": 0, "medium": 0, "low": 0},
        "strength_distribution": {},
        "breach_summary": {
            "total_breached_results": 0,
            "total_exposure_count": 0,
            "average_breach_count": 0,
        },
        "recommendations": [
            "No password risk data is available yet. Run password checks to populate this report.",
        ],
        "report_available": False,
        "evidence_available": False,
    }


def _password_admin_report_payload(args=None) -> dict[str, object]:
    try:
        records = PasswordCheck.query.order_by(
            PasswordCheck.created_at.desc(),
            PasswordCheck.id.desc(),
        ).all()
    except Exception:
        logging.exception("Failed to build admin Password Risk Summary report")
        return _password_admin_empty_report()

    if not records:
        return _password_admin_empty_report()

    records = _password_admin_apply_filters(records, args or {})
    if not records:
        return _password_admin_empty_report()

    total_checks = len(records)
    risk_distribution = {"critical": 0, "high": 0, "medium": 0, "low": 0}
    strength_distribution: dict[str, int] = {}
    breached_findings = 0
    weak_findings = 0
    strong_safe_checks = 0
    total_exposure_count = 0

    for record in records:
        breach_count = _safe_int(getattr(record, "breach_count", 0), 0)
        verdict = _safe_str(getattr(record, "verdict", "")).lower()
        strength_label = _safe_str(getattr(record, "strength_label", "Unknown"), "Unknown")
        strength_key = strength_label.strip() or "Unknown"
        score = _safe_int(getattr(record, "score", 0), 0)
        risk = _password_admin_report_risk(record)

        risk_distribution[risk] = risk_distribution.get(risk, 0) + 1
        strength_distribution[strength_key] = strength_distribution.get(strength_key, 0) + 1
        total_exposure_count += max(0, breach_count)

        breached = breach_count > 0 or verdict == "breached"
        if breached:
            breached_findings += 1
        if risk in {"high", "medium"} and not breached:
            weak_findings += 1
        if not breached and risk == "low" and (score >= 4 or strength_key.lower() == "strong"):
            strong_safe_checks += 1

    recommendations = [
        "Use long unique passphrases and avoid password reuse across services.",
        "Enable MFA for accounts that support it.",
        "Use a password manager to generate and store unique credentials.",
        "Review previous checks regularly and replace weak passwords.",
    ]
    if breached_findings > 0:
        recommendations.insert(0, "Change breached passwords immediately.")
    if weak_findings > 0:
        recommendations.insert(1 if breached_findings > 0 else 0, "Replace weak or very weak passwords with stronger unique credentials.")

    latest_check = _as_utc_datetime(getattr(records[0], "created_at", None))
    average_breach_count = round(total_exposure_count / breached_findings, 2) if breached_findings else 0
    generated_at = datetime.now(UTC).isoformat()

    return {
        "report_name": "Password Risk Summary",
        "status": "active",
        "generated_at": generated_at,
        "last_generated": latest_check.isoformat() if latest_check else None,
        "supported_formats": ["csv"],
        "data_source": "password_checker",
        "summary": {
            "total_checks": total_checks,
            "breached_findings": breached_findings,
            "weak_findings": weak_findings,
            "strong_safe_checks": strong_safe_checks,
            "latest_check_at": latest_check.isoformat() if latest_check else None,
        },
        "risk_distribution": risk_distribution,
        "strength_distribution": dict(sorted(strength_distribution.items())),
        "breach_summary": {
            "total_breached_results": breached_findings,
            "total_exposure_count": total_exposure_count,
            "average_breach_count": average_breach_count,
        },
        "recommendations": recommendations,
        "report_available": True,
        "evidence_available": breached_findings > 0 or weak_findings > 0,
    }


def admin_password_risk_report_summary():
    return jsonify({"success": True, "report": _password_admin_report_payload(request.args)})


def admin_password_risk_report_export():
    export_format = _safe_str(request.args.get("format"), "csv").lower()
    if export_format != "csv":
        return jsonify({"success": False, "message": "Password Risk Summary PDF export is not available yet."}), 400

    report = _password_admin_report_payload()
    summary = report.get("summary") if isinstance(report.get("summary"), dict) else {}
    breach_summary = report.get("breach_summary") if isinstance(report.get("breach_summary"), dict) else {}
    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow(["metric", "value"])
    writer.writerow(["report_name", _safe_str(report.get("report_name"))])
    writer.writerow(["generated_at", _safe_str(report.get("generated_at"))])
    writer.writerow(["data_source", _safe_str(report.get("data_source"))])
    for key in ("total_checks", "breached_findings", "weak_findings", "strong_safe_checks", "latest_check_at"):
        writer.writerow([key, summary.get(key)])
    for key in ("total_breached_results", "total_exposure_count", "average_breach_count"):
        writer.writerow([key, breach_summary.get(key)])
    writer.writerow([])
    writer.writerow(["risk_level", "count"])
    risk_distribution = report.get("risk_distribution") if isinstance(report.get("risk_distribution"), dict) else {}
    for key, value in risk_distribution.items():
        writer.writerow([key, value])
    writer.writerow([])
    writer.writerow(["strength_label", "count"])
    strength_distribution = report.get("strength_distribution") if isinstance(report.get("strength_distribution"), dict) else {}
    for key, value in strength_distribution.items():
        writer.writerow([key, value])

    response = make_response(output.getvalue().encode("utf-8-sig"))
    response.headers["Content-Type"] = "text/csv; charset=utf-8"
    response.headers["Content-Disposition"] = 'attachment; filename="password-risk-summary.csv"'
    return response


MONTHLY_SECURITY_EMPTY_MESSAGE = "No monthly security data is available yet."


def _monthly_security_period() -> tuple[datetime, datetime]:
    now = datetime.now(UTC)
    period_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    return period_start, now


def _monthly_security_severity(value) -> str:
    normalized = _safe_str(value).lower()
    if normalized in {"critical"}:
        return "critical"
    if normalized in {"high", "danger", "error"}:
        return "high"
    if normalized in {"medium", "warning", "warn"}:
        return "medium"
    if normalized in {"low", "info", "success", "safe", "normal"}:
        return "low"
    return "unknown"


def _monthly_security_module_label(value) -> str:
    normalized = _safe_str(value).strip().lower().replace("-", "_").replace(" ", "_")
    if normalized in {"password", "password_checker", "password_security"}:
        return "Password Checker"
    if normalized in {"identity", "identity_leak_monitor", "identity_monitor"}:
        return "Identity Leak Monitor"
    if normalized in {"pcap", "pcap_analyzer", "network_forensics"}:
        return "PCAP Analyzer"
    if normalized in {"phishing", "phishing_scanner"}:
        return "Phishing Scanner"
    if normalized in {"vault", "file_vault", "encrypted_file_vault"}:
        return "File Vault"
    if normalized in {"admin_audit", "admin_audit_trail"}:
        return "Admin Audit Trail"
    if normalized in {"activity", "user_activity"}:
        return "User Activity"
    if normalized in {"notification", "notifications"}:
        return "Notifications"
    return "Other/Unknown"


def _monthly_security_filter_value(value) -> str:
    normalized = _safe_str(value).strip().lower().replace("-", "_").replace(" ", "_").replace("/", "_")
    return "" if normalized in {"", "all", "any", "none", "null", "undefined"} else normalized


def _monthly_security_event_allowed(
    severity: str,
    module_label: str,
    severity_filter: str = "",
    module_filter_label: str = "",
) -> bool:
    if severity_filter and _monthly_security_severity(severity) != severity_filter:
        return False
    if module_filter_label and _monthly_security_module_label(module_label) != module_filter_label:
        return False
    return True


def _monthly_security_increment(counter: dict[str, int], key: str, amount: int = 1) -> None:
    counter[key] = counter.get(key, 0) + max(0, _safe_int(amount, 0))


def _monthly_security_identity_counts(
    period_start: datetime,
    severity_filter: str = "",
    module_filter_label: str = "",
) -> dict[str, object]:
    empty = {
        "scan_count": 0,
        "findings_count": 0,
        "high_risk_findings": 0,
        "severity_distribution": {"critical": 0, "high": 0, "medium": 0, "low": 0, "unknown": 0},
    }
    try:
        period_text = period_start.isoformat()
        with get_identity_web_connection() as conn:
            conn.row_factory = sqlite3.Row
            scan_count = _safe_int(
                conn.execute(
                    """
                    SELECT COUNT(*) AS count
                    FROM identity_scans
                    WHERE datetime(COALESCE(completed_at, created_at)) >= datetime(?)
                    """,
                    (period_text,),
                ).fetchone()["count"],
                0,
            )
            finding_rows = conn.execute(
                """
                SELECT severity
                FROM identity_findings
                WHERE datetime(detected_at) >= datetime(?)
                """,
                (period_text,),
            ).fetchall()
    except Exception:
        logging.info("Monthly Security Report identity aggregates unavailable", exc_info=True)
        return empty

    if module_filter_label and module_filter_label != "Identity Leak Monitor":
        return empty

    severity_distribution = dict(empty["severity_distribution"])
    for row in finding_rows:
        severity = _monthly_security_severity(row["severity"] if "severity" in row.keys() else None)
        if severity_filter and severity != severity_filter:
            continue
        severity_distribution[severity] = severity_distribution.get(severity, 0) + 1
    high_risk = severity_distribution.get("critical", 0) + severity_distribution.get("high", 0)
    return {
        "scan_count": scan_count if not severity_filter else 0,
        "findings_count": sum(severity_distribution.values()),
        "high_risk_findings": high_risk,
        "severity_distribution": severity_distribution,
    }


def _monthly_security_module_activity_summary(
    period_start: datetime,
    generated_at: datetime,
    *,
    pcap_alerts_count: int,
    identity_summary: dict[str, int],
    password_summary: dict[str, int],
    notification_count: int,
    activity_count: int,
    audit_count: int,
) -> dict[str, object]:
    period_start_db = period_start.replace(tzinfo=None)
    generated_at_db = generated_at.replace(tzinfo=None)
    latest_candidates: list[datetime] = []

    def include_timestamp(value) -> bool:
        timestamp = _as_utc_datetime(value) if isinstance(value, datetime) else _pcap_admin_datetime(value)
        if not timestamp:
            return False
        if period_start <= timestamp <= generated_at:
            latest_candidates.append(timestamp)
            return True
        naive_timestamp = timestamp.replace(tzinfo=None)
        return period_start_db <= naive_timestamp <= generated_at_db

    pcap_analyses_run = 0
    pcap_completed = 0
    pcap_failed = 0
    pcap_alert_job_ids: set[str] = set()
    try:
        for (job_id,) in (
            db.session.query(PcapAlertRecord.job_id)
            .filter(or_(PcapAlertRecord.created_at >= period_start_db, PcapAlertRecord.event_at >= period_start_db))
            .filter(or_(PcapAlertRecord.created_at <= generated_at_db, PcapAlertRecord.event_at <= generated_at_db))
            .all()
        ):
            safe_job_id = _safe_str(job_id)
            if safe_job_id:
                pcap_alert_job_ids.add(safe_job_id)
    except Exception:
        logging.exception("Monthly Security Report PCAP alert job coverage failed")

    try:
        for job_state in jobs.list_recent(limit=0):
            job_timestamp = (
                getattr(job_state, "finished_at", None)
                or getattr(job_state, "updated_at", None)
                or getattr(job_state, "created_at", None)
            )
            if not include_timestamp(job_timestamp):
                continue
            pcap_analyses_run += 1
            status = _pcap_admin_status(getattr(job_state, "status", None))
            if status == "done":
                pcap_completed += 1
            elif status == "error":
                pcap_failed += 1
    except Exception:
        logging.exception("Monthly Security Report PCAP job coverage failed")

    try:
        for latest_value in (
            db.session.query(func.max(PasswordCheck.created_at))
            .filter(PasswordCheck.created_at >= period_start_db)
            .filter(PasswordCheck.created_at <= generated_at_db)
            .scalar(),
            db.session.query(func.max(UserNotification.created_at))
            .filter(UserNotification.created_at >= period_start_db)
            .filter(UserNotification.created_at <= generated_at_db)
            .scalar(),
            db.session.query(func.max(UserActivityLog.created_at))
            .filter(UserActivityLog.created_at >= period_start_db)
            .filter(UserActivityLog.created_at <= generated_at_db)
            .scalar(),
            db.session.query(func.max(AdminAuditLog.created_at))
            .filter(AdminAuditLog.created_at >= period_start_db)
            .filter(AdminAuditLog.created_at <= generated_at_db)
            .scalar(),
            db.session.query(func.max(PcapAlertRecord.created_at))
            .filter(PcapAlertRecord.created_at >= period_start_db)
            .filter(PcapAlertRecord.created_at <= generated_at_db)
            .scalar(),
        ):
            if latest_value:
                include_timestamp(latest_value)
    except Exception:
        logging.exception("Monthly Security Report activity timestamp coverage failed")

    try:
        with get_identity_web_connection() as conn:
            conn.row_factory = sqlite3.Row
            row = conn.execute(
                """
                SELECT MAX(datetime(COALESCE(completed_at, created_at))) AS latest_at
                FROM identity_scans
                WHERE datetime(COALESCE(completed_at, created_at)) >= datetime(?)
                  AND datetime(COALESCE(completed_at, created_at)) <= datetime(?)
                """,
                (period_start.isoformat(), generated_at.isoformat()),
            ).fetchone()
            if row and row["latest_at"]:
                include_timestamp(row["latest_at"])
    except Exception:
        logging.info("Monthly Security Report identity timestamp coverage unavailable", exc_info=True)

    pcap_clean_analyses = max(pcap_completed - len(pcap_alert_job_ids), 0)
    latest_activity = max(latest_candidates).isoformat() if latest_candidates else None

    return {
        "pcap_analyses_run": pcap_analyses_run,
        "pcap_completed": pcap_completed,
        "pcap_failed": pcap_failed,
        "pcap_clean_analyses": pcap_clean_analyses,
        "pcap_alerts_generated": _safe_int(pcap_alerts_count, 0),
        "identity_scans_run": _safe_int(identity_summary.get("identity_scans"), 0),
        "identity_findings_found": _safe_int(identity_summary.get("identity_exposure_findings"), 0),
        "password_checks_run": _safe_int(password_summary.get("password_checks"), 0),
        "password_breached_results": _safe_int(password_summary.get("breached_findings"), 0),
        "notifications_created": _safe_int(notification_count, 0),
        "admin_audit_events": _safe_int(audit_count, 0),
        "user_activity_events": _safe_int(activity_count, 0),
        "latest_activity_timestamp": latest_activity,
    }


def _monthly_security_admin_report_payload() -> dict[str, object]:
    period_start, generated_at = _monthly_security_period()
    period_start_db = period_start.replace(tzinfo=None)
    generated_at_db = generated_at.replace(tzinfo=None)
    severity_filter = _monthly_security_filter_value(request.args.get("severity"))
    severity_filter = severity_filter if severity_filter in {"critical", "high", "medium", "low", "unknown"} else ""
    module_filter = _monthly_security_filter_value(request.args.get("module"))
    module_filter_label = _monthly_security_module_label(module_filter) if module_filter else ""
    severity_distribution = {"critical": 0, "high": 0, "medium": 0, "low": 0, "unknown": 0}
    module_distribution: dict[str, int] = {}
    risk_area_counter: Counter[str] = Counter()

    coverage_password_summary = {
        "password_checks": 0,
        "breached_findings": 0,
        "weak_findings": 0,
        "strong_safe_checks": 0,
    }
    password_summary = {
        "password_checks": 0,
        "breached_findings": 0,
        "weak_findings": 0,
        "strong_safe_checks": 0,
    }
    identity_summary = {
        "identity_scans": 0,
        "identity_exposure_findings": 0,
        "high_risk_exposures": 0,
    }
    pcap_alerts_count = 0
    notification_count = 0
    activity_count = 0
    audit_count = 0
    coverage_pcap_alerts_count = 0
    coverage_notification_count = 0
    coverage_activity_count = 0
    coverage_audit_count = 0

    try:
        password_records = (
            PasswordCheck.query.filter(PasswordCheck.created_at >= period_start_db)
            .filter(PasswordCheck.created_at <= generated_at_db)
            .all()
        )
        coverage_password_summary["password_checks"] = len(password_records)
        for record in password_records:
            risk = _password_admin_report_risk(record)
            breach_count = _safe_int(getattr(record, "breach_count", 0), 0)
            verdict = _safe_str(getattr(record, "verdict", "")).lower()
            breached = breach_count > 0 or verdict == "breached"
            if breached:
                coverage_password_summary["breached_findings"] += 1
            elif risk in {"critical", "high", "medium"}:
                coverage_password_summary["weak_findings"] += 1
            else:
                coverage_password_summary["strong_safe_checks"] += 1
            if not _monthly_security_event_allowed(risk, "Password Checker", severity_filter, module_filter_label):
                continue
            password_summary["password_checks"] += 1
            severity_distribution[risk] = severity_distribution.get(risk, 0) + 1
            if breached:
                password_summary["breached_findings"] += 1
            elif risk in {"critical", "high", "medium"}:
                password_summary["weak_findings"] += 1
            else:
                password_summary["strong_safe_checks"] += 1
        if password_summary["password_checks"]:
            _monthly_security_increment(module_distribution, "Password Checker", password_summary["password_checks"])
        if password_summary["breached_findings"]:
            risk_area_counter["Breached password findings"] += password_summary["breached_findings"]
        if password_summary["weak_findings"]:
            risk_area_counter["Weak password findings"] += password_summary["weak_findings"]
    except Exception:
        logging.exception("Monthly Security Report password aggregates failed")

    try:
        pcap_alerts = (
            PcapAlertRecord.query.filter(
                or_(PcapAlertRecord.created_at >= period_start_db, PcapAlertRecord.event_at >= period_start_db)
            )
            .filter(
                or_(PcapAlertRecord.created_at <= generated_at_db, PcapAlertRecord.event_at <= generated_at_db)
            )
            .all()
        )
        coverage_pcap_alerts_count = len(pcap_alerts)
        for alert in pcap_alerts:
            severity = _monthly_security_severity(getattr(alert, "severity", None))
            module_label = "Password Checker" if _admin_threat_has_password_signal(alert) else "PCAP Analyzer"
            if not _monthly_security_event_allowed(severity, module_label, severity_filter, module_filter_label):
                continue
            pcap_alerts_count += 1
            severity_distribution[severity] = severity_distribution.get(severity, 0) + 1
            _monthly_security_increment(module_distribution, module_label)
            title = _safe_str(getattr(alert, "title", None))
            if title:
                risk_area_counter[title[:120]] += 1
    except Exception:
        logging.exception("Monthly Security Report PCAP alert aggregates failed")

    try:
        notifications = (
            UserNotification.query.filter(UserNotification.created_at >= period_start_db)
            .filter(UserNotification.created_at <= generated_at_db)
            .all()
        )
        coverage_notification_count = len(notifications)
        for notification in notifications:
            severity = _monthly_security_severity(getattr(notification, "severity", None))
            metadata = {}
            try:
                metadata = json.loads(getattr(notification, "metadata_json", None) or "{}")
            except Exception:
                metadata = {}
            module_label = _monthly_security_module_label(
                metadata.get("source_module")
                or metadata.get("module")
                or metadata.get("source")
                or ("password" if getattr(notification, "type", None) == NOTIFICATION_TYPE_PASSWORD_SECURITY else "notification")
            )
            if not _monthly_security_event_allowed(severity, module_label, severity_filter, module_filter_label):
                continue
            notification_count += 1
            severity_distribution[severity] = severity_distribution.get(severity, 0) + 1
            _monthly_security_increment(module_distribution, module_label)
            title = _safe_str(getattr(notification, "title", None))
            if title and severity in {"critical", "high"}:
                risk_area_counter[title[:120]] += 1
    except Exception:
        logging.exception("Monthly Security Report notification aggregates failed")

    try:
        activities = (
            UserActivityLog.query.filter(UserActivityLog.created_at >= period_start_db)
            .filter(UserActivityLog.created_at <= generated_at_db)
            .all()
        )
        coverage_activity_count = len(activities)
        for activity in activities:
            severity = _monthly_security_severity(getattr(activity, "severity", None))
            module_label = _monthly_security_module_label(getattr(activity, "module", None) or "activity")
            if not _monthly_security_event_allowed(severity, module_label, severity_filter, module_filter_label):
                continue
            activity_count += 1
            severity_distribution[severity] = severity_distribution.get(severity, 0) + 1
            _monthly_security_increment(module_distribution, module_label)
    except Exception:
        logging.exception("Monthly Security Report activity aggregates failed")

    try:
        audit_logs = (
            AdminAuditLog.query.filter(AdminAuditLog.created_at >= period_start_db)
            .filter(AdminAuditLog.created_at <= generated_at_db)
            .all()
        )
        coverage_audit_count = len(audit_logs)
        for audit_log in audit_logs:
            severity = _monthly_security_severity(getattr(audit_log, "severity", None))
            module_label = _monthly_security_module_label(getattr(audit_log, "module", None) or "admin_audit")
            if not _monthly_security_event_allowed(severity, module_label, severity_filter, module_filter_label):
                continue
            audit_count += 1
            severity_distribution[severity] = severity_distribution.get(severity, 0) + 1
            _monthly_security_increment(module_distribution, module_label)
            title = _safe_str(getattr(audit_log, "action_label", None))
            if title and severity in {"critical", "high"}:
                risk_area_counter[title[:120]] += 1
    except Exception:
        logging.exception("Monthly Security Report audit aggregates failed")

    coverage_identity_counts = _monthly_security_identity_counts(period_start)
    identity_counts = _monthly_security_identity_counts(period_start, severity_filter, module_filter_label)
    identity_summary = {
        "identity_scans": _safe_int(identity_counts.get("scan_count"), 0),
        "identity_exposure_findings": _safe_int(identity_counts.get("findings_count"), 0),
        "high_risk_exposures": _safe_int(identity_counts.get("high_risk_findings"), 0),
    }
    if identity_summary["identity_exposure_findings"] or identity_summary["identity_scans"]:
        _monthly_security_increment(
            module_distribution,
            "Identity Leak Monitor",
            identity_summary["identity_exposure_findings"] or identity_summary["identity_scans"],
        )
        for severity, count in (identity_counts.get("severity_distribution") or {}).items():
            normalized = _monthly_security_severity(severity)
            severity_distribution[normalized] = severity_distribution.get(normalized, 0) + _safe_int(count, 0)
    if identity_summary["high_risk_exposures"]:
        risk_area_counter["High-risk identity exposure findings"] += identity_summary["high_risk_exposures"]

    module_activity_summary = _monthly_security_module_activity_summary(
        period_start,
        generated_at,
        pcap_alerts_count=coverage_pcap_alerts_count,
        identity_summary={
            "identity_scans": _safe_int(coverage_identity_counts.get("scan_count"), 0),
            "identity_exposure_findings": _safe_int(coverage_identity_counts.get("findings_count"), 0),
            "high_risk_exposures": _safe_int(coverage_identity_counts.get("high_risk_findings"), 0),
        },
        password_summary=coverage_password_summary,
        notification_count=coverage_notification_count,
        activity_count=coverage_activity_count,
        audit_count=coverage_audit_count,
    )

    total_events = (
        password_summary["password_checks"]
        + pcap_alerts_count
        + notification_count
        + activity_count
        + audit_count
        + identity_summary["identity_exposure_findings"]
    )
    empty = total_events <= 0
    top_risk_areas = [
        {"title": title, "count": count}
        for title, count in risk_area_counter.most_common(5)
        if title
    ]
    recommendations = []
    if severity_distribution.get("critical", 0) or severity_distribution.get("high", 0):
        recommendations.append("Review critical and high alerts first.")
    if password_summary["breached_findings"]:
        recommendations.append("Change breached passwords immediately.")
    if password_summary["weak_findings"]:
        recommendations.append("Reduce password reuse and replace weak credentials.")
    if identity_summary["identity_exposure_findings"]:
        recommendations.append("Review identity exposure findings and rotate affected credentials.")
    if top_risk_areas:
        recommendations.append("Investigate repeated risk patterns across connected modules.")
    if not recommendations:
        recommendations.append("Run security checks and review new alerts regularly to populate this monthly report.")
    recommendations.append("Enable MFA where applicable.")

    return {
        "report_name": "Monthly Security Report",
        "status": "active",
        "generated_at": generated_at.isoformat(),
        "reporting_period": {
            "label": "Current Month",
            "start": period_start.isoformat(),
            "end": generated_at.isoformat(),
        },
        "data_source": "admin_reports",
        "summary": {
            "reporting_period": "current_month",
            "total_events": total_events,
            "critical": severity_distribution.get("critical", 0),
            "high": severity_distribution.get("high", 0),
            "medium": severity_distribution.get("medium", 0),
            "low": severity_distribution.get("low", 0),
            "unknown": severity_distribution.get("unknown", 0),
            "total_password_findings": password_summary["breached_findings"] + password_summary["weak_findings"],
            "total_identity_findings": identity_summary["identity_exposure_findings"],
            "total_pcap_alerts": pcap_alerts_count,
        },
        "module_distribution": dict(sorted(module_distribution.items())),
        "severity_distribution": severity_distribution,
        "password_summary": password_summary,
        "identity_summary": identity_summary,
        "module_activity_summary": module_activity_summary,
        "top_risk_areas": top_risk_areas,
        "recommendations": recommendations,
        "empty": empty,
        "message": MONTHLY_SECURITY_EMPTY_MESSAGE if empty else "",
        "supported_formats": [],
        "report_available": not empty,
        "evidence_available": bool(top_risk_areas),
    }


def admin_monthly_security_report_summary():
    return jsonify({"success": True, "report": _monthly_security_admin_report_payload()})


USER_ACTIVITY_REPORT_EMPTY_MESSAGE = "No user activity data is available for this period."
USER_ACTIVITY_REPORT_MODULES = {
    "admin_audit": "Admin Audit Trail",
    "password_checker": "Password Checker",
    "identity_leak_monitor": "Identity Leak Monitor",
    "pcap_analyzer": "PCAP Analyzer",
    "reports_exports": "Reports/Exports",
    "notifications": "Notifications",
    "authentication": "Authentication",
    "user_activity": "User Activity",
    "other_unknown": "Other/Unknown",
}


def _user_activity_report_no_filter(value) -> str:
    normalized = _safe_str(value).strip().lower()
    return "" if normalized in {"", "all", "any", "none", "null", "undefined"} else normalized


def _user_activity_report_period(args) -> tuple[datetime, datetime, str]:
    now = datetime.now(UTC)
    period = _user_activity_report_no_filter(args.get("date_range") or args.get("period"))
    if period in {"last_7_days", "7d", "week"}:
        return now - timedelta(days=7), now, "Last 7 Days"
    if period in {"last_30_days", "30d", "month"}:
        return now - timedelta(days=30), now, "Last 30 Days"
    start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    return start, now, "Current Month"


def _user_activity_report_module_key(value) -> str:
    normalized = _safe_str(value).strip().lower().replace("-", "_").replace(" ", "_").replace("/", "_")
    aliases = {
        "admin": "admin_audit",
        "admin_audit_trail": "admin_audit",
        "audit": "admin_audit",
        "password": "password_checker",
        "password_security": "password_checker",
        "identity": "identity_leak_monitor",
        "identity_monitor": "identity_leak_monitor",
        "pcap": "pcap_analyzer",
        "pcap_analysis": "pcap_analyzer",
        "reports": "reports_exports",
        "exports": "reports_exports",
        "report_exports": "reports_exports",
        "notification": "notifications",
        "notifications": "notifications",
        "auth": "authentication",
        "authentication": "authentication",
        "user": "user_activity",
        "user_activity": "user_activity",
    }
    return aliases.get(normalized, normalized if normalized in USER_ACTIVITY_REPORT_MODULES else "other_unknown")


def _user_activity_report_type(value) -> str:
    normalized = _safe_str(value).strip().lower().replace("-", "_").replace(" ", "_")
    if "login" in normalized or "logout" in normalized or normalized in {"auth", "authentication", "session"}:
        return "auth"
    if "export" in normalized or "download" in normalized:
        return "export"
    if normalized in {"admin", "admin_action"} or normalized.startswith("admin_"):
        return "admin_action"
    if "audit" in normalized:
        return "audit"
    if normalized in {"module", "module_activity"}:
        return "module_activity"
    return "module_activity"


def _user_activity_report_status(value) -> str:
    normalized = _safe_str(value).strip().lower()
    if normalized in {"success", "succeeded", "completed", "done", "safe", "ok"}:
        return "success"
    if normalized in {"failed", "failure", "error", "blocked", "denied"}:
        return "failed"
    if normalized in {"warning", "warn", "pending", "running", "queued"}:
        return "warning"
    return normalized or "info"


def _user_activity_report_actor(role: str, actor_id=None, name=None) -> tuple[str, str]:
    normalized_role = "admin" if role == "admin" else "user" if role == "user" else "system"
    safe_id = _safe_str(actor_id)
    key = f"{normalized_role}:{safe_id or _safe_str(name) or 'unknown'}"
    if normalized_role == "admin":
        return key, _safe_str(name)[:80] or (f"Admin #{safe_id}" if safe_id else "Unknown Admin")
    if normalized_role == "user":
        return key, f"User #{safe_id}" if safe_id else "Unknown User"
    return key, "System"


def _user_activity_report_event(events: list[dict[str, object]], *, timestamp, role, module_key, activity_type, action, status="info", actor_id=None, actor_name=None) -> None:
    occurred_at = _as_utc_datetime(timestamp) if isinstance(timestamp, datetime) else _pcap_admin_datetime(timestamp)
    if not occurred_at:
        return
    actor_key, actor_display = _user_activity_report_actor(role, actor_id, actor_name)
    module_key = _user_activity_report_module_key(module_key)
    events.append(
        {
            "timestamp": occurred_at,
            "actor_key": actor_key,
            "actor_id": _safe_str(actor_id),
            "actor_display": actor_display,
            "role": "admin" if role == "admin" else "user" if role == "user" else "system",
            "module": USER_ACTIVITY_REPORT_MODULES.get(module_key, "Other/Unknown"),
            "module_key": module_key,
            "activity_type": _user_activity_report_type(activity_type),
            "action": _safe_str(action)[:120] or "Activity event",
            "status": _user_activity_report_status(status),
        }
    )


def _user_activity_report_user_display_name(user) -> str:
    for field in ("full_name", "name", "username", "display_name"):
        value = _safe_str(getattr(user, field, None)).strip()
        if value:
            return value[:80]
    return ""


def _user_activity_report_resolve_actor_names(events: list[dict[str, object]]) -> None:
    actor_ids: set[int] = set()
    for event in events:
        if event.get("role") not in {"admin", "user"}:
            continue
        actor_id = _safe_int(event.get("actor_id"), 0)
        if actor_id > 0:
            actor_ids.add(actor_id)

    if not actor_ids:
        return

    try:
        users = User.query.filter(User.id.in_(actor_ids)).all()
        display_by_id = {
            int(user.id): display_name
            for user in users
            if (display_name := _user_activity_report_user_display_name(user))
        }
    except Exception:
        logging.exception("User Activity Report actor name resolution failed")
        return

    for event in events:
        actor_id = _safe_int(event.get("actor_id"), 0)
        display_name = display_by_id.get(actor_id)
        if display_name:
            event["actor_display"] = display_name


def _user_activity_report_filtered(events: list[dict[str, object]], args) -> list[dict[str, object]]:
    role_filter = _user_activity_report_no_filter(args.get("role"))
    type_filter = _user_activity_report_no_filter(args.get("activity_type"))
    module_filter = _user_activity_report_no_filter(args.get("module_source") or args.get("module"))
    module_key = _user_activity_report_module_key(module_filter) if module_filter else ""

    filtered = []
    for event in events:
        if role_filter and event.get("role") != role_filter:
            continue
        if type_filter and event.get("activity_type") != type_filter:
            continue
        if module_key and event.get("module_key") != module_key:
            continue
        filtered.append(event)
    return filtered


def _user_activity_report_identity_events(events: list[dict[str, object]], period_start: datetime, period_end: datetime) -> None:
    try:
        start_text = period_start.isoformat()
        end_text = period_end.isoformat()
        with get_identity_web_connection() as conn:
            conn.row_factory = sqlite3.Row
            scans = conn.execute(
                """
                SELECT id, user_id, status, created_at, completed_at
                FROM identity_scans
                WHERE datetime(COALESCE(completed_at, created_at)) >= datetime(?)
                  AND datetime(COALESCE(completed_at, created_at)) <= datetime(?)
                ORDER BY datetime(COALESCE(completed_at, created_at)) DESC
                LIMIT 1000
                """,
                (start_text, end_text),
            ).fetchall()
            for scan in scans:
                _user_activity_report_event(
                    events,
                    timestamp=scan["completed_at"] if "completed_at" in scan.keys() and scan["completed_at"] else scan["created_at"],
                    role="user",
                    actor_id=scan["user_id"] if "user_id" in scan.keys() else None,
                    module_key="identity_leak_monitor",
                    activity_type="module_activity",
                    action="Identity scan",
                    status=scan["status"] if "status" in scan.keys() else "info",
                )
    except Exception:
        logging.info("User Activity Report identity activity unavailable", exc_info=True)


def _user_activity_report_payload(args) -> dict[str, object]:
    period_start, period_end, period_label = _user_activity_report_period(args)
    period_start_db = period_start.replace(tzinfo=None)
    period_end_db = period_end.replace(tzinfo=None)
    events: list[dict[str, object]] = []

    try:
        for item in UserActivityLog.query.filter(UserActivityLog.created_at >= period_start_db).filter(UserActivityLog.created_at <= period_end_db).limit(5000).all():
            module_key = "authentication" if normalize_activity_module(getattr(item, "module", None)) == MODULE_AUTH else _user_activity_report_module_key(getattr(item, "module", None))
            _user_activity_report_event(
                events,
                timestamp=getattr(item, "created_at", None),
                role="user",
                actor_id=getattr(item, "user_id", None),
                module_key=module_key,
                activity_type=_user_activity_report_type(getattr(item, "action_type", None)),
                action=USER_ACTIVITY_LABELS.get(normalize_activity_action_type(getattr(item, "action_type", None)), getattr(item, "title", None)),
                status=getattr(item, "status", None),
            )
    except Exception:
        logging.exception("User Activity Report user activity aggregation failed")

    try:
        for item in AdminAuditLog.query.filter(AdminAuditLog.created_at >= period_start_db).filter(AdminAuditLog.created_at <= period_end_db).limit(5000).all():
            module_key = "reports_exports" if "export" in _safe_str(getattr(item, "action_type", "")).lower() else "admin_audit"
            _user_activity_report_event(
                events,
                timestamp=getattr(item, "created_at", None),
                role="admin",
                actor_id=getattr(item, "actor_user_id", None),
                actor_name=getattr(item, "actor_name", None),
                module_key=module_key,
                activity_type=_user_activity_report_type(getattr(item, "action_type", None) or "admin_action"),
                action=getattr(item, "action_label", None) or getattr(item, "action_type", None),
                status=getattr(item, "status", None),
            )
    except Exception:
        logging.exception("User Activity Report admin audit aggregation failed")

    try:
        for item in PasswordCheck.query.filter(PasswordCheck.created_at >= period_start_db).filter(PasswordCheck.created_at <= period_end_db).limit(5000).all():
            _user_activity_report_event(events, timestamp=item.created_at, role="user", actor_id=item.user_id, module_key="password_checker", activity_type="module_activity", action="Password check", status="success")
    except Exception:
        logging.exception("User Activity Report password activity aggregation failed")

    try:
        for item in PcapAlertRecord.query.filter(or_(PcapAlertRecord.created_at >= period_start_db, PcapAlertRecord.event_at >= period_start_db)).filter(or_(PcapAlertRecord.created_at <= period_end_db, PcapAlertRecord.event_at <= period_end_db)).limit(5000).all():
            _user_activity_report_event(events, timestamp=getattr(item, "event_at", None) or getattr(item, "created_at", None), role="user", actor_id=item.user_id, module_key="pcap_analyzer", activity_type="module_activity", action="PCAP alert", status=getattr(item, "status", None))
    except Exception:
        logging.exception("User Activity Report PCAP activity aggregation failed")

    _user_activity_report_identity_events(events, period_start, period_end)

    try:
        for item in UserNotification.query.filter(UserNotification.created_at >= period_start_db).filter(UserNotification.created_at <= period_end_db).limit(5000).all():
            _user_activity_report_event(events, timestamp=item.created_at, role="user", actor_id=item.user_id, module_key="notifications", activity_type="module_activity", action="Notification", status="success" if getattr(item, "is_read", False) else "info")
    except Exception:
        logging.exception("User Activity Report notification activity aggregation failed")

    filtered = sorted(_user_activity_report_filtered(events, args), key=lambda item: item["timestamp"], reverse=True)
    _user_activity_report_resolve_actor_names(filtered)
    type_distribution = Counter(str(item["activity_type"]) for item in filtered)
    role_distribution = Counter(str(item["role"]) for item in filtered)
    module_distribution = Counter(str(item["module"]) for item in filtered)
    timeline_counter = Counter(item["timestamp"].date().isoformat() for item in filtered)
    latest = filtered[0]["timestamp"].isoformat() if filtered else None
    export_count = sum(1 for item in filtered if item["activity_type"] == "export")

    return {
        "report_name": "User Activity Report",
        "status": "active",
        "generated_at": datetime.now(UTC).isoformat(),
        "reporting_period": {"label": period_label, "start": period_start.isoformat(), "end": period_end.isoformat()},
        "summary": {
            "total_activity_events": len(filtered),
            "unique_actors": len({str(item["actor_key"]) for item in filtered}),
            "active_users": len({str(item["actor_key"]) for item in filtered if item["role"] == "user"}),
            "active_admins": len({str(item["actor_key"]) for item in filtered if item["role"] == "admin"}),
            "total_exports": export_count,
            "latest_activity_at": latest,
        },
        "activity_type_distribution": dict(sorted(type_distribution.items())),
        "role_distribution": dict(sorted(role_distribution.items())),
        "module_distribution": dict(sorted(module_distribution.items())),
        "timeline": [{"date": date, "count": count} for date, count in sorted(timeline_counter.items())],
        "recent_activity": [
            {
                "timestamp": item["timestamp"].isoformat(),
                "actor": item["actor_display"],
                "actor_display_name": item["actor_display"],
                "role": item["role"],
                "module": item["module"],
                "activity_type": item["activity_type"],
                "action": item["action"],
                "status": item["status"],
            }
            for item in filtered[:50]
        ],
        "empty": len(filtered) == 0,
        "message": USER_ACTIVITY_REPORT_EMPTY_MESSAGE if not filtered else "",
        "supported_formats": [],
        "report_available": True,
        "usingFallback": False,
    }


def admin_user_activity_report_summary():
    return jsonify({"success": True, "report": _user_activity_report_payload(request.args)})


HIGH_RISK_USERS_EMPTY_MESSAGE = "No high-risk users were found for this period."


def _high_risk_users_period(args) -> tuple[datetime, datetime, str]:
    now = datetime.now(UTC)
    period = _user_activity_report_no_filter(args.get("date_range") or args.get("period"))
    if period in {"last_7_days", "7d", "week"}:
        return now - timedelta(days=7), now, "Last 7 Days"
    if period in {"last_30_days", "30d", "month"}:
        return now - timedelta(days=30), now, "Last 30 Days"
    start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    return start, now, "Current Month"


def _high_risk_users_module_key(value) -> str:
    normalized = _safe_str(value).strip().lower().replace("-", "_").replace(" ", "_").replace("/", "_")
    aliases = {
        "password": "password_checker",
        "password_checker": "password_checker",
        "identity": "identity_leak_monitor",
        "identity_monitor": "identity_leak_monitor",
        "identity_leak_monitor": "identity_leak_monitor",
        "pcap": "pcap_analyzer",
        "pcap_analyzer": "pcap_analyzer",
        "auth": "authentication",
        "authentication": "authentication",
        "notification": "notifications",
        "notifications": "notifications",
        "activity": "user_activity",
        "user_activity": "user_activity",
        "audit": "user_activity",
        "admin_audit": "user_activity",
    }
    return aliases.get(normalized, normalized if normalized in {
        "password_checker",
        "identity_leak_monitor",
        "pcap_analyzer",
        "authentication",
        "notifications",
        "user_activity",
        "other",
    } else "other")


def _high_risk_users_level(score: int) -> str:
    if score >= 80:
        return "critical"
    if score >= 50:
        return "high"
    if score >= 20:
        return "medium"
    return "low"


def _high_risk_users_points(severity: str) -> int:
    normalized = _monthly_security_severity(severity)
    if normalized == "critical":
        return 25
    if normalized == "high":
        return 15
    if normalized == "medium":
        return 8
    if normalized == "low":
        return 2
    return 8


HIGH_RISK_USERS_SOURCE_PRIORITY = (
    "password_checker",
    "identity_leak_monitor",
    "pcap_analyzer",
    "authentication",
    "notifications",
    "user_activity",
    "other",
)


def _high_risk_users_top_source(profile: dict[str, object]) -> str:
    points = profile.get("module_points") or {}
    if not points:
        return "other"
    return max(
        HIGH_RISK_USERS_SOURCE_PRIORITY,
        key=lambda module: (_safe_int(points.get(module), 0), -HIGH_RISK_USERS_SOURCE_PRIORITY.index(module)),
    )


def _high_risk_users_recommendation(profile: dict[str, object]) -> str:
    points = profile.get("module_points") or {}
    high_risk_sources = [
        module
        for module, score in points.items()
        if module != "other" and _safe_int(score, 0) >= _high_risk_users_points("high")
    ]
    if len(high_risk_sources) > 1:
        return "Prioritize account review due to multiple high-risk signals."
    source = _high_risk_users_top_source(profile)
    if source == "password_checker":
        return "Review password security findings."
    if source == "identity_leak_monitor":
        return "Review identity exposure findings."
    if source == "pcap_analyzer":
        return "Review PCAP/network alerts."
    if source == "authentication":
        return "Review recent authentication warnings."
    if source == "notifications":
        return "Review security notifications."
    if source == "user_activity":
        return "Review recent user activity risk signals."
    return "Review recent security signals."


def _high_risk_users_activity_is_risky(status: str, severity: str, action: str, suspicious: bool) -> bool:
    if suspicious:
        return True
    if status in {"failed", "failure", "error", "blocked", "denied", "warning"}:
        return True
    if severity in {"critical", "high"}:
        return True
    security_terms = {
        "alert",
        "breach",
        "blocked",
        "critical",
        "denied",
        "exposed",
        "failed",
        "risk",
        "risky",
        "suspicious",
        "threat",
        "warning",
        "weak",
        "wrong",
    }
    return severity == "medium" and any(term in action for term in security_terms)


def _high_risk_users_add_signal(
    profiles: dict[str, dict[str, object]],
    *,
    user_id,
    role: str,
    module_key: str,
    severity: str,
    timestamp,
    points: int | None = None,
) -> None:
    safe_user_id = _safe_int(user_id, 0)
    if safe_user_id <= 0:
        return
    occurred_at = _as_utc_datetime(timestamp) if isinstance(timestamp, datetime) else _pcap_admin_datetime(timestamp)
    if not occurred_at:
        return
    safe_role = "admin" if role == "admin" else "user"
    safe_module = _high_risk_users_module_key(module_key)
    key = f"{safe_role}:{safe_user_id}"
    profile = profiles.setdefault(
        key,
        {
            "user_id": safe_user_id,
            "actor_id": str(safe_user_id),
            "role": safe_role,
            "score": 0,
            "total_signals": 0,
            "latest": None,
            "module_latest": {},
            "module_counts": Counter(),
            "module_points": Counter(),
        },
    )
    signal_points = max(0, _safe_int(points if points is not None else _high_risk_users_points(severity), 0))
    profile["score"] = min(100, _safe_int(profile["score"], 0) + signal_points)
    profile["total_signals"] = _safe_int(profile["total_signals"], 0) + 1
    profile["module_counts"][safe_module] += 1
    profile["module_points"][safe_module] += signal_points
    latest = profile.get("latest")
    if not latest or occurred_at > latest:
        profile["latest"] = occurred_at
    module_latest = profile.setdefault("module_latest", {})
    module_latest_at = module_latest.get(safe_module)
    if not module_latest_at or occurred_at > module_latest_at:
        module_latest[safe_module] = occurred_at


def _high_risk_users_resolve_actor_profiles(profiles: dict[str, dict[str, object]]) -> list[dict[str, object]]:
    actor_ids = {
        _safe_int(profile.get("user_id"), 0)
        for profile in profiles.values()
        if _safe_int(profile.get("user_id"), 0) > 0
    }
    users_by_id: dict[int, object] = {}
    if actor_ids:
        try:
            users_by_id = {int(user.id): user for user in User.query.filter(User.id.in_(actor_ids)).all()}
        except Exception:
            logging.exception("High-Risk Users actor profile resolution failed")

    merged: dict[str, dict[str, object]] = {}
    for profile in profiles.values():
        actor_id = _safe_int(profile.get("user_id"), 0)
        user = users_by_id.get(actor_id)
        display_name = _user_activity_report_user_display_name(user) if user else ""
        actual_role = "admin" if profile.get("role") == "admin" else "user"
        if user and _normalize_admin_role(getattr(user, "admin_role", "User")) == "Admin":
            actual_role = "admin"
        profile["role"] = actual_role
        if display_name:
            profile["actor_display"] = display_name

        key = f"{actual_role}:{actor_id}"
        existing = merged.get(key)
        if not existing:
            merged[key] = profile
            continue

        existing["score"] = min(100, _safe_int(existing.get("score"), 0) + _safe_int(profile.get("score"), 0))
        existing["total_signals"] = _safe_int(existing.get("total_signals"), 0) + _safe_int(profile.get("total_signals"), 0)
        existing["module_counts"].update(profile.get("module_counts") or {})
        existing["module_points"].update(profile.get("module_points") or {})
        existing_module_latest = existing.setdefault("module_latest", {})
        for module, latest_at in (profile.get("module_latest") or {}).items():
            if latest_at and (not existing_module_latest.get(module) or latest_at > existing_module_latest[module]):
                existing_module_latest[module] = latest_at
        if not existing.get("actor_display") and profile.get("actor_display"):
            existing["actor_display"] = profile.get("actor_display")
        latest = profile.get("latest")
        if latest and (not existing.get("latest") or latest > existing["latest"]):
            existing["latest"] = latest

    return list(merged.values())


def _high_risk_users_scoped_profile(profile: dict[str, object], module_filter: str = "") -> dict[str, object]:
    module_counts = profile.get("module_counts") or Counter()
    module_points = profile.get("module_points") or Counter()
    module_latest = profile.get("module_latest") or {}
    if module_filter:
        scoped_counts = Counter()
        scoped_points = Counter()
        count = _safe_int(module_counts.get(module_filter), 0)
        points = _safe_int(module_points.get(module_filter), 0)
        if count > 0:
            scoped_counts[module_filter] = count
        if points > 0:
            scoped_points[module_filter] = points
        latest = module_latest.get(module_filter)
    else:
        scoped_counts = Counter(module_counts)
        scoped_points = Counter(module_points)
        latest = profile.get("latest") or max((value for value in module_latest.values() if value), default=None)

    scoped = dict(profile)
    scoped["module_counts"] = scoped_counts
    scoped["module_points"] = scoped_points
    scoped["score"] = min(100, sum(_safe_int(value, 0) for value in scoped_points.values()))
    scoped["total_signals"] = sum(_safe_int(value, 0) for value in scoped_counts.values())
    scoped["latest"] = latest
    return scoped


def _high_risk_users_payload(args) -> dict[str, object]:
    period_start, period_end, period_label = _high_risk_users_period(args)
    period_start_db = period_start.replace(tzinfo=None)
    period_end_db = period_end.replace(tzinfo=None)
    risk_filter = _user_activity_report_no_filter(args.get("risk_level"))
    risk_filter = risk_filter if risk_filter in {"critical", "high", "medium", "low"} else ""
    module_filter = _user_activity_report_no_filter(args.get("module_source") or args.get("module"))
    module_filter = _high_risk_users_module_key(module_filter) if module_filter else ""
    role_filter = _user_activity_report_no_filter(args.get("role"))
    role_filter = role_filter if role_filter in {"admin", "user"} else ""
    profiles: dict[str, dict[str, object]] = {}
    unattributed_signals = 0

    try:
        for record in PasswordCheck.query.filter(PasswordCheck.created_at >= period_start_db).filter(PasswordCheck.created_at <= period_end_db).limit(5000).all():
            risk = _password_admin_report_risk(record)
            breach_count = _safe_int(getattr(record, "breach_count", 0), 0)
            verdict = _safe_str(getattr(record, "verdict", "")).lower()
            strength = _safe_str(getattr(record, "strength_label", "")).strip().lower().replace(" ", "_")
            if breach_count > 0 or verdict == "breached":
                _high_risk_users_add_signal(profiles, user_id=record.user_id, role="user", module_key="password_checker", severity="critical", timestamp=record.created_at, points=25)
            elif risk in {"critical", "high"}:
                _high_risk_users_add_signal(profiles, user_id=record.user_id, role="user", module_key="password_checker", severity=risk, timestamp=record.created_at)
            elif strength in {"very_weak", "weak"}:
                _high_risk_users_add_signal(profiles, user_id=record.user_id, role="user", module_key="password_checker", severity="high" if strength == "very_weak" else "medium", timestamp=record.created_at, points=15 if strength == "very_weak" else 8)
    except Exception:
        logging.exception("High-Risk Users password signals failed")

    try:
        for alert in PcapAlertRecord.query.filter(or_(PcapAlertRecord.created_at >= period_start_db, PcapAlertRecord.event_at >= period_start_db)).filter(or_(PcapAlertRecord.created_at <= period_end_db, PcapAlertRecord.event_at <= period_end_db)).limit(5000).all():
            if _safe_int(getattr(alert, "user_id", None), 0) <= 0:
                unattributed_signals += 1
                continue
            _high_risk_users_add_signal(profiles, user_id=alert.user_id, role="user", module_key="pcap_analyzer", severity=getattr(alert, "severity", None), timestamp=getattr(alert, "event_at", None) or getattr(alert, "created_at", None))
    except Exception:
        logging.exception("High-Risk Users PCAP signals failed")

    try:
        with get_identity_web_connection() as conn:
            conn.row_factory = sqlite3.Row
            rows = conn.execute(
                """
                SELECT id, user_id, risk_level, total_findings, created_at, completed_at
                FROM identity_scans
                WHERE datetime(COALESCE(completed_at, created_at)) >= datetime(?)
                  AND datetime(COALESCE(completed_at, created_at)) <= datetime(?)
                LIMIT 5000
                """,
                (period_start.isoformat(), period_end.isoformat()),
            ).fetchall()
            for row in rows:
                findings = _safe_int(row["total_findings"] if "total_findings" in row.keys() else 0, 0)
                risk = _monthly_security_severity(row["risk_level"] if "risk_level" in row.keys() else None)
                if findings <= 0 and risk not in {"critical", "high"}:
                    continue
                _high_risk_users_add_signal(
                    profiles,
                    user_id=row["user_id"] if "user_id" in row.keys() else None,
                    role="user",
                    module_key="identity_leak_monitor",
                    severity=risk if risk != "unknown" else "medium",
                    timestamp=row["completed_at"] if "completed_at" in row.keys() and row["completed_at"] else row["created_at"],
                    points=max(_high_risk_users_points(risk), 10 if findings > 0 else 0),
                )
    except Exception:
        logging.info("High-Risk Users identity signals unavailable", exc_info=True)

    try:
        for notification in UserNotification.query.filter(UserNotification.created_at >= period_start_db).filter(UserNotification.created_at <= period_end_db).limit(5000).all():
            severity = _monthly_security_severity(getattr(notification, "severity", None))
            if severity not in {"critical", "high", "medium"}:
                continue
            _high_risk_users_add_signal(profiles, user_id=notification.user_id, role="user", module_key="notifications", severity=severity, timestamp=notification.created_at)
    except Exception:
        logging.exception("High-Risk Users notification signals failed")

    try:
        for activity in UserActivityLog.query.filter(UserActivityLog.created_at >= period_start_db).filter(UserActivityLog.created_at <= period_end_db).limit(5000).all():
            severity = _monthly_security_severity(getattr(activity, "severity", None))
            status = _safe_str(getattr(activity, "status", "")).lower()
            action = _safe_str(getattr(activity, "action_type", "")).lower()
            suspicious = bool(getattr(activity, "is_suspicious", False))
            if not _high_risk_users_activity_is_risky(status, severity, action, suspicious):
                continue
            module_key = "authentication" if "login" in action or normalize_activity_module(getattr(activity, "module", None)) == MODULE_AUTH else "user_activity"
            _high_risk_users_add_signal(profiles, user_id=activity.user_id, role="user", module_key=module_key, severity=severity if severity != "unknown" else "medium", timestamp=activity.created_at)
    except Exception:
        logging.exception("High-Risk Users activity signals failed")

    try:
        for audit_log in AdminAuditLog.query.filter(AdminAuditLog.created_at >= period_start_db).filter(AdminAuditLog.created_at <= period_end_db).limit(5000).all():
            severity = _monthly_security_severity(getattr(audit_log, "severity", None))
            status = _safe_str(getattr(audit_log, "status", "")).lower()
            if not (status in {"failed", "failure", "error", "blocked", "denied", "warning"} or severity in {"critical", "high"}):
                continue
            _high_risk_users_add_signal(profiles, user_id=getattr(audit_log, "actor_user_id", None), role="admin", module_key="user_activity", severity=severity if severity != "unknown" else "medium", timestamp=audit_log.created_at)
    except Exception:
        logging.exception("High-Risk Users admin audit signals failed")

    resolved_profiles = _high_risk_users_resolve_actor_profiles(profiles)
    filtered_profiles = []
    for profile in resolved_profiles:
        profile = _high_risk_users_scoped_profile(profile, module_filter)
        if module_filter and _safe_int(profile.get("total_signals"), 0) <= 0:
            continue
        level = _high_risk_users_level(_safe_int(profile["score"], 0))
        profile["risk_level"] = level
        if role_filter and profile["role"] != role_filter:
            continue
        if risk_filter and level != risk_filter:
            continue
        filtered_profiles.append(profile)

    distribution = {"critical": 0, "high": 0, "medium": 0, "low": 0}
    module_distribution = {"password_checker": 0, "identity_leak_monitor": 0, "pcap_analyzer": 0, "authentication": 0, "notifications": 0, "user_activity": 0, "other": 0}
    for profile in filtered_profiles:
        distribution[_safe_str(profile.get("risk_level"), "low")] += 1
        for module, count in profile["module_counts"].items():
            module_distribution[_high_risk_users_module_key(module)] = module_distribution.get(_high_risk_users_module_key(module), 0) + _safe_int(count, 0)

    if not risk_filter:
        top_profiles = [profile for profile in filtered_profiles if profile.get("risk_level") in {"critical", "high"}]
    else:
        top_profiles = filtered_profiles
    top_profiles = sorted(top_profiles, key=lambda item: (_safe_int(item["score"], 0), item.get("latest") or period_start), reverse=True)[:50]
    latest = max((profile.get("latest") for profile in filtered_profiles if profile.get("latest")), default=None)
    total_signals = sum(_safe_int(profile["total_signals"], 0) for profile in filtered_profiles)

    return {
        "report_name": "High-Risk Users Report",
        "status": "active",
        "generated_at": datetime.now(UTC).isoformat(),
        "reporting_period": {"label": period_label, "start": period_start.isoformat(), "end": period_end.isoformat()},
        "summary": {
            "total_users_evaluated": len(filtered_profiles),
            "high_risk_users": distribution["high"],
            "critical_risk_users": distribution["critical"],
            "medium_risk_users": distribution["medium"],
            "low_risk_users": distribution["low"],
            "total_risk_signals": total_signals,
            "latest_risk_signal_timestamp": latest.isoformat() if latest else None,
            "unattributed_signals": unattributed_signals,
        },
        "risk_level_distribution": distribution,
        "module_signal_distribution": module_distribution,
        "top_risk_users": [
            {
                "user_id": profile["user_id"],
                "actor_display_name": profile.get("actor_display") or (f"Admin #{profile['user_id']}" if profile["role"] == "admin" else f"User #{profile['user_id']}"),
                "actor_role": profile["role"],
                "risk_score": _safe_int(profile["score"], 0),
                "risk_level": _safe_str(profile.get("risk_level"), "low"),
                "total_signals": _safe_int(profile["total_signals"], 0),
                "top_risk_source": _high_risk_users_top_source(profile),
                "password_signals_count": _safe_int(profile["module_counts"].get("password_checker"), 0),
                "identity_signals_count": _safe_int(profile["module_counts"].get("identity_leak_monitor"), 0),
                "pcap_signals_count": _safe_int(profile["module_counts"].get("pcap_analyzer"), 0),
                "auth_signals_count": _safe_int(profile["module_counts"].get("authentication"), 0),
                "notification_signals_count": _safe_int(profile["module_counts"].get("notifications"), 0),
                "latest_signal_timestamp": profile["latest"].isoformat() if profile.get("latest") else None,
                "safe_recommendation": _high_risk_users_recommendation(profile),
            }
            for profile in top_profiles
        ],
        "empty": len(top_profiles) == 0,
        "message": HIGH_RISK_USERS_EMPTY_MESSAGE if not top_profiles else "",
        "report_available": True,
        "usingFallback": False,
    }


def admin_high_risk_users_report_summary():
    return jsonify({"success": True, "report": _high_risk_users_payload(request.args)})


SECURITY_INCIDENTS_EMPTY_MESSAGE = "No security incidents were found for this period."


def _security_incidents_period(args) -> tuple[datetime, datetime, str]:
    return _high_risk_users_period(args)


def _security_incidents_no_filter(value) -> str:
    normalized = _safe_str(value).strip().lower().replace("-", "_").replace(" ", "_").replace("/", "_")
    return "" if normalized in {"", "all", "any", "none", "null", "undefined"} else normalized


def _security_incidents_source_key(value) -> str:
    normalized = _security_incidents_no_filter(value)
    aliases = {
        "pcap": "pcap_analyzer",
        "pcap_analyzer": "pcap_analyzer",
        "identity": "identity_leak_monitor",
        "identity_monitor": "identity_leak_monitor",
        "identity_leak_monitor": "identity_leak_monitor",
        "password": "password_checker",
        "password_checker": "password_checker",
        "notification": "notifications",
        "notifications": "notifications",
        "auth": "authentication",
        "authentication": "authentication",
        "threat": "threat_management",
        "threat_management": "threat_management",
        "activity": "user_activity",
        "user_activity": "user_activity",
        "audit": "admin_audit",
        "admin_audit": "admin_audit",
        "admin_audit_trail": "admin_audit",
        "other_unknown": "other",
        "other": "other",
    }
    return aliases.get(normalized, "other")


def _security_incidents_type_key(value) -> str:
    normalized = _security_incidents_no_filter(value)
    aliases = {
        "network": "network_alert",
        "network_alert": "network_alert",
        "identity": "identity_exposure",
        "identity_exposure": "identity_exposure",
        "password": "password_risk",
        "password_risk": "password_risk",
        "notification": "security_notification",
        "security_notification": "security_notification",
        "auth": "auth_warning",
        "authentication": "auth_warning",
        "auth_warning": "auth_warning",
        "audit": "audit_warning",
        "audit_warning": "audit_warning",
        "threat": "threat_management",
        "threat_management": "threat_management",
        "other": "other",
    }
    return aliases.get(normalized, "other")


def _security_incidents_status(value) -> str:
    normalized = _safe_str(value).strip().lower().replace("-", "_").replace(" ", "_")
    if normalized in {"resolved", "closed", "completed", "done", "success", "safe"}:
        return "resolved"
    if normalized in {"dismissed", "ignored", "read"}:
        return "dismissed"
    if normalized in {"investigating", "in_progress", "running", "queued", "pending"}:
        return "investigating"
    if normalized in {"open", "new", "failed", "failure", "error", "blocked", "denied", "warning"}:
        return "open"
    return "unknown"


def _security_incidents_recommendation(source: str, incident_type: str) -> str:
    if source == "pcap_analyzer":
        return "Review PCAP/network alerts."
    if source == "identity_leak_monitor":
        return "Review identity exposure findings."
    if source == "password_checker":
        return "Review password security findings."
    if source == "notifications":
        return "Review security notifications."
    if source == "authentication":
        return "Review recent authentication warnings."
    if source == "admin_audit":
        return "Review admin audit warning or failure."
    if incident_type == "threat_management" or source == "threat_management":
        return "Review threat management incident workflow."
    return "Review security incident details."


def _security_incidents_safe_actor_display_name(value, role: str = "system") -> str:
    text = _safe_str(value).strip()
    if not text or re.search(r"[\w.+-]+@[\w-]+(?:\.[\w-]+)+", text):
        if role == "admin":
            return "Unknown Admin"
        if role == "user":
            return "Unknown User"
        return "System"
    return text[:80]


def _security_incidents_add(
    incidents: list[dict[str, object]],
    *,
    incident_id: str,
    timestamp,
    severity,
    source,
    incident_type,
    title,
    status="open",
    actor_id=None,
    actor_role="user",
    actor_display_name="",
    affected_area="",
    risk_score=None,
) -> None:
    occurred_at = _as_utc_datetime(timestamp) if isinstance(timestamp, datetime) else _pcap_admin_datetime(timestamp)
    if not occurred_at:
        return
    safe_severity = _monthly_security_severity(severity)
    if safe_severity == "unknown":
        safe_severity = "unknown"
    safe_source = _security_incidents_source_key(source)
    safe_type = _security_incidents_type_key(incident_type)
    safe_status = _security_incidents_status(status)
    role = "admin" if actor_role == "admin" else "user" if actor_role == "user" else "system"
    safe_actor_display = _security_incidents_safe_actor_display_name(actor_display_name, role)
    incidents.append({
        "incident_id": _safe_str(incident_id)[:80] or f"incident-{len(incidents) + 1}",
        "timestamp": occurred_at,
        "severity": safe_severity,
        "source": safe_source,
        "incident_type": safe_type,
        "title": _safe_str(title, "Security incident detected")[:160],
        "status": safe_status,
        "actor_id": str(_safe_int(actor_id, 0)) if _safe_int(actor_id, 0) > 0 else "",
        "actor_display_name": safe_actor_display,
        "actor_role": role,
        "affected_area": _safe_str(affected_area)[:120],
        "recommendation": _security_incidents_recommendation(safe_source, safe_type),
        "risk_score": _safe_int(risk_score, 0) if risk_score is not None else _high_risk_users_points(safe_severity),
    })


def _security_incidents_resolve_actor_names(incidents: list[dict[str, object]]) -> None:
    actor_ids = {_safe_int(item.get("actor_id"), 0) for item in incidents if _safe_int(item.get("actor_id"), 0) > 0}
    if not actor_ids:
        return
    try:
        users = User.query.filter(User.id.in_(actor_ids)).all()
        names = {int(user.id): _user_activity_report_user_display_name(user) for user in users}
        roles = {
            int(user.id): "admin" if _normalize_admin_role(getattr(user, "admin_role", "User")) == "Admin" else "user"
            for user in users
        }
    except Exception:
        logging.exception("Security Incidents actor name resolution failed")
        return
    for item in incidents:
        actor_id = _safe_int(item.get("actor_id"), 0)
        if actor_id in roles and item.get("actor_role") != "admin":
            item["actor_role"] = roles[actor_id]
        if actor_id in names and names[actor_id]:
            item["actor_display_name"] = _security_incidents_safe_actor_display_name(
                names[actor_id],
                _safe_str(item.get("actor_role"), "system"),
            )


def _security_incidents_payload(args) -> dict[str, object]:
    period_start, period_end, period_label = _security_incidents_period(args)
    period_start_db = period_start.replace(tzinfo=None)
    period_end_db = period_end.replace(tzinfo=None)
    severity_filter = _security_incidents_no_filter(args.get("severity"))
    severity_filter = severity_filter if severity_filter in {"critical", "high", "medium", "low", "unknown"} else ""
    source_filter = _security_incidents_source_key(args.get("module_source") or args.get("module")) if _security_incidents_no_filter(args.get("module_source") or args.get("module")) else ""
    type_filter = _security_incidents_type_key(args.get("incident_type")) if _security_incidents_no_filter(args.get("incident_type")) else ""
    status_filter = _security_incidents_status(args.get("status")) if _security_incidents_no_filter(args.get("status")) else ""
    status_filter = status_filter if status_filter in {"open", "investigating", "resolved", "dismissed", "unknown"} else ""
    incidents: list[dict[str, object]] = []

    try:
        for alert in PcapAlertRecord.query.filter(or_(PcapAlertRecord.created_at >= period_start_db, PcapAlertRecord.event_at >= period_start_db)).filter(or_(PcapAlertRecord.created_at <= period_end_db, PcapAlertRecord.event_at <= period_end_db)).limit(5000).all():
            severity = _monthly_security_severity(getattr(alert, "severity", None))
            if severity not in {"critical", "high", "medium"}:
                continue
            _security_incidents_add(incidents, incident_id=f"pcap-{getattr(alert, 'id', '')}", timestamp=getattr(alert, "event_at", None) or getattr(alert, "created_at", None), severity=severity, source="pcap_analyzer", incident_type="network_alert", title=getattr(alert, "title", None) or "PCAP security alert detected", status=getattr(alert, "status", None), actor_id=getattr(alert, "user_id", None), affected_area="Network traffic", risk_score=_high_risk_users_points(severity))
    except Exception:
        logging.exception("Security Incidents PCAP source failed")

    try:
        with get_identity_web_connection() as conn:
            conn.row_factory = sqlite3.Row
            rows = conn.execute(
                """
                SELECT id, scan_id, user_id, source, category, severity, detected_at
                FROM identity_findings
                WHERE datetime(detected_at) >= datetime(?)
                  AND datetime(detected_at) <= datetime(?)
                LIMIT 5000
                """,
                (period_start.isoformat(), period_end.isoformat()),
            ).fetchall()
            for row in rows:
                severity = _monthly_security_severity(row["severity"] if "severity" in row.keys() else None)
                _security_incidents_add(incidents, incident_id=f"identity-{row['id']}", timestamp=row["detected_at"], severity=severity, source="identity_leak_monitor", incident_type="identity_exposure", title="Identity exposure finding detected", status="open", actor_id=row["user_id"] if "user_id" in row.keys() else None, affected_area="Identity exposure", risk_score=_high_risk_users_points(severity))
    except Exception:
        logging.info("Security Incidents identity findings unavailable", exc_info=True)

    try:
        for record in PasswordCheck.query.filter(PasswordCheck.created_at >= period_start_db).filter(PasswordCheck.created_at <= period_end_db).limit(5000).all():
            risk = _password_admin_report_risk(record)
            breached = _password_admin_record_breached(record)
            strength = _password_admin_record_strength(record)
            if not (breached or risk in {"critical", "high"} or strength in {"very_weak", "weak"}):
                continue
            severity = "critical" if breached else risk
            _security_incidents_add(incidents, incident_id=f"password-{getattr(record, 'id', '')}", timestamp=getattr(record, "created_at", None), severity=severity, source="password_checker", incident_type="password_risk", title="Password security finding detected", status="open", actor_id=getattr(record, "user_id", None), affected_area="Password security", risk_score=_high_risk_users_points(severity))
    except Exception:
        logging.exception("Security Incidents password source failed")

    try:
        for notification in UserNotification.query.filter(UserNotification.created_at >= period_start_db).filter(UserNotification.created_at <= period_end_db).limit(5000).all():
            severity = _monthly_security_severity(getattr(notification, "severity", None))
            title = _safe_str(getattr(notification, "title", ""))
            type_text = _safe_str(getattr(notification, "type", ""))
            lower = f"{title} {type_text}".lower()
            if not (severity in {"critical", "high", "medium"} or any(term in lower for term in {"warning", "failed", "suspicious", "breach", "exposed", "threat", "risk"})):
                continue
            _security_incidents_add(incidents, incident_id=f"notification-{getattr(notification, 'id', '')}", timestamp=getattr(notification, "created_at", None), severity=severity, source="notifications", incident_type="security_notification", title=title or "Security notification", status="dismissed" if bool(getattr(notification, "is_read", False)) else "open", actor_id=getattr(notification, "user_id", None), affected_area="Notifications", risk_score=_high_risk_users_points(severity))
    except Exception:
        logging.exception("Security Incidents notification source failed")

    try:
        for activity in UserActivityLog.query.filter(UserActivityLog.created_at >= period_start_db).filter(UserActivityLog.created_at <= period_end_db).limit(5000).all():
            severity = _monthly_security_severity(getattr(activity, "severity", None))
            status = _safe_str(getattr(activity, "status", "")).lower()
            action = _safe_str(getattr(activity, "action_type", "")).lower()
            suspicious = bool(getattr(activity, "is_suspicious", False))
            if not _high_risk_users_activity_is_risky(status, severity, action, suspicious):
                continue
            source = "authentication" if "login" in action or normalize_activity_module(getattr(activity, "module", None)) == MODULE_AUTH else "user_activity"
            incident_type = "auth_warning" if source == "authentication" else "other"
            _security_incidents_add(incidents, incident_id=f"activity-{getattr(activity, 'id', '')}", timestamp=getattr(activity, "created_at", None), severity=severity, source=source, incident_type=incident_type, title=getattr(activity, "title", None) or USER_ACTIVITY_LABELS.get(action, "Security-relevant activity detected"), status=status, actor_id=getattr(activity, "user_id", None), affected_area="Authentication" if source == "authentication" else "User activity", risk_score=getattr(activity, "risk_score", None))
    except Exception:
        logging.exception("Security Incidents activity source failed")

    try:
        for audit_log in AdminAuditLog.query.filter(AdminAuditLog.created_at >= period_start_db).filter(AdminAuditLog.created_at <= period_end_db).limit(5000).all():
            severity = _monthly_security_severity(getattr(audit_log, "severity", None))
            status = _safe_str(getattr(audit_log, "status", "")).lower()
            if not (status in {"failed", "failure", "error", "blocked", "denied", "warning"} or severity in {"critical", "high"}):
                continue
            module = _safe_str(getattr(audit_log, "module", "")).lower()
            source = "threat_management" if "threat" in module else "admin_audit"
            _security_incidents_add(incidents, incident_id=f"audit-{getattr(audit_log, 'id', '')}", timestamp=getattr(audit_log, "created_at", None), severity=severity, source=source, incident_type="threat_management" if source == "threat_management" else "audit_warning", title=getattr(audit_log, "action_label", None) or "Admin audit warning", status=status, actor_id=getattr(audit_log, "actor_user_id", None), actor_role="admin", actor_display_name=getattr(audit_log, "actor_name", None), affected_area=_safe_str(getattr(audit_log, "module", "Admin audit")), risk_score=_high_risk_users_points(severity))
    except Exception:
        logging.exception("Security Incidents admin audit source failed")

    _security_incidents_resolve_actor_names(incidents)
    filtered = []
    for item in incidents:
        if severity_filter and item.get("severity") != severity_filter:
            continue
        if source_filter and item.get("source") != source_filter:
            continue
        if type_filter and item.get("incident_type") != type_filter:
            continue
        if status_filter and item.get("status") != status_filter:
            continue
        filtered.append(item)

    severity_distribution = {"critical": 0, "high": 0, "medium": 0, "low": 0, "unknown": 0}
    source_distribution = {"pcap_analyzer": 0, "identity_leak_monitor": 0, "password_checker": 0, "notifications": 0, "authentication": 0, "threat_management": 0, "user_activity": 0, "admin_audit": 0, "other": 0}
    type_distribution = {"network_alert": 0, "identity_exposure": 0, "password_risk": 0, "security_notification": 0, "auth_warning": 0, "audit_warning": 0, "threat_management": 0, "other": 0}
    status_distribution = {"open": 0, "investigating": 0, "resolved": 0, "dismissed": 0, "unknown": 0}
    timeline_counter: Counter[str] = Counter()
    risk_areas: Counter[str] = Counter()
    risk_area_severity: dict[str, str] = {}
    rank = {"unknown": 0, "low": 1, "medium": 2, "high": 3, "critical": 4}
    for item in filtered:
        severity_distribution[_safe_str(item.get("severity"), "unknown")] += 1
        source_distribution[_safe_str(item.get("source"), "other")] += 1
        type_distribution[_safe_str(item.get("incident_type"), "other")] += 1
        status_distribution[_safe_str(item.get("status"), "unknown")] += 1
        occurred_at = item.get("timestamp")
        if isinstance(occurred_at, datetime):
            timeline_counter[occurred_at.date().isoformat()] += 1
        area = _safe_str(item.get("affected_area"), "Security")
        risk_areas[area] += 1
        severity = _safe_str(item.get("severity"), "unknown")
        if rank.get(severity, 0) > rank.get(risk_area_severity.get(area, "unknown"), 0):
            risk_area_severity[area] = severity

    sorted_incidents = sorted(filtered, key=lambda item: item.get("timestamp") or period_start, reverse=True)
    latest = sorted_incidents[0].get("timestamp") if sorted_incidents else None
    top_risk_areas = [
        {
            "title": title,
            "count": count,
            "severity": risk_area_severity.get(title, "unknown"),
            "recommendation": "Review related security incidents and prioritize the highest severity items.",
        }
        for title, count in risk_areas.most_common(8)
    ]

    return {
        "report_name": "Security Incidents Report",
        "status": "active",
        "generated_at": datetime.now(UTC).isoformat(),
        "reporting_period": {"label": period_label, "start": period_start.isoformat(), "end": period_end.isoformat()},
        "summary": {
            "total_incidents": len(filtered),
            "critical_incidents": severity_distribution["critical"],
            "high_incidents": severity_distribution["high"],
            "medium_incidents": severity_distribution["medium"],
            "low_incidents": severity_distribution["low"],
            "open_incidents": status_distribution["open"],
            "resolved_incidents": status_distribution["resolved"],
            "latest_incident_timestamp": latest.isoformat() if isinstance(latest, datetime) else None,
        },
        "severity_distribution": severity_distribution,
        "source_distribution": source_distribution,
        "incident_type_distribution": type_distribution,
        "status_distribution": status_distribution,
        "timeline": [{"date": key, "count": value} for key, value in sorted(timeline_counter.items())],
        "recent_incidents": [
            {
                "incident_id": _safe_str(item.get("incident_id")),
                "timestamp": item["timestamp"].isoformat() if isinstance(item.get("timestamp"), datetime) else None,
                "severity": _safe_str(item.get("severity"), "unknown"),
                "source": _safe_str(item.get("source"), "other"),
                "incident_type": _safe_str(item.get("incident_type"), "other"),
                "title": _safe_str(item.get("title"), "Security incident detected"),
                "status": _safe_str(item.get("status"), "unknown"),
                "actor_display_name": _safe_str(item.get("actor_display_name")) or ("System" if item.get("actor_role") == "system" else "Unknown User"),
                "actor_role": _safe_str(item.get("actor_role"), "system"),
                "affected_area": _safe_str(item.get("affected_area")),
                "recommendation": _safe_str(item.get("recommendation"), "Review security incident details."),
                "risk_score": _safe_int(item.get("risk_score"), 0),
            }
            for item in sorted_incidents[:50]
        ],
        "top_risk_areas": top_risk_areas,
        "empty": len(filtered) == 0,
        "message": SECURITY_INCIDENTS_EMPTY_MESSAGE if not filtered else "",
        "supported_formats": ["pdf", "csv"],
        "report_available": True,
        "usingFallback": False,
    }


def admin_security_incidents_report_summary():
    return jsonify({"success": True, "report": _security_incidents_payload(request.args)})


PCAP_ADMIN_DONE_STATUSES = {"done", "completed", "success", "succeeded"}
PCAP_ADMIN_FAILED_STATUSES = {"error", "failed", "failure"}
PCAP_ADMIN_RUNNING_STATUSES = {"running", "processing", "in_progress"}
PCAP_ADMIN_QUEUED_STATUSES = {"queued", "pending", "waiting"}


def _pcap_admin_status(value) -> str:
    normalized = str(value or "").strip().lower()
    if normalized in PCAP_ADMIN_DONE_STATUSES:
        return "done"
    if normalized in PCAP_ADMIN_FAILED_STATUSES:
        return "error"
    if normalized in PCAP_ADMIN_RUNNING_STATUSES:
        return "running"
    if normalized in PCAP_ADMIN_QUEUED_STATUSES:
        return "queued"
    return normalized or "unknown"


def _pcap_admin_datetime(value) -> Optional[datetime]:
    if value is None:
        return None
    if isinstance(value, datetime):
        if value.tzinfo is None:
            return value.replace(tzinfo=UTC)
        return value.astimezone(UTC)

    text_value = str(value or "").strip()
    if not text_value:
        return None
    try:
        parsed = datetime.fromisoformat(text_value.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        return parsed.replace(tzinfo=UTC)
    return parsed.astimezone(UTC)


def _pcap_admin_iso(value) -> Optional[str]:
    parsed = _pcap_admin_datetime(value)
    return parsed.isoformat() if parsed else None


def _pcap_admin_epoch(value) -> float:
    parsed = _pcap_admin_datetime(value)
    return parsed.timestamp() if parsed else 0.0


def _pcap_admin_number(value) -> Optional[float]:
    try:
        if value is None or value == "":
            return None
        numeric = float(value)
        if math.isnan(numeric) or math.isinf(numeric):
            return None
        return numeric
    except (TypeError, ValueError):
        return None


def _pcap_admin_int(value, default: int = 0) -> int:
    numeric = _pcap_admin_number(value)
    if numeric is None:
        return default
    return int(numeric)


def _pcap_admin_nested(payload: dict | None, *keys):
    current = payload
    for key in keys:
        if not isinstance(current, dict):
            return None
        current = current.get(key)
    return current


def _pcap_admin_report_for_job(job_state) -> dict | None:
    try:
        report = _load_report_payload_for_job(job_state)
        return report if isinstance(report, dict) else None
    except Exception:
        logging.exception(
            "Failed to load PCAP report for admin overview | job_id=%s",
            getattr(job_state, "job_id", "unknown"),
        )
        return None


def _pcap_admin_processing_time_seconds(job_state, report: dict | None = None) -> Optional[float]:
    candidates = [
        _pcap_admin_nested(report, "summary", "processing_time_seconds"),
        _pcap_admin_nested(report, "meta", "processing_time_seconds"),
        _pcap_admin_nested(report, "meta", "pipeline", "processing_time_seconds"),
        getattr(job_state, "processing_time_seconds", None),
    ]
    for candidate in candidates:
        numeric = _pcap_admin_number(candidate)
        if numeric is not None and numeric >= 0:
            return round(numeric, 3)

    finished_at = _pcap_admin_datetime(getattr(job_state, "finished_at", None))
    if finished_at is None:
        return None

    started_at = _pcap_admin_datetime(getattr(job_state, "started_at", None))
    created_at = _pcap_admin_datetime(getattr(job_state, "created_at", None))
    start_time = started_at or created_at
    if start_time is None:
        return None

    seconds = (finished_at - start_time).total_seconds()
    return round(max(0.0, seconds), 3)


def _pcap_admin_score_from_report(report: dict | None) -> Optional[float]:
    if not isinstance(report, dict):
        return None

    direct_candidates = [
        _pcap_admin_nested(report, "summary", "risk_score"),
        _pcap_admin_nested(report, "summary", "score"),
        report.get("risk_score"),
        report.get("score"),
        _pcap_admin_nested(report, "module_contract", "supporting_metrics", "risk_score"),
    ]
    for candidate in direct_candidates:
        numeric = _pcap_admin_number(candidate)
        if numeric is not None:
            return round(max(0.0, min(100.0, numeric)), 1)

    overall_risk = (
        _pcap_admin_number(_pcap_admin_nested(report, "summary", "overall_risk"))
        or _pcap_admin_number(_pcap_admin_nested(report, "module_contract", "supporting_metrics", "overall_risk"))
        or _pcap_admin_number(report.get("overall_risk"))
    )
    if overall_risk is not None:
        if overall_risk <= 1:
            overall_risk *= 100.0
        return round(max(0.0, min(100.0, overall_risk)), 1)

    # The analyzer report exposes security_score where higher means safer. The
    # admin control uses risk score semantics, so invert only when no risk score
    # field exists.
    security_score = (
        _pcap_admin_number(_pcap_admin_nested(report, "summary", "security_score"))
        or _pcap_admin_number(_pcap_admin_nested(report, "module_contract", "module_score"))
        or _pcap_admin_number(report.get("security_score"))
    )
    if security_score is not None:
        return round(max(0.0, min(100.0, 100.0 - security_score)), 1)

    return None


def _pcap_admin_risk_level(score: Optional[float], raw_level=None) -> str:
    raw = str(raw_level or "").strip().lower()
    if raw in {"critical", "severe"}:
        return "critical"
    if raw in {"high", "risky"}:
        return "high"
    if raw in {"medium", "warning", "elevated"}:
        return "medium"
    if raw in {"low", "normal", "secure", "safe"}:
        return "low"

    if score is None:
        return "unknown"
    if score >= 85:
        return "critical"
    if score >= 70:
        return "high"
    if score >= 40:
        return "medium"
    return "low"


def _pcap_admin_analysis_mode(report: dict | None) -> str:
    if not isinstance(report, dict):
        return "Unknown"

    meta = report.get("meta") if isinstance(report.get("meta"), dict) else {}
    raw_mode = str(meta.get("analysis_mode") or "").strip().lower()
    zeek_used = bool(
        meta.get("zeek_enrichment_succeeded")
        or meta.get("zeek_evidence_available")
        or _pcap_admin_nested(report, "summary", "zeek_used")
    )

    alerts = report.get("alerts") if isinstance(report.get("alerts"), list) else []
    clusters = report.get("clusters") if isinstance(report.get("clusters"), list) else []
    has_ml = any(
        isinstance(item, dict)
        and (item.get("ml_label") or item.get("attack_type") or item.get("type") == "ML")
        for item in [*alerts[:50], *clusters[:50]]
    )
    has_heuristics = any(
        isinstance(item, dict)
        and (
            item.get("heuristic")
            or item.get("heuristic_score")
            or item.get("heuristic_type")
            or item.get("reason")
        )
        for item in alerts[:50]
    )

    if raw_mode in {"enriched", "hybrid", "hybrid_logic"} or zeek_used or (has_ml and has_heuristics):
        return "Hybrid Logic"
    if has_ml:
        return "ML Only"
    if has_heuristics:
        return "Heuristics Only"
    if raw_mode == "base_only":
        return "ML Only"
    return "Unknown"


def _pcap_admin_zeek_used(report: dict | None, evidence_available: bool = False) -> str:
    if evidence_available:
        return "yes"
    if not isinstance(report, dict):
        return "unknown"

    meta = report.get("meta") if isinstance(report.get("meta"), dict) else {}
    if bool(meta.get("zeek_enrichment_succeeded") or meta.get("zeek_evidence_available")):
        return "yes"
    if meta.get("zeek_requested") is False:
        return "no"
    if str(meta.get("run_folder") or "").lower().find("zeek") >= 0:
        return "yes"
    return "unknown"


def _pcap_admin_feature_contract_status(report: dict | None) -> Optional[str]:
    if not isinstance(report, dict):
        return None
    if isinstance(report.get("module_contract"), dict):
        return "Report contract available"
    if isinstance(report.get("summary"), dict):
        return "Summary contract available"
    return None


def _pcap_admin_model_version() -> Optional[str]:
    metrics_path = Path(__file__).resolve().parent / "model" / "metrics_pcap65.json"
    if not metrics_path.exists():
        return None
    try:
        updated_at = datetime.fromtimestamp(metrics_path.stat().st_mtime, tz=UTC)
        return f"pcap65-{updated_at.strftime('%Y%m%d%H%M')}"
    except OSError:
        return None


def _pcap_admin_detection_source(item: dict, report: dict | None) -> str:
    mode = _pcap_admin_analysis_mode(report)
    if mode == "Hybrid Logic":
        return "Hybrid"
    if item.get("heuristic") or item.get("heuristic_score") or item.get("heuristic_type"):
        return "Heuristic"
    if item.get("ml_label") or item.get("attack_type") or item.get("type") == "ML":
        return "ML"
    return "Hybrid" if mode == "Hybrid Logic" else "ML"


def _pcap_admin_family_from_item(item: dict, report: dict | None) -> Optional[dict[str, object]]:
    label = (
        item.get("attack_type")
        or item.get("ml_label")
        or item.get("label")
        or item.get("name")
        or item.get("verdict")
    )
    family = _humanize_pcap_attack_label(label)
    if not family or family.lower() in {"normal", "unknown"}:
        return None

    severity = str(item.get("severity") or item.get("verdict") or "").strip().lower()
    if severity == "normal":
        severity = "low"

    return {
        "family": family,
        "count": max(
            1,
            _pcap_admin_int(
                item.get("count")
                or item.get("count_flows")
                or item.get("flows")
                or item.get("flow_count")
                or 1,
                1,
            ),
        ),
        "severity": severity or None,
        "source": _pcap_admin_detection_source(item, report),
    }


def _pcap_admin_latest_attack_families(reports: list[dict]) -> list[dict[str, object]]:
    families: dict[str, dict[str, object]] = {}
    severity_rank = {"low": 1, "medium": 2, "high": 3, "critical": 4}

    for report in reports[:30]:
        if not isinstance(report, dict):
            continue
        clusters = report.get("clusters") if isinstance(report.get("clusters"), list) else []
        alerts = report.get("alerts") if isinstance(report.get("alerts"), list) else []
        raw_items = clusters if clusters else alerts
        if not raw_items:
            raw_items = (report.get("timeline") if isinstance(report.get("timeline"), list) else [])[:200]

        for item in raw_items[:80]:
            if not isinstance(item, dict):
                continue
            family_item = _pcap_admin_family_from_item(item, report)
            if not family_item:
                continue
            key = str(family_item["family"]).lower()
            existing = families.setdefault(
                key,
                {
                    "family": family_item["family"],
                    "count": 0,
                    "severity": family_item.get("severity"),
                    "source": family_item.get("source") or "Hybrid",
                },
            )
            existing["count"] = int(existing.get("count") or 0) + int(family_item["count"])
            new_severity = str(family_item.get("severity") or "").lower()
            old_severity = str(existing.get("severity") or "").lower()
            if severity_rank.get(new_severity, 0) > severity_rank.get(old_severity, 0):
                existing["severity"] = new_severity
            if existing.get("source") != family_item.get("source"):
                existing["source"] = "Hybrid"

    return sorted(
        families.values(),
        key=lambda item: (
            int(item.get("count") or 0),
            severity_rank.get(str(item.get("severity") or "").lower(), 0),
        ),
        reverse=True,
    )[:8]


def _pcap_admin_job_filename(job_state) -> str:
    upload_path = getattr(job_state, "upload_path", None)
    if not upload_path:
        return str(getattr(job_state, "job_id", "") or "Not available")
    try:
        return Path(upload_path).name
    except Exception:
        return str(upload_path)


def _pcap_admin_job_row(job_state, report: dict | None = None) -> dict[str, object]:
    artifacts = _collect_job_export_artifacts(job_state)
    status = _pcap_admin_status(getattr(job_state, "status", None))
    score = _pcap_admin_score_from_report(report)
    raw_level = (
        _pcap_admin_nested(report, "summary", "risk_level")
        or _pcap_admin_nested(report, "module_contract", "supporting_metrics", "risk_level")
    )
    top_risk = _pcap_admin_nested(report, "summary", "top_risk")
    detected_family = None
    if isinstance(top_risk, dict):
        detected_family = top_risk.get("name")
    if not detected_family and isinstance(report, dict):
        families = _pcap_admin_latest_attack_families([report])
        if families:
            detected_family = families[0].get("family")

    processing_time = _pcap_admin_processing_time_seconds(job_state, report)
    risk_level = _pcap_admin_risk_level(score, raw_level)
    detected_family_text = str(detected_family or "").strip().lower()
    threat_detected = (
        risk_level in {"medium", "high", "critical"}
        or (score is not None and float(score) > 0)
        or (
            bool(detected_family_text)
            and detected_family_text
            not in {"unknown / not classified", "unknown", "benign", "normal", "not classified"}
        )
    )
    return {
        "job_id": str(getattr(job_state, "job_id", "") or ""),
        "filename": _pcap_admin_job_filename(job_state),
        "status": status,
        "score": score,
        "risk_level": risk_level,
        "detected_family": detected_family or "Unknown / Not classified",
        "analysis_mode": _pcap_admin_analysis_mode(report),
        "zeek_used": _pcap_admin_zeek_used(report, bool(artifacts["zeek_files"])),
        "processing_time_seconds": processing_time,
        "created_at": _pcap_admin_iso(getattr(job_state, "created_at", None)),
        "started_at": _pcap_admin_iso(getattr(job_state, "started_at", None)),
        "finished_at": _pcap_admin_iso(getattr(job_state, "finished_at", None)),
        "report_available": artifacts["report_path"] is not None,
        "evidence_available": bool(artifacts["zeek_files"]),
        "threat_detected": threat_detected,
        "timeline_available": bool(
            isinstance(report, dict)
            and isinstance(report.get("timeline"), list)
            and len(report.get("timeline") or []) > 0
        ),
    }


def _pcap_admin_queue_health(counts: dict[str, int], latest_status: str) -> dict[str, object]:
    failed = counts.get("failed_jobs", 0)
    queued = counts.get("queued_jobs", 0)
    running = counts.get("running_jobs", 0)

    if failed >= 3:
        return {
            "status": "critical",
            "message": "Multiple PCAP jobs failed recently. Review failed jobs before starting more analysis.",
            "latest_job_status": latest_status,
        }
    if failed > 0 or queued >= 10:
        return {
            "status": "warning",
            "message": "Queue needs attention because failed jobs exist or the waiting queue is growing.",
            "latest_job_status": latest_status,
        }
    if running > 3 and queued > 0:
        return {
            "status": "warning",
            "message": "Workers are busy and new jobs are waiting. Monitor throughput.",
            "latest_job_status": latest_status,
        }
    if latest_status == "unknown" and sum(counts.values()) == 0:
        return {
            "status": "unknown",
            "message": "No PCAP job activity is available yet.",
            "latest_job_status": latest_status,
        }
    return {
        "status": "healthy",
        "message": "Queue looks healthy. Failed jobs are low and workload is within normal limits.",
        "latest_job_status": latest_status,
    }


def _pcap_admin_timeline_for_job(job_state, report: dict | None = None) -> list[dict[str, object]]:
    job_id = str(getattr(job_state, "job_id", "") or "")
    filename = _pcap_admin_job_filename(job_state)
    status = _pcap_admin_status(getattr(job_state, "status", None))
    created_at = _pcap_admin_iso(getattr(job_state, "created_at", None))
    started_at = _pcap_admin_iso(getattr(job_state, "started_at", None))
    finished_at = _pcap_admin_iso(getattr(job_state, "finished_at", None))
    zeek_status = _pcap_admin_zeek_used(report, bool(getattr(job_state, "evidence_dir", None)))

    events: list[dict[str, object]] = []

    def add(label: str, timestamp: Optional[str], state: str, detail: str):
        if not timestamp:
            return
        events.append(
            {
                "job_id": job_id,
                "filename": filename,
                "label": label,
                "timestamp": timestamp,
                "status": state,
                "detail": detail,
            }
        )

    add("File uploaded", created_at, "info", "PCAP file was accepted by the analyzer.")
    add("Job queued", created_at, "queued", "Analysis job entered the backend registry.")
    add("Packet export started", started_at, "running", "Packet export and CIC-style aggregation began.")

    if status == "done":
        add("ML inference completed", finished_at, "done", "The model inference stage completed.")
        add(
            "Heuristic validation completed",
            finished_at,
            "done",
            "Heuristic validation and scoring were applied where available.",
        )
        add(
            "Zeek enrichment completed" if zeek_status == "yes" else "Zeek enrichment skipped",
            finished_at,
            "done" if zeek_status == "yes" else "info",
            "Evidence enrichment status was derived from report metadata and artifacts.",
        )
        add("Final score generated", finished_at, "done", "Risk score and report summary were generated.")
        add("Report ready", finished_at, "done", "Report artifact is available for review." if report else "Job completed.")
    elif status == "error":
        add("Job failed", finished_at, "error", _summarize_job_error(getattr(job_state, "error", None)) or "Processing failed.")

    return events


@app.route("/api/admin/pcap/overview", methods=["GET"])
@admin_auth_required
def admin_pcap_overview():
    limit = _parse_positive_int(request.args.get("limit"), 100)
    limit = 100 if limit is None else min(max(limit, 20), 250)
    all_jobs = jobs.list_recent(limit=0)
    recent_jobs = all_jobs[:limit]

    reports_by_job_id: dict[str, dict] = {}
    completed_reports: list[dict] = []
    for job_state in recent_jobs:
        if _pcap_admin_status(getattr(job_state, "status", None)) != "done":
            continue
        report = _pcap_admin_report_for_job(job_state)
        if report:
            reports_by_job_id[str(getattr(job_state, "job_id", ""))] = report
            completed_reports.append(report)

    status_counts = {
        "queued_jobs": 0,
        "running_jobs": 0,
        "completed_jobs": 0,
        "failed_jobs": 0,
    }
    day_ago = datetime.now(UTC) - timedelta(hours=24)
    failed_jobs_24h = 0
    for job_state in all_jobs:
        status = _pcap_admin_status(getattr(job_state, "status", None))
        if status == "queued":
            status_counts["queued_jobs"] += 1
        elif status == "running":
            status_counts["running_jobs"] += 1
        elif status == "done":
            status_counts["completed_jobs"] += 1
        elif status == "error":
            status_counts["failed_jobs"] += 1
            failed_at = (
                _pcap_admin_datetime(getattr(job_state, "finished_at", None))
                or _pcap_admin_datetime(getattr(job_state, "updated_at", None))
                or _pcap_admin_datetime(getattr(job_state, "created_at", None))
            )
            if failed_at and failed_at >= day_ago:
                failed_jobs_24h += 1

    processing_times = [
        value
        for value in (
            _pcap_admin_processing_time_seconds(
                job_state,
                reports_by_job_id.get(str(getattr(job_state, "job_id", ""))),
            )
            for job_state in all_jobs
            if _pcap_admin_status(getattr(job_state, "status", None)) == "done"
        )
        if value is not None
    ]

    latest_status = _pcap_admin_status(getattr(recent_jobs[0], "status", None)) if recent_jobs else "unknown"
    latest_finished = max(
        (
            _pcap_admin_epoch(getattr(job_state, "finished_at", None))
            for job_state in all_jobs
            if _pcap_admin_status(getattr(job_state, "status", None)) == "done"
        ),
        default=0.0,
    )
    last_analysis_time = (
        datetime.fromtimestamp(latest_finished, tz=UTC).isoformat()
        if latest_finished > 0
        else None
    )

    rows = [
        _pcap_admin_job_row(
            job_state,
            reports_by_job_id.get(str(getattr(job_state, "job_id", "")))
            or _pcap_admin_report_for_job(job_state),
        )
        for job_state in recent_jobs
    ]

    latest_files = [
        row
        for row in sorted(
            rows,
            key=lambda item: _pcap_admin_epoch(item.get("finished_at") or item.get("created_at")),
            reverse=True,
        )
        if row.get("status") == "done"
    ][:5]

    top_suspicious_files = [
        row
        for row in sorted(
            [item for item in rows if item.get("score") is not None],
            key=lambda item: float(item.get("score") or 0),
            reverse=True,
        )
    ][:5]

    timeline: list[dict[str, object]] = []
    for job_state in recent_jobs[:8]:
        report = reports_by_job_id.get(str(getattr(job_state, "job_id", "")))
        timeline.extend(_pcap_admin_timeline_for_job(job_state, report))
    timeline.sort(key=lambda item: _pcap_admin_epoch(item.get("timestamp")), reverse=True)

    latest_completed_with_report = None
    for job_state in recent_jobs:
        report = reports_by_job_id.get(str(getattr(job_state, "job_id", "")))
        if report:
            latest_completed_with_report = (job_state, report)
            break

    latest_report = latest_completed_with_report[1] if latest_completed_with_report else None
    latest_row = (
        _pcap_admin_job_row(latest_completed_with_report[0], latest_report)
        if latest_completed_with_report
        else None
    )
    zeek_used = (
        _pcap_admin_zeek_used(latest_report, bool(latest_row and latest_row.get("evidence_available")))
        if latest_report
        else "unknown"
    )

    payload = {
        "success": True,
        "summary": {
            "total_uploaded_files": len(
                {
                    str(getattr(job_state, "upload_path", "") or "")
                    for job_state in all_jobs
                    if str(getattr(job_state, "upload_path", "") or "").strip()
                }
            ),
            "total_jobs": len(all_jobs),
            **status_counts,
            "failed_jobs_24h": failed_jobs_24h,
            "average_processing_time_seconds": (
                round(sum(processing_times) / len(processing_times), 3)
                if processing_times
                else None
            ),
            "last_analysis_time": last_analysis_time,
        },
        "queue_health": _pcap_admin_queue_health(status_counts, latest_status),
        "latest_attack_families": _pcap_admin_latest_attack_families(completed_reports),
        "top_suspicious_files": top_suspicious_files,
        "latest_files": latest_files,
        "performance": {
            "average_processing_time_seconds": (
                round(sum(processing_times) / len(processing_times), 3)
                if processing_times
                else None
            ),
            "fastest_processing_time_seconds": min(processing_times) if processing_times else None,
            "slowest_processing_time_seconds": max(processing_times) if processing_times else None,
            "processed_files": status_counts["completed_jobs"],
            "failed_processing_rate": (
                round((status_counts["failed_jobs"] / max(len(all_jobs), 1)) * 100.0, 2)
                if all_jobs
                else 0,
            ),
        },
        "engine_status": {
            "zeek_used": zeek_used,
            "analysis_mode": _pcap_admin_analysis_mode(latest_report),
            "model_version": _pcap_admin_model_version(),
            "feature_contract_status": _pcap_admin_feature_contract_status(latest_report),
            "report_evidence_availability": (
                "Report and evidence available"
                if latest_row and latest_row.get("report_available") and latest_row.get("evidence_available")
                else "Report available"
                if latest_row and latest_row.get("report_available")
                else None
            ),
            "last_successful_analysis": last_analysis_time,
        },
        "timeline": timeline[:18],
        "generated_at": datetime.now(UTC).isoformat(),
    }

    return jsonify(_sanitize_for_json(payload))


@app.route("/api/admin/pcap/jobs/<job_id>/export", methods=["GET"])
@admin_auth_required
def admin_export_pcap_job_artifact(job_id):
    job_state = jobs.get(job_id)
    if not job_state:
        return jsonify({"success": False, "message": "PCAP job not found."}), 404

    export_type = str(request.args.get("type", "report")).strip().lower()
    if export_type == "bundle":
        export_type = "evidence"
    if export_type not in {"report", "evidence"}:
        return jsonify({"success": False, "message": "Invalid export type."}), 400

    if _pcap_admin_status(getattr(job_state, "status", None)) != "done":
        return jsonify({"success": False, "message": "PCAP job is not completed yet."}), 409

    artifacts = _collect_job_export_artifacts(job_state)
    if export_type == "report":
        report_path = artifacts.get("report_path")
        if report_path is None or not report_path.exists():
            return jsonify({"success": False, "message": "Report artifact not found."}), 404

        log_admin_action(
            getattr(g, "current_admin", None),
            "report_exported",
            "Exported PCAP analysis report",
            "PCAP Analysis",
            target_type="pcap_job",
            target_id=job_id,
            target_label=_pcap_admin_job_filename(job_state),
            status="success",
            severity="high",
            metadata={"export_type": "report", "job_id": job_id},
            request=request,
        )
        return send_file(
            report_path,
            as_attachment=True,
            download_name=f"pcap_report_{job_id}.json",
            mimetype="application/json",
        )

    bundle_path = _build_job_evidence_bundle(job_state)
    if bundle_path is None or not bundle_path.exists():
        return jsonify({"success": False, "message": "Evidence bundle not available."}), 404

    log_admin_action(
        getattr(g, "current_admin", None),
        "report_exported",
        "Exported PCAP evidence bundle",
        "PCAP Analysis",
        target_type="pcap_job",
        target_id=job_id,
        target_label=_pcap_admin_job_filename(job_state),
        status="success",
        severity="critical",
        metadata={"export_type": "evidence", "job_id": job_id},
        request=request,
    )
    return send_file(
        bundle_path,
        as_attachment=True,
        download_name=f"pcap_evidence_{job_id}.zip",
        mimetype="application/zip",
    )


@app.route("/api/admin/users", methods=["POST"])
@admin_auth_required
def admin_create_user():
    data = request.get_json(silent=True) or {}
    email = _normalize_linked_account_email(data.get("email", ""))
    full_name = str(data.get("name") or "").strip()
    role = _normalize_admin_role(data.get("role") or "User")
    require_two_factor = bool(data.get("twoFA"))

    if not email:
        return jsonify({"success": False, "message": "Email is required."}), 400

    now = datetime.now(UTC)
    invite_token = secrets.token_urlsafe(32)
    invite_exp = now + timedelta(hours=ADMIN_INVITATION_EXPIRE_HOURS)
    existing_user = User.query.filter(func.lower(User.email) == email).first()

    if existing_user and (
        existing_user.is_email_verified
        or not getattr(existing_user, "invite_token", None)
        or getattr(existing_user, "invite_accepted_at", None) is not None
    ):
        return jsonify({"success": False, "message": "A user with this email already exists."}), 409

    if existing_user:
        existing_user.full_name = full_name or existing_user.full_name
        existing_user.password_hash = generate_password_hash(secrets.token_urlsafe(18))
        existing_user.is_email_verified = False
        existing_user.email_verification_token = None
        existing_user.email_verification_expires_at = None
        existing_user.invite_token = invite_token
        existing_user.invite_expires_at = invite_exp
        existing_user.invite_accepted_at = None
        existing_user.invite_require_2fa = require_two_factor
        existing_user.is_two_factor_enabled = False
        existing_user.two_factor_secret = None
        existing_user.require_two_factor_enrollment = require_two_factor
        existing_user.admin_role = role
        existing_user.admin_status = "Active"
        existing_user.updated_at = now
        invite_user = existing_user
    else:
        invite_user = User(
            email=email,
            password_hash=generate_password_hash(secrets.token_urlsafe(18)),
            full_name=full_name or None,
            is_email_verified=False,
            email_verification_token=None,
            email_verification_expires_at=None,
            invite_token=invite_token,
            invite_expires_at=invite_exp,
            invite_accepted_at=None,
            invite_require_2fa=require_two_factor,
            is_two_factor_enabled=False,
            two_factor_secret=None,
            require_two_factor_enrollment=require_two_factor,
            admin_role=role,
            admin_status="Active",
            created_at=now,
            updated_at=now,
        )

    try:
        if not existing_user:
            db.session.add(invite_user)
        db.session.flush()
        db.session.commit()
    except Exception:
        db.session.rollback()
        logging.exception("Failed to create admin-managed invitation")
        return jsonify({"success": False, "message": "Failed to create invitation."}), 500

    invite_link = f"{FRONTEND_BASE_URL}/accept-invitation?token={quote(invite_token)}"
    invitation_email_sent = True
    try:
        send_admin_invitation_email(invite_user)
    except Exception:
        invitation_email_sent = False
        logging.exception("Failed to send admin-managed invitation email")

    log_admin_action(
        getattr(g, "current_admin", None),
        "role_changed" if existing_user else "user_invited",
        (
            "Updated invited user role"
            if existing_user
            else (
                "Created admin-managed user invitation"
                if invitation_email_sent
                else "Created admin-managed user invitation without email delivery"
            )
        ),
        "Users & Roles",
        target_type="user",
        target_id=getattr(invite_user, "id", None),
        target_label=str(getattr(invite_user, "email", "") or email).strip().lower(),
        status="success" if invitation_email_sent else "warning",
        severity="high" if role == "Admin" else "medium",
        metadata={
            "role": role,
            "requires_2fa": require_two_factor,
            "existing_user": bool(existing_user),
            "invitation_email_sent": invitation_email_sent,
        },
        request=request,
    )
    return jsonify(
        {
            "success": True,
            "message": (
                "Invitation sent successfully."
                if invitation_email_sent
                else "Invitation created, but email delivery failed. Use the invitation link."
            ),
            "invitation_email_sent": invitation_email_sent,
            "invite_link": None if invitation_email_sent else invite_link,
            "user": _serialize_admin_user(invite_user),
        }
    ), (200 if existing_user else 201)


@app.route("/api/invitations/<token>", methods=["GET"])
def get_invitation_details(token: str):
    invitation_token = str(token or "").strip()
    if not invitation_token:
        return jsonify({"success": False, "message": "Invitation token is required."}), 400

    user = User.query.filter_by(invite_token=invitation_token).first()
    if user is None:
        return jsonify({"success": False, "message": "Invitation not found."}), 404

    expires_at = _as_utc_datetime(getattr(user, "invite_expires_at", None))
    if getattr(user, "invite_accepted_at", None):
        return jsonify({"success": False, "message": "Invitation has already been accepted."}), 409
    if expires_at and datetime.now(UTC) > expires_at:
        return jsonify({"success": False, "message": "Invitation has expired."}), 410

    return jsonify(
        {
            "success": True,
            "invitation": {
                "email": str(getattr(user, "email", "") or "").strip().lower(),
                "name": str(getattr(user, "full_name", "") or "").strip(),
                "role": _normalize_admin_role(getattr(user, "admin_role", "User")),
                "requireTwoFactor": bool(getattr(user, "invite_require_2fa", False)),
                "expiresAt": expires_at.isoformat() if expires_at else None,
            },
        }
    )


@app.route("/api/invitations/<token>/accept", methods=["POST"])
def accept_invitation(token: str):
    invitation_token = str(token or "").strip()
    data = request.get_json(silent=True) or {}
    password = str(data.get("password") or "")
    full_name = str(data.get("name") or "").strip()

    if not invitation_token:
        return jsonify({"success": False, "message": "Invitation token is required."}), 400
    if len(password) < 8:
        return jsonify({"success": False, "message": "Password must be at least 8 characters."}), 400

    user = User.query.filter_by(invite_token=invitation_token).first()
    if user is None:
        return jsonify({"success": False, "message": "Invitation not found."}), 404

    expires_at = _as_utc_datetime(getattr(user, "invite_expires_at", None))
    if getattr(user, "invite_accepted_at", None):
        return jsonify({"success": False, "message": "Invitation has already been accepted."}), 409
    if expires_at and datetime.now(UTC) > expires_at:
        return jsonify({"success": False, "message": "Invitation has expired."}), 410

    require_two_factor = bool(getattr(user, "invite_require_2fa", False))
    now = datetime.now(UTC)
    user.password_hash = generate_password_hash(password)
    user.full_name = full_name or user.full_name
    user.is_email_verified = True
    user.email_verification_token = None
    user.email_verification_expires_at = None
    user.invite_accepted_at = now
    user.invite_token = None
    user.invite_expires_at = None
    user.require_two_factor_enrollment = require_two_factor
    user.is_two_factor_enabled = False
    user.two_factor_secret = None
    user.updated_at = now

    try:
        db.session.commit()
    except Exception:
        db.session.rollback()
        logging.exception("Failed to accept invitation for user_id=%s", getattr(user, "id", None))
        return jsonify({"success": False, "message": "Invitation could not be completed."}), 500

    if require_two_factor:
        pending_token = create_pending_2fa_token(
            user.id,
            PENDING_2FA_SETUP_STATE,
            PENDING_2FA_SETUP_EXPIRE_MINUTES,
        )
        resp = jsonify(
            {
                "success": True,
                "message": "Password set successfully. Continue to 2FA setup.",
                "email": str(getattr(user, "email", "") or "").strip().lower(),
                "requires_2fa_setup": True,
                "pending_token": pending_token,
            }
        )
        clear_auth_cookies(resp)
        set_cookie(
            resp,
            PENDING_2FA_TOKEN_COOKIE,
            pending_token,
            PENDING_2FA_SETUP_EXPIRE_MINUTES * 60,
        )
        return resp

    return jsonify(
        {
            "success": True,
            "message": "Invitation accepted successfully. You can now sign in.",
            "email": str(getattr(user, "email", "") or "").strip().lower(),
            "requires_2fa_setup": False,
        }
    )


@app.route("/api/admin/users/<int:user_id>/status", methods=["PATCH"])
@admin_auth_required
def admin_update_user_status(user_id: int):
    data = request.get_json(silent=True) or {}
    requested_status = str(data.get("status") or "").strip().lower()
    if requested_status in {"suspended", "locked"}:
        next_status = "Locked"
    else:
        next_status = _normalize_admin_status(data.get("status") or "")
    if next_status not in ADMIN_STATUS_CHOICES:
        return jsonify({"success": False, "message": "Invalid user status."}), 400

    user = db.session.get(User, int(user_id))
    if user is None:
        return jsonify({"success": False, "message": "User not found."}), 404
    previous_status = _normalize_admin_status(getattr(user, "admin_status", "Active"))

    user.admin_status = next_status
    user.updated_at = datetime.now(UTC)
    if next_status == "Locked":
        user.session_version = _get_user_session_version(user) + 1

    try:
        db.session.commit()
    except Exception:
        db.session.rollback()
        logging.exception("Failed to update admin-managed user status | user_id=%s", user_id)
        return jsonify({"success": False, "message": "Failed to update user status."}), 500

    action_type = "user_locked" if next_status == "Locked" else "user_unlocked" if previous_status == "Locked" else "settings_updated"
    log_admin_action(
        getattr(g, "current_admin", None),
        action_type,
        f"Changed user status to {next_status}",
        "Users & Roles",
        target_type="user",
        target_id=user_id,
        target_label=str(getattr(user, "email", "") or "").strip().lower(),
        status="success",
        severity="critical" if next_status == "Locked" else "high",
        metadata={"previous_status": previous_status, "new_status": next_status},
        request=request,
    )
    return jsonify({"success": True, "user": _serialize_admin_user(user)})


@app.route("/api/admin/users/<int:user_id>", methods=["DELETE"])
@admin_auth_required
def admin_delete_user(user_id: int):
    user = db.session.get(User, int(user_id))
    if user is None:
        return jsonify({"success": False, "message": "User not found."}), 404

    current_admin = getattr(g, "current_admin", {}) or {}
    current_admin_email = str(current_admin.get("email") or "").strip().lower()
    user_email = str(getattr(user, "email", "") or "").strip().lower()
    if current_admin_email and user_email == current_admin_email:
        return jsonify(
            {"success": False, "message": "You cannot delete the currently signed-in admin."}
        ), 400

    try:
        from encrypted_file_vault.models import VaultDocument

        db.session.query(PasswordCheck).filter(
            PasswordCheck.user_id == user.id
        ).delete(synchronize_session=False)
        db.session.query(PasswordHistory).filter(
            PasswordHistory.user_id == user.id
        ).delete(synchronize_session=False)
        db.session.query(VaultDocument).filter(
            VaultDocument.user_id == user.id
        ).delete(synchronize_session=False)
        try:
            db_path = next((path for path in _phishing_db_candidates() if path.exists()), None)
            if db_path is not None:
                with sqlite3.connect(db_path) as conn:
                    conn.execute("DELETE FROM scans WHERE user_id=?", (int(user.id),))
                    conn.commit()
        except Exception:
            logging.exception("Failed to delete phishing scans for user | user_id=%s", user_id)
        try:
            clear_identity_web_history(int(user.id))
        except Exception:
            logging.exception("Failed to delete identity history for user | user_id=%s", user_id)
        db.session.query(RefreshToken).filter(
            RefreshToken.user_id == user.id
        ).delete(synchronize_session=False)
        db.session.query(SecurityAuditLog).filter(
            SecurityAuditLog.user_id == user.id
        ).delete(synchronize_session=False)
        db.session.query(UserNotification).filter(
            UserNotification.user_id == user.id
        ).delete(synchronize_session=False)
        db.session.query(PcapAlertRecord).filter(
            PcapAlertRecord.user_id == user.id
        ).delete(synchronize_session=False)
        db.session.query(MonthlySecurityReport).filter(
            MonthlySecurityReport.user_id == user.id
        ).delete(synchronize_session=False)
        db.session.query(LinkedAccount).filter(
            LinkedAccount.user_id == user.id
        ).delete(synchronize_session=False)
        db.session.delete(user)
        db.session.commit()
    except Exception:
        db.session.rollback()
        logging.exception("Failed to delete admin-managed user | user_id=%s", user_id)
        return jsonify({"success": False, "message": "Failed to delete user."}), 500

    log_admin_action(
        getattr(g, "current_admin", None),
        "user_deleted",
        "Deleted admin-managed user",
        "Users & Roles",
        target_type="user",
        target_id=user_id,
        target_label=user_email,
        status="success",
        severity="critical",
        metadata={"deleted_user_email": user_email},
        request=request,
    )
    return jsonify({"success": True, "message": "User deleted successfully."})


