@app.route("/api/admin/ai-governance/confidence-thresholds", methods=["PATCH"])
@admin_auth_required
def admin_ai_governance_update_confidence_thresholds():
    data = request.get_json(silent=True) or {}

    try:
        confirmed = float(data.get("confirmed", AI_GOVERNANCE_THRESHOLDS["confirmed"]))
        suspicious = float(data.get("suspicious", AI_GOVERNANCE_THRESHOLDS["suspicious"]))
        ignore_below = float(data.get("ignore_below", AI_GOVERNANCE_THRESHOLDS["ignore_below"]))
        escalation = float(
            data.get(
                "minimum_severity_escalation_confidence",
                AI_GOVERNANCE_THRESHOLDS["minimum_severity_escalation_confidence"],
            )
        )
    except (TypeError, ValueError):
        return jsonify({"success": False, "message": "Thresholds must be numeric."}), 400

    if not (0 <= ignore_below <= suspicious < confirmed <= 1):
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Threshold order must be ignore <= suspicious < confirmed within 0..1.",
                }
            ),
            400,
        )

    if not (suspicious <= escalation <= confirmed):
        return (
            jsonify(
                {
                    "success": False,
                    "message": "Escalation confidence must be between suspicious and confirmed.",
                }
            ),
            400,
        )

    AI_GOVERNANCE_THRESHOLDS.update(
        {
            "confirmed": round(confirmed, 2),
            "suspicious": round(suspicious, 2),
            "ignore_below": round(ignore_below, 2),
            "minimum_severity_escalation_confidence": round(escalation, 2),
        }
    )
    log_admin_action(
        getattr(g, "current_admin", None),
        "settings_updated",
        "Updated AI governance confidence thresholds",
        "AI Governance",
        target_type="runtime_thresholds",
        target_label="AI governance thresholds",
        status="success",
        severity="high",
        metadata={"thresholds": dict(AI_GOVERNANCE_THRESHOLDS)},
        request=request,
    )
    return (
        jsonify(
            {
                "success": True,
                "message": "Confidence thresholds saved for the current admin runtime.",
                "thresholds": dict(AI_GOVERNANCE_THRESHOLDS),
            }
        ),
        200,
    )


